//! Comptime V8 Interface Binding Generator
//!
//! This module generates V8 bindings for WebIDL interfaces using pre-computed
//! hints from Meta.properties and Meta.methods (generated by codegen).
//!
//! ## How It Works
//!
//! 1. Takes a generated interface struct (e.g., `Element.Element`)
//! 2. Reads Meta.properties and Meta.methods (pre-computed, no reflection needed)
//! 3. Generates V8 FunctionTemplate with prototype at compile time
//! 4. Returns a type with methods to register the interface in V8
//!
//! ## Usage Example
//!
//! ```zig
//! const ElementBinding = V8Interface(@import("generated/interfaces/Element.zig").Element);
//!
//! // In your V8 initialization code:
//! ElementBinding.registerGlobal(isolate, context, "Element");
//! ```
//!
//! ## Features
//!
//! - Property getters/setters (from Meta.properties)
//! - Methods on prototype (from Meta.methods)
//! - Inheritance chain (BaseType)
//! - Mixins (flattened into prototype)
//! - Internal fields for Zig instance storage

const std = @import("std");
const log = std.log.scoped(.v8_interface);
const debug = @import("debug.zig");
const v8 = @import("ffi.zig");
const cross_origin = @import("cross_origin.zig");
const engine_capabilities = @import("protocol.zig").capabilities;
const conv = @import("conversions.zig");
const runtime = @import("runtime");
/// Public for tests/v8, which builds and frees overloads with the testing
/// allocator.
pub const overload_resolver = @import("overload_resolver.zig");
const wrapper_type_info = @import("wrapper_type_info.zig");
const template_registry = @import("template_registry.zig");
const window_properties = @import("window_properties.zig");
const value_operations = @import("value_operations.zig");

/// Re-export WrapperTypeInfo for use by generated bindings
pub const WrapperTypeInfo = wrapper_type_info.WrapperTypeInfo;

/// Import webidl for Opt type checking
const webidl = @import("webidl");

/// Number of internal fields required for wrapped objects
/// Slot 0: Zig instance pointer
/// Slot 1: WrapperTypeInfo pointer (for type-safe unwrapping)
pub const INTERNAL_FIELD_COUNT: c_int = 2;

/// Check if a type is a webidl.Opt (Optional) wrapper type by checking for notPassed() declaration
fn isWebIdlOpt(comptime T: type) bool {
    const info = @typeInfo(T);
    // Must be a struct to have declarations
    if (info != .@"struct") return false;
    // Must have notPassed() and wasPassed() functions (characteristic of webidl.Optional/Opt)
    return @hasDecl(T, "notPassed") and @hasDecl(T, "wasPassed");
}

/// Get the default value for a parameter type when the argument was not provided.
/// Returns null if no default is possible and NotEnoughArguments should be returned.
/// This function handles all the type-specific logic at comptime to avoid
/// generating invalid code paths for incompatible types.
fn getDefaultArgValue(comptime T: type) ?T {
    const info = @typeInfo(T);

    // Check webidl.Opt first (highest priority)
    if (info == .@"struct" and @hasDecl(T, "notPassed") and @hasDecl(T, "wasPassed")) {
        return T.notPassed();
    }

    // Check for dictionary types with all-optional fields
    if (info == .@"struct" and canDefaultInit(T)) {
        return defaultInit(T);
    }

    // Check Zig optional type
    if (info == .optional) {
        return null;
    }

    // Check DOMString type
    if (T == runtime.DOMString) {
        return runtime.DOMString.initEmpty();
    }

    // Check runtime.JSValue - default to undefined
    // This handles cases like postMessage(message, transfer) where transfer is optional
    // and the JavaScript caller provides only one argument
    if (T == runtime.JSValue) {
        return runtime.JSValue{ .undefined = {} };
    }

    // For anyopaque pointers, we can't return a valid default
    // Caller must handle this case specially
    if (T == *const anyopaque or T == *anyopaque) {
        return null; // Signal to use undefined
    }

    // Check for slice types (variadic arguments like "any... arguments")
    // Return empty slice as default - variadic args are optional by nature
    if (info == .pointer and info.pointer.size == .slice) {
        return &[_]info.pointer.child{};
    }

    // No valid default
    return null;
}

/// Check if a type can have a default or should use undefined (for anyopaque pointers)
fn canUseUndefined(comptime T: type) bool {
    return T == *const anyopaque or T == *anyopaque;
}

/// Check if a type can be default-initialized (all fields have defaults or are optional/struct)
fn canDefaultInit(comptime T: type) bool {
    const info = @typeInfo(T);
    if (info != .@"struct") {
        return switch (info) {
            .optional => true,
            .bool, .int, .float => true,
            else => false,
        };
    }

    // Check all fields
    inline for (info.@"struct".fields) |field| {
        if (field.default_value_ptr != null) {
            // Has explicit default - OK
            continue;
        }
        // No default value - check if we can recursively init
        const field_info = @typeInfo(field.type);
        if (field_info == .@"struct") {
            if (!canDefaultInit(field.type)) return false;
        } else if (field_info == .optional) {
            // Optional without default - OK (use null)
            continue;
        } else {
            // Required field without default - cannot default init
            return false;
        }
    }
    return true;
}

/// Recursively creates a default-initialized value for a struct type.
/// Handles nested structs (like dictionary inheritance with `base` fields)
/// by recursively initializing them as well.
/// Only call this if canDefaultInit(T) returns true.
fn defaultInit(comptime T: type) T {
    const info = @typeInfo(T);
    if (info != .@"struct") {
        // Non-struct types: use zero/null default
        return switch (info) {
            .optional => null,
            .bool => false,
            .int, .float => 0,
            else => unreachable, // canDefaultInit should have caught this
        };
    }

    // Build struct with default values for all fields
    var result: T = undefined;
    inline for (info.@"struct".fields) |field| {
        if (field.default_value_ptr) |default_ptr| {
            // Field has explicit default value (Zig 0.15: default_value_ptr)
            const typed_ptr: *const field.type = @ptrCast(@alignCast(default_ptr));
            @field(result, field.name) = typed_ptr.*;
        } else {
            // No default value - recursively initialize if struct, otherwise use null
            const field_info = @typeInfo(field.type);
            if (field_info == .@"struct") {
                @field(result, field.name) = defaultInit(field.type);
            } else if (field_info == .optional) {
                @field(result, field.name) = null;
            } else {
                unreachable; // canDefaultInit should have caught this
            }
        }
    }
    return result;
}

/// Comptime V8 interface binding generator
///
/// Takes a WebIDL interface struct and generates V8 bindings.
/// Uses pre-computed hints from Meta.properties and Meta.methods
/// to avoid expensive comptime reflection loops.
///
/// Template:
/// - `Interface`: Generated interface struct type (e.g., `Element.Element`)
///
/// Returns:
/// A type with methods to register the interface in V8:
/// - `registerGlobal(isolate, context, name)` - Register as global constructor
/// - `createTemplate(isolate)` - Create FunctionTemplate
/// Can a value of type `T` cause argument conversion to RETAIN the V8
/// context beyond the call?
///
/// Expressed as an ALLOWLIST of provably inert types, and that direction is
/// the whole point. Twice I wrote this as a blocklist - "retains unless it
/// is an Instance pointer", "retains only for *runtime.CallbackWrapper" -
/// and twice an unlisted type slipped through and became a use-after-free:
/// 2-3 crashes per timers run the first time, 10 of 12 files the second,
/// because `setTimeout`'s handler is `typedefs.TimerHandler`, a union whose
/// `function` arm is a callback. A blocklist is wrong by default for an
/// open set of types; an allowlist is merely conservative.
///
/// An unrecognised type therefore answers TRUE - assume retention, keep the
/// old leak - which costs memory and never correctness.
pub fn typeRetainsContext(comptime T: type) bool {
    return typeRetainsContextDepth(T, 0);
}

fn typeRetainsContextDepth(comptime T: type, comptime depth: u32) bool {
    return comptime blk: {
        // Dictionaries are walked member by member, recursively.
        @setEvalBranchQuota(100_000);
        // Inert scalars: conversion produces a Zig value holding no handle.
        if (T == void or T == bool) break :blk false;
        if (T == i8 or T == i16 or T == i32 or T == i64 or T == isize) break :blk false;
        if (T == u8 or T == u16 or T == u32 or T == u64 or T == usize) break :blk false;
        if (T == f32 or T == f64) break :blk false;

        // Strings own their own bytes; no V8 handle survives the call.
        if (T == runtime.DOMString or T == []const u8) break :blk false;
        if (@hasDecl(runtime, "USVString") and T == runtime.USVString) break :blk false;
        if (@hasDecl(runtime, "ByteString") and T == runtime.ByteString) break :blk false;

        const info = @typeInfo(T);

        // WebIDL enums convert to a plain tag.
        if (info == .@"enum") break :blk false;

        // `JSValue` is inert FOR THE CONTEXT, which is what this predicate
        // governs. `conv.fromV8Value`'s JSValue branch returns
        // `.handle = .{ .ptr = value }` - it keeps the VALUE pointer and uses
        // `context` only transiently, for `v8_Value_NumberValue` and
        // `v8_Value_ToString`. Retaining a value handle
        // is a different question from retaining the context, and conflating them
        // kept `createElement` - whose second parameter is `webidl.Opt(JSValue)` -
        // leaking its context on the hottest path in the DOM.
        if (T == runtime.JSValue) break :blk false;

        // Optionals and error unions are inert exactly when their payload is.
        if (info == .optional) break :blk typeRetainsContextDepth(info.optional.child, depth + 1);
        if (info == .error_union) break :blk typeRetainsContextDepth(info.error_union.payload, depth + 1);

        // `webidl.Opt(T)` wraps a payload in `.value`.
        if (info == .@"struct" and @hasField(T, "value") and @hasField(T, "was_passed")) {
            break :blk typeRetainsContextDepth(@FieldType(T, "value"), depth + 1);
        }

        // A wrapped platform object: conversion checks the wrapper, reads its
        // internal fields and returns the pointer, keeping nothing of the
        // context.
        if (T == *runtime.Instance) break :blk false;

        // A callback interface converts to a CallbackWrapper, which keeps a
        // context handle of its own (callback_wrapper.initFunction/initObject);
        // a callback function converts to its own argument handle, tagged, and
        // never reads the context. Neither keeps the caller's.
        if (T == *runtime.CallbackWrapper) break :blk false;
        if (info == .pointer and info.pointer.size == .one and @typeInfo(info.pointer.child) == .@"fn") break :blk false;

        // Buffer sources are made without the context: a BufferSource, an
        // AllowSharedBufferSource or an ArrayBufferView is a reference to its
        // object (conv.convertBufferSource and convertAllowSharedBufferSource
        // read the kind and the view's Describe, nothing else). Whether the
        // ARGUMENT handle may go is argHandleIsCopied's question, not this one.
        if (T == webidl.BufferSource or T == webidl.ArrayBufferView or T == webidl.AllowSharedBufferSource) break :blk false;

        // A self-referential dictionary would recurse without end; past this
        // depth, give the safe answer.
        if (depth >= 8) break :blk true;

        // A sequence converts element by element (fromV8Sequence), a dictionary
        // member by member, and a union by trying its arms - each with these
        // same rules, the context used only while it does. So each is inert
        // exactly when every part is: one callback member, function pointer or
        // unknown pointer anywhere makes the whole type retain.
        if (info == .pointer and info.pointer.size == .slice) {
            break :blk typeRetainsContextDepth(info.pointer.child, depth + 1);
        }
        if (info == .@"struct") {
            for (info.@"struct".fields) |field| {
                if (typeRetainsContextDepth(field.type, depth + 1)) break :blk true;
            }
            break :blk false;
        }
        if (info == .@"union") {
            for (info.@"union".fields) |field| {
                if (typeRetainsContextDepth(field.type, depth + 1)) break :blk true;
            }
            break :blk false;
        }

        // Everything else - callbacks, function pointers, unknown pointers -
        // is assumed to retain.
        break :blk true;
    };
}

/// Does converting an argument of type `T` COPY out of the V8 handle, so the
/// `Global<Value>` that `info.get(N)` allocated can be released once the
/// conversion returns?
///
/// `v8_FunctionCallbackInfo_GetArgument` heap-allocates a `Global<Value>` where
/// V8 hands back a borrowed `Local`, and nothing released it: `leaks --atExit`
/// counted 199,997 abandoned argument handles per 200,000 cycles - one per
/// `document.createElement` call.
///
/// An ALLOWLIST, for the same reason `typeRetainsContext` is one, and the
/// danger here is sharper: some conversions KEEP this exact pointer as the
/// value rather than copying from it. `conv.fromV8Value`'s function-pointer
/// branch does - the value is that Global, freed with the value
/// (`freeConvertedArg`) - and `runtime.JSValue` keeps it as `.handle.ptr`.
/// Releasing either at conversion is a use-after-free.
///
/// So an unrecognised type answers FALSE: keep the handle, keep the old leak.
pub fn argHandleIsCopied(comptime T: type) bool {
    return comptime blk: {
        // Dictionaries are walked member by member, recursively.
        @setEvalBranchQuota(100_000);
        // Scalars decode to a Zig value; the handle is read and done with.
        if (T == void or T == bool) break :blk true;
        if (T == i8 or T == i16 or T == i32 or T == i64 or T == isize) break :blk true;
        if (T == u8 or T == u16 or T == u32 or T == u64 or T == usize) break :blk true;
        if (T == f32 or T == f64) break :blk true;

        // Strings are copied out: the DOMString branch ends at
        // `fromV8String` -> `DOMString.initOwned(buffer)`, an owned buffer, and
        // the V8 string it read from is released by `v8_FreeToStringResult`
        // before it returns.
        if (T == runtime.DOMString or T == []const u8) break :blk true;
        if (@hasDecl(runtime, "USVString") and T == runtime.USVString) break :blk true;
        if (@hasDecl(runtime, "ByteString") and T == runtime.ByteString) break :blk true;

        const info = @typeInfo(T);

        // WebIDL enums decode to a plain tag.
        if (info == .@"enum") break :blk true;

        // Wrappers are copied exactly when their payload is. Note these are NOT
        // recursive beyond one level on purpose - a payload that is itself a
        // wrapper falls through to the conservative answer.
        if (info == .optional) break :blk argHandleIsCopied(info.optional.child);
        if (info == .error_union) break :blk argHandleIsCopied(info.error_union.payload);
        if (info == .@"struct" and @hasField(T, "value") and @hasField(T, "was_passed")) {
            break :blk argHandleIsCopied(@FieldType(T, "value"));
        }

        // JSValue keeps the pointer it was given (see the test that pins it).
        if (T == runtime.JSValue) break :blk false;

        // A buffer source IS a reference to the object it was converted from:
        // the handle itself (conv.convertBufferSource,
        // convertAllowSharedBufferSource, convertArrayBufferView), released
        // with the value (`bufferHandleIsKeptInValue`). Named before the
        // structural rules, which must never get to call it copied.
        //
        // AllowSharedBufferSource was "copied" here while its conversion was
        // a slice over the backing store, and its Global went at conversion -
        // but the slice did not survive a later argument's getter that
        // transferred the buffer (TextDecoder.decode read the freed store).
        // It is a reference now, kept until the call returns.
        if (T == webidl.BufferSource or T == webidl.ArrayBufferView or T == webidl.AllowSharedBufferSource) break :blk false;

        // A wrapped platform object: the conversion returns the Instance from
        // the wrapper's internal field, and the argument's own handle is not
        // referred to again.
        if (T == *runtime.Instance) break :blk true;

        // BodyInit: convertBodyInit copies out of the handle on every path -
        // an owned USVString, a copy of a buffer's bytes, or the Instance a
        // platform object's wrapper holds (see `freeBodyInitArg`).
        if (T == copied_arg_types.BodyInit) break :blk true;

        // A sequence reads each element through its own handle (v8_Array_Get):
        // copied when its elements are - and when they are callback
        // functions, each of which holds its OWN element handle, freed with
        // the sequence (`freeConvertedArg`), never the sequence's.
        if (info == .pointer and info.pointer.size == .slice) {
            break :blk argHandleIsCopied(info.pointer.child) or isCallbackFunctionShape(info.pointer.child);
        }

        // A dictionary reads each member through its own handle (Get), so no
        // member aliases the dictionary's handle. Members are still held to a
        // rule - a JSValue member aliasing ITS OWN handle is fine - so that an
        // unknown pointer keeps the conservative answer.
        if (info == .@"struct" and !@hasDecl(T, "Meta")) {
            for (info.@"struct".fields) |field| {
                // A member that is a sequence of the dictionary itself
                // (AuctionAdConfig.componentAuctions,
                // HIDCollectionInfo.children) is as safe as the rest of
                // the dictionary; walking it would recurse forever.
                if (isSelfMember(field.type, T)) continue;
                if (!memberHandleIsSafe(field.type)) break :blk false;
            }
            break :blk true;
        }

        // A union converts the same handle through whichever arm matches.
        if (info == .@"union") {
            for (info.@"union".fields) |field| {
                if (!argHandleIsCopied(field.type)) break :blk false;
            }
            break :blk true;
        }

        // Callbacks, function pointers, buffer views, unknown pointers: assume
        // the handle is kept.
        break :blk false;
    };
}

/// Whether member type `M` is dictionary `T` itself, through optionals and
/// sequences.
fn isSelfMember(comptime M: type, comptime T: type) bool {
    if (M == T) return true;
    const info = @typeInfo(M);
    if (info == .optional) return isSelfMember(info.optional.child, T);
    if (info == .pointer and info.pointer.size == .slice) return isSelfMember(info.pointer.child, T);
    return false;
}

/// A dictionary member's conversion may alias the handle Get made for that
/// member - a JSValue does, so does a buffer source (a reference to its
/// object) or an `object` arm - but never the dictionary's own.
fn memberHandleIsSafe(comptime T: type) bool {
    if (argHandleIsCopied(T)) return true;
    if (T == runtime.JSValue) return true;
    if (argumentHandleIsKeptInValue(T)) return true;
    // A callback function member - a function pointer, codegen's type for a
    // callback function - holds the handle Get made for IT: conv.fromV8Value's
    // function-pointer branch makes that Global the value, freed with the
    // dictionary (freeConvertedArg), and an impl that keeps the callback takes
    // a hold of its own (engine.takeCallbackFunction). Never the
    // dictionary's. QueuingStrategy's `size` (`?callbacks.QueuingStrategySize`)
    // made every strategy keep its argument's handle: one Global per
    // `new WritableStream(sink, strategy)`, `new ReadableStream(...)` and
    // TransformStream strategy (lane leaks2). Blink's bindings read the
    // dictionary and its members as Locals of the callback's HandleScope, so
    // nothing of the dictionary outlives the call; a callback member is a
    // CallbackFunctionBase holding a reference of its own made from its
    // member's Local (platform/bindings/callback_function_base.h,
    // `TraceWrapperV8Reference<v8::Object> callback_function_`).
    if (isCallbackFunctionType(T)) return true;
    const info = @typeInfo(T);
    if (info == .optional) return memberHandleIsSafe(info.optional.child);
    // A sequence<any> / sequence<object> member reads each element through
    // its own handle (v8_Array_Get on the member's array), so no element can
    // alias the dictionary's handle either: StructuredSerializeOptions'
    // `transfer` kept every postMessage(message, options) dictionary's
    // argument handle - one Global per call (workers2's leaks --atExit).
    // JSValue elements only: a sequence of copied elements is already
    // copied (argHandleIsCopied).
    if (info == .pointer and info.pointer.size == .slice and info.pointer.child == runtime.JSValue) return true;
    return false;
}

/// `T` is a callback function as codegen types one: a pointer to a Zig
/// function (`callbacks.X = *const fn (...) R`), the type conv.fromV8Value's
/// function-pointer branch converts by holding the handle it was given - a
/// value BORROWED for the call, freed with it (`freeConvertedArg`).
/// Not `*anyopaque` (a union's Function arm), which stays unknown here.
fn isCallbackFunctionType(comptime T: type) bool {
    const info = @typeInfo(T);
    return info == .pointer and info.pointer.size == .one and @typeInfo(info.pointer.child) == .@"fn";
}

/// A callback function or its nullable form: what conv.fromV8Value converts
/// by holding the handle it was given (or, for null, holding nothing).
fn isCallbackFunctionShape(comptime T: type) bool {
    const info = @typeInfo(T);
    if (info == .optional) return isCallbackFunctionType(info.optional.child);
    return isCallbackFunctionType(T);
}

/// A tagged union whose arms are copied (`argHandleIsCopied`) or callback
/// functions, with at least one callback function.
fn callbackArmsOnlyKeepHandle(comptime T: type) bool {
    return comptime blk: {
        const info = @typeInfo(T);
        if (info != .@"union" or info.@"union".tag_type == null) break :blk false;
        if (T == runtime.JSValue or T == runtime.DOMString) break :blk false;
        var callbacks = 0;
        for (info.@"union".fields) |field| {
            if (isCallbackFunctionShape(field.type)) {
                callbacks += 1;
            } else if (!argHandleIsCopied(field.type)) {
                break :blk false;
            }
        }
        break :blk callbacks > 0;
    };
}

/// The Global a callback-function value holds: its address, untagged
/// (conversions.zig stores it as the function pointer's value).
fn callbackFunctionGlobal(comptime T: type, value: T) *v8.Value {
    comptime std.debug.assert(isCallbackFunctionType(T));
    return @ptrFromInt(@intFromPtr(value));
}

/// Does `conv.toV8Value(T, ...)` make a fresh Global for every value of `T` -
/// numbers, booleans, strings and enums, and the null of their optional forms
/// - rather than hand back one it borrows (a cached wrapper, a stored callback,
/// a script value)? A result the binding hands V8 through `setReturnValue` is
/// read into a Local there and not released (`v8_PropertyCallbackInfo_
/// SetReturnValue`, `v8_FunctionCallbackInfo_SetReturnValueGlobal`), so a
/// fresh one is released by the binding after it: the attribute getters, and
/// the indexed and named property interceptors. A named getter's string kept
/// was one Global per `el.dataset.x` read - 60,000 a page on
/// encoding/legacy-mb-*-decode, the heap growing a megabyte a page.
///
/// An ALLOWLIST, for the reason `argHandleIsCopied` is one: `*runtime.Instance`
/// converts to the wrapper cache's own handle, a JSValue may be the impl's
/// handle or a wrapper, an ArrayBufferView its buffer's - releasing any of
/// them is a use-after-free. So a type not named here answers FALSE: keep
/// the handle, keep the leak.
///
/// One more is listed: an ArrayBufferView, which conv.toV8Value hands back as
/// its `js` - a handle the impl handed over. A view result is the binding's,
/// as a JSValue result's handle is (ArrayBufferView.jsHandle): an impl that
/// returns a view it keeps (ReadableStreamBYOBRequest.view) or was given
/// (Crypto.getRandomValues) returns it over a hold of its own.
pub fn getterValueIsOwned(comptime T: type) bool {
    const owned = [_]type{
        u8,                u16,                u32,               i8,   i16,  i32,                    u64, i64, f32, f64, bool,
        runtime.DOMString, ?runtime.DOMString, runtime.USVString, ?u64, ?i64, webidl.ArrayBufferView,
    };
    inline for (owned) |O| {
        if (T == O) return true;
    }
    const info = @typeInfo(T);
    // An optional of one of them - `?f64`, `?bool`, `?u32`: conv.toV8Value
    // converts a non-null one by converting its payload, as fresh as the
    // payload's own conversion, and a null one to a fresh Null. Only these
    // were listed before, so every non-null `?f64` read
    // (writer.desiredSize) leaked its Number. The payload decides, so an
    // optional of anything not listed - an Instance, a JSValue - stays kept.
    if (info == .optional) {
        const Payload = info.optional.child;
        if (@typeInfo(Payload) == .optional) return false;
        return getterValueIsOwned(Payload);
    }
    return info == .@"enum";
}

/// Whether an attribute setter's value, converted as a `T` that
/// `argHandleIsCopied` does not accept, leaves the handle it was converted
/// from referred to by nothing - so that the binding, which owns it
/// (`info.get` allocates), releases it. Read off the VALUE, as
/// `keptArgumentHandle` reads an operation argument's:
///
/// - a type `argumentHandleIsKeptInValue` accepts (an `any`, an `object`
///   union arm, a buffer source): when `keptArgumentHandle` finds none - a
///   primitive, a string copied out, null;
/// - any other nullable type: when the value is null. `conv.fromV8Value`
///   answers null for null and undefined, and an optional callback
///   (EventHandler) for a value that is not a function, before converting
///   anything - so nothing was made that could refer to the handle.
///
/// Everything else keeps the conservative answer (false: the value may
/// refer to the handle). An object assigned to an `any` attribute is one
/// here; `setterValueIsBorrowed` releases it once the setter has returned.
///
/// The rule every converted value is held to: `conversionLeavesHandle`.
pub fn setterValueLeavesHandle(comptime T: type, value: T) bool {
    return conversionLeavesHandle(T, value);
}

/// Whether `value`, converted from a handle as a `T` that `argHandleIsCopied`
/// does not accept, leaves that handle referred to by nothing - so that
/// whoever owns the handle (the binding, for an argument `info.get` made or
/// a member Get made) releases it now. Read off the VALUE, mirroring the
/// converter's branches in its order (conv.fromV8ValueAs,
/// fromV8ValueInteger):
///
/// 1. A copied type: false - the copied rule releases it, whatever the value.
/// 2. A type `argumentHandleIsKeptInValue` accepts (an `any`, an `object`
///    union arm, a buffer source): when `keptArgumentHandle` finds none - a
///    primitive, a string copied out, null.
/// 3. A nullable type: when the value is null. The optional branch answers
///    null for null and undefined, and an optional callback for a value that
///    is not a function, BEFORE converting anything; any other value is its
///    payload's conversion, which the payload's rule decides.
/// 4. A `webidl.Opt`: when not passed - undefined, read before anything is
///    converted - and otherwise as its value.
///
/// Everything else keeps the conservative answer (false: the value may refer
/// to the handle) - a callback function's value IS the handle, a callback
/// interface's wrapper took it over. Kept, a null optional callback was one
/// Global per call: QueuingStrategy's absent `size` member (one Get handle
/// per `new WritableStream(sink, {highWaterMark: 0})`) and
/// `addEventListener(type, null)`'s argument (lane leaks2).
pub fn conversionLeavesHandle(comptime T: type, value: T) bool {
    if (comptime argHandleIsCopied(T)) return false;
    if (comptime argumentHandleIsKeptInValue(T)) return keptArgumentHandle(T, value) == null;
    // A union whose only arms that are not copied are callback functions
    // (TimerHandler, ObserverUnion): the function arm holds the handle, and
    // every other arm copied out of it - the union path converts a callable
    // to the function arm and everything else through its own branches. So
    // the handle is left when the active arm is not a callback. Kept, a
    // string TimerHandler kept its argument's Global.
    if (comptime callbackArmsOnlyKeepHandle(T)) {
        switch (value) {
            inline else => |payload| return !comptime isCallbackFunctionShape(@TypeOf(payload)),
        }
    }
    const info = @typeInfo(T);
    if (comptime info == .optional) {
        const payload = value orelse return true;
        return conversionLeavesHandle(info.optional.child, payload);
    }
    if (comptime isOptWrapper(T)) {
        if (!value.was_passed) return true;
        return conversionLeavesHandle(@FieldType(T, "value"), value.value);
    }
    return false;
}

/// Does an attribute setter whose value is a `T` BORROW the value for the
/// call, so that the binding releases the handle `info.get(0)` made once the
/// setter has returned - or failed, or its conversion failed?
///
/// True exactly for the `any` shapes, `anyHandleIsKeptOnlyAsHandle`: an
/// `any` (`runtime.JSValue`, nullable or a `webidl.Opt`), or a union whose
/// only non-copying arm is `object`. Their conversion makes an object,
/// function or symbol into a `.handle` over that very Global and copies every
/// other value out, so nothing outlives the call that refers to it - once
/// the impl keeps nothing. The engine protocol says it keeps nothing: "A
/// `JSValue` parameter is BORROWED for the call" (engine_protocol.zig; recipe
/// 0.4: "to keep it past the call: engine.retainValue"), which is the rule
/// `releaseAnyArgument` already relies on for an operation's arguments.
///
/// Every attribute setter of such a type was read for a keeper (lane
/// setterleak, 2026-10-15: 110 generated setters, all `runtime.JSValue` or
/// `?runtime.JSValue`; no setter takes a union with an `object` arm):
/// - ShadowRoot.adoptedStyleSheets keeps its own hold (engine.retainValue).
/// - ElementInternals' seven ARIA element arrays read the input through
///   engine.typeOf and engine.iterate and keep their own holds of the items
///   (engine.retainValue) and a frozen array of their own.
/// - HTMLElement.hidden converts with engine.convertToDOMString,
///   HTMLInputElement.valueAsDate reads engine.thisTimeValue, and
///   Window.opener asks only isNull - each borrows for the call.
/// - The [Replaceable] setters (Window, WindowOrWorkerGlobalScope and the
///   worker and ShadowRealm global scopes) call engine.defineOwnProperty,
///   which makes a Global of its own (protocol_values.defineOwnProperty,
///   support.ownGlobal).
/// - The [LegacyLenientSetter] setters (Document's fullscreenEnabled,
///   fullscreen and fullscreenElement; ShadowRoot's and
///   DocumentOrShadowRoot's fullscreenElement), Document's
///   adoptedStyleSheets and Element's seven ARIA element arrays do nothing.
/// - The rest are NotImplemented stubs that read nothing: the 2D contexts'
///   fillStyle and strokeStyle, Animation's and AnimationTrigger's ranges,
///   ARIAMixin's arrays, the permission results' devices and scans, DataCue,
///   Global.value, MediaMetadata.artwork, the encoded frames' data,
///   SpeechRecognition.phrases, WaveShaperNode.curve,
///   RemoteDocument.document, CSSColor.channels, SVGPathSegment.values,
///   XRPermissionStatus.granted and DocumentOrShadowRoot.adoptedStyleSheets.
/// So a setter that implements one of these keeps a hold of its own, as an
/// operation does. Kept, each assignment of an object was a Global for the
/// agent's life, and every ElementInternals ARIA array assignment rooted its
/// input iterable for good.
///
/// A callback function and its nullable form are borrowed too, as every
/// callback-function value is (`needsArgCleanup`): the value IS the handle,
/// and the setter that keeps it - an event handler IDL attribute's
/// (EventTarget.setEventHandler), a callback attribute's - takes a hold of
/// its own (engine.takeCallbackFunction), which moves the function out. Every
/// such setter was read for that (lane leaks7, 2026-10-25): the event handler
/// attributes go through dom.event_handlers to setEventHandler, which takes;
/// the other callback attributes (WebGPU's, MediaSession's) are stubs that
/// read nothing.
///
/// An ALLOWLIST: a buffer source, a dictionary or sequence that merely
/// contains an `any`, and every type nobody named answer FALSE - the value
/// stays handed over and, if nothing takes it, leaks, which costs memory and
/// never correctness. A copied type (`argHandleIsCopied`) answers false too:
/// the binding releases it whatever the value.
pub fn setterValueIsBorrowed(comptime T: type) bool {
    return comptime anyHandleIsKeptOnlyAsHandle(T) or isCallbackFunctionShape(T);
}

/// Whether an attribute getter's result of type `T` is a number or a boolean
/// that `setPrimitiveReturn` writes straight into the return slot, with no
/// handle. An allowlist: anything not named here - optionals included, whose
/// null is a value of its own - takes the conversion path, as before.
pub fn primitiveGetterResult(comptime T: type) bool {
    const primitive = [_]type{ u8, u16, u32, i8, i16, i32, u64, i64, f32, f64, bool };
    inline for (primitive) |P| {
        if (T == P) return true;
    }
    return false;
}

/// Set `value` (a `primitiveGetterResult` type) as the callback's return
/// value: the JS value the getter's conversion gives - an integer of up to 32
/// bits as that integer, a 64-bit integer or a float as the double it converts
/// to (`@floatFromInt`, `@floatCast`, as conv.toV8* do), a boolean as itself.
fn setPrimitiveReturn(info: *const v8.FunctionCallbackInfo, comptime T: type, value: T) void {
    switch (T) {
        u8, u16, u32 => v8.FunctionCallbackInfo.v8_FunctionCallbackInfo_SetReturnValueUint32(info, value),
        i8, i16, i32 => v8.FunctionCallbackInfo.v8_FunctionCallbackInfo_SetReturnValueInt32(info, value),
        u64, i64 => v8.FunctionCallbackInfo.v8_FunctionCallbackInfo_SetReturnValueDouble(info, @floatFromInt(value)),
        f32 => v8.FunctionCallbackInfo.v8_FunctionCallbackInfo_SetReturnValueDouble(info, @floatCast(value)),
        f64 => v8.FunctionCallbackInfo.v8_FunctionCallbackInfo_SetReturnValueDouble(info, value),
        bool => v8.FunctionCallbackInfo.v8_FunctionCallbackInfo_SetReturnValueBool(info, value),
        else => @compileError("setPrimitiveReturn: not a primitive getter result: " ++ @typeName(T)),
    }
}

/// Free the text of a JSValue string result an impl handed over owned
/// (`owned` true) - the one arm whose memory is the impl's allocation rather
/// than an engine handle. The same rule as the operation path: every result
/// is the binding's, and a getter that keeps a string returns a reference to
/// it (`JSValue.fromStringRef`), which this leaves alone.
fn freeOwnedString(allocator: std.mem.Allocator, result: runtime.JSValue) void {
    if (result != .string) return;
    var text = result.string;
    text.deinit(allocator);
}

/// Free a string an indexed or named property interceptor's getter returned
/// owned: a DOMString whose arm says `.owned` (DOMTokenList's item() copies
/// its token), or a JSValue string flagged owned. Interned and empty strings,
/// and a JSValue reference, are left alone - the union says whose memory it
/// is. Each interceptor converted the result and dropped it: one leaked copy
/// per `classList[0]` read, where `classList.item(0)` - an operation, which
/// frees its result - leaked nothing.
fn freeOwnedResult(comptime T: type, allocator: std.mem.Allocator, value: T) void {
    if (T == runtime.DOMString) {
        var text = value;
        text.deinit(allocator);
    } else if (T == ?runtime.DOMString) {
        if (value) |present| {
            var text = present;
            text.deinit(allocator);
        }
    } else if (T == runtime.JSValue) {
        freeOwnedString(allocator, value);
    } else if (T == ?runtime.JSValue) {
        if (value) |present| freeOwnedString(allocator, present);
    }
}

/// Types `argHandleIsCopied` names by identity, re-exported so `tests/v8` can
/// name them too.
pub const copied_arg_types = struct {
    pub const BodyInit = @import("typedefs").BodyInit;
};

/// Free a converted BodyInit argument - what `conv.convertBodyInit` allocated,
/// and nothing else.
///
/// Ownership is the conversion's, not the type's, so this is decided here by
/// arm rather than by the structural rules. Those would get the BufferSource
/// arm wrong: a BufferSource is a reference to its object everywhere else
/// (`freeBufferSourceArg` releases its handle), but BodyInit's is a copy (an
/// ArrayBuffer struct and its bytes) so that nothing in the call can detach
/// the buffer under it. Left to the structural rules, every
/// `new Response(bytes)` leaked the copy.
///
/// - `readable_stream`, `blob`, `form_data`, `urlsearch_params`: the Instance
///   a wrapper holds. Not ours.
/// - `buffer_source`: always `.array_buffer`, struct and data both owned.
/// - `usvstring`: an owned buffer, or a literal "" (length 0) never freed.
pub fn freeBodyInitArg(allocator: std.mem.Allocator, arg: copied_arg_types.BodyInit) void {
    switch (arg) {
        .readable_stream => {},
        .xmlhttp_request_body_init => |inner| switch (inner) {
            .blob, .form_data, .urlsearch_params => {},
            .buffer_source => |source| switch (source) {
                .array_buffer => |buffer| {
                    buffer.deinit(allocator);
                    allocator.destroy(buffer);
                },
                // Never produced by convertBodyInit.
                .array_buffer_view => {},
            },
            .usvstring => |text| if (text.len > 0) allocator.free(text),
        },
    }
}

/// Does converting an argument of type `T` yield a NON-OWNING view - memory
/// this engine never allocated and must therefore never free?
///
/// `needsArgCleanup`'s slice rule answers "owned" for *any* slice - a
/// blocklist over an open set, wrong by default in exactly the way AGENTS.md
/// warns about - and a conversion that returns a slice aliasing V8's heap
/// would have it freed: `conv.convertAllowSharedBufferSource` returned
/// `.{ .byte_slice = <the backing store> }`, and `freeConvertedArg` handed
/// the store to `allocator.free` (`panic: Invalid free` on every
/// `new TextDecoder(x).decode(bytes)`, 67 of 149 `encoding/` WPT files).
/// Flipping that default would leak every string argument, so the narrow
/// repair is to name the conversions known not to allocate here, consulted
/// before the structural rules.
///
/// None does today: AllowSharedBufferSource is a reference to its object
/// (`bufferHandleIsKeptInValue`), freed by `freeBufferSourceArg`, and its
/// `.byte_slice` arm - Zig's own bytes, or the empty value null converts to -
/// is never freed there. `grep -n "non-owning" conversions.zig` is how you
/// check that is still true; a new non-owning conversion is named here, or
/// its slice is freed.
pub fn argConversionIsNonOwning(comptime T: type) bool {
    _ = T;
    return false;
}

/// The buffer-source types the ownership rules name, re-exported so
/// `tests/v8` can name them: that test target imports `clock`, `host`,
/// `runtime` and `v8`, but not `webidl`.
pub const non_owning_arg_types = struct {
    pub const AllowSharedBufferSource = webidl.buffer_sources.AllowSharedBufferSource;
    pub const BufferSource = webidl.buffer_sources.BufferSource;
    pub const ArrayBufferView = webidl.buffer_sources.ArrayBufferView;
};

/// `conv.fromV8Value`, releasing the argument handle afterwards when
/// `argHandleIsCopied` can prove that is safe - or, for any other type, when
/// the value it converted to proves nothing refers to the handle
/// (`conversionLeavesHandle`: an `any` or `object` arm with no `.handle`, a
/// buffer source that is none, a null optional, an Opt not passed). For a
/// type whose value says whether it still refers to the handle
/// (`argumentHandleIsKeptInValue`: an `any`, an `object` union arm, a buffer
/// source) the release fires on the error path too, which is where the
/// handle would otherwise be lost silently: a failed conversion made nothing
/// that refers to it.
pub fn convertArgReleasing(
    comptime T: type,
    allocator: std.mem.Allocator,
    isolate: *v8.Isolate,
    context: *v8.Context,
    arg: *v8.Value,
) !T {
    return convertArgReleasingAs(T, .modulo, allocator, isolate, context, arg);
}

/// `convertArgReleasing`, with an integer argument's ConvertToInt branch:
/// [EnforceRange] or [Clamp] (`conv.fromV8ValueInteger`), as codegen's
/// `enforce_range` / `clamp` tables name the argument.
pub fn convertArgReleasingAs(
    comptime T: type,
    comptime integer: conv.IntegerConversion,
    allocator: std.mem.Allocator,
    isolate: *v8.Isolate,
    context: *v8.Context,
    arg: *v8.Value,
) !T {
    return convertArgReleasingWith(T, .{ .integer = integer }, allocator, isolate, context, arg);
}

/// `convertArgReleasing` by the argument's `mode`: its ConvertToInt branch,
/// and - for an interface-typed argument - the interface it converts to
/// (`argumentInterface`; a TypeError unless the value implements it).
pub fn convertArgReleasingWith(
    comptime T: type,
    comptime mode: ArgMode,
    allocator: std.mem.Allocator,
    isolate: *v8.Isolate,
    context: *v8.Context,
    arg: *v8.Value,
) !T {
    if (comptime argHandleIsCopied(T)) {
        defer v8.v8_Value_Dispose(arg);
        return convertArgValue(T, mode, allocator, isolate, context, arg);
    }
    // A conversion that fails adopted nothing: every converter refuses before
    // its value would refer to the handle (a callback function is checked
    // callable, a callback interface's wrapper is made only from an object,
    // an interface is checked implements, a dictionary reads its members
    // through Gets of its own) and frees what it made. So the handle goes,
    // whatever the type - kept, a TypeError left it referred to by nothing:
    // LockManager.request(name, null) leaked one per call
    // (web-locks/acquire.https.any.js, under rejectOnThrow).
    const value = convertArgValue(T, mode, allocator, isolate, context, arg) catch |err| {
        v8.v8_Value_Dispose(arg);
        return err;
    };
    // A value that refers to nothing - an `any`'s primitive, a null optional
    // callback, an optional argument not passed - leaves the handle to the
    // binding (`conversionLeavesHandle`).
    if (conversionLeavesHandle(T, value)) v8.v8_Value_Dispose(arg);
    return value;
}

/// One argument's whole conversion by its `mode` (`convertArgReleasingWith`),
/// then the steps codegen's tables add to it: for a restricted `double` or
/// `float` (`restricted_floats`, `constructor_restricted_floats`) that
/// conversion's last step - NaN and the infinities are a TypeError (WebIDL
/// 3.2.5 step 2, 3.2.7 step 2); for a ByteString (`byte_string_arguments`), a
/// code unit above 0xFF is; for an `object` (`object_arguments`), a value
/// that is not an Object is. Each check is part of this argument's own
/// conversion, so no later argument is converted first, and what the
/// conversion made is freed when it fails.
///
/// Every path that converts an argument goes through here: an operation's,
/// a constructor's (sole or overloaded: overload_resolver.zig), a static
/// operation's and a namespace operation's (namespace.zig). Blink's
/// conversions carry the restriction in the type (NativeValueTraits<IDLDouble>
/// calls ToRestrictedDouble, bindings/core/v8/native_value_traits_impl.h,
/// chromium 23520b2ec9fc); Crane's f64 cannot, so a path that skips this
/// skips the check - as constructors and namespaces did until lane bindfix1
/// (`new CSSUnitValue(NaN, "px")`, `CSS.px(Infinity)`).
pub fn convertArgChecked(
    comptime T: type,
    comptime mode: ArgMode,
    allocator: std.mem.Allocator,
    isolate: *v8.Isolate,
    context: *v8.Context,
    arg: *v8.Value,
) !T {
    var value = try convertArgReleasingWith(T, mode, allocator, isolate, context, arg);
    if (comptime mode.restricted) {
        conv.requireFinite(T, value) catch |err| {
            freeConvertedArg(T, allocator, value);
            return err;
        };
    }
    if (comptime mode.byte_string) {
        conv.encodeByteStringOwned(T, allocator, &value) catch |err| {
            freeConvertedArg(T, allocator, value);
            return err;
        };
    }
    if (comptime mode.object) {
        conv.requireObject(T, value) catch |err| {
            freeConvertedArg(T, allocator, value);
            return err;
        };
    }
    return value;
}

/// One argument's conversion by its `mode`: to the interface it names, or by
/// its integer branch (an interface type has none).
fn convertArgValue(
    comptime T: type,
    comptime mode: ArgMode,
    allocator: std.mem.Allocator,
    isolate: *v8.Isolate,
    context: *v8.Context,
    arg: *v8.Value,
) conv.ConversionError!T {
    if (comptime mode.interface != null) return conv.fromV8ValueAs(T, mode.interface, allocator, isolate, context, arg);
    return conv.fromV8ValueInteger(T, mode.integer, allocator, isolate, context, arg);
}

/// Is `T` a type whose conversion can keep its argument's handle in exactly
/// one place, recoverable from the value - so that the VALUE says whether the
/// handle is still in use (`keptArgumentHandle`)? An ALLOWLIST, as
/// `argHandleIsCopied` is: anything else keeps the conservative answer (keep
/// the handle). Two families, released in different places once the call
/// returns:
///
/// - `anyHandleIsKeptOnlyAsHandle`: an `any`, or a union whose only
///   non-copying arm is `object` - a `.handle` JSValue over the argument's
///   own Global. Released by `releaseAnyArgument`, for an operation's or a
///   constructor's argument.
/// - `bufferHandleIsKeptInValue`: a BufferSource or ArrayBufferView, or a
///   union whose only non-copying arms are buffer sources - a reference to
///   the object (WebIDL 3.2.26), the Global it was converted from. Released
///   with the value itself (`freeConvertedArg`), wherever it sits: an
///   argument, a dictionary member, a sequence element.
///
/// Never true of a type `argHandleIsCopied` accepts - a conversion that copies
/// keeps nothing - so a caller that releases a copied type's handle and also
/// asks this question cannot release it twice. BodyInit is the case that
/// bit: its XMLHttpRequestBodyInit arm holds a BufferSource, but
/// convertBodyInit copies the bytes, and a RequestInit's `body` member was
/// released by the dictionary loop's copied rule AND by this one (every
/// `fetch(url, init)` crashed).
pub fn argumentHandleIsKeptInValue(comptime T: type) bool {
    if (comptime argHandleIsCopied(T)) return false;
    return anyHandleIsKeptOnlyAsHandle(T) or bufferHandleIsKeptInValue(T);
}

/// The argument handle `value` still refers to, if it does, for a `T` that
/// `argumentHandleIsKeptInValue` accepts.
pub fn keptArgumentHandle(comptime T: type, value: T) ?*anyopaque {
    comptime std.debug.assert(argumentHandleIsKeptInValue(T));
    if (comptime anyHandleIsKeptOnlyAsHandle(T)) return anyArgumentHandle(T, value);
    return bufferArgumentHandle(T, value);
}

/// `T` is a `webidl.Opt` wrapper.
fn isOptWrapper(comptime T: type) bool {
    return @typeInfo(T) == .@"struct" and @hasField(T, "value") and @hasField(T, "was_passed");
}

/// The union arm `name` of `T` is a reference to an object: WebIDL's
/// `object`, or a typed array type (3.2.26, "a reference to the same
/// object"). Codegen types both as runtime.JSValue and names the arm for the
/// type - `object`, `uint8clamped_array` - and `conv.fromV8Value`'s union
/// path gives each the argument's own handle. A JSValue arm under another
/// name is not one - CryptoKeyID's and MLNumber's `bigint`.
///
/// The typed array arms joined when their conversion was written
/// (2026-10-04); every impl taking such a union was read for keepers:
/// ImageData takes its own hold of its data (engine.retainValue), and the
/// rest - WebGL's Float32List/Int32List/Uint32List, OrientationSensor's
/// RotationMatrixType - are stubs that keep nothing.
fn isObjectArm(comptime T: type, comptime name: []const u8) bool {
    if (@FieldType(T, name) != runtime.JSValue) return false;
    return std.mem.eql(u8, name, "object") or conv.typedArrayArmName(name) != null;
}

/// Is `T` an `any` - `runtime.JSValue`, nullable, or a `webidl.Opt` of
/// either - or a union whose `object` arm is its only non-copying arm (or a
/// nullable or optional one), so that its conversion can keep its argument's
/// handle in exactly one place: a `.handle` JSValue?
///
/// `conv.fromV8Value`'s JSValue branch makes undefined, null, a boolean or a
/// number into a Zig value, a string into an owned copy (`.string`), and ONLY
/// an object, function or symbol into `.handle` over the very handle it was
/// given ("the argument's own handle ... which the impl borrows for the
/// call"). Its union path gives an `object` arm the same `.handle` (WebIDL
/// 3.2.25: "the IDL value that is a reference to the object V"), and every
/// other arm here copies out (`argHandleIsCopied`). A nullable one converts
/// null and undefined to null; a `webidl.Opt` one converts undefined to "not
/// passed". So for these shapes the value converted says whether the handle
/// is still referred to - ownership read off the conversion, not the type
/// (see `argConversionIsNonOwning`).
///
/// An ALLOWLIST of those shapes: a union whose JSValue arm is NOT named
/// `object`, or a dictionary or sequence that merely contains an `any`, keeps
/// the conservative answer (false: keep the handle).
pub fn anyHandleIsKeptOnlyAsHandle(comptime T: type) bool {
    return comptime blk: {
        if (T == runtime.JSValue) break :blk true;
        const info = @typeInfo(T);
        if (info == .optional) break :blk anyHandleIsKeptOnlyAsHandle(info.optional.child);
        if (isOptWrapper(T)) break :blk anyHandleIsKeptOnlyAsHandle(@FieldType(T, "value"));
        if (info == .@"union" and info.@"union".tag_type != null) {
            var objects = 0;
            for (info.@"union".fields) |field| {
                if (isObjectArm(T, field.name)) {
                    objects += 1;
                } else if (!argHandleIsCopied(field.type)) {
                    break :blk false;
                }
            }
            break :blk objects > 0;
        }
        break :blk false;
    };
}

/// Whether `value`, converted from an argument handle as a `T` that
/// `anyHandleIsKeptOnlyAsHandle` accepts, still refers to that handle: true
/// exactly for a `.handle` JSValue (an `object` arm's included).
pub fn anyConversionKeepsHandle(comptime T: type, value: T) bool {
    return anyArgumentHandle(T, value) != null;
}

/// The argument handle `value` still refers to, if it does: a `.handle`
/// JSValue's, for a `T` that `anyHandleIsKeptOnlyAsHandle` accepts.
pub fn anyArgumentHandle(comptime T: type, value: T) ?*anyopaque {
    comptime std.debug.assert(anyHandleIsKeptOnlyAsHandle(T));
    if (T == runtime.JSValue) return if (value == .handle) value.handle.ptr else null;
    const info = @typeInfo(T);
    if (info == .optional) return if (value) |v| anyArgumentHandle(info.optional.child, v) else null;
    if (comptime isOptWrapper(T)) {
        if (!value.was_passed) return null;
        return anyArgumentHandle(@FieldType(T, "value"), value.value);
    }
    switch (value) {
        inline else => |payload, tag| {
            if (comptime isObjectArm(T, @tagName(tag))) return anyArgumentHandle(runtime.JSValue, payload);
            return null;
        },
    }
}

/// Release an operation's or a constructor's `any` argument - or its
/// `object` union arm - once the call is over: the handle `info.get` made,
/// which a `.handle` still refers to (a primitive's went at conversion,
/// `convertArgReleasing`).
///
/// The argument is BORROWED for the call (AGENTS.md "The engine boundary",
/// rule 3): an impl that keeps it takes a hold of its own first
/// (`engine.retainValue`). Every impl parameter typed `any` was read for
/// that (the hardening lane's audit, 2026-09-30: 422 parameters; the three
/// that kept the argument - IDBKeyRange's factories, XSLTProcessor's
/// setParameter, ShadowRoot's adoptedStyleSheets setter - take their own
/// hold now). Kept, it was one Global per call for the process's life.
/// `object` arms reached the impls only once their conversion was written
/// (2026-10-02): AlgorithmIdentifier's, which SubtleCrypto reads during the
/// call (normalize an algorithm) and never keeps.
///
/// An attribute setter's `any` value is released by its binding once the
/// setter returns (`setterValueIsBorrowed`, whose keepers were read the same
/// way); a dictionary's `any` member with its dictionary (`freeConvertedArg`)
/// and a sequence's `any` element with its sequence (`freeSequenceElement`).
/// A buffer source is released with the value instead, by `freeConvertedArg`.
pub fn releaseAnyArgument(comptime T: type, value: T) void {
    if (comptime !anyHandleIsKeptOnlyAsHandle(T)) return;
    if (anyArgumentHandle(T, value)) |handle| v8.v8_Value_Dispose(@ptrCast(@alignCast(handle)));
}

/// Is `T` a buffer source whose conversion keeps, as the IDL value's
/// reference to its object (WebIDL 3.2.26), the handle it was converted
/// from: BufferSource, AllowSharedBufferSource or ArrayBufferView, nullable
/// or a `webidl.Opt` of one, or a union whose only non-copying arms are
/// buffer sources?
///
/// `conv.convertBufferSource`, `conv.convertAllowSharedBufferSource` and
/// `conv.convertArrayBufferView` return the handle they were given as `js` -
/// no clone, no copy of the bytes - and fail for anything else, keeping
/// nothing. The value says which: a view, an ArrayBuffer or
/// SharedArrayBuffer struct, or null / not passed / a copying union arm /
/// AllowSharedBufferSource's empty `.byte_slice` for null and undefined.
///
/// Such a handle is the VALUE's until it is freed: `freeConvertedArg` releases
/// it, for an argument once the call returns, for a dictionary member or a
/// sequence element with its dictionary or sequence. The impl BORROWS it for
/// the call; one that keeps the object past it takes a hold of its own
/// (`engine.retainValue`). Every impl that took an ArrayBufferView argument
/// was read for that (2026-10-02): the streams' BYOB read, enqueue and
/// respondWithNewView disposed it themselves when the value owned a clone,
/// and now borrow it; the rest (WebGL, RTCDataChannel, PresentationConnection,
/// Crypto) never kept it. No impl received a BufferSource before - its
/// conversion was a TypeError for every value.
pub fn bufferHandleIsKeptInValue(comptime T: type) bool {
    return comptime blk: {
        if (T == webidl.BufferSource or T == webidl.ArrayBufferView or T == webidl.AllowSharedBufferSource) break :blk true;
        // A conversion that copies keeps nothing (BodyInit: convertBodyInit
        // copies its buffer).
        if (argHandleIsCopied(T)) break :blk false;
        const info = @typeInfo(T);
        if (info == .optional) break :blk bufferHandleIsKeptInValue(info.optional.child);
        if (isOptWrapper(T)) break :blk bufferHandleIsKeptInValue(@FieldType(T, "value"));
        if (info == .@"union" and info.@"union".tag_type != null) {
            var buffers = 0;
            for (info.@"union".fields) |field| {
                if (bufferHandleIsKeptInValue(field.type)) {
                    buffers += 1;
                } else if (!argHandleIsCopied(field.type)) {
                    break :blk false;
                }
            }
            break :blk buffers > 0;
        }
        break :blk false;
    };
}

/// The handle `value` refers to as a buffer source, if it does, for a `T`
/// that `bufferHandleIsKeptInValue` accepts.
pub fn bufferArgumentHandle(comptime T: type, value: T) ?*anyopaque {
    comptime std.debug.assert(bufferHandleIsKeptInValue(T));
    if (T == webidl.BufferSource or T == webidl.ArrayBufferView or T == webidl.AllowSharedBufferSource) return value.jsHandle();
    const info = @typeInfo(T);
    if (info == .optional) return if (value) |v| bufferArgumentHandle(info.optional.child, v) else null;
    if (comptime isOptWrapper(T)) {
        if (!value.was_passed) return null;
        return bufferArgumentHandle(@FieldType(T, "value"), value.value);
    }
    switch (value) {
        inline else => |payload| {
            if (comptime bufferHandleIsKeptInValue(@TypeOf(payload))) return bufferArgumentHandle(@TypeOf(payload), payload);
            return null;
        },
    }
}

/// Free a converted buffer source: release the reference it holds (the
/// handle it was converted from, see `bufferHandleIsKeptInValue`) and, for an
/// ArrayBuffer or a SharedArrayBuffer, the struct `conv.convertBufferSource`
/// or `conv.convertAllowSharedBufferSource` allocated for it. A value made in
/// Zig (`js` null) holds no handle; its struct, and a `.byte_slice`'s bytes,
/// are its maker's.
pub fn freeBufferSourceArg(comptime T: type, allocator: std.mem.Allocator, arg: T) void {
    const handle = arg.jsHandle() orelse return;
    v8.v8_Value_Dispose(@ptrCast(@alignCast(handle)));
    if (T == webidl.ArrayBufferView) return;
    switch (arg) {
        inline else => |payload, tag| {
            const name = @tagName(tag);
            if (comptime std.mem.eql(u8, name, "array_buffer") or std.mem.eql(u8, name, "shared_array_buffer")) {
                allocator.destroy(payload);
            }
        },
    }
}

/// WebIDL [LegacyNullToEmptyString] (3.3.23): the arguments of `fn_name` -
/// bit i for argument i, bit 0 for an attribute setter's value - for which
/// JavaScript null converts to "" instead of "null". Codegen writes the table
/// (`legacy_null_to_empty` in a generated interface) from the IDL; an
/// interface without one answers 0 and converts as before.
/// Whether `fn_name` is a promise-returning operation of `Interface`: codegen
/// lists them in `promise_returning` (WebIDL 3.7.6).
pub fn returnsPromise(comptime Interface: type, comptime fn_name: []const u8) bool {
    if (!@hasDecl(Interface, "promise_returning")) return false;
    inline for (Interface.promise_returning) |name| {
        if (comptime std.mem.eql(u8, name, fn_name)) return true;
    }
    return false;
}

/// WebIDL 3.7.6, for an operation whose return type is a promise: its steps -
/// the brand check, argument conversion and the operation itself - run with
/// an exception handler, and an exception becomes a promise rejected with it.
/// `fetch(url, {referrerPolicy: "foo"})` threw where it must reject, and so
/// did every promise-returning API's failed conversion.
fn rejectOnThrow(info: *const v8.FunctionCallbackInfo, comptime body: fn (*const v8.FunctionCallbackInfo) void) void {
    const Thunk = struct {
        fn run(data: ?*anyopaque) callconv(.c) void {
            body(@ptrCast(@alignCast(data.?)));
        }
    };
    const isolate = info.getIsolate();
    var thrown: ?*v8.Value = null;
    if (!v8.v8_RunCatching(isolate, Thunk.run, @ptrCast(@constCast(info)), &thrown)) return;
    const reason = thrown orelse return;
    defer v8.v8_Value_Dispose(reason);
    const context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return;
    defer v8.v8_Context_Dispose(context);
    const resolver = v8.v8_PromiseResolver_New(context) orelse return;
    defer v8.v8_PromiseResolver_Dispose(resolver);
    _ = v8.v8_PromiseResolver_Reject(resolver, context, reason);
    const promise = v8.v8_PromiseResolver_GetPromise(resolver) orelse return;
    defer v8.v8_Promise_Dispose(promise);
    info.setReturnValue(@ptrCast(promise));
}

/// HTML 4.13.6 [CEReactions]: whether `fn_name` runs a custom element
/// reactions bracket - its generated interface lists it in `ce_reactions`.
pub fn runsCEReactions(comptime Interface: type, comptime fn_name: []const u8) bool {
    if (!@hasDecl(Interface, "ce_reactions")) return false;
    inline for (Interface.ce_reactions) |name| {
        if (comptime std.mem.eql(u8, name, fn_name)) return true;
    }
    return false;
}

/// An operation's dispatch - installed for its first overload, which may
/// forward to `<zig_name>__<k>`: whether any function it can run brackets.
pub fn dispatchRunsCEReactions(comptime Interface: type, comptime zig_name: []const u8) bool {
    if (!@hasDecl(Interface, "ce_reactions")) return false;
    inline for (Interface.ce_reactions) |name| {
        if (comptime std.mem.eql(u8, name, zig_name) or std.mem.startsWith(u8, name, zig_name ++ "__")) return true;
    }
    return false;
}

/// Run `body(info)` in a binding catch scope (v8_wrapper.cpp, "Binding catch
/// scopes"): the dispatch of a [CEReactions] member, so what its steps leave
/// pending is held where engine.withPendingExceptionSetAside can set it aside - V8 hands a
/// thrown exception only to a TryCatch made before the throw. Blink's
/// CEReactionsScope holds a v8::TryCatch for its life the same way
/// (third_party/blink/renderer/core/html/custom/ce_reactions_scope.cc). A
/// caught exception is rethrown when the scope ends, so script sees what it
/// would have.
fn inBindingCatchScope(info: *const v8.FunctionCallbackInfo, comptime body: fn (*const v8.FunctionCallbackInfo) void) void {
    const Thunk = struct {
        fn run(data: ?*anyopaque) callconv(.c) void {
            body(@ptrCast(@alignCast(data.?)));
        }
    };
    v8.v8_RunInBindingCatchScope(info.getIsolate(), Thunk.run, @ptrCast(@constCast(info)));
}

/// `function(args)`, in a binding catch scope when its generated interface
/// lists `fn_name` in `ce_reactions` - an interceptor's call of a special
/// setter, which has no FunctionCallbackInfo to scope.
fn callInCatchScopeIfListed(
    comptime Interface: type,
    comptime fn_name: []const u8,
    isolate: *v8.Isolate,
    comptime function: anytype,
    args: anytype,
) @typeInfo(@TypeOf(function)).@"fn".return_type.? {
    const Result = @typeInfo(@TypeOf(function)).@"fn".return_type.?;
    if (comptime !runsCEReactions(Interface, fn_name)) return @call(.auto, function, args);
    const Call = struct {
        args: @TypeOf(args),
        result: Result = undefined,

        fn run(data: ?*anyopaque) callconv(.c) void {
            const self: *@This() = @ptrCast(@alignCast(data.?));
            self.result = @call(.auto, function, self.args);
        }
    };
    var call: Call = .{ .args = args };
    v8.v8_RunInBindingCatchScope(isolate, Call.run, &call);
    return call.result;
}

pub fn legacyNullToEmptyMask(comptime Interface: type, comptime fn_name: []const u8) u32 {
    if (!@hasDecl(Interface, "legacy_null_to_empty")) return 0;
    inline for (Interface.legacy_null_to_empty) |entry| {
        if (comptime std.mem.eql(u8, entry[0], fn_name)) return entry[1];
    }
    return 0;
}

/// WebIDL `double` and `float`, not `unrestricted` (3.2.7, 3.2.9): the
/// arguments of `fn_name` - bit i for argument i, bit 0 for an attribute
/// setter's value - whose NaN and infinities are a TypeError. Codegen writes
/// the table (`restricted_floats` in a generated interface) from the IDL; an
/// interface without one answers 0 and converts as before.
pub fn restrictedFloatMask(comptime Interface: type, comptime fn_name: []const u8) u32 {
    if (!@hasDecl(Interface, "restricted_floats")) return 0;
    inline for (Interface.restricted_floats) |entry| {
        if (comptime std.mem.eql(u8, entry[0], fn_name)) return entry[1];
    }
    return 0;
}

pub fn restrictedBit(comptime mask: u32, comptime index: usize) bool {
    return index < 32 and (mask >> @intCast(index)) & 1 != 0;
}

/// WebIDL [EnforceRange] and [Clamp] (3.3.6, 3.3.3): the arguments of
/// `fn_name` - bit i for argument i, bit 0 for an attribute setter's value -
/// whose integer conversion takes ConvertToInt's step 6 or 7 instead of
/// wrapping. Codegen writes the tables (`enforce_range`, `clamp`) from the
/// IDL; the binding converts with the branch (`conv.fromV8ValueInteger`) on
/// the number itself, before anything wraps - an optional argument left out
/// is not passed, never a TypeError.
pub fn integerConversionMask(comptime Interface: type, comptime fn_name: []const u8, comptime which: conv.IntegerConversion) u32 {
    const table = switch (which) {
        .enforce_range => if (@hasDecl(Interface, "enforce_range")) Interface.enforce_range else return 0,
        .clamp => if (@hasDecl(Interface, "clamp")) Interface.clamp else return 0,
        .modulo => return 0,
    };
    inline for (table) |entry| {
        if (comptime std.mem.eql(u8, entry[0], fn_name)) return entry[1];
    }
    return 0;
}

/// A sole constructor's argument `index`: its ConvertToInt branch, the
/// interface it converts to (`constructorArgumentInterface`), and whether it
/// is a restricted float (`constructorRestrictedFloatMask`).
fn constructorArgMode(comptime Interface: type, comptime index: usize) ArgMode {
    return .{
        .integer = constructorIntegerConversion(Interface, index),
        .interface = constructorArgumentInterface(Interface, "", index),
        .restricted = restrictedBit(constructorRestrictedFloatMask(Interface, ""), index),
    };
}

/// WebIDL `double` and `float`, not `unrestricted` (3.2.5, 3.2.7): the
/// constructor arguments - bit i for argument i - of the ConstructorArgs
/// variant `variant` for an overloaded constructor, of the constructor ("")
/// otherwise, whose NaN and infinities are a TypeError. Codegen writes the
/// table (`constructor_restricted_floats`); an interface without one answers
/// 0 for every variant.
pub fn constructorRestrictedFloatMask(comptime Interface: type, comptime variant: []const u8) u32 {
    if (!@hasDecl(Interface, "constructor_restricted_floats")) return 0;
    return restrictedFloatTableMask(Interface.constructor_restricted_floats, variant);
}

/// The mask a `restricted_floats`-shaped table (`.{ .{ key, mask }, ... }`)
/// gives `key`, or 0.
pub fn restrictedFloatTableMask(comptime table: anytype, comptime key: []const u8) u32 {
    inline for (table) |entry| {
        if (comptime std.mem.eql(u8, entry[0], key)) return entry[1];
    }
    return 0;
}

/// The constructor's [EnforceRange] and [Clamp] arguments (codegen's
/// `constructor_enforce_range` / `constructor_clamp` masks).
fn constructorIntegerConversion(comptime Interface: type, comptime index: usize) conv.IntegerConversion {
    if (@hasDecl(Interface, "constructor_enforce_range") and restrictedBit(Interface.constructor_enforce_range, index)) return .enforce_range;
    if (@hasDecl(Interface, "constructor_clamp") and restrictedBit(Interface.constructor_clamp, index)) return .clamp;
    return .modulo;
}

/// WebIDL ByteString (3.2.11): the arguments of `fn_name` - bit i for
/// argument i, bit 0 for an attribute setter's value - whose code units above
/// 0xFF are a TypeError. ByteString and USVString are both `[]const u8`, so
/// codegen writes the table (`byte_string_arguments` in a generated
/// interface) from the IDL; an interface without one answers 0.
/// WebIDL 3.2.14 object: the arguments of `fn_name` - bit i for argument i -
/// that must be an Object, from codegen's `object_arguments` (`object` and
/// `any` are both runtime.JSValue); an interface without one answers 0.
pub fn objectMask(comptime Interface: type, comptime fn_name: []const u8) u32 {
    if (!@hasDecl(Interface, "object_arguments")) return 0;
    inline for (Interface.object_arguments) |entry| {
        if (comptime std.mem.eql(u8, entry[0], fn_name)) return entry[1];
    }
    return 0;
}

pub fn byteStringMask(comptime Interface: type, comptime fn_name: []const u8) u32 {
    if (!@hasDecl(Interface, "byte_string_arguments")) return 0;
    inline for (Interface.byte_string_arguments) |entry| {
        if (comptime std.mem.eql(u8, entry[0], fn_name)) return entry[1];
    }
    return 0;
}

/// WebIDL 3.2.15 interface types: the interface argument `index` of
/// `fn_name` converts to - for an attribute setter, its value is argument 0 -
/// from codegen's `interface_arguments` table (a nullable, optional or
/// sequence argument by its elements' interface), or null for an argument of
/// no interface type. Every interface type is `*runtime.Instance` in Zig, so
/// the table is the only place the binding can learn which interface a value
/// must implement; converting an interface-typed argument without one is a
/// compile error (`conv.fromV8ValueAs`).
pub fn argumentInterface(comptime Interface: type, comptime fn_name: []const u8, comptime index: usize) ?type {
    comptime {
        @setEvalBranchQuota(1_000_000);
        if (!@hasDecl(Interface, "interface_arguments")) return null;
        for (Interface.interface_arguments) |entry| {
            if (entry[1] == index and std.mem.eql(u8, entry[0], fn_name)) return conv.interfaceNamed(entry[2]);
        }
        return null;
    }
}

/// `argumentInterface` for a constructor's argument `index`: of the
/// ConstructorArgs variant `variant` for an overloaded constructor, of the
/// constructor ("") otherwise (`constructor_interface_arguments`).
pub fn constructorArgumentInterface(comptime Interface: type, comptime variant: []const u8, comptime index: usize) ?type {
    comptime {
        @setEvalBranchQuota(100_000);
        if (!@hasDecl(Interface, "constructor_interface_arguments")) return null;
        for (Interface.constructor_interface_arguments) |entry| {
            if (entry[1] == index and std.mem.eql(u8, entry[0], variant)) return conv.interfaceNamed(entry[2]);
        }
        return null;
    }
}

/// Per-argument conversion steps codegen's tables add to an operation's
/// arguments: the restricted float check, the ByteString check, the integer
/// branch, and the interface an interface-typed argument converts to.
pub const ArgModes = struct {
    restricted: u32 = 0,
    byte_string: u32 = 0,
    object: u32 = 0,
    enforce_range: u32 = 0,
    clamp: u32 = 0,
    /// The interface whose `interface_arguments` name each argument's
    /// interface (`argumentInterface`), and the function they are listed
    /// under; `void` for none.
    Interface: type = void,
    fn_name: []const u8 = "",
};

/// One argument's: whether it is a restricted float or a ByteString, its
/// ConvertToInt branch, and the interface it converts to.
pub const ArgMode = struct {
    restricted: bool = false,
    byte_string: bool = false,
    object: bool = false,
    integer: conv.IntegerConversion = .modulo,
    interface: ?type = null,
};

fn argModesOf(comptime Interface: type, comptime fn_name: []const u8) ArgModes {
    return .{
        .restricted = restrictedFloatMask(Interface, fn_name),
        .byte_string = byteStringMask(Interface, fn_name),
        .object = objectMask(Interface, fn_name),
        .enforce_range = integerConversionMask(Interface, fn_name, .enforce_range),
        .clamp = integerConversionMask(Interface, fn_name, .clamp),
        .Interface = Interface,
        .fn_name = fn_name,
    };
}

fn argMode(comptime modes: ArgModes, comptime index: usize) ArgMode {
    return .{
        .restricted = restrictedBit(modes.restricted, index),
        .byte_string = restrictedBit(modes.byte_string, index),
        .object = restrictedBit(modes.object, index),
        .integer = if (restrictedBit(modes.enforce_range, index)) .enforce_range else if (restrictedBit(modes.clamp, index)) .clamp else .modulo,
        .interface = if (modes.Interface == void) null else argumentInterface(modes.Interface, modes.fn_name, index),
    };
}

/// `value` itself, or - when it is null and [LegacyNullToEmptyString] applies -
/// a new empty string in its place. The argument handles here are owned
/// (`v8_FunctionCallbackInfo_GetArgument` allocates), so the replaced handle is
/// disposed and the caller owns the substitute exactly as it owned `value`.
fn nullToEmptyString(isolate: *v8.Isolate, value: *v8.Value) *v8.Value {
    if (!v8.v8_Value_IsNull(value)) return value;
    const empty = v8.v8_String_NewFromUtf8(isolate, "", 0) orelse return value;
    v8.v8_Value_Dispose(value);
    return @ptrCast(empty);
}

/// A FunctionCallbackInfo whose `get` applies [LegacyNullToEmptyString] to the
/// arguments `mask` names, so every arity of `callMethodWithArgs` converts
/// through one place.
fn ArgView(comptime mask: u32) type {
    return struct {
        raw: *const v8.FunctionCallbackInfo,
        isolate: *v8.Isolate,

        pub inline fn length(self: @This()) c_int {
            return self.raw.length();
        }

        pub inline fn get(self: @This(), index: c_int) *v8.Value {
            const value = self.raw.get(index);
            if (comptime mask == 0) return value;
            if (index >= 32 or (mask >> @intCast(index)) & 1 == 0) return value;
            return nullToEmptyString(self.isolate, value);
        }
    };
}

/// Throw the WebIDL error an impl's member returned, in the member's own
/// realm (`member_context`, the current realm) - a SecurityError too: a
/// member's own steps throw it there (document.open's origin check, as
/// html/webappapis/dynamic-markup-insertion/opening-the-input-stream/
/// bailout-exception-vs-return-origin.sub.window.js expects of
/// `iframe.contentDocument.open()`). The cross-origin checks of the
/// WindowProxy and Location are V8's [cross_origin_objects]: their
/// SecurityError is the caller's, made by the access check's interceptors
/// (cross_origin.zig) before any member runs. This used to make every
/// SecurityError in the entered realm, for the checks impls made then.
///
/// ExceptionPending is not an error to make: the member's steps ran script
/// that threw (an iterator, a toString, a callback) and the engine has that
/// exception pending (engine.Error: "return without throwing another"). It
/// throws nothing, so script catches its own object. Thrown over, it became
/// `Error("ExceptionPending")` - an attribute setter's catch called this
/// where an operation's caught it first (review-codex-aria D7).
fn throwMemberError(isolate: *v8.Isolate, member_context: *v8.Context, err: anyerror) void {
    if (err == error.ExceptionPending) return;
    if (comptime engine_capabilities.cross_origin_objects == .unsupported) {
        if (err == error.SecurityError) {
            if (v8.v8_Isolate_GetEnteredOrMicrotaskContext(isolate)) |entered| {
                // Owned: a fresh Global<Context>, used only to pick the realm.
                defer v8.v8_Context_Dispose(entered);
                conv.throwWebIDLErrorFromContext(isolate, entered, @errorName(err));
                return;
            }
        }
    }
    conv.throwWebIDLErrorFromContext(isolate, member_context, @errorName(err));
}

// ============================================================================
// Argument cleanup: what a converted argument, dictionary member or
// sequence element holds once its call is over
// ============================================================================

/// Check if a type is a webidl.Opt wrapper (has wasPassed method and value field)
pub fn isOptionalWrapper(comptime T: type) bool {
    if (@typeInfo(T) != .@"struct") return false;
    // Check for the wasPassed method and value field that webidl.Optional has
    return @hasDecl(T, "wasPassed") and @hasField(T, "value") and @hasField(T, "was_passed");
}

/// Get the inner value type from an Optional wrapper
pub fn getOptionalValueType(comptime T: type) ?type {
    if (@typeInfo(T) != .@"struct") return null;
    if (!@hasField(T, "value")) return null;
    const fields = std.meta.fields(T);
    inline for (fields) |field| {
        if (comptime std.mem.eql(u8, field.name, "value")) {
            return field.type;
        }
    }
    return null;
}

/// Check if a converted argument type needs to be freed after use.
/// String types ([]const u8 and DOMString) need cleanup as they're allocated by fromV8String.
/// JSValue types may contain owned strings that need cleanup.
/// CallbackWrapper types are the call's: released once it returns.
/// Struct types (dictionaries) may contain string fields that need cleanup.
pub fn needsArgCleanup(comptime T: type) bool {
    @setEvalBranchQuota(10000);
    // Non-owning views alias memory this engine did not allocate. This
    // must come first: the union arm that holds the view IS a
    // `[]const u8`, so every rule below would claim it. See
    // `argConversionIsNonOwning`.
    if (argConversionIsNonOwning(T)) return false;
    // BodyInit: freed by arm, as its conversion allocated it - before
    // the union rule below, which would take its copied BufferSource
    // arm for a reference (`freeBodyInitArg`).
    if (T == copied_arg_types.BodyInit) return true;
    // A buffer source holds the handle it refers to, and an
    // ArrayBuffer or SharedArrayBuffer the struct made for it
    // (`freeBufferSourceArg`) - before the union rule below, which would
    // take AllowSharedBufferSource's `.byte_slice` arm for an owned slice.
    if (T == webidl.BufferSource or T == webidl.ArrayBufferView or T == webidl.AllowSharedBufferSource) return true;
    // Raw string slice - allocated by fromV8Value
    if (T == []const u8) return true;
    // DOMString - allocated by fromV8String
    if (T == runtime.DOMString) return true;
    // JSValue may contain owned strings
    if (T == runtime.JSValue) return true;
    // CallbackWrapper - the call's; a method that keeps the callback
    // (addEventListener) takes its own CallbackInterface first.
    if (T == *runtime.CallbackWrapper) return true;
    // A callback function (codegen's function-pointer type) - the Global
    // its conversion made, BORROWED for the call as a CallbackWrapper is: an
    // impl that keeps the callback takes a hold of its own
    // (engine.takeCallbackFunction), and the binding frees this one with the
    // value - an argument, a dictionary member, a union arm, a sequence
    // element. Before, the take adopted it and the binding freed nothing, so
    // every impl that never took its callback kept it for the agent's life:
    // `new ResizeObserver(fn)`, `canvas.toBlob(fn)`, `new Observable(fn)`
    // (lane leaks7).
    if (isCallbackFunctionType(T)) return true;
    // Generic slice types (sequences) - allocated by fromV8Sequence
    // This handles []const JSValue, []const DOMString, etc.
    if (@typeInfo(T) == .pointer) {
        const ptr_info = @typeInfo(T).pointer;
        if (ptr_info.size == .slice) {
            // All slices from fromV8Sequence are allocated and need cleanup
            return true;
        }
    }
    // Zig optional variants
    if (@typeInfo(T) == .optional) {
        const Child = @typeInfo(T).optional.child;
        if (Child == []const u8) return true;
        if (Child == runtime.DOMString) return true;
        if (Child == runtime.JSValue) return true;
        if (Child == *runtime.CallbackWrapper) return true;
        // Recurse for nested optionals or other wrapper types
        if (needsArgCleanup(Child)) return true;
    }
    // webidl.Opt wrapper types - check if inner type needs cleanup
    if (isOptionalWrapper(T)) {
        if (getOptionalValueType(T)) |vt| {
            return needsArgCleanup(vt);
        }
    }
    // Struct types (dictionaries) - check if any field needs cleanup
    if (@typeInfo(T) == .@"struct") {
        inline for (std.meta.fields(T)) |field| {
            if (needsArgCleanup(field.type)) return true;
        }
    }
    // Union types (WebIDL union types) - check if any variant needs cleanup
    if (@typeInfo(T) == .@"union") {
        inline for (std.meta.fields(T)) |field| {
            if (needsArgCleanup(field.type)) return true;
        }
    }
    return false;
}

/// Static empty slice used by fromV8Value for empty strings - must not be freed
const static_empty_u8: []const u8 = &[_]u8{};

/// Free a converted argument if it was allocated.
/// Empty strings return a static slice that must NOT be freed.
pub fn freeConvertedArg(comptime T: type, allocator: std.mem.Allocator, arg: T) void {
    if (comptime !needsArgCleanup(T)) return;
    if (T == copied_arg_types.BodyInit) return freeBodyInitArg(allocator, arg);
    if (T == webidl.BufferSource or T == webidl.ArrayBufferView or T == webidl.AllowSharedBufferSource) return freeBufferSourceArg(T, allocator, arg);

    if (T == []const u8) {
        // Only free if it's not the static empty slice and has content
        if (arg.len > 0 and arg.ptr != static_empty_u8.ptr) {
            allocator.free(arg);
        }
    } else if (@typeInfo(T) == .pointer and @typeInfo(T).pointer.size == .slice) {
        // Generic slice types (sequences) - allocated by fromV8Sequence
        // First free each element if needed, then free the slice itself
        const ElemType = @typeInfo(T).pointer.child;
        if (comptime needsArgCleanup(ElemType) or anyHandleIsKeptOnlyAsHandle(ElemType)) {
            for (arg) |elem| freeSequenceElement(ElemType, allocator, elem);
        }
        // Free the slice itself (cast away const for freeing)
        if (arg.len > 0) {
            const mutable_ptr: [*]ElemType = @constCast(arg.ptr);
            allocator.free(mutable_ptr[0..arg.len]);
        }
    } else if (T == runtime.DOMString) {
        // DOMString is a tagged union - only free if owned
        switch (arg) {
            .owned => |s| if (s.len > 0) allocator.free(s),
            .empty, .interned => {}, // Static, don't free
        }
    } else if (T == runtime.JSValue) {
        // JSValue may contain an owned string that needs cleanup
        switch (arg) {
            .string => |str| {
                if (str.owned and str.data.len > 0) {
                    allocator.free(str.data);
                }
            },
            else => {}, // Other variants don't need cleanup here
        }
    } else if (T == *runtime.CallbackWrapper) {
        // A callback interface argument is the call's, like every
        // argument: the impl borrowed it, and one that keeps the
        // callback (addEventListener) took a CallbackInterface of its
        // own. Its wrapper goes now.
        conv.releaseCallbackWrapper(arg);
    } else if (comptime isCallbackFunctionType(T)) {
        // A callback function is the call's too: the value IS the Global
        // its conversion made (conv.fromV8Value's function-pointer branch,
        // untagged). An impl that keeps the callback took a hold of its own,
        // which moved the function out and left this Global empty
        // (engine.takeCallbackFunction); either way it goes now - an emptied
        // one without the general dispose's registry lookups.
        v8.v8_Global_DisposeCallbackValue(callbackFunctionGlobal(T, arg));
    } else if (@typeInfo(T) == .optional) {
        // Handle all optional types by recursively freeing the inner value
        if (arg) |val| {
            const Child = @typeInfo(T).optional.child;
            freeConvertedArg(Child, allocator, val);
        }
    } else if (comptime isOptionalWrapper(T)) {
        // webidl.Opt wrapper - free inner value if it was passed
        if (arg.was_passed) {
            if (comptime getOptionalValueType(T)) |vt| {
                freeConvertedArg(vt, allocator, arg.value);
            }
        }
    } else if (@typeInfo(T) == .@"struct") {
        // Struct types (dictionaries) - free any fields that need
        // cleanup, and release each `any`-family member's handle (an
        // `any` or `object` member, a union typed JSValue, an
        // `object` union arm): the Get handle the dictionary loop
        // kept as the member's `.handle`, BORROWED for the call as
        // an `any` argument's is (releaseAnyArgument). An impl that
        // keeps a member takes a hold of its own; every keeper was
        // read for that (2026-10-02, 108 dictionaries with a JSValue
        // member): the events take holds, Navigation retains or
        // serializes, PopStateEvent now holds its state. Kept, an
        // object `detail` held its realm for the process's life
        // (realms3: a removed frame kept alive by a dropped
        // CustomEvent). A sequence<any> member's elements go with
        // the sequence (`freeSequenceElement`).
        inline for (std.meta.fields(T)) |field| {
            if (comptime needsArgCleanup(field.type)) {
                freeConvertedArg(field.type, allocator, @field(arg, field.name));
            }
            releaseAnyArgument(field.type, @field(arg, field.name));
        }
    } else if (@typeInfo(T) == .@"union") {
        // Union types (WebIDL union types) - free the active variant if it needs cleanup
        const union_info = @typeInfo(T).@"union";
        if (union_info.tag_type) |_| {
            // Tagged union - we can switch on it
            switch (arg) {
                inline else => |val| {
                    // Zig 0.16 removed std.meta.TagPayloadByName; inside an
                    // `inline else` prong the capture already has the payload type.
                    const FieldType = @TypeOf(val);
                    if (comptime needsArgCleanup(FieldType)) {
                        freeConvertedArg(FieldType, allocator, val);
                    }
                },
            }
        }
        // Untagged unions cannot be safely freed (we don't know which variant is active)
    }
}

/// A sequence's element, once its sequence is freed - by `freeConvertedArg`
/// with the sequence, or by a sequence conversion that failed part-way: what
/// its conversion allocated, and, for an `any` element (or an `object` arm),
/// the Get handle it still refers to (`releaseAnyArgument`).
///
/// The element is BORROWED for the call, as an `any` argument is (engine
/// protocol rule 3): an impl that keeps one takes a hold of its own. Every
/// impl that reads a sequence<any> or sequence<object> was read for that
/// (binding3, 2026-10-16). Variadic `any...` arguments were already released
/// one by one (`freeArgument`); the rest are dictionary members, and only
/// StructuredSerializeOptions.transfer has readers - structuredClone and the
/// postMessage steps of Window, MessagePort, Worker and
/// DedicatedWorkerGlobalScope - which hand it to
/// `engine.structuredSerializeWithTransfer`, whose walk takes Globals of its
/// own. The other 25 dictionaries with such a member (WebGPU, WebNN, the
/// WebCodecs inits, Bluetooth, Protected Audience, MediaTrackCapabilities)
/// have no impl that reads it. Kept, each transferred object's handle was
/// a 16 B Global per call, rooting the object for the agent's life.
pub fn freeSequenceElement(comptime T: type, allocator: std.mem.Allocator, element: T) void {
    freeConvertedArg(T, allocator, element);
    releaseAnyArgument(T, element);
}

/// An operation's or constructor's argument, once the call is over:
/// what its conversion allocated (`freeConvertedArg`) and, for an
/// `any`, the handle it still refers to (`releaseAnyArgument`).
pub fn freeArgument(comptime T: type, allocator: std.mem.Allocator, arg: T) void {
    freeConvertedArg(T, allocator, arg);
    releaseAnyArgument(T, arg);
}

/// The private key marking a function as an interface object
/// `materializeInterfaceObject` has set up in its realm.
const materialized_interface_object_key = "crane:interface-object";

/// Whether `constructor` is an interface object already set up: marked by
/// `markMaterializedInterfaceObject`. Needs an entered context.
fn isMaterializedInterfaceObject(constructor: *v8.Function) bool {
    const marker = v8.v8_Object_GetPrivateRef(@ptrCast(constructor), materialized_interface_object_key.ptr, materialized_interface_object_key.len) orelse return false;
    v8.v8_Value_Dispose(marker);
    return true;
}

/// Mark `constructor` as set up - a private property, invisible to script,
/// whose value is the function itself (an edge to itself, nothing kept).
fn markMaterializedInterfaceObject(constructor: *v8.Function) void {
    v8.v8_Object_SetPrivateRef(@ptrCast(constructor), materialized_interface_object_key.ptr, materialized_interface_object_key.len, @ptrCast(constructor));
}

/// Whether `context`'s realm's environment settings object is a secure
/// context (HTML 8.1.3.5; ContextData.secure_context, from the realm's
/// options). A context with no realm record answers true: it exposes
/// everything, as every realm did before the flag.
pub fn realmIsSecureContext(context: *v8.Context) bool {
    const realm = @import("context_manager.zig").get(context) orelse return true;
    return realm.secure_context;
}

/// Only codegen's scalar ByteString results use byte-to-code-unit
/// conversion. With no table (or no entry), the existing conversion stays.
pub fn returnsByteString(comptime Interface: type, comptime name: []const u8) bool {
    if (!@hasDecl(Interface, "byte_string_returns")) return false;
    inline for (Interface.byte_string_returns) |member| {
        if (comptime std.mem.eql(u8, member, name)) return true;
    }
    return false;
}

pub fn realmExposureScope(context: *v8.Context) webidl.helpers.GlobalScope {
    const entry = @import("context_manager.zig").getEntry(context) orelse return .Window;
    return entry.exposure_scope;
}

fn exposureOverrides(comptime Interface: type, comptime static: bool) type {
    return struct {
        const name = if (static) "exposed_static_members" else "exposed_members";
        const entries = if (@hasDecl(Interface.Meta, name)) @field(Interface.Meta, name) else .{};
    };
}

pub fn hasExposureOverride(comptime Interface: type, comptime name: []const u8, comptime static: bool) bool {
    @setEvalBranchQuota(100_000);
    inline for (exposureOverrides(Interface, static).entries) |entry| {
        if (comptime std.mem.eql(u8, entry[0], name)) return true;
    }
    return false;
}

/// Only these interfaces need work after a wrapper is instantiated. Keep
/// the predicate metadata-only so the dispatcher compiles out every other
/// interface before instantiating its binding.
pub fn hasConditionalUnforgeables(comptime Interface: type) bool {
    @setEvalBranchQuota(1_000_000);
    if (@hasDecl(Interface.Meta, "unforgeable_members")) {
        inline for (Interface.Meta.unforgeable_members) |member| {
            if (comptime hasExposureOverride(Interface, member, false)) return true;
        }
    }
    if (@hasDecl(Interface.Meta, "ParentInterface")) return hasConditionalUnforgeables(Interface.Meta.ParentInterface);
    return false;
}

/// WebIDL "exposed": a member defaults to its interface's exposure. A
/// partial/mixin override is intersected with the host interface's set.
pub fn memberIsExposed(comptime Interface: type, comptime name: []const u8, comptime static: bool, scope: webidl.helpers.GlobalScope) bool {
    if (!interfaceIsExposedInScope(Interface, scope)) return false;
    inline for (exposureOverrides(Interface, static).entries) |entry| {
        if (comptime std.mem.eql(u8, entry[0], name)) {
            inline for (entry[1]) |global| {
                if (comptime std.mem.eql(u8, global, "*")) return true;
                if (scope.matchesExposure(global)) return true;
            }
            return false;
        }
    }
    return true;
}

/// The existing exposure helper consumes heterogeneous comptime metadata.
/// Resolve each scope at comptime, then choose its result for this realm.
pub fn interfaceIsExposedInScope(comptime Interface: type, scope: webidl.helpers.GlobalScope) bool {
    return switch (scope) {
        inline else => |current| comptime webidl.helpers.isExposedIn(Interface, current),
    };
}

fn hideUnexposedMembers(comptime Interface: type, comptime static: bool, isolate: *v8.Isolate, context: *v8.Context, object: *v8.Object) void {
    inline for (exposureOverrides(Interface, static).entries) |entry| {
        if (!memberIsExposed(Interface, entry[0], static, realmExposureScope(context))) {
            hideNames(isolate, context, object, .{entry[0]});
        }
    }
}

/// Delete each of `names` from `object`: WebIDL 3.3.13, the [SecureContext]
/// constructs a realm that is not a secure context does not expose.
pub fn hideNames(isolate: *v8.Isolate, context: *v8.Context, object: *v8.Object, comptime names: anytype) void {
    inline for (names) |name| {
        if (v8.v8_String_NewFromUtf8(isolate, name.ptr, @intCast(name.len))) |key| {
            defer v8.v8_String_Dispose(key);
            _ = v8.v8_Object_Delete(object, context, @ptrCast(key));
        }
    }
}

/// Whether `Interface` declares `name` as `fn (*runtime.Instance, u32)`: an
/// indexed property getter's shape (WebIDL 2.5.6.1).
fn takesIndex(comptime Interface: type, comptime name: []const u8) bool {
    if (!@hasDecl(Interface, name)) return false;
    const info = @typeInfo(@TypeOf(@field(Interface, name)));
    if (info != .@"fn") return false;
    const params = info.@"fn".params;
    if (params.len != 2) return false;
    return (params[1].type orelse return false) == u32;
}

/// What the binding installs for an interface's special operations (WebIDL
/// 2.5.6, 3.9 legacy platform objects): the generated functions codegen's
/// `Meta.special_operations` (webidl.SpecialOperations) names - each only
/// when its impl implements it - and the extended attributes that change its
/// named properties. Never a function guessed from its name: Storage's
/// `getter DOMString? getItem(DOMString key)` is `call_getItem`,
/// SVGNumberList's indexed `getItem(unsigned long)` too, and NamedNodeMap's
/// regular `setNamedItem(Attr)` is no setter at all.
pub const SpecialBinding = struct {
    indexed_getter: ?[]const u8 = null,
    indexed_setter: ?[]const u8 = null,
    named_getter: ?[]const u8 = null,
    named_setter: ?[]const u8 = null,
    named_deleter: ?[]const u8 = null,
    /// The per-name query (webidl.SpecialOperations.supported_property_name):
    /// `isSupportedPropertyName`, when the named getter is bound and its impl
    /// declares one. Null - the default - searches the supported property
    /// names' list instead.
    supported_property_name: ?[]const u8 = null,
    legacy_override_built_ins: bool = false,
    legacy_unenumerable_named_properties: bool = false,
    /// [[OwnPropertyKeys]] (3.9.6) step 3 lists the visible named
    /// properties (webidl.SpecialOperations.named_properties_in_own_keys).
    /// The default is the spec's; false only where codegen records that
    /// every browser leaves them out (HTMLFormElement). Named lookup is the
    /// same either way: it asks the supported property names, never the key
    /// list.
    named_properties_in_own_keys: bool = true,
    /// The named getter and setter stand in for CSSOM's camel-cased
    /// attributes (webidl.SpecialOperations.crane_css_properties).
    crane_css_properties: bool = false,
};

const SpecialShape = enum { index, index_value, name, name_value };

/// The function `op` (a ?webidl.special_operations.Operation) names, when
/// the impl implements it; a compile error when the generated interface
/// does not declare it with `shape`'s parameters - the codegen's contract.
fn boundSpecialOperation(comptime Interface: type, comptime op: anytype, comptime shape: SpecialShape) ?[]const u8 {
    const o = op orelse return null;
    if (!o.implemented) return null;
    if (!@hasDecl(Interface, o.function))
        @compileError(@typeName(Interface) ++ ": Meta.special_operations names " ++ o.function ++ ", which the generated interface does not declare");
    const params = @typeInfo(@TypeOf(@field(Interface, o.function))).@"fn".params;
    const key: type = switch (shape) {
        .index, .index_value => u32,
        .name, .name_value => runtime.DOMString,
    };
    const arity: usize = switch (shape) {
        .index, .name => 2,
        .index_value, .name_value => 3,
    };
    if (params.len != arity or params[0].type != *runtime.Instance or params[1].type != key)
        @compileError(@typeName(Interface) ++ "." ++ o.function ++ " is not a special operation of the shape Meta.special_operations says");
    return o.function;
}

/// `Interface`'s special operations as the binding installs them. A [Global]
/// interface's named properties are its named properties object's (WebIDL
/// 3.7.4, HTML's WindowProperties), not the global object's own, so it has
/// none here. A named getter comes with the generated
/// `getSupportedPropertyNames`, its supported property names (2.5.6.2).
pub fn specialBinding(comptime Interface: type) SpecialBinding {
    comptime {
        const Meta = Interface.Meta;
        if (!@hasDecl(Meta, "special_operations")) return .{};
        const ops = Meta.special_operations;
        var binding: SpecialBinding = .{};
        binding.indexed_getter = boundSpecialOperation(Interface, ops.indexed_getter, .index);
        if (binding.indexed_getter != null) binding.indexed_setter = boundSpecialOperation(Interface, ops.indexed_setter, .index_value);
        if (!isGlobalInterface(Meta)) {
            binding.named_getter = boundSpecialOperation(Interface, ops.named_getter, .name);
            if (binding.named_getter != null) {
                if (!@hasDecl(Interface, "getSupportedPropertyNames"))
                    @compileError(@typeName(Interface) ++ " has a named getter and no getSupportedPropertyNames");
                binding.named_setter = boundSpecialOperation(Interface, ops.named_setter, .name_value);
                binding.named_deleter = boundSpecialOperation(Interface, ops.named_deleter, .name);
                binding.supported_property_name = boundSpecialOperation(Interface, ops.supported_property_name, .name);
                binding.legacy_override_built_ins = ops.legacy_override_built_ins;
                binding.legacy_unenumerable_named_properties = ops.legacy_unenumerable_named_properties;
                binding.named_properties_in_own_keys = ops.named_properties_in_own_keys;
                binding.crane_css_properties = ops.crane_css_properties;
            }
        }
        return binding;
    }
}

/// Whether `Meta`'s interface is declared [Global] (WebIDL 3.4.8).
fn isGlobalInterface(comptime Meta: type) bool {
    if (!@hasDecl(Meta, "extended_attributes")) return false;
    for (Meta.extended_attributes) |attr| {
        if (@hasField(@TypeOf(attr), "name") and std.mem.eql(u8, attr.name, "Global")) return true;
    }
    return false;
}

pub fn V8Interface(comptime Interface: type) type {
    // Validate interface type at compile time
    const iface_info = @typeInfo(Interface);
    if (iface_info != .@"struct") {
        @compileError("V8Interface requires a struct type, got: " ++ @typeName(Interface));
    }

    // Check for required Meta and State
    if (!@hasDecl(Interface, "Meta")) {
        @compileError("Interface must have Meta declaration: " ++ @typeName(Interface));
    }
    if (!@hasDecl(Interface, "State")) {
        @compileError("Interface must have State declaration: " ++ @typeName(Interface));
    }

    const Meta = Interface.Meta;
    const interface_name = Meta.name;

    // WebIDL 2.5.6: the special operations, from codegen's table
    // (specialBinding). The indexed getter is `call_item` for `getter T?
    // item(unsigned long index)`, `call_getItem` for SVGNumberList's, and an
    // anonymous one's `call_getter` - installed only once its impl implements
    // it (DataTransferItemList, TextTrackList yes; AudioTrackList and most
    // others not yet).
    const special = comptime specialBinding(Interface);
    const indexed_getter_name: ?[]const u8 = special.indexed_getter;
    const has_indexed_getter = indexed_getter_name != null;
    // A getter that answers null past the end (`item`) says itself which
    // indices are supported; one that answers a value or throws (an
    // anonymous getter: IndexSizeError; SVGNumberList's getItem;
    // CSSStyleDeclaration's item, "" past the end) is asked only for a
    // supported property index - those below `length` (3.9.1 step 1.2).
    const indexed_getter_checks_length = comptime has_indexed_getter and @hasDecl(Interface, "get_length") and
        @typeInfo(@typeInfo(@typeInfo(@TypeOf(@field(Interface, indexed_getter_name.?))).@"fn".return_type.?).error_union.payload) != .optional;
    const has_indexed_setter = comptime special.indexed_setter != null;
    const has_named_getter = comptime special.named_getter != null;
    const has_named_setter = comptime special.named_setter != null;
    const has_named_deleter = comptime special.named_deleter != null;
    // An interface with named properties and no indexed ones (none declared:
    // HTMLAllCollection's unimplemented anonymous getter is still its
    // indexed one) takes an array index as a name (WebIDL 3.9 knows only
    // String keys; V8 routes an index to the indexed interceptors).
    const forwards_indices = comptime has_named_getter and
        (!@hasDecl(Meta, "special_operations") or Meta.special_operations.indexed_getter == null);

    // WebIDL 2.5.9: one type parameter is a value iterator, two a pair
    // iterator. Codegen's Meta.iterable carries a null key type for the first.
    // A value iterator's members are the realm's Array.prototype functions
    // (3.7.9 step 1, installed on the prototype template); a pair iterator's
    // are this binding's own callbacks (step 2, setUpPrototype).
    const has_value_iterator = comptime @hasDecl(Meta, "iterable") and
        @TypeOf(Meta.iterable.key_type) == @TypeOf(null);
    const has_pair_iterator = comptime @hasDecl(Meta, "iterable") and !has_value_iterator;
    // WebIDL 2.5.12: a setlike declaration's members are this binding's
    // (3.7.12), over the impl's set entries.
    const has_setlike = comptime @hasDecl(Meta, "setlike");

    // Use pre-computed hints from Meta (generated by codegen)
    // This avoids expensive comptime reflection loops
    const properties = Meta.properties;
    const methods = Meta.methods;

    // Every attribute is an accessor on the prototype (WebIDL 3.7.6). Codegen
    // once served some from `Meta.lazy_properties` through a named property
    // interceptor on the prototype template; V8 calls a named SETTER
    // interceptor only when its holder is the receiver (objects.cc,
    // Object::SetPropertyInternal), so their setters never ran for an
    // instance, and the interceptor's instance-returning getter leaked a
    // Context Global per read. property_classifier makes everything eager;
    // this refuses a table that says otherwise.
    const eager_properties = if (@hasDecl(Meta, "eager_properties")) Meta.eager_properties else properties;
    comptime {
        if (@hasDecl(Meta, "lazy_properties") and Meta.lazy_properties.len != 0)
            @compileError(interface_name ++ ": Meta.lazy_properties must be empty - every attribute is an accessor (property_classifier)");
    }

    // Method override tracking for prototype chain optimization
    // TODO: Use own_methods instead of all methods once we have runtime filtering
    // const own_methods = if (@hasDecl(Meta, "own_methods")) Meta.own_methods else &.{};

    // Check if this interface has [Global] extended attribute
    // Per WebIDL §3.8: [Global] interfaces have special `this` handling:
    // - If `this` is null/undefined, use the method's relevant global object
    // - If `this` is an incompatible object, throw TypeError from method's realm
    // HTML 3.2.3 [HTMLConstructor]: the interface's construction is HTML's
    // "HTML element constructors" when the agent's host installed
    // HostHooks.htmlConstructor (its generated `html_constructor`).
    const is_html_constructor = comptime @hasDecl(Interface, "html_constructor") and Interface.html_constructor;

    const is_global_interface = comptime isGlobalInterface(Meta);

    // WebIDL 3.7.6/3.7.7, [Global]: a [Global] interface's regular attributes
    // and operations - its mixins' included - are properties of the global
    // object, not of the interface prototype object. The globals this engine
    // gives them as own properties are Window's (protocol_realms
    // bindWindowToGlobal, context_manager hydrateWindowContext) and the
    // worker scopes' (worker_realm bindGlobalScope); their prototypes hold
    // none. Other [Global] interfaces (the worklets', ShadowRealmGlobalScope)
    // keep them on the prototype until their globals do the same.
    // IndexedDB/idlharness: "Window.prototype must not have indexedDB".
    const members_on_global_object = comptime is_global_interface and
        (std.mem.eql(u8, interface_name, "Window") or
            std.mem.eql(u8, interface_name, "DedicatedWorkerGlobalScope") or
            std.mem.eql(u8, interface_name, "SharedWorkerGlobalScope") or
            std.mem.eql(u8, interface_name, "ServiceWorkerGlobalScope"));

    return struct {
        const Self = @This();

        /// All methods in this interface
        const all_methods = methods;

        /// Interface name
        pub const name = interface_name;

        // ============================================================================
        // HTML 7.2.1 cross-origin objects [cross_origin_objects]
        // ============================================================================

        /// Whether this interface's function for `use` of member `js_name`
        /// accepts any receiver (cross_origin.acceptsAnyReceiver): false
        /// makes V8 run WebIDL's "perform a security check" for a WindowProxy
        /// or Location `this` of another realm before the callback.
        fn acceptsAnyReceiver(comptime js_name: []const u8, comptime use: cross_origin.Use) bool {
            return comptime cross_origin.acceptsAnyReceiver(interface_name, js_name, use);
        }

        /// Whether operation `zig_name`'s function lets V8 run its security
        /// check: every checked one but those returning a promise, whose
        /// SecurityError the binding rejects with (MethodCallback,
        /// cross_origin.receiverIsAccessible).
        fn engineChecksReceiver(comptime js_name: []const u8, comptime zig_name: []const u8) bool {
            return comptime !acceptsAnyReceiver(js_name, .operation) and !bindingChecksReceiver(zig_name);
        }

        /// Whether operation `zig_name` runs WebIDL's security check in the
        /// binding, where its SecurityError rejects the promise the operation
        /// returns (WebIDL 3.7.6): fetch() and createImageBitmap(), the
        /// promise-returning members of the interfaces a Window implements
        /// that every browser exposes on any page (WindowOrWorkerGlobalScope).
        /// Every other operation of those interfaces throws V8's synchronous
        /// SecurityError, as html/browsers/origin/cross-origin-objects/
        /// cross-origin-objects.html expects ("Only certain properties are
        /// usable as cross-origin this objects": fetch and createImageBitmap
        /// reject, everything else throws). Two deviations meet here: the
        /// CSSOM View scroll methods return a Promise in Crane's IDL but
        /// undefined in Chrome, Firefox and Safari; and Crane exposes the
        /// [SecureContext] promise-returning members (showOpenFilePicker,
        /// getDigitalGoodsService, ...) on a non-secure page, where browsers
        /// expose none. When [SecureContext] exposure lands, this widens to
        /// every promise-returning operation but the scroll methods.
        fn bindingChecksReceiver(comptime zig_name: []const u8) bool {
            if (comptime !cross_origin.isSecurityChecked(interface_name) or !returnsPromise(Interface, zig_name)) return false;
            const rejecting = [_][]const u8{ "call_fetch", "call_createImageBitmap", "call_createImageBitmap__1" };
            inline for (rejecting) |rejecting_name| {
                if (comptime std.mem.eql(u8, rejecting_name, zig_name)) return true;
            }
            return false;
        }

        /// The binding's own callback for operation `js_name`: the steps of
        /// the cross-origin function CrossOriginGetOwnPropertyHelper makes
        /// for it (cross_origin.zig), on its `this`.
        pub fn operationCallback(comptime js_name: []const u8) v8.FunctionCallback {
            inline for (methods) |method| {
                if (comptime std.mem.eql(u8, method[0], js_name)) return MethodCallback(method[1]).callback;
            }
            @compileError(interface_name ++ " has no operation " ++ js_name);
        }

        /// Operation `js_name`'s `length` (WebIDL 3.7.6: its shortest
        /// overload's required arguments), as the binding gives it.
        pub fn operationLength(comptime js_name: []const u8) c_int {
            inline for (methods) |method| {
                if (comptime std.mem.eql(u8, method[0], js_name)) return if (method.len >= 3) method[2] else 0;
            }
            @compileError(interface_name ++ " has no operation " ++ js_name);
        }

        /// The binding's own getter callback for attribute `js_name`.
        pub fn attributeGetterCallback(comptime js_name: []const u8) v8.FunctionCallback {
            inline for (properties) |prop| {
                if (comptime std.mem.eql(u8, prop[0], js_name)) return PropertyGetterCallback(interface_name, prop[1]).callback;
            }
            @compileError(interface_name ++ " has no attribute " ++ js_name);
        }

        /// The binding's own setter callback for attribute `js_name`: its
        /// [PutForwards] setter or its own.
        pub fn attributeSetterCallback(comptime js_name: []const u8) v8.FunctionCallback {
            if (comptime @hasDecl(Meta, "put_forwards_attributes")) {
                inline for (Meta.put_forwards_attributes) |pf| {
                    if (comptime std.mem.eql(u8, pf[0], js_name)) return PutForwardsSetterCallback(js_name, pf[1]).callback;
                }
            }
            inline for (properties) |prop| {
                if (comptime std.mem.eql(u8, prop[0], js_name)) {
                    const setter_name: ?[]const u8 = prop[2];
                    return makeSetterCallback(interface_name, setter_name orelse @compileError(interface_name ++ "." ++ js_name ++ " has no setter"));
                }
            }
            @compileError(interface_name ++ " has no attribute " ++ js_name);
        }

        // ============================================================================
        // Static Callback Storage (Chromium Pattern)
        // ============================================================================
        // Callbacks are stored ONCE in static arrays at comptime.
        // Both registerExternalReferences() and createTemplate() reference the SAME
        // callbacks from these arrays, ensuring V8 snapshot restoration works correctly.
        //
        // This solves the problem where PropertyGetterCallback(name, getter).callback
        // creates DIFFERENT function instances at different call sites, causing
        // V8 to fail reconnecting callbacks after snapshot restore.
        // ============================================================================

        /// Static storage for eager property callbacks - generated ONCE at comptime
        const EagerCallbackStore = struct {
            /// Getter callbacks for eager properties
            pub const getters: [eager_properties.len]v8.FunctionCallback = blk: {
                var cbs: [eager_properties.len]v8.FunctionCallback = undefined;
                for (eager_properties, 0..) |prop, i| {
                    const getter_name: []const u8 = prop[1];
                    cbs[i] = PropertyGetterCallback(interface_name, getter_name).callback;
                }
                break :blk cbs;
            };

            /// Setter callbacks for eager properties (null if read-only)
            pub const setters: [eager_properties.len]?v8.FunctionCallback = blk: {
                var cbs: [eager_properties.len]?v8.FunctionCallback = undefined;
                for (eager_properties, 0..) |prop, i| {
                    const setter_name: ?[]const u8 = prop[2];
                    if (setter_name) |s_name| {
                        cbs[i] = makeSetterCallback(interface_name, s_name);
                    } else {
                        cbs[i] = null;
                    }
                }
                break :blk cbs;
            };
        };

        /// Register all callbacks used by this interface with the external references registry
        ///
        /// This MUST be called before creating a V8 snapshot. The external references
        /// array tells V8 where to find callback functions when loading a snapshot.
        ///
        /// Call this for ALL interfaces before snapshot creation:
        /// ```zig
        /// // Register all interface callbacks
        /// inline for (@typeInfo(interfaces).@"struct".decls) |decl| {
        ///     const InterfaceType = @field(interfaces, decl.name);
        ///     if (@hasDecl(InterfaceType, "Meta")) {
        ///         V8Interface(InterfaceType).registerExternalReferences();
        ///     }
        /// }
        /// // Now create snapshot with external_references.getRuntimeExternalReferencesPtr()
        /// ```
        pub fn registerExternalReferences() void {
            const ext_refs = @import("external_references.zig");

            // Set registration context for manifest tracking
            ext_refs.setRegistrationContext(interface_name, .interface_constructor);

            // Register constructor/non-constructor callback
            if (has_constructor) {
                ext_refs.registerCallbackRuntime(constructorCallback);
            } else {
                ext_refs.registerCallbackRuntime(nonConstructorCallback);
            }

            // Register property getter/setter callbacks from static CallbackStore
            // Callbacks are stored ONCE at comptime in EagerCallbackStore
            // and referenced from both here AND createTemplate() to ensure V8 snapshot works
            ext_refs.setRegistrationContext(interface_name, .interface_property_getter);
            inline for (0..eager_properties.len) |i| {
                // Use callback from static store - SAME callback used in createTemplate()
                const getter_cb = EagerCallbackStore.getters[i];
                ext_refs.registerCallbackRuntime(getter_cb);

                // Register setter callback if present (also from static store)
                if (EagerCallbackStore.setters[i]) |setter_cb| {
                    ext_refs.setRegistrationContext(interface_name, .interface_property_setter);
                    ext_refs.registerCallbackRuntime(setter_cb);
                    ext_refs.setRegistrationContext(interface_name, .interface_property_getter);
                }
            }

            // Register PutForwards setter callbacks if interface has put_forwards_attributes
            // Per WebIDL §4.3.10: [PutForwards] attributes use a special setter that
            // forwards to a property on the attribute's value
            if (@hasDecl(Meta, "put_forwards_attributes")) {
                inline for (Meta.put_forwards_attributes) |pf| {
                    const attr_name: []const u8 = pf[0];
                    const forward_prop: []const u8 = pf[1];
                    const PutForwardsSetter = PutForwardsSetterCallback(attr_name, forward_prop);
                    ext_refs.registerCallbackRuntime(PutForwardsSetter.callback);
                }
            }

            // Register method callbacks
            // Method tuple format: { js_name, zig_call_name, arg_count }
            ext_refs.setRegistrationContext(interface_name, .interface_method);
            inline for (methods) |method| {
                const zig_name: []const u8 = method[1];
                const Callback = MethodCallback(zig_name);
                ext_refs.registerCallbackRuntime(Callback.callback);
            }

            // Register static method callbacks
            // Static methods are defined in Meta.static_operations or Meta.static_methods
            // Static operation tuple format: { js_name, zig_call_name, arg_count }
            ext_refs.setRegistrationContext(interface_name, .interface_static_method);
            if (@hasDecl(Meta, "static_operations")) {
                inline for (Meta.static_operations) |op| {
                    const zig_name: []const u8 = op[1];
                    const StaticCallback = StaticMethodCallback(zig_name);
                    ext_refs.registerCallbackRuntime(StaticCallback.callback);
                }
            }

            // Also check for static_methods (another name for the same thing)
            if (@hasDecl(Meta, "static_methods")) {
                inline for (Meta.static_methods) |op| {
                    const zig_name: []const u8 = op[1];
                    const StaticCallback = StaticMethodCallback(zig_name);
                    ext_refs.registerCallbackRuntime(StaticCallback.callback);
                }
            }

            // Static attributes: accessors of the interface object, called the
            // way a static operation is.
            if (@hasDecl(Meta, "static_properties")) {
                inline for (Meta.static_properties) |prop| {
                    const setter_name: ?[]const u8 = prop[2];
                    ext_refs.registerCallbackRuntime(StaticMethodCallback(prop[1]).callback);
                    if (setter_name) |s_name| ext_refs.registerCallbackRuntime(StaticMethodCallback(s_name).callback);
                }
            }

            // Register iterator callbacks if interface has a pair iterator (a
            // value iterator's members are Array.prototype's, not callbacks)
            ext_refs.setRegistrationContext(interface_name, .interface_iterator);
            if (has_pair_iterator) {
                ext_refs.registerCallbackRuntime(entriesCallback);
                ext_refs.registerCallbackRuntime(keysCallback);
                ext_refs.registerCallbackRuntime(valuesCallback);
                ext_refs.registerCallbackRuntime(forEachCallback);
                // Also register iterator prototype callbacks (used by getOrCreateIteratorPrototype)
                ext_refs.registerCallbackRuntime(iteratorSelfCallback);
                ext_refs.registerCallbackRuntime(pairIteratorNextCallback);
                ext_refs.registerCallbackRuntime(unifiedIteratorNextCallback);
            }

            // Register the setlike members' callbacks (3.7.12).
            if (has_setlike) registerSetlikeExternalReferences();

            // Register async iterator callbacks if interface is async iterable
            if (@hasDecl(Meta, "async_iterable")) {
                ext_refs.registerCallbackRuntime(asyncIteratorCallback);
            }

            // Register pair iterator callbacks
            if (@hasDecl(Meta, "pair_iterable")) {
                ext_refs.registerCallbackRuntime(iteratorSelfCallback);
                ext_refs.registerCallbackRuntime(pairIteratorNextCallback);
                // Also register the unified iterator callback (used for shared iterator prototype)
                ext_refs.registerCallbackRuntime(unifiedIteratorNextCallback);
            }

            // Register value iterator callbacks
            if (@hasDecl(Meta, "value_iterable")) {
                ext_refs.registerCallbackRuntime(iteratorSelfCallback);
                ext_refs.registerCallbackRuntime(iteratorNextCallback);
                // Also register the unified iterator callback (used for shared iterator prototype)
                ext_refs.registerCallbackRuntime(unifiedIteratorNextCallback);
            }

            // Register indexed property callbacks if interface has call_item with u32 parameter
            // This matches the condition in createTemplate() for indexed property handler registration
            ext_refs.setRegistrationContext(interface_name, .interface_indexed_property);
            if (has_indexed_getter) {
                ext_refs.registerPointer(@intFromPtr(&indexedPropertyGetter));
                ext_refs.registerPointer(@intFromPtr(&indexedPropertySetter));
                ext_refs.registerPointer(@intFromPtr(&indexedPropertySetterReadOnly));
                ext_refs.registerPointer(@intFromPtr(&indexedPropertyQuery));
                ext_refs.registerPointer(@intFromPtr(&indexedPropertyEnumerator));
                ext_refs.registerPointer(@intFromPtr(&indexedPropertyDefiner));
                ext_refs.registerPointer(@intFromPtr(&indexedPropertyDescriptor));
                ext_refs.registerPointer(@intFromPtr(&indexedPropertyDeleter));
            }
            if (forwards_indices) {
                ext_refs.registerPointer(@intFromPtr(&forwardedIndexGetter));
                ext_refs.registerPointer(@intFromPtr(&forwardedIndexSetter));
                ext_refs.registerPointer(@intFromPtr(&forwardedIndexQuery));
                ext_refs.registerPointer(@intFromPtr(&forwardedIndexDeleter));
                ext_refs.registerPointer(@intFromPtr(&forwardedIndexDefiner));
                ext_refs.registerPointer(@intFromPtr(&forwardedIndexDescriptor));
            }

            // Register named property callbacks if interface has named getter
            // This matches the condition in createTemplate() for named property handler registration
            ext_refs.setRegistrationContext(interface_name, .interface_named_property);
            if (has_named_getter) {
                ext_refs.registerPointer(@intFromPtr(&namedPropertyGetter));
                ext_refs.registerPointer(@intFromPtr(&namedPropertySetter));
                ext_refs.registerPointer(@intFromPtr(&namedPropertySetterReadOnly));
                ext_refs.registerPointer(@intFromPtr(&namedPropertyQuery));
                ext_refs.registerPointer(@intFromPtr(&namedPropertyEnumerator));
                ext_refs.registerPointer(@intFromPtr(&namedPropertyDefiner));
                ext_refs.registerPointer(@intFromPtr(&namedPropertyDescriptor));
                ext_refs.registerPointer(@intFromPtr(&namedPropertyDeleter));
            }

            // Register HTMLAllCollection call handler if this is HTMLAllCollection
            // This is needed for V8 snapshots to work with undetectable objects
            if (comptime std.mem.eql(u8, interface_name, "HTMLAllCollection")) {
                ext_refs.registerCallbackRuntime(htmlAllCollectionCallHandler);
            }
        }

        /// Register interface as a global constructor in V8
        ///
        /// Creates a FunctionTemplate and attaches it to the global object.
        /// Also registers the template in the global registry for instance wrapping.
        ///
        /// The global is taken for the call and released: a Global of the
        /// global proxy left behind keeps the realm's whole context alive
        /// after the realm ends.
        pub fn registerGlobal(
            isolate: *v8.Isolate,
            context: *v8.Context,
            global_name: []const u8,
        ) void {
            const global = v8.v8_Context_Global(context) orelse return;
            defer v8.v8_Object_Dispose(global);
            registerGlobalFast(isolate, context, global, global_name);
        }

        /// Register interface as a global constructor in V8 (fast path)
        ///
        /// Same as registerGlobal but accepts a pre-cached global object.
        /// Used by registerAllInterfaces() to avoid 1231 calls to v8_Context_Global().
        ///
        /// OPTIMIZATION: Skips the (always-failing) attempts to delete "arguments"
        /// and "caller" properties. These are non-configurable V8 accessor properties
        /// that cannot be deleted - trying wastes 4 FFI calls per interface.
        ///
        /// NOTE: This does NOT call template_registry.register() because it's already
        /// called by GlobalTemplateRegistry.precreateAllTemplates() during isolate init.
        /// Skipping the redundant registration saves ~1231 hashmap operations.
        pub fn registerGlobalFast(
            isolate: *v8.Isolate,
            context: *v8.Context,
            global: *v8.Object,
            global_name: []const u8,
        ) void {
            const constructor = materializeInterfaceObject(isolate, context, global_name) orelse return;
            defer v8.v8_Function_Dispose(constructor);
            const key_str = v8.v8_String_NewFromUtf8(isolate, global_name.ptr, @intCast(global_name.len)) orelse return;
            defer v8.v8_String_Dispose(key_str);

            // Per WebIDL spec, interface constructors on global object must be:
            // - writable: true
            // - enumerable: false (not in for...in loops or Object.keys)
            // - configurable: true
            _ = v8.v8_Object_DefineProperty(
                global,
                context,
                @ptrCast(key_str),
                @ptrCast(constructor),
                true, // writable = true
                false, // enumerable = false (per WebIDL spec)
                true, // configurable = true
            );
        }

        /// The interface object in `context`: the function V8 instantiates from
        /// this interface's template, plus what WebIDL puts on it and on its
        /// prototype that the template does not carry - a read-only `prototype`,
        /// @@toStringTag, the iterable and async-iterable members, @@unscopables,
        /// constants, static operations and static attributes. The caller owns
        /// the returned handle.
        ///
        /// Every other handle acquired here is disposed before returning. A
        /// Global left behind is a strong root: one per interface per realm
        /// kept every iframe's realm alive for the life of the process.
        ///
        /// Called once per interface per realm - eagerly for the main context,
        /// and by the lazy data property on a child realm's global the first time
        /// script reads it (global_constructor_handler.lazyConstructorGetter).
        pub fn materializeInterfaceObject(
            isolate: *v8.Isolate,
            context: *v8.Context,
            global_name: []const u8,
        ) ?*v8.Function {
            @setEvalBranchQuota(10000); // Raise branch limit for multiple inline loops

            // CRITICAL: Get template from registry if it exists, otherwise create and register.
            // This ensures we use the SAME template whether the interface is registered
            // directly or first referenced as a parent by a child interface.
            // Without this, prototype objects would differ and instanceof would fail.
            const cached = template_registry.getTemplate(global_name);
            const template = cached orelse blk: {
                const new_template = createTemplate(isolate);
                template_registry.register(global_name, new_template, isolate);
                break :blk new_template;
            };
            const constructor = v8.v8_FunctionTemplate_GetFunction(template, context) orelse return null;

            // Set up once per realm. V8 instantiates a template once per
            // context, so a second call - an inheriting interface
            // materializing this one as its parent, then this one's own
            // global property or lazy getter - is handed the object already
            // made, and finds it marked.
            if (isMaterializedInterfaceObject(constructor)) return constructor;
            markMaterializedInterfaceObject(constructor);

            // WebIDL 3.7.1, create an interface object, steps 2-4: "If I
            // inherits from another interface, let constructorProto be the
            // interface object of that inherited interface in realm;
            // otherwise %Function.prototype%" - and F's [[Prototype]] is
            // constructorProto. V8's Inherit() links only the prototype
            // objects (api-natives.cc InstantiateFunction), so the interface
            // object is linked here, as Blink's V8PerContextData::
            // ConstructorForTypeSlowCase builds the parent's interface object
            // first and creates the child's over it. Every path that makes
            // an interface object comes through here - a snapshot-restored
            // page's registerGlobalFast, a frame's lazy getter, a worker's
            // installForScope - and setupConstructorInheritance ran on none
            // of them: Object.getPrototypeOf(IDBRequest) was
            // %Function.prototype%, for 616 interfaces of a window.
            if (comptime InheritedInterface) |Parent| {
                if (V8Interface(Parent).materializeInterfaceObject(isolate, context, Parent.Meta.name)) |parent_object| {
                    defer v8.v8_Function_Dispose(parent_object);
                    _ = v8.v8_Object_SetPrototypeV2(@ptrCast(constructor), context, @ptrCast(parent_object));
                }
            }

            // NOTE: V8 LIMITATION - Constructor Property Enumeration Order
            //
            // Per WebIDL spec, interface constructors should not have legacy "arguments"
            // and "caller" properties. However, V8's FunctionTemplate creates functions
            // with these as non-configurable accessor properties that CANNOT be deleted.
            //
            // IMPACT: Two WPT tests fail due to this V8 API limitation:
            //   - webidl/ecmascript-binding/builtin-function-properties.any.js
            //   - webidl/ecmascript-binding/legacy-factory-function-builtin-properties.window.js

            // CRITICAL: Skip ALL prototype setup for callback interfaces!
            // Per WebIDL §3.12, callback interfaces do NOT have a .prototype property.
            // Accessing or defining the prototype property would re-create it.
            if (is_callback_interface) {
                defineConstants(isolate, context, @ptrCast(constructor));
                return constructor;
            }

            // Fix the "prototype" property to be non-writable (spec-compliant)
            // By default V8 makes constructor.prototype writable, but in browsers it's read-only
            if (v8.v8_String_NewFromUtf8(isolate, "prototype", 9)) |prototype_key| {
                defer v8.v8_String_Dispose(prototype_key);
                if (v8.v8_Object_Get(@ptrCast(constructor), context, @ptrCast(prototype_key))) |proto| {
                    defer v8.v8_Value_Dispose(proto);
                    _ = v8.v8_Object_DefineProperty(
                        @ptrCast(constructor),
                        context,
                        @ptrCast(prototype_key),
                        proto,
                        false, // writable = false (read-only)
                        false, // enumerable = false
                        false, // configurable = false
                    );
                    setUpPrototype(isolate, context, @ptrCast(proto));

                    // WebIDL "create an interface prototype object" step 4:
                    // DOMException's prototype inherits from the realm's
                    // %Error.prototype%, so a DOMException is an Error.
                    if (comptime std.mem.eql(u8, interface_name, "DOMException")) {
                        if (v8.v8_Context_ErrorPrototype(context)) |error_proto| {
                            defer v8.v8_Object_Dispose(error_proto);
                            _ = v8.v8_Object_SetPrototypeV2(@ptrCast(proto), context, @ptrCast(error_proto));
                        }
                    }
                }
            }

            defineConstants(isolate, context, @ptrCast(constructor));

            // Register static methods on constructor
            // Static methods like AbortSignal.abort(), AbortSignal.timeout()
            if (@hasDecl(Meta, "static_methods")) {
                inline for (Meta.static_methods) |method| {
                    const method_name: []const u8 = method[0];
                    const zig_name: []const u8 = method[1];
                    const arity: c_int = if (method.len >= 3) method[2] else 0;
                    const static_callback = StaticMethodCallback(zig_name).callback;
                    if (v8.v8_FunctionTemplate_New(isolate, static_callback, null)) |tmpl| {
                        defer v8.v8_FunctionTemplate_Dispose(tmpl);
                        v8.v8_FunctionTemplate_SetLength(tmpl, arity);
                        if (v8.v8_FunctionTemplate_GetFunction(tmpl, context)) |func| {
                            defer v8.v8_Function_Dispose(func);
                            if (v8.v8_String_NewFromUtf8(isolate, method_name.ptr, @intCast(method_name.len))) |method_name_v8| {
                                defer v8.v8_String_Dispose(method_name_v8);
                                // Set the function's .name property per WebIDL spec
                                v8.v8_Function_SetName(func, method_name_v8);
                                // Static methods: writable=true, enumerable=true, configurable=true
                                _ = v8.v8_Object_DefineProperty(@ptrCast(constructor), context, @ptrCast(method_name_v8), @ptrCast(func), true, true, true);
                            }
                        }
                    }
                }
            }

            // Static attributes (WebIDL §3.7.6): accessor properties of the
            // interface object - a getter "get <name>", a setter "set <name>"
            // or undefined, enumerable and configurable.
            if (@hasDecl(Meta, "static_properties")) {
                inline for (Meta.static_properties) |prop| {
                    const prop_name: []const u8 = prop[0];
                    const setter_name: ?[]const u8 = prop[2];
                    const getter_cb: v8.FunctionCallback = StaticMethodCallback(prop[1]).callback;
                    const setter_cb: ?v8.FunctionCallback = if (setter_name) |s_name| StaticMethodCallback(s_name).callback else null;
                    if (v8.v8_String_NewFromUtf8(isolate, prop_name.ptr, @intCast(prop_name.len))) |name_v8| {
                        defer v8.v8_String_Dispose(name_v8);
                        _ = v8.v8_Object_SetAccessorProperty(@ptrCast(constructor), context, name_v8, getter_cb, setter_cb);
                    }
                }
            }

            // WebIDL 3.3.13 and "exposed": a [SecureContext] member exists
            // only in a realm whose settings object is a secure context. The
            // template carries every member (one template serves every realm
            // of the isolate, and the snapshot), so a realm that is not one
            // drops them from its own interface object and prototype as they
            // are made - lazily or eagerly, restored or afresh.
            if (comptime @hasDecl(Meta, "secure_context_members") or @hasDecl(Meta, "secure_context_static_members")) {
                if (!realmIsSecureContext(context)) {
                    if (comptime @hasDecl(Meta, "secure_context_static_members")) {
                        hideNames(isolate, context, @ptrCast(constructor), Meta.secure_context_static_members);
                    }
                    if (comptime @hasDecl(Meta, "secure_context_members")) {
                        if (v8.v8_String_NewFromUtf8(isolate, "prototype", 9)) |prototype_key| {
                            defer v8.v8_String_Dispose(prototype_key);
                            if (v8.v8_Object_Get(@ptrCast(constructor), context, @ptrCast(prototype_key))) |prototype| {
                                defer v8.v8_Value_Dispose(prototype);
                                if (v8.v8_Value_IsObject(prototype)) hideNames(isolate, context, @ptrCast(prototype), Meta.secure_context_members);
                            }
                        }
                    }
                }
            }

            // These configurable members came from isolate-wide templates;
            // filter the realm's objects, never the shared template.
            hideUnexposedMembers(Interface, true, isolate, context, @ptrCast(constructor));
            if (comptime @hasDecl(Meta, "exposed_members")) {
                if (v8.v8_String_NewFromUtf8(isolate, "prototype", 9)) |key| {
                    defer v8.v8_String_Dispose(key);
                    if (v8.v8_Object_Get(@ptrCast(constructor), context, @ptrCast(key))) |prototype| {
                        defer v8.v8_Value_Dispose(prototype);
                        if (v8.v8_Value_IsObject(prototype)) hideUnexposedMembers(Interface, false, isolate, context, @ptrCast(prototype));
                    }
                }
            }

            return constructor;
        }

        /// The interface this one inherits from - the parent whose template
        /// createTemplate Inherit()s - or null.
        const InheritedInterface: ?type = blk: {
            if (@hasDecl(Meta, "ParentInterface")) {
                const Parent = Meta.ParentInterface;
                if (@typeInfo(Parent) == .@"struct" and @hasDecl(Parent, "Meta")) break :blk Parent;
                break :blk null;
            }
            if (@typeInfo(@TypeOf(Meta.BaseType)) == .optional) {
                if (Meta.BaseType) |Base| {
                    const base_info = @typeInfo(Base);
                    if (base_info == .pointer and @typeInfo(base_info.pointer.child) == .@"struct" and @hasDecl(base_info.pointer.child, "Meta")) {
                        break :blk base_info.pointer.child;
                    }
                }
            }
            break :blk null;
        };

        /// Constants on `target`, the interface object: writable=false,
        /// enumerable=true, configurable=false (WebIDL §3.7.2).
        fn defineConstants(isolate: *v8.Isolate, context: *v8.Context, target: *v8.Object) void {
            if (!@hasDecl(Meta, "constants")) return;
            inline for (Meta.constants) |constant| {
                install_member: {
                    const const_name: []const u8 = constant[0];
                    if (comptime hasExposureOverride(Interface, const_name, true)) {
                        if (!memberIsExposed(Interface, const_name, true, realmExposureScope(context))) break :install_member;
                    }
                    const getter_name: []const u8 = constant[1];
                    const value = @field(Interface, getter_name)();
                    const v8_value = v8.v8_Number_New(isolate, @floatFromInt(value));
                    defer v8.v8_Value_Dispose(@ptrCast(v8_value));
                    if (v8.v8_String_NewFromUtf8(isolate, const_name.ptr, @intCast(const_name.len))) |const_name_v8| {
                        defer v8.v8_String_Dispose(const_name_v8);
                        _ = v8.v8_Object_DefineProperty(target, context, @ptrCast(const_name_v8), @ptrCast(v8_value), false, true, false);
                    }
                }
            }
        }

        /// A pair iterator's method: CreateBuiltinFunction(steps, length,
        /// name, « », realm) - the function `callback` runs, named
        /// `method_name`, in `context`. OWNED, or null.
        fn pairIterationMethod(isolate: *v8.Isolate, context: *v8.Context, comptime method_name: []const u8, callback: v8.FunctionCallback, length: c_int) ?*v8.Function {
            const tmpl = v8.v8_FunctionTemplate_New(isolate, callback, null) orelse return null;
            defer v8.v8_FunctionTemplate_Dispose(tmpl);
            v8.v8_FunctionTemplate_SetLength(tmpl, length);
            const name_v8 = v8.v8_String_NewFromUtf8(isolate, method_name.ptr, @intCast(method_name.len)) orelse return null;
            defer v8.v8_String_Dispose(name_v8);
            v8.v8_FunctionTemplate_SetClassName(tmpl, name_v8);
            return v8.v8_FunctionTemplate_GetFunction(tmpl, context);
        }

        /// CreateDataPropertyOrThrow(proto, name, func): writable, enumerable,
        /// configurable.
        fn definePairIterationMethod(isolate: *v8.Isolate, context: *v8.Context, proto: *v8.Object, comptime method_name: []const u8, func: *v8.Function) void {
            const key = v8.v8_String_NewFromUtf8(isolate, method_name.ptr, @intCast(method_name.len)) orelse return;
            defer v8.v8_String_Dispose(key);
            _ = v8.v8_Object_DefineProperty(proto, context, @ptrCast(key), @ptrCast(func), true, true, true);
        }

        /// What WebIDL puts on the interface prototype object beyond the
        /// template: @@toStringTag, the iterable and async-iterable members and
        /// @@unscopables.
        fn setUpPrototype(isolate: *v8.Isolate, context: *v8.Context, proto: *v8.Object) void {
            // Non-configurable constants with [Exposed] cannot be removed
            // from a template-created object: define them only in this realm.
            if (comptime @hasDecl(Meta, "constants")) {
                inline for (Meta.constants) |constant| {
                    install_constant: {
                        if (comptime !hasExposureOverride(Interface, constant[0], false)) continue;
                        if (!memberIsExposed(Interface, constant[0], false, realmExposureScope(context))) break :install_constant;
                        const value = @field(Interface, constant[1])();
                        const number = v8.v8_Number_New(isolate, @floatFromInt(value));
                        defer v8.v8_Value_Dispose(@ptrCast(number));
                        const constant_name = v8.v8_String_NewFromUtf8(isolate, constant[0].ptr, @intCast(constant[0].len)) orelse break :install_constant;
                        defer v8.v8_String_Dispose(constant_name);
                        _ = v8.v8_Object_DefineProperty(proto, context, @ptrCast(constant_name), @ptrCast(number), false, true, false);
                    }
                }
            }
            // Set Symbol.toStringTag on prototype
            // This makes Object.prototype.toString.call(prototype) return "[object InterfaceName]"
            if (v8.v8_Symbol_GetToStringTag(isolate)) |symbol| {
                defer v8.v8_Symbol_Dispose(symbol);
                if (v8.v8_String_NewFromUtf8(isolate, interface_name.ptr, @intCast(interface_name.len))) |name_v8| {
                    defer v8.v8_String_Dispose(name_v8);
                    // writable = false, enumerable = false, configurable = true (per WebIDL spec)
                    _ = v8.v8_Object_DefineProperty(proto, context, @ptrCast(symbol), @ptrCast(name_v8), false, false, true);
                }
            }

            // WebIDL 3.7.9 step 2: a pair iterator's %Symbol.iterator%,
            // entries, keys, values and forEach. (Step 1, a value iterator's,
            // is on the prototype template: createTemplate.)
            if (has_pair_iterator) {
                // Step 2.1: F, named "entries", is both %Symbol.iterator%
                // (DefineMethodProperty: not enumerable) and entries
                // (CreateDataPropertyOrThrow) - one function object.
                if (pairIterationMethod(isolate, context, "entries", entriesCallback, 0)) |entries| {
                    defer v8.v8_Function_Dispose(entries);
                    if (v8.v8_Symbol_GetIterator(isolate)) |symbol| {
                        defer v8.v8_Symbol_Dispose(symbol);
                        _ = v8.v8_Object_DefineProperty(proto, context, @ptrCast(symbol), @ptrCast(entries), true, false, true);
                    }
                    definePairIterationMethod(isolate, context, proto, "entries", entries);
                }
                // Steps 2.2-2.4: keys, values and forEach, each named for
                // itself; forEach's length is 1.
                const others = [_]struct { name: []const u8, cb: v8.FunctionCallback, length: c_int }{
                    .{ .name = "keys", .cb = keysCallback, .length = 0 },
                    .{ .name = "values", .cb = valuesCallback, .length = 0 },
                    .{ .name = "forEach", .cb = forEachCallback, .length = 1 },
                };
                inline for (others) |method| {
                    if (pairIterationMethod(isolate, context, method.name, method.cb, method.length)) |func| {
                        defer v8.v8_Function_Dispose(func);
                        definePairIterationMethod(isolate, context, proto, method.name, func);
                    }
                }
            }

            // WebIDL 3.7.12: a setlike declaration's members.
            if (has_setlike) defineSetlikeMembers(isolate, context, proto);

            // Set Symbol.asyncIterator on prototype if interface is async iterable
            if (@hasDecl(Meta, "async_iterable")) {
                if (v8.v8_Symbol_GetAsyncIterator(isolate)) |symbol| {
                    defer v8.v8_Symbol_Dispose(symbol);
                    // Create async iterator function that wraps call_values()
                    if (v8.v8_FunctionTemplate_New(isolate, asyncIteratorCallback, null)) |tmpl| {
                        defer v8.v8_FunctionTemplate_Dispose(tmpl);
                        if (v8.v8_FunctionTemplate_GetFunction(tmpl, context)) |func| {
                            defer v8.v8_Function_Dispose(func);
                            // writable = true, enumerable = false, configurable = true
                            _ = v8.v8_Object_DefineProperty(proto, context, @ptrCast(symbol), @ptrCast(func), true, false, true);
                        }

                        // Also register "values" method with the same callback
                        // Per WebIDL async iterable spec, values() does the same thing as [Symbol.asyncIterator]()
                        if (v8.v8_String_NewFromUtf8(isolate, "values", 6)) |name_str| {
                            defer v8.v8_String_Dispose(name_str);
                            if (v8.v8_FunctionTemplate_GetFunction(tmpl, context)) |func2| {
                                defer v8.v8_Function_Dispose(func2);
                                _ = v8.v8_Object_DefineProperty(proto, context, @ptrCast(name_str), @ptrCast(func2), true, false, true);
                            }
                        }
                    }
                }
            }

            // NOTE: toString() for stringifiers is handled by Meta.methods
            // which maps "toString" -> "serialize" via MethodCallback.
            // Do NOT add redundant toString registration here - it would
            // overwrite the correct binding from createTemplate().

            // Set Symbol.unscopables on prototype if interface has [Unscopable] members
            // Per WebIDL spec §3.7.6, the @@unscopables property is:
            // - An object with null prototype
            // - Contains properties for each [Unscopable] member with value true
            // - writable=false, enumerable=false, configurable=true
            if (@hasDecl(Meta, "unscopables")) {
                const unscopables = Meta.unscopables;
                if (unscopables.len > 0) {
                    if (v8.v8_Symbol_GetUnscopables(isolate)) |symbol| {
                        defer v8.v8_Symbol_Dispose(symbol);
                        if (v8.v8_Object_NewWithNullPrototype(context)) |obj| {
                            defer v8.v8_Object_Dispose(obj);
                            const true_val = v8.v8_Boolean_New(isolate, true);
                            defer if (true_val) |t| v8.v8_Value_Dispose(t);
                            // Add each unscopable member as a property with value true
                            inline for (unscopables) |member_name| {
                                if (v8.v8_String_NewFromUtf8(isolate, member_name.ptr, @intCast(member_name.len))) |key| {
                                    defer v8.v8_String_Dispose(key);
                                    if (true_val) |t| {
                                        // Per spec: writable=true, enumerable=true, configurable=true
                                        _ = v8.v8_Object_DefineProperty(obj, context, @ptrCast(key), @ptrCast(t), true, true, true);
                                    }
                                }
                            }
                            // Per spec: writable=false, enumerable=false, configurable=true
                            _ = v8.v8_Object_DefineProperty(proto, context, @ptrCast(symbol), @ptrCast(obj), false, false, true);
                        }
                    }
                }
            }
        }

        /// WebIDL 3.3.13: in a realm that is not a secure context, delete
        /// this interface's [SecureContext] attributes and operations from
        /// `object` - for a [Global] interface, the global object that holds
        /// them as own properties.
        pub fn hideSecureContextMembers(isolate: *v8.Isolate, context: *v8.Context, object: *v8.Object) void {
            if (comptime !@hasDecl(Meta, "secure_context_members")) return;
            if (realmIsSecureContext(context)) return;
            hideNames(isolate, context, object, Meta.secure_context_members);
        }

        /// Register interface properties as own properties on an existing V8 object
        ///
        /// This is used for [Global] interfaces (like Window) where the properties
        /// need to be own properties of the global object, not just inherited from
        /// the prototype chain. This is required for cross-realm compliance:
        ///
        /// `Object.getOwnPropertyDescriptor(iframe.contentWindow, "name")` must return
        /// a descriptor with getter/setter, not undefined.
        ///
        /// Per WebIDL §3.8: For [Global] interfaces, the global object should have
        /// the interface's properties as own properties.
        pub fn registerPropertiesAsOwnOnObject(
            isolate: *v8.Isolate,
            context: *v8.Context,
            target_object: *v8.Object,
        ) void {
            installOwnProperties(isolate, context, target_object, false);
        }

        fn installOwnProperties(isolate: *v8.Isolate, context: *v8.Context, target_object: *v8.Object, comptime conditional_only: bool) void {
            @setEvalBranchQuota(10000);

            // Register EAGER properties as accessor properties on the target object
            inline for (eager_properties) |prop| {
                install_member: {
                    const prop_name: []const u8 = prop[0];
                    if (comptime conditional_only and !(isUnforgeableMember(prop_name) and hasExposureOverride(Interface, prop_name, false))) continue;
                    if (comptime hasExposureOverride(Interface, prop_name, false)) {
                        if (!memberIsExposed(Interface, prop_name, false, realmExposureScope(context))) break :install_member;
                    }
                    const getter_name: []const u8 = prop[1];
                    const setter_name: ?[]const u8 = prop[2];

                    // `self` and `frames` are [Replaceable]: the realm defines them
                    // as own data properties whose value is the global itself
                    // (protocol_realms bindWindowToGlobal), which testharness.js's
                    // `(function (global_scope) { ... })(self)` needs. `window` is
                    // an accessor like any other member, the global's own: its
                    // getter answers the global (answerWindowGetter).
                    if (comptime is_global_interface and (std.mem.eql(u8, prop_name, "self") or
                        std.mem.eql(u8, prop_name, "frames")))
                    {
                        continue;
                    }

                    const prop_name_str = v8.v8_String_NewFromUtf8(
                        isolate,
                        prop_name.ptr,
                        @intCast(prop_name.len),
                    ).?;
                    defer v8.v8_String_Dispose(prop_name_str);

                    // Use PropertyGetterCallback to generate the getter callback
                    const getter_cb: v8.FunctionCallback = PropertyGetterCallback(interface_name, getter_name).callback;

                    // Check if this property has [PutForwards] extended attribute
                    const put_forwards_target: ?[]const u8 = comptime blk: {
                        if (!@hasDecl(Meta, "put_forwards_attributes")) break :blk null;
                        for (Meta.put_forwards_attributes) |pf| {
                            if (std.mem.eql(u8, pf[0], prop_name)) {
                                break :blk pf[1];
                            }
                        }
                        break :blk null;
                    };

                    // Generate setter callback
                    const setter_cb: ?v8.FunctionCallback = if (put_forwards_target) |forward_prop|
                        PutForwardsSetterCallback(prop_name, forward_prop).callback
                    else if (setter_name) |s_name|
                        makeSetterCallback(interface_name, s_name)
                    else
                        null;

                    // Set as accessor property on the target object
                    // This creates an own property visible to Object.getOwnPropertyDescriptor.
                    // Each function runs WebIDL's security check for a
                    // cross-origin `this` unless HTML lists it (cross_origin.zig).
                    _ = v8.v8_Object_SetAccessorPropertyChecked(
                        target_object,
                        context,
                        prop_name_str,
                        getter_cb,
                        setter_cb,
                        comptime acceptsAnyReceiver(prop_name, .getter),
                        comptime acceptsAnyReceiver(prop_name, .setter),
                        comptime if (isUnforgeableMember(prop_name)) v8.PropertyAttribute.DontDelete else v8.PropertyAttribute.None,
                    );
                }
            }
        }

        /// Reinstall accessor callbacks on a prototype object after loading from snapshot
        ///
        /// V8 snapshots serialize JavaScript objects but native callback pointers become
        /// stale. This function re-installs accessor callbacks on the prototype object
        // NOTE: reinstallAccessorCallbacksOnPrototype and reinstallMethodCallbacksOnPrototype
        // have been REMOVED. These functions were obsoleted by the Chromium pattern fix (whatwg-41la6).
        // Calling GetFunction() before NewInstance() in template_registry.zig correctly materializes
        // prototype chains during snapshot creation. Accessors/methods set on PrototypeTemplate
        // are preserved through snapshot restore without reinstallation.

        /// Register methods as OWN properties on a specific V8 object
        ///
        /// This is used for [Global] interfaces (like Window) to make methods
        /// accessible as own properties on the global object.
        /// Required for cross-realm compliance:
        /// `Object.create(iframe.contentWindow).focus()` must work because
        /// `focus` should be accessible through the prototype chain.
        ///
        /// Per WebIDL §3.8: For [Global] interfaces, the global object should have
        /// the interface's operations as own properties (callable functions).
        pub fn registerMethodsAsOwnOnObject(
            isolate: *v8.Isolate,
            context: *v8.Context,
            target_object: *v8.Object,
        ) void {
            installOwnMethods(isolate, context, target_object, false);
        }

        fn installOwnMethods(isolate: *v8.Isolate, context: *v8.Context, target_object: *v8.Object, comptime conditional_only: bool) void {
            @setEvalBranchQuota(20000);

            // Register all methods as function properties on the target object
            inline for (methods) |method| {
                install_member: {
                    const method_name: []const u8 = method[0];
                    const zig_name: []const u8 = method[1];
                    if (comptime conditional_only and !(isUnforgeableMember(method_name) and hasExposureOverride(Interface, method_name, false))) continue;
                    if (comptime hasExposureOverride(Interface, method_name, false)) {
                        if (!memberIsExposed(Interface, method_name, false, realmExposureScope(context))) break :install_member;
                    }
                    // WebIDL 3.7.6 (create an operation function): its `length`
                    // is the shortest overload's required argument count and its
                    // `name` the operation's identifier - as on the prototype,
                    // where createTemplate sets both. Left out here, every
                    // window operation read `length` 0 and `name` "".
                    const arity: c_int = if (method.len >= 3) method[2] else 0;

                    // Create the method callback using FunctionTemplate
                    const Callback = MethodCallback(zig_name);

                    // Create FunctionTemplate for this method
                    const method_tmpl = v8.v8_FunctionTemplate_New(
                        isolate,
                        Callback.callback,
                        null,
                    );

                    // Every handle here is owned and released once the property is
                    // set. The function lives in `context`, so one leaked handle
                    // per method kept every context this ran for alive - every
                    // page and every frame.
                    if (method_tmpl) |tmpl| {
                        defer v8.v8_FunctionTemplate_Dispose(tmpl);
                        v8.v8_FunctionTemplate_SetLength(tmpl, arity);
                        // Not a constructor: no `prototype` (as on the prototype).
                        v8.v8_FunctionTemplate_RemovePrototype(tmpl);
                        // WebIDL's security check for a cross-origin `this`,
                        // unless HTML lists the operation (cross_origin.zig).
                        if (comptime engineChecksReceiver(method_name, zig_name)) v8.v8_FunctionTemplate_SetAcceptAnyReceiver(tmpl, false);
                        // Get Function from template
                        const method_fn = v8.v8_FunctionTemplate_GetFunction(
                            tmpl,
                            context,
                        );

                        if (method_fn) |func| {
                            defer v8.v8_Function_Dispose(func);
                            // Create string for method name
                            const name_str = v8.v8_String_NewFromUtf8(
                                isolate,
                                method_name.ptr,
                                @intCast(method_name.len),
                            );

                            if (name_str) |name_v8_str| {
                                defer v8.v8_String_Dispose(name_v8_str);
                                v8.v8_Function_SetName(func, name_v8_str);
                                // Defined, never assigned (a [[Set]] runs whatever
                                // the prototype chain has under the name):
                                // { writable, enumerable, configurable }, WebIDL
                                // 3.7.6 for a regular operation.
                                _ = v8.v8_Object_DefineProperty(
                                    target_object,
                                    context,
                                    @ptrCast(name_v8_str),
                                    @ptrCast(func),
                                    !isUnforgeableMember(method_name),
                                    true,
                                    !isUnforgeableMember(method_name),
                                );
                            }
                        }
                    }
                }
            }
        }

        /// WebIDL 3.8: non-configurable exposed members belong to this
        /// realm's wrapper. The isolate's templates cannot hold them.
        pub fn installConditionalUnforgeables(isolate: *v8.Isolate, context: *v8.Context, object: *v8.Object) void {
            if (comptime !hasConditionalUnforgeables(Interface)) return;
            if (@hasDecl(Meta, "ParentInterface")) {
                V8Interface(Meta.ParentInterface).installConditionalUnforgeables(isolate, context, object);
            }
            installOwnProperties(isolate, context, object, true);
            installOwnMethods(isolate, context, object, true);
        }

        /// Check if interface has a constructor (from Meta.has_constructor hint)
        const has_constructor = Meta.has_constructor;

        /// Check if this is a callback interface (from Meta.is_callback_interface hint)
        /// Callback interfaces have special behavior per WebIDL §3.12:
        /// - Must NOT have a .prototype property
        /// - instanceof should throw TypeError
        const is_callback_interface = if (@hasDecl(Meta, "is_callback_interface"))
            Meta.is_callback_interface
        else
            false;

        /// Create a FunctionTemplate for this interface
        ///
        /// Returns a V8 FunctionTemplate with:
        /// - Constructor callback (if interface has constructor)
        /// - Prototype with all methods
        /// - Internal fields for Zig instance storage
        ///
        /// ## Template caching
        ///
        /// Templates are cached in the isolate's own template storage (its data
        /// slot), cleaned up with the isolate. There was a per-interface static
        /// "backup" cache too: one isolate's template in a process global,
        /// written by every isolate that made one - a page and a worker on two
        /// threads (docs/instances.md) could read each other's half-written pair
        /// and get the other isolate's template. Callers register templates in
        /// template_registry, keyed by isolate, and look there first.
        ///
        /// IMPORTANT: For constructable interfaces, we MUST ensure callbacks are fresh.
        /// After snapshot restore, templates in cache may have stale callback pointers.
        pub fn createTemplate(isolate: *v8.Isolate) *v8.FunctionTemplate {
            // Force fresh creation for constructable interfaces to ensure callbacks work
            // This is critical after snapshot restore - cached templates have stale callbacks
            if (has_constructor) {
                return createTemplateFresh(isolate);
            }
            return createTemplateCached(isolate);
        }

        /// Create a fresh template, bypassing all caches
        fn createTemplateFresh(isolate: *v8.Isolate) *v8.FunctionTemplate {
            @setEvalBranchQuota(20000);
            const isolate_alloc = @import("isolate_allocator.zig");
            const isolate_templates = @import("isolate_templates.zig");

            // Create the template
            const template = createTemplateCore(isolate);

            // Still cache it for future use within this session
            if (isolate_alloc.getIsolateAllocator(isolate)) |alloc| {
                if (isolate_templates.getOrCreateTemplateStorage(isolate, alloc) catch null) |storage| {
                    storage.put(interface_name, template) catch {};
                }
            }

            return template;
        }

        /// Create a template with caching
        fn createTemplateCached(isolate: *v8.Isolate) *v8.FunctionTemplate {
            @setEvalBranchQuota(20000);
            const isolate_templates = @import("isolate_templates.zig");
            const isolate_alloc = @import("isolate_allocator.zig");

            // Skip cache lookup in snapshot mode - always create fresh templates
            // as Local handles that V8 can serialize without complaining about Global handles
            if (!template_registry.snapshot_mode) {
                // The isolate's own template storage: templates live with their
                // isolate.
                if (isolate_alloc.getIsolateAllocator(isolate)) |alloc| {
                    if (isolate_templates.getOrCreateTemplateStorage(isolate, alloc) catch null) |storage| {
                        if (storage.get(interface_name)) |cached| {
                            return cached;
                        }
                    }
                }
            }

            return createTemplateCore(isolate);
        }

        /// Core template creation logic
        fn createTemplateCore(isolate: *v8.Isolate) *v8.FunctionTemplate {
            @setEvalBranchQuota(20000);
            const isolate_templates = @import("isolate_templates.zig");
            const isolate_alloc = @import("isolate_allocator.zig");

            // Create function template - only with constructor callback if interface is constructible
            const ctor_callback: ?v8.FunctionCallback = if (has_constructor) constructorCallback else nonConstructorCallback;

            const template = v8.v8_FunctionTemplate_New(
                isolate,
                ctor_callback,
                null,
            ).?;

            // NOTE: Window's prototype chain is set up manually in interface_bindings.zig
            // via window_properties.insertIntoPrototypeChain() AFTER the context is created.
            // This is necessary because we need to insert a WindowProperties INSTANCE
            // (not WindowProperties.prototype) into the chain.
            // SetPrototypeProviderTemplate is NOT used because it uses the provider's
            // .prototype property, not an instance.

            // Set class name. The template keeps the name itself
            // (FunctionTemplate::SetClassName takes a Local), so this handle
            // is released once it is set: it is made for every interface in
            // every isolate, and a worker realm rebuilds every template.
            const name_str = v8.v8_String_NewFromUtf8(
                isolate,
                name.ptr,
                @intCast(name.len),
            ).?;
            defer v8.v8_String_Dispose(name_str);
            v8.v8_FunctionTemplate_SetClassName(template, name_str);

            // WebIDL 3.7.1 step 9: the shortest effective constructor list.
            // Nullable and sequence types do not imply optional arguments.
            const constructor_length: c_int = comptime if (@hasDecl(Interface, "constructor_required_arguments")) @intCast(Interface.constructor_required_arguments) else 0;
            v8.v8_FunctionTemplate_SetLength(template, constructor_length);

            // Handle callback interfaces differently per WebIDL §3.12
            // Legacy callback interface objects do NOT have a .prototype property
            if (is_callback_interface) {
                // Remove the prototype property entirely for callback interfaces
                // This makes Object.getOwnPropertyDescriptor(NodeFilter, 'prototype') return undefined
                v8.v8_FunctionTemplate_RemovePrototype(template);

                // CRITICAL: Return immediately for callback interfaces!
                // Do NOT call InstanceTemplate(), PrototypeTemplate(), or any other template
                // operations - they may re-create the prototype that RemovePrototype() removed.
                // Constants are registered separately in registerGlobal().

                // Cache the template for callback interfaces too
                if (!template_registry.snapshot_mode) {
                    if (isolate_alloc.getIsolateAllocator(isolate)) |alloc| {
                        if (isolate_templates.getOrCreateTemplateStorage(isolate, alloc) catch null) |storage| {
                            storage.put(interface_name, template) catch {};
                        }
                    }
                }
                return template;
            }

            // Make the "prototype" property read-only for regular interfaces.
            // Per WebIDL spec, Constructor.prototype should be non-writable.
            // Note: This does NOT remove legacy "arguments"/"caller" properties -
            // that's a V8 limitation we cannot work around without V8 internal APIs.
            v8.v8_FunctionTemplate_ReadOnlyPrototype(template);

            // Get instance template and set internal field count
            // Field 0: pointer to Zig instance (*runtime.Instance)
            // Field 1: pointer to type tag (for type-safe unwrapping)
            const instance_tmpl = v8.v8_FunctionTemplate_InstanceTemplate(template);
            defer v8.v8_ObjectTemplate_Dispose(instance_tmpl);
            v8.v8_ObjectTemplate_SetInternalFieldCount(instance_tmpl, 2);

            // Per WebIDL spec, platform objects of [Global] interfaces have immutable [[Prototype]].
            // Also some specific interfaces like Location.
            if (is_global_interface or comptime std.mem.eql(u8, interface_name, "Location")) {
                v8.v8_ObjectTemplate_SetImmutableProto(instance_tmpl);
            }

            // HTML 7.2.3 and 7.2.4: the WindowProxy and a Location are exotic
            // objects whose internal methods are cross-origin ones when
            // IsPlatformObjectSameOrigin fails - V8's access check and its
            // interceptors [cross_origin_objects]. Window's instance template
            // is every realm's global template (protocol_realms.windowTemplate,
            // the snapshot generator), so its global proxy - the WindowProxy -
            // has them.
            if (comptime std.mem.eql(u8, interface_name, "Window")) {
                cross_origin.installOnTemplate(instance_tmpl, .window);
            } else if (comptime std.mem.eql(u8, interface_name, "Location")) {
                cross_origin.installOnTemplate(instance_tmpl, .location);
            }

            // Trusted Types: a TrustedScript is code-like (TC39 Dynamic Code
            // Brand Checks, [[HostDefinedIsCodeLike]]), so `eval(ts)` and
            // `new Function(ts)` reach HostEnsureCanCompileStrings with
            // isCodeLike true and CSP 4.4.1 step 2 skips the Trusted Types
            // check for it. Without it, Function(trustedScript) under
            // require-trusted-types-for is checked as a string and blocked
            // when there is no default policy.
            if (comptime std.mem.eql(u8, interface_name, "TrustedScript")) {
                v8.v8_ObjectTemplate_SetCodeLike(instance_tmpl);
            }

            // HTMLAllCollection has [[IsHTMLDDA]] internal slot per ECMA-262
            // This makes it "undetectable" - typeof returns "undefined", coerces to false
            // V8 requires undetectable objects to have a call-as-function handler
            // Per HTML spec, document.all(x) calls item(x) or namedItem(x) based on argument type
            if (comptime std.mem.eql(u8, interface_name, "HTMLAllCollection")) {
                // Mark instances as undetectable (falsy despite being objects)
                v8.v8_ObjectTemplate_MarkAsUndetectable(instance_tmpl);

                // Set call-as-function handler on instance template - V8 requires this for undetectable objects
                // The callback implements document.all(nameOrIndex) behavior
                v8.v8_ObjectTemplate_SetCallAsFunctionHandler(instance_tmpl, htmlAllCollectionCallHandler, null);
            }

            // Get prototype template (only used for non-callback interfaces).
            // The function template owns it; this handle to it is ours, for
            // the calls below.
            const proto_tmpl = v8.v8_FunctionTemplate_PrototypeTemplate(template);
            defer v8.v8_ObjectTemplate_Dispose(proto_tmpl);

            // ========================================
            // INHERITANCE SETUP - MUST BE FIRST
            // ========================================
            // Per Chromium's pattern, Inherit() must be called BEFORE registering methods.
            // This ensures the prototype chain is properly established before any
            // properties or methods are added to the prototype template.
            //
            // Use ParentInterface (the actual interface type) for prototype chain setup
            // ParentInterface is set when BaseType is an embedded state struct
            //
            // Window goes through normal inheritance (→ EventTarget).
            // WindowProperties is inserted into the chain manually in interface_bindings.zig
            // AFTER the context is created.
            if (@hasDecl(Meta, "ParentInterface")) {
                const ParentType = Meta.ParentInterface;
                if (@hasDecl(ParentType, "Meta")) {
                    // Get parent template from registry (or create and register it)
                    // This ensures the SAME template is used for both the parent's global
                    // constructor and for inheritance, which is CRITICAL for instanceof to work.
                    const parent_name = ParentType.Meta.name;
                    const cached = template_registry.getTemplate(parent_name);
                    const parent_template = cached orelse blk: {
                        const ParentBinding = V8Interface(ParentType);
                        const new_template = ParentBinding.createTemplate(isolate);
                        template_registry.register(parent_name, new_template, isolate);
                        break :blk new_template;
                    };

                    // Set up prototype chain - BEFORE registering methods
                    v8.v8_FunctionTemplate_Inherit(template, parent_template);
                }
            } else if (comptime @typeInfo(@TypeOf(Meta.BaseType)) == .optional) {
                // BaseType is ?type - check if it's non-null
                if (comptime Meta.BaseType) |BaseType| {
                    // Fallback: check if BaseType is a pointer to an interface (for backwards compatibility)
                    const BaseTypeInfo = @typeInfo(BaseType);
                    if (BaseTypeInfo == .pointer) {
                        const ChildType = BaseTypeInfo.pointer.child;
                        if (@hasDecl(ChildType, "Meta")) {
                            // Get parent template from registry (or create and register it)
                            const parent_name = ChildType.Meta.name;
                            const parent_template = template_registry.getTemplate(parent_name) orelse blk: {
                                const ParentBinding = V8Interface(ChildType);
                                const new_template = ParentBinding.createTemplate(isolate);
                                template_registry.register(parent_name, new_template, isolate);
                                break :blk new_template;
                            };

                            // Set up prototype chain - BEFORE registering methods
                            v8.v8_FunctionTemplate_Inherit(template, parent_template);
                        }
                    }
                }
            }

            // Per WebIDL spec §3.8, all objects in the global prototype chain must have
            // immutable [[Prototype]]. Object.setPrototypeOf(globalThis, {}) must throw TypeError.
            // Most interfaces get immutable prototypes.
            // Exception: DOMException (special case per WebIDL spec)
            // Exception: Window - we need to modify Window.prototype's [[Prototype]] after creation
            //   to insert WindowProperties into the chain. Immutability is set in window_properties.zig
            //   AFTER the chain is set up.
            const has_immutable_proto = comptime !(std.mem.eql(u8, interface_name, "DOMException") or
                std.mem.eql(u8, interface_name, "Window"));

            if (has_immutable_proto) {
                v8.v8_ObjectTemplate_SetImmutableProto(proto_tmpl);
            }

            // HTML "Location object setup" adds valueOf and @@toPrimitive.
            // Member placement itself follows WebIDL metadata below.
            if (comptime std.mem.eql(u8, interface_name, "Location")) v8.v8_ObjectTemplate_SetLocationValueOfAndToPrimitive(instance_tmpl);

            registerInheritedUnforgeables(isolate, template, instance_tmpl);
            registerEagerProperties(isolate, instance_tmpl, proto_tmpl, false);

            // Register constants on prototype template
            // This allows instance.CONSTANT to work (e.g., xhr.UNSENT)
            // Per WebIDL spec, constants must be available on both constructor AND instances
            if (@hasDecl(Meta, "constants")) {
                inline for (Meta.constants) |proto_const| {
                    const proto_const_name: []const u8 = proto_const[0];
                    if (comptime hasExposureOverride(Interface, proto_const_name, false)) continue;
                    const proto_getter_name: []const u8 = proto_const[1];

                    // Get constant value at comptime
                    const proto_const_value = @field(Interface, proto_getter_name)();

                    // Create V8 number for constant value
                    const proto_v8_value = v8.v8_Number_New(isolate, @floatFromInt(proto_const_value));
                    defer v8.v8_Value_Dispose(@ptrCast(proto_v8_value));

                    // Create string for constant name
                    const proto_name_str = v8.v8_String_NewFromUtf8(
                        isolate,
                        proto_const_name.ptr,
                        @intCast(proto_const_name.len),
                    );

                    if (proto_name_str) |proto_const_name_v8| {
                        // ObjectTemplate::Set keeps the key and value itself.
                        defer v8.v8_String_Dispose(proto_const_name_v8);
                        // Set constant on prototype template with correct attributes
                        // V8 PropertyAttribute flags:
                        //   None = 0, ReadOnly = 1, DontEnum = 2, DontDelete = 4
                        // Per WebIDL spec, constants must be:
                        //   writable: false (ReadOnly), enumerable: true (!DontEnum), configurable: false (DontDelete)
                        // So: ReadOnly (1) | DontDelete (4) = 5
                        v8.v8_ObjectTemplate_SetWithAttributes(
                            proto_tmpl,
                            @ptrCast(proto_const_name_v8),
                            @ptrCast(proto_v8_value),
                            5, // ReadOnly | DontDelete (enumerable = true)
                        );
                    }
                }
            }

            // Register indexed property handler if interface has call_item with u32 parameter
            // This enables array-like access: obj[0], obj[1], etc.
            // WebIDL interfaces with "getter" operations support bracket notation
            // Examples: HTMLCollection, NodeList, DOMTokenList (all have "getter Element? item()")
            //
            // Note: This is separate from iterable support. An interface can have:
            // - call_item only (like HTMLCollection): supports obj[0] but not for...of
            // - iterable only: supports for...of but not obj[0]
            // - both: supports both features
            //
            // The indexed getter Meta.special_operations names (specialBinding).
            const has_indexed_item = has_indexed_getter;
            // Check if interface has get_length for enumerator support
            const has_length = comptime @hasDecl(Interface, "get_length");
            if (has_indexed_item) {
                if (has_length) {
                    // Use full indexed property handler with query and descriptor callbacks
                    v8.v8_ObjectTemplate_SetIndexedPropertyHandlerWithDefiner(
                        instance_tmpl,
                        indexedPropertyGetter,
                        if (has_indexed_setter) indexedPropertySetter else indexedPropertySetterReadOnly,
                        indexedPropertyQuery,
                        indexedPropertyDeleter,
                        indexedPropertyEnumerator,
                        indexedPropertyDefiner,
                        indexedPropertyDescriptor,
                    );
                } else {
                    // No length property - just use getter without enumerator
                    v8.v8_ObjectTemplate_SetIndexedPropertyHandler(
                        instance_tmpl,
                        indexedPropertyGetter,
                    );
                }
            }

            // WebIDL §3.7.9 "define the iteration methods", step 1: an
            // interface with an indexed property getter - HTMLCollection,
            // NamedNodeMap, HTMLFormControlsCollection, NodeList - takes
            // %Array.prototype.values% as its %Symbol.iterator%, so
            // `[...el.children]` and `for (const x of form.elements)` work.
            // An anonymous indexed getter, `getter T (unsigned long)`, counts
            // once its impl implements it (`has_indexed_getter`). A value
            // iterator is declared only where there is an indexed getter
            // (2.5.9), and step 1.2 gives it %Array.prototype.entries%,
            // keys, values and forEach as well: the realm's own function
            // objects (`NodeList.prototype.forEach === Array.prototype.forEach`),
            // which an intrinsic data property of the template resolves in
            // each context it is instantiated in. Blink installs the same
            // intrinsics (bind_gen/interface.py, "Value iterator's
            // properties"). A pair iterator's members are setUpPrototype's.
            // None of it for a [Global] interface: "create an interface
            // prototype object" step 12 defines the iteration methods only
            // when the interface is not declared [Global] - Window's indexed
            // getter (its WindowProxy's child navigables) makes no
            // `Window.prototype[Symbol.iterator]`, as in Blink.
            if (!is_global_interface and (has_indexed_item or has_value_iterator)) {
                v8.v8_ObjectTemplate_SetIteratorToArrayValues(proto_tmpl);
            }
            if (!is_global_interface and has_value_iterator) {
                v8.v8_ObjectTemplate_SetValueIteratorToArrayMethods(proto_tmpl);
            }

            // WebIDL 3.9: the named property handler of a legacy platform
            // object with a named getter (Meta.special_operations, through
            // specialBinding: never for a [Global] interface, whose named
            // properties are its named properties object's). Its names come
            // from the generated getSupportedPropertyNames. It masks the
            // prototype chain with [LegacyOverrideBuiltIns] (3.4.7) on the
            // interface or an ancestor, and for CSSStyleDeclaration's CSS
            // attributes (computed style answers every property, and
            // CSS2Properties-style accessors may sit on a prototype).
            if (has_named_getter) {
                v8.v8_ObjectTemplate_SetNamedPropertyHandlerWithDefiner(
                    instance_tmpl,
                    namedPropertyGetter,
                    if (has_named_setter) namedPropertySetter else namedPropertySetterReadOnly,
                    namedPropertyQuery,
                    namedPropertyDeleter,
                    // [[OwnPropertyKeys]] lists the names unless every
                    // browser leaves them out (Blink: no enumerator for a
                    // [NotEnumerable] named getter).
                    if (special.named_properties_in_own_keys) namedPropertyEnumerator else null,
                    namedPropertyDefiner,
                    namedPropertyDescriptor,
                    if (named_properties_mask) .kOnlyInterceptStrings else .kNonMaskingAndOnlyInterceptStrings,
                );
            }
            // Named properties and no indexed ones: an array index is a
            // String P (3.9) that V8 hands to the indexed interceptors, which
            // run the named steps with its text. No enumerator: the named
            // one lists every supported name, an index-like key included.
            if (forwards_indices) {
                v8.v8_ObjectTemplate_SetIndexedPropertyHandlerWithDefiner(
                    instance_tmpl,
                    forwardedIndexGetter,
                    forwardedIndexSetter,
                    forwardedIndexQuery,
                    forwardedIndexDeleter,
                    null,
                    forwardedIndexDefiner,
                    forwardedIndexDescriptor,
                );
            }

            // Register only own methods on prototype (not inherited methods)
            // Inherited methods are accessible via V8's prototype chain
            //
            // Build a comptime hash set of own method names for O(1) lookup
            // Hash set construction and lookup still require comptime string comparisons
            @setEvalBranchQuota(10000);

            const own_method_names = if (@hasDecl(Meta, "own_methods")) Meta.own_methods else &.{};
            const OwnMethodSet = std.StaticStringMap(void);
            const own_method_set = comptime blk: {
                var entries: [own_method_names.len]struct { []const u8, void } = undefined;
                for (own_method_names, 0..) |method_name, i| {
                    entries[i] = .{ method_name, {} };
                }
                break :blk OwnMethodSet.initComptime(entries);
            };

            // Register only methods that are in the own_method_set
            inline for (methods) |method| {
                const method_name: []const u8 = method[0];
                const zig_name: []const u8 = method[1];
                const arity: c_int = if (method.len >= 3) method[2] else 0;

                // Skip "values" for async iterable interfaces - it's registered separately
                // with the asyncIteratorCallback which properly wraps async iterators
                const is_async_iterable_values = comptime (@hasDecl(Meta, "async_iterable") and
                    std.mem.eql(u8, method_name, "values"));

                // If we have own_methods, check membership; otherwise register all.
                // A [Global] interface's are the global object's own instead
                // (members_on_global_object).
                const should_register = comptime (!members_on_global_object and !is_async_iterable_values and
                    (own_method_names.len == 0 or own_method_set.has(method_name)));

                if (should_register) {
                    // Pass zig_name as comptime parameter to generate proper callback
                    // Also pass template for signature-based receiver type checking
                    // [LegacyUnforgeable] operations: { [[Writable]]: false,
                    // [[Configurable]]: false }, on the instance.
                    const unforgeable = comptime isUnforgeableMember(method_name);
                    if (comptime unforgeable and hasExposureOverride(Interface, method_name, false)) continue;
                    registerMethod(zig_name, method_name, isolate, template, if (unforgeable) instance_tmpl else proto_tmpl, arity, if (unforgeable) v8.PropertyAttribute.ReadOnly | v8.PropertyAttribute.DontDelete else v8.PropertyAttribute.None);
                }
            }

            // NOTE: Inheritance is now set up earlier (before method registration)
            // per Chromium's pattern. See the INHERITANCE SETUP section above.

            // TODO: Handle mixins

            // Skip caching in snapshot mode - prevents V8's "CheckGlobalAndEternalHandles failed"
            // In snapshot mode, templates are created as Local handles and not stored in Zig caches.
            if (template_registry.snapshot_mode) {
                return template;
            }

            // Cache the template in the isolate's own storage (cleaned up
            // with the isolate).
            if (isolate_alloc.getIsolateAllocator(isolate)) |alloc| {
                if (isolate_templates.getOrCreateTemplateStorage(isolate, alloc) catch null) |storage| {
                    storage.put(interface_name, template) catch {};
                }
            }

            return template;
        }

        /// WebIDL 3.8 step 11: define inherited unforgeables on each instance.
        /// V8 13.1 api-natives.cc ConfigureInstance inherits native AccessorInfo
        /// entries, but copies the JS accessor property_list only from this
        /// template. SetAccessorProperty's entries therefore need installing
        /// explicitly with their defining interface's callbacks.
        fn registerInheritedUnforgeables(isolate: *v8.Isolate, template: *v8.FunctionTemplate, instance_tmpl: *v8.ObjectTemplate) void {
            if (@hasDecl(Meta, "ParentInterface")) {
                const ParentBinding = V8Interface(Meta.ParentInterface);
                ParentBinding.registerInheritedUnforgeables(isolate, template, instance_tmpl);
                ParentBinding.registerEagerProperties(isolate, instance_tmpl, instance_tmpl, true);
                ParentBinding.registerOwnUnforgeableMethods(isolate, template, instance_tmpl);
            }
        }

        fn registerOwnUnforgeableMethods(isolate: *v8.Isolate, template: *v8.FunctionTemplate, instance_tmpl: *v8.ObjectTemplate) void {
            inline for (methods) |method| {
                if (comptime isUnforgeableMember(method[0]) and !hasExposureOverride(Interface, method[0], false)) {
                    registerMethod(method[1], method[0], isolate, template, instance_tmpl, if (method.len >= 3) method[2] else 0, v8.PropertyAttribute.ReadOnly | v8.PropertyAttribute.DontDelete);
                }
            }
        }

        fn registerEagerProperties(isolate: *v8.Isolate, instance_tmpl: *v8.ObjectTemplate, proto_tmpl: *v8.ObjectTemplate, comptime only_unforgeable: bool) void {
            // Register EAGER properties as accessors on prototype (defined upfront)
            // eager_properties is tuple array: .{ "propName", "get_propName", "set_propName" or null }
            // IMPORTANT: Use callbacks from EagerCallbackStore - SAME callbacks registered in registerExternalReferences()
            inline for (eager_properties, 0..) |prop, prop_idx| {
                // A [Global] interface's are the global object's own instead
                // (members_on_global_object).
                if (comptime members_on_global_object) continue;
                const prop_name: []const u8 = prop[0];
                const unforgeable = comptime isUnforgeableMember(prop_name);
                if (comptime unforgeable and hasExposureOverride(Interface, prop_name, false)) continue;
                if (comptime only_unforgeable and !unforgeable) continue;

                const prop_name_str = v8.v8_String_NewFromUtf8(
                    isolate,
                    prop_name.ptr,
                    @intCast(prop_name.len),
                ).?;
                // SetAccessorProperty reads it as a Local; the template keeps its own.
                defer v8.v8_String_Dispose(prop_name_str);

                // Use callback from static store - SAME callback registered in registerExternalReferences()
                // This ensures V8 snapshot restoration can reconnect the callback correctly
                const getter_cb: v8.FunctionCallback = EagerCallbackStore.getters[prop_idx];

                // Check if this property has [PutForwards] extended attribute
                // Per WebIDL spec §4.3.10: setting the attribute forwards to a property on the value
                const put_forwards_target: ?[]const u8 = comptime blk: {
                    if (!@hasDecl(Meta, "put_forwards_attributes")) break :blk null;
                    for (Meta.put_forwards_attributes) |pf| {
                        if (std.mem.eql(u8, pf[0], prop_name)) {
                            break :blk pf[1]; // The forwarded property name
                        }
                    }
                    break :blk null;
                };

                // Generate setter callback - use PutForwards setter if applicable, otherwise use stored callback
                const setter_cb: ?v8.FunctionCallback = if (put_forwards_target) |forward_prop|
                    // Use PutForwards setter that uses JavaScript [[Get]]/[[Set]] semantics
                    PutForwardsSetterCallback(prop_name, forward_prop).callback
                else
                    // Use setter from static store (null if read-only)
                    EagerCallbackStore.setters[prop_idx];

                // Use SetAccessorProperty instead of SetAccessor to create visible descriptors
                // This makes the getter/setter appear in Object.getOwnPropertyDescriptor.
                // Each function runs WebIDL's security check for a
                // cross-origin `this` unless HTML lists it (cross_origin.zig).
                v8.v8_ObjectTemplate_SetAccessorPropertyChecked(
                    if (unforgeable) instance_tmpl else proto_tmpl,
                    prop_name_str,
                    getter_cb,
                    setter_cb,
                    comptime acceptsAnyReceiver(prop_name, .getter),
                    comptime acceptsAnyReceiver(prop_name, .setter),
                    // [LegacyUnforgeable]: { [[Configurable]]: false }.
                    if (unforgeable) v8.PropertyAttribute.DontDelete else v8.PropertyAttribute.None,
                );
            }
        }

        /// WebIDL 3.7.6/3.7.7: unannotated members remain on the prototype.
        fn isUnforgeableMember(comptime member_name: []const u8) bool {
            if (!@hasDecl(Meta, "unforgeable_members")) return false;
            inline for (Meta.unforgeable_members) |member| {
                if (comptime std.mem.eql(u8, member, member_name)) return true;
            }
            return false;
        }

        /// Check if a property name is in the [LegacyLenientThis] attributes list
        /// Per WebIDL §4.3.10: [LegacyLenientThis] attributes do NOT throw TypeError
        /// when called with invalid `this` values - getters return undefined, setters silently return.
        fn isLenientThisProperty(comptime prop_name: []const u8) bool {
            if (!@hasDecl(Meta, "lenient_this_attributes")) return false;
            const lenient_attrs = Meta.lenient_this_attributes;
            inline for (lenient_attrs) |attr_name| {
                if (std.mem.eql(u8, attr_name, prop_name)) return true;
            }
            return false;
        }

        /// Check if a type is a pointer to runtime.Instance (handles typedefs like WindowProxy)
        /// This is needed because type aliases from different modules may not compare equal
        /// with direct == comparison at comptime.
        fn isRuntimeInstancePtr(comptime T: type) bool {
            const type_info = @typeInfo(T);
            if (type_info != .pointer) return false;
            // Check if it's a pointer to runtime.Instance by comparing child type
            return type_info.pointer.child == runtime.Instance;
        }

        /// Check if a type is an optional pointer to runtime.Instance
        fn isOptionalRuntimeInstancePtr(comptime T: type) bool {
            const type_info = @typeInfo(T);
            if (type_info != .optional) return false;
            const child_info = @typeInfo(type_info.optional.child);
            if (child_info != .pointer) return false;
            return child_info.pointer.child == runtime.Instance;
        }

        /// Check if a type is an optional callback type (like EventHandler = ?*const fn(...))
        /// A value of one holds the function's Global<Value>* (conversions.zig), so a
        /// getter returning one needs special handling for return value conversion.
        /// A union the getter converts through conv.toV8Value - a tagged
        /// one, other than the string and `any` types, which are unions in
        /// Zig but values of their own here.
        fn isUnionResult(comptime T: type) bool {
            const info = @typeInfo(T);
            if (info != .@"union" or info.@"union".tag_type == null) return false;
            return T != runtime.DOMString and T != runtime.JSValue;
        }

        fn isOptionalCallbackType(comptime T: type) bool {
            const type_info = @typeInfo(T);
            if (type_info != .optional) return false;

            const child_info = @typeInfo(type_info.optional.child);
            if (child_info != .pointer) return false;

            const ptr_child_info = @typeInfo(child_info.pointer.child);
            return ptr_child_info == .@"fn";
        }

        /// The Window of the realm a [Global] accessor or operation belongs to.
        ///
        /// V8 calls a global's accessors and operations with the global PROXY as
        /// `this`, and the proxy's internal field names the Window it is attached
        /// to now. A navigation that makes a new Window reattaches the proxy, so
        /// for code left behind in the old realm - an unload handler, a timer, a
        /// function another window kept - the field names the NEW Window, while
        /// an unqualified `document` there resolves on the old realm's own global
        /// object (the old Window) by the spec. Blink reads the holder, the global
        /// object itself; here the context manager records each realm's Window.
        /// For an attached realm both answers are the same Window.
        /// HTML: "The window, frames, and self getter steps are to return
        /// this's relevant realm.[[GlobalEnv]].[[GlobalThisValue]]" - the
        /// WindowProxy, which the getter's own realm answers without its
        /// Window: when `this` is that realm's global, its global this value
        /// is the context's global proxy. `self` and `frames` are own data
        /// properties holding it already; `window` is an accessor, and a
        /// removed frame's realm ends (engine.WindowRealmEnd.
        /// navigable_destroyed) with its global still attached but its Window
        /// freed, so looking the Window up made `w.window` throw where
        /// `w.self` answered (self-et-al.window.js). Answers false for any
        /// other `this`, which the generic path brand-checks.
        fn answerWindowGetter(info: *const v8.FunctionCallbackInfo) bool {
            const isolate = info.getIsolate();
            // V8 enters the getter's creation context: the method's realm.
            const method_ctx = v8.v8_Isolate_GetCurrentContext(isolate) orelse return false;
            defer v8.v8_Context_Dispose(method_ctx);
            const method_global = v8.v8_Context_Global(method_ctx) orelse return false;
            defer v8.v8_Object_Dispose(method_global);
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            if (!v8.v8_Value_StrictEquals(@ptrCast(this_obj), @ptrCast(method_global))) return false;
            // Copied into the return value; ours is released above.
            info.setReturnValue(@ptrCast(method_global));
            return true;
        }

        fn realmWindow(method_ctx: *v8.Context, method_global: *v8.Object) ?*anyopaque {
            if (@import("context_manager.zig").getWindowForContext(method_ctx)) |window| return @ptrCast(window);
            return v8.v8_Object_GetAlignedPointerFromInternalField(method_global, 0);
        }

        /// The Window of `this_obj` when it is a realm's global object - its
        /// creation context's WindowProxy - or null for any other object.
        fn globalReceiverWindow(this_obj: *v8.Object) ?*anyopaque {
            const this_ctx = v8.v8_Object_GetCreationContext(this_obj) orelse return null;
            defer v8.v8_Context_Dispose(this_ctx);
            const this_global = v8.v8_Context_Global(this_ctx) orelse return null;
            // Owned, and only compared and read here.
            defer v8.v8_Object_Dispose(this_global);
            if (!v8.v8_Value_StrictEquals(@ptrCast(this_obj), @ptrCast(this_global))) return null;
            return realmWindow(this_ctx, this_global);
        }

        /// WebIDL 3.7.6 attribute getter and setter step 1: "If O is not a
        /// platform object that implements the interface, throw a TypeError"
        /// ([LegacyLenientThis]: return undefined). The receiver checks in
        /// the accessor callbacks read WrapperTypeInfo, which
        /// `wrapper_type_info_registry` never supplies and `dom_type_info`
        /// supplies for 24 interfaces, so every other wrapper - and every
        /// constructor-made one - was unwrapped unchecked, and
        /// `HTMLInputElement.value` answered for a textarea. The state
        /// ancestry is the brand, as it is for operations (MethodCallback)
        /// and for an interface-typed value (`conv.implements`). A vtable
        /// with no ancestry implements nothing: it passed as everything, but
        /// every generated vtable has one (runtime.buildVTable) - only a
        /// test's hand-made vtable lacks it.
        fn implementsInterface(instance: *const runtime.Instance) bool {
            if (comptime !@hasDecl(Interface, "State")) return true;
            return conv.implements(instance, Interface);
        }

        /// Generate a property getter callback for a specific property at comptime
        ///
        /// This creates a callback that:
        /// 1. Gets the Zig Instance from V8 object's internal field
        /// 2. Calls the getter function (either static or instance)
        /// 3. Converts and returns the result to V8
        ///
        /// The iface_name parameter ensures that each interface gets unique function objects
        /// for its attributes, as required by WebIDL spec.
        fn PropertyGetterCallback(comptime iface_name: []const u8, comptime getter_name: []const u8) type {
            return struct {
                pub fn callback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
                    // Use compile-time debug logging to avoid runtime overhead
                    // This is called on every property access, so must be zero-cost when disabled
                    debug.print("[PropertyGetterCallback] Called for {s}.{s}\n", .{ iface_name, getter_name });

                    const zig_getter = @field(Interface, getter_name);
                    const isolate_inner = info.getIsolate();

                    // The realm a thrown error is made in. WebIDL: "throw a TypeError
                    // using the function's realm" - the getter's creation context, or
                    // the current one when V8 knows none. Only the throwing paths use
                    // it, and each is a fresh Global<Context> the caller owns, so it
                    // is taken on the first throw, not on every call: taken eagerly,
                    // the two were made and disposed per `list.length` - a third of
                    // the binding's cost in a profile of NodeList-static-length-
                    // getter-tampered-1.html (2026-10-01). Released on every exit
                    // (the per-element context leak this once was: 1.00 per
                    // createElement, one per `document` / `el.id` read).
                    const ErrorRealm = struct {
                        info: *const v8.FunctionCallbackInfo,
                        isolate: *v8.Isolate,
                        owned: ?*v8.Context = null,

                        fn get(self: *@This()) ?*v8.Context {
                            if (self.owned == null) {
                                self.owned = self.info.getFunctionCreationContext() orelse
                                    v8.v8_Isolate_GetCurrentContext(self.isolate);
                            }
                            return self.owned;
                        }

                        fn throwTypeError(self: *@This(), message: []const u8) void {
                            if (self.get()) |realm| {
                                conv.throwTypeErrorFromContext(self.isolate, realm, message);
                            } else {
                                conv.throwError(self.isolate, message);
                            }
                        }

                        fn release(self: *@This()) void {
                            if (self.owned) |c| v8.v8_Context_Dispose(c);
                            self.owned = null;
                        }
                    };
                    var error_realm: ErrorRealm = .{ .info = info, .isolate = isolate_inner };
                    defer error_realm.release();

                    // WebIDL attribute getter 1.1.2.2 / HTML 7.2.1.1: a
                    // Proxy's borrowed getter must check its platform target.
                    if (comptime std.mem.eql(u8, iface_name, "Location") and
                        !acceptsAnyReceiver(getter_name["get_".len..], .getter))
                    {
                        if (!cross_origin.receiverIsAccessible(info)) {
                            if (error_realm.get()) |realm| conv.throwWebIDLErrorFromContext(isolate_inner, realm, "SecurityError");
                            return;
                        }
                    }

                    // Check return type
                    const fn_info = @typeInfo(@TypeOf(zig_getter)).@"fn";
                    const ReturnType = fn_info.return_type.?;

                    // Skip void return types (skipped properties)
                    if (ReturnType == void) {
                        conv.throwError(isolate_inner, "Property not implemented");
                        return;
                    }

                    // Check if getter takes an instance argument
                    const params = fn_info.params;
                    if (params.len == 0) {
                        // Static getter (constants)
                        const result = zig_getter();
                        const v8_num = conv.toV8Long(isolate_inner, @intCast(result));
                        info.setReturnValue(@ptrCast(v8_num));
                    } else {
                        // `window` needs no Window (see answerWindowGetter).
                        if (comptime is_global_interface and std.mem.eql(u8, getter_name, "get_window")) {
                            if (answerWindowGetter(info)) return;
                        }

                        // Derive property name from getter_name (strip "get_" prefix)
                        const prop_name = comptime blk: {
                            if (getter_name.len > 4 and std.mem.eql(u8, getter_name[0..4], "get_")) {
                                break :blk getter_name[4..];
                            }
                            break :blk getter_name;
                        };

                        // Instance getter - extract instance from 'this' and call.
                        //
                        // A handle for `this` only where one is used: a [Global]
                        // interface compares it with globals and asks its
                        // creation context, and a [SameObject] attribute draws an
                        // edge from it. Every other getter reads the receiver's
                        // internal fields from `info` (ThisInstanceFields), which
                        // makes no handle: the Global, made and disposed per read,
                        // was most of `list.length` in NodeList-static-length-
                        // getter-tampered-[123].html (~6e7 reads each).
                        const needs_this_handle = comptime is_global_interface or stateCachesSameObject("cached_" ++ prop_name);
                        const this_handle: ?*v8.Object = if (needs_this_handle) info.getThis() else null;
                        defer if (this_handle) |held| v8.v8_Object_Dispose(held);

                        // Check if this is a [LegacyLenientThis] attribute
                        // Per WebIDL §4.3.10: these attributes do NOT throw TypeError on invalid this
                        // Instead, getters return undefined
                        const is_lenient_this = comptime isLenientThisProperty(prop_name);

                        // For [Global] interfaces (like Window), we need special handling:
                        // Per WebIDL §3.8, if this is null/undefined, use the method's global object.
                        //
                        // The challenge is that when getter.call(null) is used:
                        // - V8 may coerce null to the CALLER's global in sloppy mode
                        // - But we need to use the METHOD's global (where the getter was defined)
                        //
                        // Solution: For [Global] interfaces, ALWAYS use the method's global object.
                        // This is correct because:
                        // 1. window.name -> this is method's global -> use it
                        // 2. otherNameGetter.call(null) -> should use method's global
                        // 3. otherNameGetter.call(wrongObject) -> should throw from method's realm
                        //
                        // Case 3 is handled by checking if the this object is the method's global.
                        // If it's not, we throw TypeError.
                        const resolved_instance: ?*anyopaque = blk: {
                            if (is_global_interface) {
                                const this_obj = this_handle.?;
                                // Get the method's context - V8 enters the function's creation context
                                if (v8.v8_Isolate_GetCurrentContext(isolate_inner)) |method_ctx| {
                                    // The last of the two per-element context leaks that
                                    // `leaks --atExit` named. This branch runs for [Global]
                                    // interfaces, so every `window.document` read reached it
                                    // and abandoned a Global<Context>: 31,597 per 200,000
                                    // cycles, 1.00 per createElement.
                                    //
                                    // Safe to release, and provably so rather than hopefully:
                                    // `method_ctx` appears on exactly two lines - this one and
                                    // the call below - and `v8_Context_Global` reads it into a
                                    // Local and returns a FRESH Global<Object> built from
                                    // `local_context->Global()`. It keeps no pointer to the
                                    // context. That is the distinction from the disposes
                                    // reverted in 5abd41550 and 6c64a3925, where the callee's
                                    // retention was never established.
                                    defer v8.v8_Context_Dispose(method_ctx);
                                    if (v8.v8_Context_Global(method_ctx)) |method_global| {
                                        // Owned: v8_Context_Global allocates where V8's Context::Global()
                                        // returns a borrowed Local. Everything below only compares it or
                                        // reads an internal field, so releasing at block exit is correct.
                                        defer v8.v8_Object_Dispose(method_global);
                                        // Check if this IS the method's global object
                                        // (handles normal case: window.name where this === window)
                                        if (v8.v8_Value_StrictEquals(@ptrCast(this_obj), @ptrCast(method_global))) {
                                            const global_ptr = realmWindow(method_ctx, method_global);
                                            if (global_ptr != null) {
                                                break :blk global_ptr;
                                            }
                                        }

                                        // this is NOT the method's global - could be:
                                        // 1. getter.call(null) -> V8 coerced to caller's global
                                        // 2. getter.call(wrongObject) -> explicit wrong this
                                        //
                                        // Per WebIDL, we should use the method's global for case 1,
                                        // and throw TypeError for case 2.
                                        //
                                        // How to distinguish? Check if this_obj has internal field 0
                                        // pointing to a valid Window instance. If not, it's case 1.
                                        // If yes but it's a DIFFERENT window, it's case 2.
                                        const this_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(this_obj, 0);

                                        if (this_ptr == null) {
                                            // No internal field -> this is NOT a valid global object
                                            // (globals always have internal fields pointing to Window instance)
                                            //
                                            // This happens for Object.create(Window.prototype) or other
                                            // incompatible objects. Per WebIDL §3.8, we must throw TypeError.
                                            //
                                            // Note: if getter.call(null) is used, V8 coerces null to
                                            // the caller's global in sloppy mode, which DOES have internal
                                            // fields. So this_ptr == null means it's definitely NOT
                                            // a coerced null - it's an incompatible object.
                                            //
                                            // Fall through to throw TypeError
                                        } else {
                                            // `this` has a Window field: when it is a global
                                            // object - another realm's WindowProxy - the
                                            // attribute acts on THAT window (WebIDL 3.7.6:
                                            // O is `this`; a null `this` V8 already made the
                                            // function's own global). A cross-origin one got
                                            // here only for a member HTML lets through
                                            // (cross_origin.acceptsAnyReceiver).
                                            if (globalReceiverWindow(this_obj)) |this_window| break :blk this_window;

                                            // this is not a global object but has Window internal field
                                            // This is Object.create(Window.prototype) case -> throw TypeError
                                        }
                                    }
                                }
                                // Fall through to throw TypeError
                            } else {
                                // Non-[Global] interface: use normal this handling
                                //
                                // We MUST verify that `this` is actually an instance of this interface
                                // BEFORE using the internal field pointer. This is critical because in
                                // sloppy mode, `getter.call(null)` coerces null to the global object (Window),
                                // which HAS internal fields but is NOT an instance of this interface.
                                // Without this check, we'd pass the Window's internal pointer to the getter,
                                // causing InvalidStateError instead of the correct TypeError.
                                //
                                // Per WebIDL spec:
                                // - For regular attributes: throw TypeError if `this` is not a valid instance
                                // - For [LegacyLenientThis]: return undefined if `this` is not a valid instance

                                // CROSS-REALM SUPPORT: Use internal slot checking instead of HasInstance.
                                // HasInstance uses prototype chain which fails across realms because
                                // different realms have different prototype objects even for same interface.
                                // Internal slot (WrapperTypeInfo in slot 1) works across realms because
                                // it's tied to the Zig type system, not the JavaScript prototype chain.
                                //
                                // Per WebIDL spec, type checking should be done via internal slots:
                                // "If the this value is null or undefined, or is not a platform object
                                // that implements the interface, then throw a TypeError"
                                // Use comptime-generated registry which has ALL interfaces
                                const wrapper_type_info_registry = @import("wrapper_type_info_registry.zig");
                                if (wrapper_type_info_registry.getWrapperTypeInfoByName(interface_name)) |expected_type| {
                                    const this_obj = info.getThis();
                                    defer v8.v8_Object_Dispose(this_obj);
                                    if (getInstanceTypeSafe(runtime.Instance, this_obj, expected_type)) |inst| {
                                        break :blk @ptrCast(inst);
                                    }
                                    // Type check failed - not an instance of this interface
                                    if (is_lenient_this) {
                                        // [LegacyLenientThis] - return undefined per WebIDL §4.3.10
                                        conv.setReturnUndefined(info);
                                        return;
                                    }
                                    // Regular attribute - fall through to throw TypeError
                                } else {
                                    // Type info not found via comptime lookup - check WrapperTypeInfo in slot 1
                                    // (read from `info` with slot 0, as getWrapperTypeInfo and
                                    // getInstance read them from a handle)
                                    var this_instance: ?*anyopaque = null;
                                    var this_type_info: ?*anyopaque = null;
                                    v8.FunctionCallbackInfo.v8_FunctionCallbackInfo_ThisInstanceFields(info, &this_instance, &this_type_info);
                                    if (if (this_type_info) |ptr| @as(?*const WrapperTypeInfo, @ptrCast(@alignCast(ptr))) else null) |stored_type_info| {
                                        // WrapperTypeInfo is present - use it for type checking
                                        // Per WebIDL spec: "If the this value is null or undefined, or is not a
                                        // platform object that implements the interface, then throw a TypeError"
                                        //
                                        // IMPORTANT: Check inheritance chain, not just exact match!
                                        // E.g., if getter is on Node.prototype and this is HTMLDivElement,
                                        // we need to check if HTMLDivElement inherits from Node.
                                        var current_type: ?*const WrapperTypeInfo = stored_type_info;
                                        const type_matches = while (current_type) |type_info| {
                                            if (std.mem.eql(u8, type_info.getName(), interface_name)) {
                                                break true;
                                            }
                                            current_type = type_info.parent;
                                        } else false;

                                        if (type_matches) {
                                            // Type matches (including inheritance) - get instance pointer from slot 0
                                            const instance_ptr = this_instance;
                                            if (instance_ptr != null) {
                                                break :blk instance_ptr;
                                            }
                                        }
                                        // Type mismatch - fall through to throw TypeError
                                    } else {
                                        // No WrapperTypeInfo in slot 1 - fall back to legacy getInstance check
                                        const instance_ptr = this_instance;
                                        if (instance_ptr != null) {
                                            break :blk instance_ptr;
                                        }
                                    }
                                    // [LegacyLenientThis] - return undefined instead of throwing
                                    if (is_lenient_this) {
                                        conv.setReturnUndefined(info);
                                        return;
                                    }
                                }
                            }

                            // [LegacyLenientThis] on a [Global] interface (Window's
                            // onmouseenter, onmouseleave): `this` is no Window -
                            // return undefined (WebIDL 3.7.6 step 1.2.1).
                            if (is_lenient_this) {
                                conv.setReturnUndefined(info);
                                return;
                            }

                            // Throw TypeError from getter's realm (function's creation context)
                            // Per WebIDL spec: "Throw a TypeError using the function's realm."
                            error_realm.throwTypeError("Illegal invocation");

                            return;
                        };

                        // Shouldn't happen - we either have a valid instance or returned above
                        if (resolved_instance == null) {
                            error_realm.throwTypeError("Illegal invocation");
                            return;
                        }

                        // Safety check: detect use-after-free by checking for poison patterns
                        // Common allocator poison values: 0xaaaa... (freed), 0xdead... (deleted)
                        const ptr_as_int = @intFromPtr(resolved_instance.?);
                        const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
                        const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
                        if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
                            (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
                        {
                            // Instance was freed - return undefined to prevent crash
                            conv.setReturnUndefined(info);
                            return;
                        }

                        const instance: *runtime.Instance = @ptrCast(@alignCast(resolved_instance.?));

                        if (!implementsInterface(instance)) {
                            const lenient = comptime isLenientThisProperty(if (std.mem.startsWith(u8, getter_name, "get_")) getter_name[4..] else getter_name);
                            if (lenient) {
                                conv.setReturnUndefined(info);
                            } else {
                                error_realm.throwTypeError("Illegal invocation");
                            }
                            return;
                        }

                        // Additional safety check: validate instance.ctx is not corrupted
                        // This catches cases where the Instance struct was freed but V8 still holds a reference
                        const ctx_as_int = @intFromPtr(instance.ctx);
                        if (ctx_as_int == poison_pattern_aa or ctx_as_int == poison_pattern_dead or
                            (ctx_as_int & 0xFFFF000000000000) == 0xaaaa000000000000 or ctx_as_int == 0)
                        {
                            // Instance was freed - return undefined to prevent crash
                            conv.setReturnUndefined(info);
                            return;
                        }

                        // Deep validation: check if the allocator inside ContextData is valid
                        // The ctx pointer may be valid, but the ContextData contents may be freed
                        const allocator_vtable_int = @intFromPtr(instance.ctx.allocator.vtable);
                        if (allocator_vtable_int == poison_pattern_aa or allocator_vtable_int == poison_pattern_dead or
                            (allocator_vtable_int & 0xFFFF000000000000) == 0xaaaa000000000000 or allocator_vtable_int == 0)
                        {
                            // ContextData was freed - return undefined to prevent crash
                            conv.setReturnUndefined(info);
                            return;
                        }

                        // SPECIAL HANDLING: Window.self and Window.window must return the V8 global object
                        // Per HTML spec, these properties return the WindowProxy which IS the global object.
                        // testharness.js relies on this: (function(global_scope){...})(self)
                        // If we return a wrapped Window instance instead of the actual global, the
                        // exposed functions won't be accessible as global variables.
                        if (comptime is_global_interface and std.mem.eql(u8, iface_name, "Window")) {
                            if (comptime std.mem.eql(u8, getter_name, "get_self") or
                                std.mem.eql(u8, getter_name, "get_window") or
                                std.mem.eql(u8, getter_name, "get_frames"))
                            {
                                // Return info.This() - the actual receiver object
                                // For a property access on the global, this is the global proxy
                                // that JS uses for variable resolution
                                // Owned, like every getThis(): the return value
                                // is a copy, so the handle goes when this returns.
                                // Kept, it leaked one handle to the global per
                                // `window`/`self` read - and a handle to the
                                // global pins its whole page.
                                const global_this = info.getThis();
                                defer v8.v8_Object_Dispose(global_this);
                                info.setReturnValue(@ptrCast(global_this));
                                return;
                            }
                        }

                        // Capture allocator BEFORE calling getter and converting to V8
                        // This prevents use-after-free if V8 operations trigger GC that frees ctx
                        const cleanup_allocator = instance.ctx.allocator;

                        // Determine payload type from return type
                        const return_type_info = @typeInfo(ReturnType);
                        const PayloadType = if (return_type_info == .error_union)
                            return_type_info.error_union.payload
                        else
                            ReturnType;

                        // Call getter (handle error union)
                        const result: PayloadType = if (return_type_info == .error_union)
                            zig_getter(instance) catch |err| {
                                if (err == error.NotImplemented) {
                                    // For WPT constructor tests, don't throw for unimplemented properties
                                    // when they are accessed during global object enumeration
                                    conv.setReturnUndefined(info);
                                    return;
                                }
                                // The error is the getter's realm's - a SecurityError
                                // too (throwMemberError says why): the cross-origin
                                // checks are V8's [cross_origin_objects]. Without them,
                                // a SecurityError is made in the CALLER's (entered)
                                // realm, as the impls' own checks needed. Each context
                                // is a fresh Global, owned, used only to pick the realm.
                                const entered_ctx = if (comptime engine_capabilities.cross_origin_objects == .unsupported)
                                    v8.v8_Isolate_GetEnteredOrMicrotaskContext(isolate_inner)
                                else
                                    null;
                                defer if (entered_ctx) |ctx| v8.v8_Context_Dispose(ctx);
                                const getter_context = error_realm.get();
                                const error_context = if (err == error.SecurityError)
                                    entered_ctx orelse getter_context
                                else
                                    getter_context;
                                if (error_context) |ctx| {
                                    conv.throwWebIDLErrorFromContext(isolate_inner, ctx, @errorName(err));
                                } else {
                                    conv.throwError(isolate_inner, @errorName(err));
                                }
                                return;
                            }
                        else
                            zig_getter(instance);

                        // For string types that allocate memory, free after V8 conversion.
                        // IMPORTANT: Impls MUST use instance.ctx.allocator for returned strings,
                        // not internal.allocator, so this cleanup uses the correct allocator.
                        // Static strings (empty string "") have len=0 and won't be freed.
                        // NOTE: We use cleanup_allocator captured before the getter call to avoid
                        // use-after-free if V8 operations during conversion trigger GC.
                        //
                        // IMPORTANT: Getters that return internal references (not newly allocated)
                        // MUST be updated to dupe the string first, or the cleanup will double-free.
                        // NOTE: JSValue is NOT cleaned up here because getters typically return
                        // internal state references (e.g., MessageEvent.data). Operations that
                        // allocate new JSValue data (like structuredClone) are cleaned up in
                        // callMethodWithArgs instead.
                        // Check for both direct string types and optional string types (?DOMString, etc.)
                        const is_optional_type = comptime @typeInfo(PayloadType) == .optional;
                        const inner_type = comptime if (is_optional_type) @typeInfo(PayloadType).optional.child else PayloadType;
                        const needs_cleanup = comptime (inner_type == runtime.USVString or inner_type == []const u8 or inner_type == runtime.DOMString);

                        defer if (needs_cleanup) {
                            // Re-validate allocator before cleanup - it could have been invalidated
                            const cleanup_vtable_int = @intFromPtr(cleanup_allocator.vtable);
                            const is_poisoned = (cleanup_vtable_int == poison_pattern_aa or
                                cleanup_vtable_int == poison_pattern_dead or
                                (cleanup_vtable_int & 0xFFFF000000000000) == 0xaaaa000000000000 or
                                cleanup_vtable_int == 0);
                            if (!is_poisoned) {
                                // Handle optional types - unwrap first using comptime branching
                                if (comptime is_optional_type) {
                                    if (result) |val| {
                                        if (inner_type == runtime.DOMString) {
                                            var mutable = val;
                                            mutable.deinit(cleanup_allocator);
                                        } else if (inner_type == runtime.USVString or inner_type == []const u8) {
                                            if (val.len > 0) {
                                                cleanup_allocator.free(val);
                                            }
                                        }
                                    }
                                } else {
                                    if (inner_type == runtime.DOMString) {
                                        var mutable = result;
                                        mutable.deinit(cleanup_allocator);
                                    } else if (inner_type == runtime.USVString or inner_type == []const u8) {
                                        if (result.len > 0) {
                                            cleanup_allocator.free(result);
                                        }
                                    }
                                }
                            }
                            // else: Allocator was freed during V8 operations - skip cleanup
                            // This leaks memory but prevents crash. The memory will be
                            // reclaimed when the context/isolate is disposed.
                        };

                        // A number or boolean goes straight into the return
                        // slot: no Global to make and release per read (200,000
                        // v8_Number_New for 200,000 `list.length` reads). The
                        // value is the one the conversions below give: a WebIDL
                        // integer type up to 32 bits as that integer, a 64-bit
                        // one or a float as the double it converts to, a
                        // boolean as itself (WebIDL 3.2.x, "converted to an
                        // ECMAScript value").
                        if (comptime primitiveGetterResult(PayloadType)) {
                            setPrimitiveReturn(info, PayloadType, result);
                            return;
                        }

                        // Convert to V8 using comptime type dispatch
                        const v8_value: *v8.Value = comptime_convert: {
                            if (comptime returnsByteString(Interface, getter_name)) {
                                break :comptime_convert conv.byteStringToV8(PayloadType, isolate_inner, result) catch
                                    (v8.v8_Undefined(isolate_inner) orelse unreachable);
                            }
                            // WebIDL primitive types
                            // Handle all unsigned integer types (u8, u16, u32)
                            if (PayloadType == u32 or PayloadType == runtime.UnsignedLong) {
                                break :comptime_convert @ptrCast(conv.toV8UnsignedLong(isolate_inner, result));
                            } else if (PayloadType == u16) {
                                // WebIDL unsigned short (u16) - convert to u32 for V8
                                break :comptime_convert @ptrCast(conv.toV8UnsignedLong(isolate_inner, @as(u32, result)));
                            } else if (PayloadType == u8) {
                                // WebIDL octet (u8) - convert to u32 for V8
                                break :comptime_convert @ptrCast(conv.toV8UnsignedLong(isolate_inner, @as(u32, result)));
                            } else if (PayloadType == i32 or PayloadType == runtime.Long) {
                                break :comptime_convert @ptrCast(conv.toV8Long(isolate_inner, result));
                            } else if (PayloadType == i16) {
                                // WebIDL short (i16) - convert to i32 for V8
                                break :comptime_convert @ptrCast(conv.toV8Long(isolate_inner, @as(i32, result)));
                            } else if (PayloadType == i8) {
                                // WebIDL byte (i8) - convert to i32 for V8
                                break :comptime_convert @ptrCast(conv.toV8Long(isolate_inner, @as(i32, result)));
                            } else if (PayloadType == u64 or PayloadType == runtime.UnsignedLongLong) {
                                const val: f64 = @floatFromInt(result);
                                break :comptime_convert @ptrCast(v8.v8_Number_New(isolate_inner, val));
                            } else if (PayloadType == ?u64) {
                                // Optional u64 - null or number
                                if (result) |num| {
                                    const val: f64 = @floatFromInt(num);
                                    break :comptime_convert @ptrCast(v8.v8_Number_New(isolate_inner, val));
                                } else {
                                    break :comptime_convert v8.v8_Null(isolate_inner) orelse unreachable;
                                }
                            } else if (PayloadType == i64 or PayloadType == runtime.LongLong) {
                                const val: f64 = @floatFromInt(result);
                                break :comptime_convert @ptrCast(v8.v8_Number_New(isolate_inner, val));
                            } else if (PayloadType == ?i64) {
                                // Optional i64 - null or number
                                if (result) |num| {
                                    const val: f64 = @floatFromInt(num);
                                    break :comptime_convert @ptrCast(v8.v8_Number_New(isolate_inner, val));
                                } else {
                                    break :comptime_convert v8.v8_Null(isolate_inner) orelse unreachable;
                                }
                            } else if (PayloadType == f64 or PayloadType == runtime.Double) {
                                break :comptime_convert @ptrCast(v8.v8_Number_New(isolate_inner, result));
                            } else if (PayloadType == f32 or PayloadType == runtime.Float) {
                                break :comptime_convert @ptrCast(v8.v8_Number_New(isolate_inner, @floatCast(result)));
                            } else if (PayloadType == bool or PayloadType == runtime.Boolean) {
                                break :comptime_convert v8.v8_Boolean_New(isolate_inner, result) orelse unreachable;
                            } else if (PayloadType == runtime.DOMString) {
                                break :comptime_convert @ptrCast(conv.toV8String(isolate_inner, result));
                            } else if (PayloadType == ?runtime.DOMString) {
                                // Optional DOMString - null or convert to string
                                if (result) |str| {
                                    break :comptime_convert @ptrCast(conv.toV8String(isolate_inner, str));
                                } else {
                                    break :comptime_convert v8.v8_Null(isolate_inner) orelse unreachable;
                                }
                            } else if (PayloadType == runtime.USVString or PayloadType == []const u8) {
                                // USVString is []const u8 - convert to V8 string
                                if (conv.newStringFromWtf8(isolate_inner, result)) |str| {
                                    break :comptime_convert str;
                                } else {
                                    break :comptime_convert v8.v8_Undefined(isolate_inner) orelse unreachable;
                                }
                            } else if (@typeInfo(PayloadType) == .@"enum") {
                                // WebIDL enum - convert to string using @tagName
                                // This is a runtime conversion so we use a helper function
                                break :comptime_convert @ptrCast(conv.enumToV8String(PayloadType, isolate_inner, result));
                            } else if (PayloadType == *runtime.Instance or comptime isRuntimeInstancePtr(PayloadType)) {
                                // Instance pointer - wrap with correct V8 prototype
                                // This handles both *runtime.Instance directly and typedefs like WindowProxy
                                break :comptime_convert @ptrCast(conv.instanceToV8(isolate_inner, result));
                            } else if (PayloadType == ?*runtime.Instance or comptime isOptionalRuntimeInstancePtr(PayloadType)) {
                                // Optional Instance pointer - null or wrap
                                if (result) |inst| {
                                    break :comptime_convert @ptrCast(conv.instanceToV8(isolate_inner, inst));
                                } else {
                                    break :comptime_convert v8.v8_Null(isolate_inner) orelse unreachable;
                                }
                            } else if (PayloadType == *const anyopaque) {
                                // SAFETY: Cannot blindly cast *const anyopaque to V8 Value.
                                // These are often Zig-side objects (like *runtime.Instance for
                                // Promise returns) that need proper wrapping, not raw casting.
                                // For now, return undefined to prevent crashes.
                                // TODO: Implement proper Promise creation for [NewObject] methods
                                break :comptime_convert v8.v8_Undefined(isolate_inner) orelse unreachable;
                            } else if (PayloadType == runtime.JSValue) {
                                // JSValue - use conv.toV8Value to convert to V8 Value
                                // This handles all JSValue variants: undefined, null, boolean, number, string, handle, instance
                                const current_context = v8.v8_Isolate_GetCurrentContext(isolate_inner) orelse {
                                    break :comptime_convert v8.v8_Undefined(isolate_inner) orelse unreachable;
                                };
                                // Owned: v8_Isolate_GetCurrentContext allocates a Global per call.
                                defer v8.v8_Context_Dispose(current_context);
                                const v8_converted = conv.toV8Value(runtime.JSValue, isolate_inner, current_context, result) catch {
                                    break :comptime_convert v8.v8_Undefined(isolate_inner) orelse unreachable;
                                };
                                break :comptime_convert v8_converted;
                            } else if (comptime isOptionalCallbackType(PayloadType)) {
                                // An optional callback function type (EventHandler is
                                // ?EventHandlerNonNull, a function pointer): the value
                                // is the function's Global<Value>* (conversions.zig,
                                // UNTAGGED - a tag in a function pointer's low bits is
                                // illegal behaviour an optimized build acts on), which
                                // is what setReturnValue reads. Null is JavaScript null.
                                if (result) |function_value| {
                                    const address: usize = @intFromPtr(function_value);
                                    break :comptime_convert @ptrFromInt(address);
                                } else {
                                    break :comptime_convert v8.v8_Null(isolate_inner) orelse unreachable;
                                }
                            } else {
                                // For complex types (unions, optionals, etc.), use conv.toV8Value
                                // which handles all types including optional unions like MessageEventSource
                                const current_context = v8.v8_Isolate_GetCurrentContext(isolate_inner) orelse {
                                    break :comptime_convert v8.v8_Undefined(isolate_inner) orelse unreachable;
                                };
                                // Owned: v8_Isolate_GetCurrentContext allocates a Global per call.
                                defer v8.v8_Context_Dispose(current_context);
                                const v8_converted = conv.toV8Value(PayloadType, isolate_inner, current_context, result) catch {
                                    break :comptime_convert v8.v8_Undefined(isolate_inner) orelse unreachable;
                                };
                                break :comptime_convert v8_converted;
                            }
                        };

                        // [SameObject]: the owner hands out one child for its
                        // whole life, and caches it as a bare pointer (the
                        // generated `cached_<name>`). Nothing in script need
                        // hold the child, so tie its wrapper to the owner's -
                        // Blink traces the same edge - or a collection frees it
                        // under the cache.
                        if (comptime stateCachesSameObject("cached_" ++ prop_name)) {
                            recordSameObjectEdge(isolate_inner, this_handle.?, prop_name, v8_value);
                        }

                        info.setReturnValue(v8_value);
                        // setReturnValue reads the handle into a Local. A value the
                        // conversion above made is ours: every number, boolean,
                        // string and enum read leaked a Global - 200,000
                        // `v8_Number_New`s for 200,000 `list.length` reads. So is
                        // every JSValue result but an instance's wrapper: a handle
                        // the impl returns is the binding's (engine.Owned.take),
                        // and the other arms are made here.
                        if (comptime getterValueIsOwned(PayloadType)) {
                            v8.v8_Global_Dispose(v8_value);
                        } else if (comptime PayloadType == runtime.JSValue) {
                            if (result != .instance) v8.v8_Global_Dispose(v8_value);
                            // A string the impl made for the result is the
                            // binding's too, as an operation's is
                            // (callMethodWithArgs): xhr.response's text
                            // leaked on every read. A string the impl keeps
                            // goes out as a reference (`owned` false), which
                            // this leaves alone.
                            freeOwnedString(cleanup_allocator, result);
                        } else if (comptime PayloadType == ?runtime.JSValue) {
                            if (result == null or result.? != .instance) v8.v8_Global_Dispose(v8_value);
                            if (result) |value| freeOwnedString(cleanup_allocator, value);
                        } else if (comptime isUnionResult(PayloadType)) {
                            // A union (CSSNumberish, LineAndPositionSetting):
                            // its active member's conversion, and so that
                            // member's ownership - a number or string made
                            // here is released, a wrapper or an `any`
                            // member's handle (ImageData.data's, the
                            // ImageData's own) is kept (conv.unionValueIsOwned).
                            if (conv.unionValueIsOwned(PayloadType, result)) v8.v8_Global_Dispose(v8_value);
                        } else if (comptime @typeInfo(PayloadType) == .optional and isUnionResult(@typeInfo(PayloadType).optional.child)) {
                            // A nullable union: null as below, a member as above.
                            if (result) |member| {
                                if (conv.unionValueIsOwned(@typeInfo(PayloadType).optional.child, member)) v8.v8_Global_Dispose(v8_value);
                            } else v8.v8_Global_Dispose(v8_value);
                        } else if (comptime @typeInfo(PayloadType) == .optional) {
                            // Any other optional: a null result's value is made
                            // here, fresh - `v8.v8_Null(isolate_inner)` in the
                            // instance and callback branches, `toV8Null` in
                            // conv.toV8Value's optional branch, and the
                            // wrapper's v8_Null news a Global per call - so it
                            // is ours. A non-null one stays: it may be a
                            // wrapper the cache owns or a stored callback. Kept,
                            // every `event.target` read before dispatch, every
                            // `messageEvent.source` of a WebSocket message,
                            // leaked a Null Global.
                            if (result == null) v8.v8_Global_Dispose(v8_value);
                        }
                    }
                }
            };
        }

        /// Whether this interface's own or mixin state has the generated
        /// [SameObject] cache field `name` (an inherited attribute binds
        /// through its own interface, so its own State answers).
        /// Tie the wrapper of a [SameObject] child to its owner's wrapper - the
        /// edge Blink traces - with one edge per realm. An element has one
        /// wrapper whatever realm reads it, but its child gets a wrapper in
        /// each realm that reads it, and one shared key let each realm's read
        /// cut the edge to the other realm's wrapper.
        fn recordSameObjectEdge(isolate: *v8.Isolate, owner: *v8.Object, comptime prop_name: []const u8, child: *v8.Value) void {
            const realm = v8.v8_Isolate_GetCurrentContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(realm);
            const addr = @intFromPtr(v8.v8_Context_GetRawAddress(realm));
            var buf: [160]u8 = undefined;
            const key = std.fmt.bufPrint(&buf, "crane:SameObject:" ++ prop_name ++ "@{x}", .{addr}) catch return;
            v8.v8_Object_SetPrivateRef(owner, key.ptr, @intCast(key.len), child);

            // And the edge back. A [SameObject] child - classList, dataset,
            // attributes, style - reads and writes through its owner, and
            // script can keep the child and drop the owner; the owner must then
            // live as long as the child (Blink traces the child to its element;
            // WebKit forwards the child's refcount to it). A JS-heap edge, not
            // a Global, so the pair still collects as a unit. Without it,
            // `el.attributes` kept past `el` read a freed element.
            if (!v8.v8_Value_IsObject(child)) return;
            var back_buf: [168]u8 = undefined;
            const back = std.fmt.bufPrint(&back_buf, "crane:SameObjectOwner:" ++ prop_name ++ "@{x}", .{addr}) catch return;
            v8.v8_Object_SetPrivateRef(@ptrCast(child), back.ptr, @intCast(back.len), @ptrCast(owner));
        }

        fn stateCachesSameObject(comptime field_name: []const u8) bool {
            const S = Interface.State;
            if (@typeInfo(S) != .@"struct") return false;
            if (@hasField(S, "own") and @typeInfo(@FieldType(S, "own")) == .@"struct" and @hasField(@FieldType(S, "own"), field_name)) return true;
            if (@hasField(S, "mixins") and @typeInfo(@FieldType(S, "mixins")) == .@"struct" and @hasField(@FieldType(S, "mixins"), field_name)) return true;
            return false;
        }

        /// Generate a method callback for a specific method at comptime
        ///
        /// This creates a callback that:
        /// 1. Gets the Zig Instance from V8 object's internal field
        /// 2. Parses arguments from V8 using comptime reflection
        /// 3. Calls the Interface method
        /// 4. Converts and returns the result to V8
        /// The overload set whose FIRST overload is `zig_name`, if any - the
        /// function the binding installs for an overloaded operation. See
        /// `overloads` in a generated interface.
        fn overloadSetFor(comptime zig_name: []const u8) ?[]const webidl.overload_resolution.Overload {
            if (!@hasDecl(Interface, "overloads")) return null;
            inline for (Interface.overloads) |entry| {
                const set: []const webidl.overload_resolution.Overload = entry[1];
                if (comptime std.mem.eql(u8, set[0].function, zig_name)) return set;
            }
            return null;
        }

        /// WebIDL "create an operation function" step 3: run the overload
        /// resolution algorithm over `set` with the call's arguments, and let
        /// the chosen overload's own binding convert them and run it - the
        /// entries left in S agree on every type before the distinguishing
        /// index, so that conversion IS steps 11, 15 and 16.
        ///
        /// Returns true when the call has been handled here (forwarded, or a
        /// TypeError thrown), false when the first overload - the caller's own
        /// - is the one to run. An overload the impl does not provide yet runs
        /// the first overload instead, which is exactly what every call did
        /// before overloads were bound, so an unmigrated impl changes nothing.
        fn forwardToOverload(
            comptime set: []const webidl.overload_resolution.Overload,
            info: *const v8.FunctionCallbackInfo,
        ) bool {
            const isolate = info.getIsolate();
            var args = OverloadArgs{ .info = info, .isolate = isolate };
            defer args.release();

            const arg_count: usize = @intCast(@max(info.length(), 0));
            const chosen = webidl.overload_resolution.select(set, arg_count, &args) catch |err| {
                switch (err) {
                    error.TypeError => {
                        args.release();
                        // Step 12.20 throws only after step 11 has converted
                        // the arguments before the distinguishing index; an
                        // exception one of those throws is the one script sees.
                        if (webidl.overload_resolution.distinguishingPrefix(set, arg_count)) |prefix| {
                            convertOverloadPrefix(set, prefix, info, isolate) catch |conversion_err| {
                                if (conversion_err == conv.ConversionError.ExceptionPending) return true;
                            };
                        }
                        conv.throwTypeError(isolate, "Failed to execute '" ++ comptime set[0].function["call_".len..] ++ "' on '" ++ interface_name ++ "': no overload matches these arguments");
                    },
                    // GetMethod threw; the exception is already pending.
                    error.JavaScriptException => {},
                }
                return true;
            };

            if (chosen == 0 or !set[chosen].implemented) return false;
            inline for (set, 0..) |overload, k| {
                if (k != 0 and k == chosen) {
                    MethodCallback(overload.function).callback(info);
                    return true;
                }
            }
            return false;
        }

        /// Step 11 alone, for a call step 12 is about to reject: convert,
        /// and free again, the arguments before the distinguishing index as
        /// overload `prefix.entry`'s parameters (every entry left in S agrees
        /// on them), so that what those conversions run runs and what they
        /// throw is thrown.
        fn convertOverloadPrefix(
            comptime set: []const webidl.overload_resolution.Overload,
            prefix: webidl.overload_resolution.Prefix,
            info: *const v8.FunctionCallbackInfo,
            isolate: *v8.Isolate,
        ) !void {
            const context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(context);
            const isolate_alloc = @import("isolate_allocator.zig");
            const allocator = isolate_alloc.getOrInitAllocator(isolate, std.heap.c_allocator) catch return;
            inline for (set, 0..) |overload, k| {
                if (k == prefix.entry) {
                    // The generated delegate: (instance, arguments...).
                    const params = @typeInfo(@TypeOf(@field(Interface, overload.function))).@"fn".params;
                    inline for (params[1..], 0..) |param, i| {
                        if (i < prefix.d) {
                            const P = param.type.?;
                            const value = try convertArgReleasingWith(P, .{ .interface = comptime argumentInterface(Interface, overload.function, i) }, allocator, isolate, context, info.get(@intCast(i)));
                            freeArgument(P, allocator, value);
                        }
                    }
                }
            }
        }

        /// How many arguments the operation `zig_name` requires: its
        /// `length`, which codegen writes into `methods` / `static_methods` -
        /// the fewest required arguments of any overload (WebIDL "the length
        /// of the shortest argument list in the effective overload set"). 0
        /// for a function those tables do not name (a later overload, reached
        /// through forwardToOverload, whose set has already been checked).
        fn requiredArguments(comptime zig_name: []const u8) usize {
            comptime {
                for (.{ "methods", "static_methods" }) |table| {
                    if (!@hasDecl(Meta, table)) continue;
                    for (@field(Meta, table)) |entry| {
                        if (entry.len >= 3 and std.mem.eql(u8, entry[1], zig_name)) return entry[2];
                    }
                }
                return 0;
            }
        }

        /// WebIDL "create an operation function" step 3, the overload
        /// resolution algorithm, for the argument count alone: an operation's
        /// effective overload set has an entry for each number of arguments
        /// it can be called with, and none below the fewest it requires, so
        /// the algorithm throws a TypeError there - before any argument is
        /// converted. (A missing required DOMString used to convert as "", so
        /// `localStorage.getItem()` returned null instead of throwing.)
        /// True when it threw.
        fn throwIfTooFewArguments(comptime zig_name: []const u8, info: *const v8.FunctionCallbackInfo, isolate: *v8.Isolate, context: *v8.Context) bool {
            const required = comptime requiredArguments(zig_name);
            if (comptime required == 0) return false;
            const given: usize = @intCast(@max(info.length(), 0));
            if (given >= required) return false;
            var buffer: [256]u8 = undefined;
            const operation = comptime if (std.mem.startsWith(u8, zig_name, "call_static_")) zig_name["call_static_".len..] else if (std.mem.startsWith(u8, zig_name, "call_")) zig_name["call_".len..] else zig_name;
            const message = std.fmt.bufPrint(&buffer, "Failed to execute '" ++ operation ++ "' on '" ++ interface_name ++ "': {d} argument{s} required, but only {d} present.", .{ required, if (required == 1) "" else "s", given }) catch "Not enough arguments";
            conv.throwTypeErrorFromContext(isolate, context, message);
            return true;
        }

        fn MethodCallback(comptime zig_name: []const u8) type {
            return struct {
                fn callback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
                    if (comptime returnsPromise(Interface, zig_name)) return rejectOnThrow(info, scoped);
                    scoped(info);
                }

                /// A [CEReactions] operation is dispatched in a binding catch
                /// scope (engine.withPendingExceptionSetAside).
                fn scoped(info: *const v8.FunctionCallbackInfo) void {
                    if (comptime dispatchRunsCEReactions(Interface, zig_name)) return inBindingCatchScope(info, body);
                    body(info);
                }

                fn body(info: *const v8.FunctionCallbackInfo) void {
                    // WebIDL operation 2.1.2.2 / HTML 7.2.1.1. Location's
                    // Proxy needs an explicit check; promise-returning members
                    // keep this inside rejectOnThrow. Cross-origin replace is
                    // allowed by the same table that configures V8's checks.
                    const location_checks_receiver = comptime blk: {
                        if (!std.mem.eql(u8, interface_name, "Location")) break :blk false;
                        for (methods) |method| {
                            if (std.mem.eql(u8, method[1], zig_name))
                                break :blk !acceptsAnyReceiver(method[0], .operation);
                        }
                        break :blk true;
                    };
                    if (comptime bindingChecksReceiver(zig_name) or location_checks_receiver) {
                        if (!cross_origin.receiverIsAccessible(info)) {
                            const isolate = info.getIsolate();
                            if (v8.v8_Isolate_GetCurrentContext(isolate)) |current| {
                                // Owned: a fresh Global<Context>, used only to pick the realm.
                                defer v8.v8_Context_Dispose(current);
                                conv.throwWebIDLErrorFromContext(isolate, current, "SecurityError");
                            }
                            return;
                        }
                    }
                    // An overloaded operation is installed as its FIRST
                    // overload; pick the one the arguments mean.
                    if (comptime overloadSetFor(zig_name)) |set| {
                        if (forwardToOverload(set, info)) return;
                    }

                    const isolate = info.getIsolate();

                    // Get V8 context - for arguments parsing, we use the current context
                    const current_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse {
                        conv.throwError(isolate, "No current V8 context");
                        return;
                    };

                    // This handle is ours to release unless converting one of the
                    // arguments makes the engine keep the context. `conv.fromV8Value`
                    // stores it into a persistent `runtime.CallbackWrapper` for
                    // callback-typed parameters, so `createElement(DOMString)` is
                    // transient while `setTimeout(TimerHandler, ...)` is not.
                    //
                    // `typeRetainsContext` is an ALLOWLIST of provably inert types
                    // and answers "retains" for anything it does not recognise. That
                    // direction matters: written as a blocklist, this exact check
                    // released a context `setTimeout` still needed and produced 10
                    // crashes out of 12 files. See tests/v8/retention_predicate_test.zig.
                    //
                    // Six handles per DOM object created were leaking here.
                    const params_retain = comptime blk: {
                        const fi = @typeInfo(@TypeOf(@field(Interface, zig_name))).@"fn";
                        for (fi.params) |prm| {
                            const P = prm.type orelse break :blk true;
                            if (P == *runtime.Instance) continue; // the receiver
                            if (typeRetainsContext(P)) break :blk true;
                        }
                        break :blk false;
                    };
                    defer if (comptime !params_retain) v8.v8_Context_Dispose(current_context);

                    // CROSS-REALM SUPPORT: For return value conversion, we need the METHOD's realm.
                    // When calling other.SomeInterface.prototype.method.call(obj), the result object
                    // should have its prototype from 'other' (the method's realm), not the caller's realm.
                    // This is critical for WPT test: default-toJSON-cross-realm.html
                    //
                    // We use getFunctionCreationContext() which accesses V8's internal layout to get
                    // the target function being called, then returns its creation context. This gives
                    // us the context where the function was instantiated (e.g., iframe context for
                    // other.DOMRectReadOnly.prototype.toJSON).
                    // Owned: this returns a fresh Global<Context> per call, which nothing was
                    // disposing - 2 leaked handles per DOM object created. Dispose the OWNED
                    // one only; the `orelse` fallback is borrowed and freeing it would be a
                    // double free.
                    const method_context_owned = info.getFunctionCreationContext();
                    defer if (method_context_owned) |c| v8.v8_Context_Dispose(c);
                    const method_context = method_context_owned orelse current_context;

                    // Use current_context for argument parsing (input comes from caller's realm)
                    // Use method_context for return value conversion (output goes to method's realm)
                    const v8_context = current_context;

                    // Get allocator
                    const isolate_alloc = @import("isolate_allocator.zig");
                    const allocator = isolate_alloc.getOrInitAllocator(isolate, std.heap.c_allocator) catch {
                        conv.throwError(isolate, "Failed to get isolate allocator");
                        return;
                    };

                    // Get 'this' object and extract the Zig instance
                    const this_obj = info.getThis();
                    defer v8.v8_Object_Dispose(this_obj);

                    // For [Global] interfaces (like Window), we need special handling:
                    // Per WebIDL §3.8, if this is null/undefined, use the method's global object.
                    // See PropertyGetterCallback for detailed explanation.
                    const instance = blk: {
                        if (is_global_interface) {
                            if (v8.v8_Isolate_GetCurrentContext(isolate)) |method_ctx| {
                                defer v8.v8_Context_Dispose(method_ctx);
                                if (v8.v8_Context_Global(method_ctx)) |method_global| {
                                    // Owned: v8_Context_Global allocates where V8's Context::Global()
                                    // returns a borrowed Local. Everything below only compares it or
                                    // reads an internal field, so releasing at block exit is correct.
                                    defer v8.v8_Object_Dispose(method_global);
                                    // Check if this IS the method's global object
                                    if (v8.v8_Value_StrictEquals(@ptrCast(this_obj), @ptrCast(method_global))) {
                                        const global_ptr = realmWindow(method_ctx, method_global);
                                        if (global_ptr != null) {
                                            break :blk @as(*runtime.Instance, @ptrCast(@alignCast(global_ptr)));
                                        }
                                    }

                                    // this is NOT the method's global - check handling
                                    const this_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(this_obj, 0);

                                    if (this_ptr == null) {
                                        // No internal field -> this is NOT a valid global object
                                        // (globals always have internal fields pointing to Window instance)
                                        //
                                        // This happens for Object.create(Window.prototype) or other
                                        // incompatible objects. Per WebIDL §3.8, we must throw TypeError.
                                        //
                                        // Note: if setter.call(null, value) is used, V8 coerces null to
                                        // the caller's global in sloppy mode, which DOES have internal
                                        // fields. So this_ptr == null means it's definitely NOT
                                        // a coerced null - it's an incompatible object.
                                        //
                                        // Fall through to throw TypeError
                                    } else {
                                        // Another realm's WindowProxy: the operation acts
                                        // on that window (see PropertyGetterCallback).
                                        if (globalReceiverWindow(this_obj)) |this_window| {
                                            break :blk @as(*runtime.Instance, @ptrCast(@alignCast(this_window)));
                                        }
                                    }
                                }
                            }
                            // Fall through to throw TypeError
                        } else {
                            // Non-[Global] interface: use normal this handling
                            //
                            // First, try to get instance using type-safe check with comptime registry
                            const wrapper_type_info_registry_method = @import("wrapper_type_info_registry.zig");
                            if (wrapper_type_info_registry_method.getWrapperTypeInfoByName(interface_name)) |expected_type| {
                                if (getInstanceTypeSafe(runtime.Instance, this_obj, expected_type)) |inst| {
                                    break :blk inst;
                                }
                            } else {
                                // Type info not found via comptime lookup - check WrapperTypeInfo in slot 1
                                if (getWrapperTypeInfo(this_obj)) |stored_type_info| {
                                    // WrapperTypeInfo is present - use it for type checking
                                    //
                                    // IMPORTANT: Check inheritance chain, not just exact match!
                                    // E.g., if method is on Node.prototype and this is HTMLDivElement,
                                    // we need to check if HTMLDivElement inherits from Node.
                                    var current_type: ?*const WrapperTypeInfo = stored_type_info;
                                    const type_matches = while (current_type) |type_info| {
                                        if (std.mem.eql(u8, type_info.getName(), interface_name)) {
                                            break true;
                                        }
                                        current_type = type_info.parent;
                                    } else false;

                                    if (type_matches) {
                                        // Type matches (including inheritance) - get instance using legacy getInstance
                                        if (getInstance(runtime.Instance, this_obj)) |inst| {
                                            break :blk inst;
                                        }
                                    }
                                    // Type mismatch - fall through to implicit this handling or TypeError
                                } else {
                                    // No WrapperTypeInfo in slot 1 - fall back to legacy getInstance check
                                    if (getInstance(runtime.Instance, this_obj)) |inst| {
                                        break :blk inst;
                                    }
                                    // Continue to implicit this handling
                                }
                            }

                            // IMPLICIT THIS HANDLING FOR GLOBAL OBJECTS:
                            // Per WebIDL §3.8, when an operation is called without a receiver
                            // (e.g., `const f = dispatchEvent; f(event)`), V8 may coerce `this`
                            // to the caller's global object in sloppy mode.
                            //
                            // For methods inherited from parent interfaces (like EventTarget),
                            // even though EventTarget itself doesn't have [Global], the method
                            // may be called on a global object (Window) which inherits from EventTarget.
                            //
                            // Check if `this` IS a global object and use it as implicit this.
                            if (v8.v8_Isolate_GetCurrentContext(isolate)) |ctx| {
                                defer v8.v8_Context_Dispose(ctx);
                                if (v8.v8_Context_Global(ctx)) |context_global| {
                                    // Owned: v8_Context_Global allocates where V8's Context::Global()
                                    // returns a borrowed Local. Everything below only compares it or
                                    // reads an internal field, so releasing at block exit is correct.
                                    defer v8.v8_Object_Dispose(context_global);
                                    // Check if this_obj IS the current context's global
                                    if (v8.v8_Value_StrictEquals(@ptrCast(this_obj), @ptrCast(context_global))) {
                                        const global_ptr = realmWindow(ctx, context_global);
                                        if (global_ptr != null) {
                                            break :blk @as(*runtime.Instance, @ptrCast(@alignCast(global_ptr)));
                                        }
                                    }
                                }
                            }
                        }
                        // Throw TypeError from method's realm (function's creation context)
                        // Per WebIDL spec: "Throw a TypeError using the function's realm."
                        // method_context is already the function's creation context from line 1783
                        conv.throwTypeErrorFromContext(isolate, method_context, "Illegal invocation");
                        return;
                    };

                    // WebIDL "create an operation function" step 2.4: "If O does
                    // not implement the interface target, throw a TypeError."
                    // Nothing above asks that of every receiver: the implicit-this
                    // path hands back the realm's GLOBAL for a null `this` whatever
                    // the interface (idlharness calls every operation as
                    // `op.apply(null, args)`), and a wrapper with no type info in
                    // slot 1 - any interface outside dom_type_info's 24 - is
                    // unwrapped unchecked. The impl then reads another interface's
                    // state as its own: `XMLHttpRequest.open` on the Window died on
                    // `_internal.?`. The state ancestry is the brand check; an
                    // instance whose vtable carries none implements nothing
                    // (`conv.implements`: only a test's hand-made vtable lacks
                    // one).
                    if (!conv.implements(instance, Interface)) {
                        conv.throwTypeErrorFromContext(isolate, method_context, "Illegal invocation");
                        return;
                    }

                    // Step 3: too few arguments is a TypeError, in the
                    // operation's realm, before any is converted.
                    if (throwIfTooFewArguments(zig_name, info, isolate, method_context)) return;

                    // Get the method function at comptime
                    const method_fn = @field(Interface, zig_name);
                    const fn_info = @typeInfo(@TypeOf(method_fn)).@"fn";
                    const params = fn_info.params;
                    const ReturnType = fn_info.return_type.?;

                    // First parameter should be *runtime.Instance (self)
                    if (params.len < 1) {
                        @compileError("Method must have at least instance parameter");
                    }

                    // Calculate number of WebIDL parameters (excluding instance)
                    const webidl_param_count = params.len - 1;

                    // Call the method with appropriate arguments
                    // CROSS-REALM SUPPORT: Pass method_context for return value object creation
                    var result_owned = false;
                    const result = callMethodWithArgs(
                        method_fn,
                        params,
                        webidl_param_count,
                        ReturnType,
                        comptime legacyNullToEmptyMask(Interface, zig_name),
                        comptime argModesOf(Interface, zig_name),
                        instance,
                        info,
                        allocator,
                        isolate,
                        v8_context,
                        method_context, // Use method's realm for return value
                        &result_owned,
                    ) catch |err| {
                        // ExceptionPending means an exception was already rethrown during conversion
                        if (err == conv.ConversionError.ExceptionPending) {
                            return;
                        }
                        // Throw proper DOMException for WebIDL errors
                        throwMemberError(isolate, method_context, err);
                        return;
                    };

                    // Convert and set return value. setReturnValue copies, so a
                    // handle the conversion made or the impl handed over is
                    // released here - kept, a promise or an object pinned its
                    // whole page.
                    if (result) |v8_result| {
                        info.setReturnValue(v8_result);
                        if (result_owned) v8.v8_Global_Dispose(v8_result);
                    }
                    // If result is null, V8 will return undefined (correct for void methods)
                }
            };
        }

        /// Check if a type is a variadic parameter (slice type but NOT []const u8)
        /// Variadic parameters collect all remaining JS arguments into a slice.
        fn isVariadicParam(comptime T: type) bool {
            const type_info = @typeInfo(T);
            if (type_info != .pointer) return false;
            if (type_info.pointer.size != .slice) return false;
            // []const u8 is a string type, not variadic
            if (type_info.pointer.child == u8) return false;
            return true;
        }

        /// One argument's conversion with the checks codegen's tables add
        /// (`convertArgChecked`).
        fn convertArg(
            comptime T: type,
            comptime mode: ArgMode,
            allocator: std.mem.Allocator,
            isolate: *v8.Isolate,
            context: *v8.Context,
            arg: *v8.Value,
        ) !T {
            return convertArgChecked(T, mode, allocator, isolate, context, arg);
        }

        /// Convert multiple JS arguments into a slice for variadic parameters:
        /// each one as the variadic argument's own conversion
        /// (`convertArgChecked` with its `mode`: the interface an
        /// interface-typed one converts to, and the restricted float, ByteString,
        /// object and integer steps codegen's tables give its index), one at a
        /// time - a NaN for a restricted `double...` is a TypeError before the
        /// next argument converts, as for a fixed argument. One that fails
        /// frees the ones before it.
        fn collectVariadicArgs(
            comptime ElemType: type,
            comptime mode: ArgMode,
            allocator_inner: std.mem.Allocator,
            isolate_inner: *v8.Isolate,
            context_inner: *v8.Context,
            info_inner: *const v8.FunctionCallbackInfo,
            start_idx: usize,
        ) ![]const ElemType {
            const arg_count: usize = @intCast(info_inner.length());
            const variadic_count = if (arg_count > start_idx) arg_count - start_idx else 0;

            if (variadic_count == 0) {
                // Return empty slice for no variadic args
                return &[_]ElemType{};
            }

            // Allocate slice for variadic arguments
            var result = try allocator_inner.alloc(ElemType, variadic_count);
            errdefer allocator_inner.free(result);

            // Convert each JS argument to the element type. Each handle is
            // owned; released when the conversion copied out of it, as for a
            // fixed argument - a leaked one per `append(...nodes)` argument
            // kept its page alive. The ones converted before one that fails
            // are freed (docs/lessons/architecture-a-conversion-that-fails-
            // part-way-converted-the-rest.md).
            var i: usize = 0;
            errdefer for (result[0..i]) |done| freeArgument(ElemType, allocator_inner, done);
            while (i < variadic_count) : (i += 1) {
                const v8_arg = info_inner.get(@intCast(start_idx + i));
                result[i] = try convertArgChecked(ElemType, mode, allocator_inner, isolate_inner, context_inner, v8_arg);
            }

            return result;
        }

        /// Call method with arguments parsed using comptime reflection
        ///
        /// Supports cross-realm object creation via return_context parameter:
        /// - v8_context: Context for parsing input arguments (caller's realm)
        /// - return_context: Context for creating return value objects (method's realm)
        fn callMethodWithArgs(
            comptime method_fn: anytype,
            comptime params: anytype,
            comptime webidl_param_count: usize,
            comptime ReturnType: type,
            comptime null_to_empty: u32,
            comptime modes: ArgModes,
            instance: *runtime.Instance,
            raw_info: *const v8.FunctionCallbackInfo,
            allocator: std.mem.Allocator,
            isolate: *v8.Isolate,
            v8_context: *v8.Context,
            return_context: *v8.Context,
            result_owned: *bool,
        ) !?*v8.Value {
            const info = ArgView(null_to_empty){ .raw = raw_info, .isolate = isolate };
            const js_arg_count = info.length();

            // Call method based on parameter count
            const zig_result = blk: {
                if (webidl_param_count == 0) {
                    break :blk try method_fn(instance);
                } else if (webidl_param_count == 1) {
                    const Param1Type = params[1].type.?;

                    // Check if this is a variadic parameter (slice type, not []const u8)
                    if (comptime isVariadicParam(Param1Type)) {
                        // Collect all JS arguments into a slice
                        const ElemType = @typeInfo(Param1Type).pointer.child;
                        const arg1 = try collectVariadicArgs(ElemType, comptime argMode(modes, 0), allocator, isolate, v8_context, info.raw, 0);
                        // Free each element in the slice, then free the slice itself
                        defer {
                            for (arg1) |elem| freeArgument(ElemType, allocator, elem);
                            if (arg1.len > 0) allocator.free(arg1);
                        }
                        break :blk try method_fn(instance, arg1);
                    }

                    const arg1 = if (js_arg_count >= 1) arg_blk: {
                        const v8_arg1 = info.get(0);
                        break :arg_blk try convertArg(Param1Type, comptime argMode(modes, 0), allocator, isolate, v8_context, v8_arg1);
                    } else arg_blk: {
                        // Get default value for optional parameter
                        if (comptime getDefaultArgValue(Param1Type)) |default_val| {
                            break :arg_blk default_val;
                        } else if (comptime canUseUndefined(Param1Type)) {
                            break :arg_blk undefined;
                        } else {
                            return error.NotEnoughArguments;
                        }
                    };
                    defer freeArgument(Param1Type, allocator, arg1);
                    break :blk try method_fn(instance, arg1);
                } else if (webidl_param_count == 2) {
                    const Param1Type = params[1].type.?;
                    const Param2Type = params[2].type.?;

                    // Handle first parameter - may be optional
                    const arg1 = if (js_arg_count >= 1) arg_blk: {
                        const v8_arg1 = info.get(0);
                        break :arg_blk try convertArg(Param1Type, comptime argMode(modes, 0), allocator, isolate, v8_context, v8_arg1);
                    } else arg_blk: {
                        // Get default value for optional parameter
                        if (comptime getDefaultArgValue(Param1Type)) |default_val| {
                            break :arg_blk default_val;
                        } else if (comptime canUseUndefined(Param1Type)) {
                            break :arg_blk undefined;
                        } else {
                            return error.NotEnoughArguments;
                        }
                    };
                    defer freeArgument(Param1Type, allocator, arg1);

                    // A trailing variadic `T... rest` collects every argument
                    // from its index, as a sole one does: converting the one
                    // value at that index as a slice threw a TypeError for
                    // createHTML("x", "a") and console.assert(c, "m").
                    if (comptime isVariadicParam(Param2Type)) {
                        const ElemType = @typeInfo(Param2Type).pointer.child;
                        const rest = try collectVariadicArgs(ElemType, comptime argMode(modes, 1), allocator, isolate, v8_context, info.raw, 1);
                        defer {
                            for (rest) |elem| freeArgument(ElemType, allocator, elem);
                            if (rest.len > 0) allocator.free(rest);
                        }
                        break :blk try method_fn(instance, arg1, rest);
                    }

                    const arg2 = if (js_arg_count >= 2) arg_blk: {
                        const v8_arg2 = info.get(1);
                        break :arg_blk try convertArg(Param2Type, comptime argMode(modes, 1), allocator, isolate, v8_context, v8_arg2);
                    } else arg_blk: {
                        // Get default value for optional parameter
                        if (comptime getDefaultArgValue(Param2Type)) |default_val| {
                            break :arg_blk default_val;
                        } else if (comptime canUseUndefined(Param2Type)) {
                            break :arg_blk undefined;
                        } else {
                            return error.NotEnoughArguments;
                        }
                    };
                    defer freeArgument(Param2Type, allocator, arg2);
                    break :blk try method_fn(instance, arg1, arg2);
                } else if (webidl_param_count == 3) {
                    const Param1Type = params[1].type.?;
                    const Param2Type = params[2].type.?;
                    const Param3Type = params[3].type.?;

                    // Handle first parameter - may be optional
                    const arg1 = if (js_arg_count >= 1) arg_blk: {
                        const v8_arg1 = info.get(0);
                        break :arg_blk try convertArg(Param1Type, comptime argMode(modes, 0), allocator, isolate, v8_context, v8_arg1);
                    } else arg_blk: {
                        if (comptime getDefaultArgValue(Param1Type)) |default_val| {
                            break :arg_blk default_val;
                        } else if (comptime canUseUndefined(Param1Type)) {
                            break :arg_blk undefined;
                        } else {
                            return error.NotEnoughArguments;
                        }
                    };
                    defer freeArgument(Param1Type, allocator, arg1);

                    // Handle second parameter - may be optional
                    const arg2 = if (js_arg_count >= 2) arg_blk: {
                        const v8_arg2 = info.get(1);
                        break :arg_blk try convertArg(Param2Type, comptime argMode(modes, 1), allocator, isolate, v8_context, v8_arg2);
                    } else arg_blk: {
                        if (comptime getDefaultArgValue(Param2Type)) |default_val| {
                            break :arg_blk default_val;
                        } else if (comptime canUseUndefined(Param2Type)) {
                            break :arg_blk undefined;
                        } else {
                            return error.NotEnoughArguments;
                        }
                    };
                    defer freeArgument(Param2Type, allocator, arg2);

                    // A trailing variadic, as in the two-parameter branch.
                    if (comptime isVariadicParam(Param3Type)) {
                        const ElemType = @typeInfo(Param3Type).pointer.child;
                        const rest = try collectVariadicArgs(ElemType, comptime argMode(modes, 2), allocator, isolate, v8_context, info.raw, 2);
                        defer {
                            for (rest) |elem| freeArgument(ElemType, allocator, elem);
                            if (rest.len > 0) allocator.free(rest);
                        }
                        break :blk try method_fn(instance, arg1, arg2, rest);
                    }

                    const arg3 = if (js_arg_count >= 3) arg_blk: {
                        const v8_arg3 = info.get(2);
                        break :arg_blk try convertArg(Param3Type, comptime argMode(modes, 2), allocator, isolate, v8_context, v8_arg3);
                    } else arg_blk: {
                        // Get default value for optional parameter
                        if (comptime getDefaultArgValue(Param3Type)) |default_val| {
                            break :arg_blk default_val;
                        } else if (comptime canUseUndefined(Param3Type)) {
                            break :arg_blk undefined;
                        } else {
                            return error.NotEnoughArguments;
                        }
                    };
                    defer freeArgument(Param3Type, allocator, arg3);
                    break :blk try method_fn(instance, arg1, arg2, arg3);
                } else if (webidl_param_count == 4) {
                    const Param1Type = params[1].type.?;
                    const Param2Type = params[2].type.?;
                    const Param3Type = params[3].type.?;
                    const Param4Type = params[4].type.?;

                    // Handle first parameter - may be optional
                    const arg1 = if (js_arg_count >= 1) arg_blk: {
                        const v8_arg1 = info.get(0);
                        break :arg_blk try convertArg(Param1Type, comptime argMode(modes, 0), allocator, isolate, v8_context, v8_arg1);
                    } else arg_blk: {
                        if (comptime getDefaultArgValue(Param1Type)) |default_val| {
                            break :arg_blk default_val;
                        } else if (comptime canUseUndefined(Param1Type)) {
                            break :arg_blk undefined;
                        } else {
                            return error.NotEnoughArguments;
                        }
                    };
                    defer freeArgument(Param1Type, allocator, arg1);

                    // Handle second parameter - may be optional
                    const arg2 = if (js_arg_count >= 2) arg_blk: {
                        const v8_arg2 = info.get(1);
                        break :arg_blk try convertArg(Param2Type, comptime argMode(modes, 1), allocator, isolate, v8_context, v8_arg2);
                    } else arg_blk: {
                        if (comptime getDefaultArgValue(Param2Type)) |default_val| {
                            break :arg_blk default_val;
                        } else if (comptime canUseUndefined(Param2Type)) {
                            break :arg_blk undefined;
                        } else {
                            return error.NotEnoughArguments;
                        }
                    };
                    defer freeArgument(Param2Type, allocator, arg2);

                    const arg3 = if (js_arg_count >= 3) arg_blk: {
                        const v8_arg3 = info.get(2);
                        break :arg_blk try convertArg(Param3Type, comptime argMode(modes, 2), allocator, isolate, v8_context, v8_arg3);
                    } else arg_blk: {
                        if (comptime getDefaultArgValue(Param3Type)) |default_val| {
                            break :arg_blk default_val;
                        } else if (comptime canUseUndefined(Param3Type)) {
                            break :arg_blk undefined;
                        } else {
                            return error.NotEnoughArguments;
                        }
                    };
                    defer freeArgument(Param3Type, allocator, arg3);

                    const arg4 = if (js_arg_count >= 4) arg_blk: {
                        const v8_arg4 = info.get(3);
                        break :arg_blk try convertArg(Param4Type, comptime argMode(modes, 3), allocator, isolate, v8_context, v8_arg4);
                    } else arg_blk: {
                        if (comptime getDefaultArgValue(Param4Type)) |default_val| {
                            break :arg_blk default_val;
                        } else if (comptime canUseUndefined(Param4Type)) {
                            break :arg_blk undefined;
                        } else {
                            return error.NotEnoughArguments;
                        }
                    };
                    defer freeArgument(Param4Type, allocator, arg4);
                    break :blk try method_fn(instance, arg1, arg2, arg3, arg4);
                } else {
                    // Five or more: the same per-argument conversion as the
                    // branches above, as a loop. This used to return
                    // NotImplemented, so every operation that takes five
                    // arguments - `arc(x, y, r, start, end)`,
                    // `setTransform(a, b, c, d, e, f)`,
                    // `open(method, url, async, username, password)` - threw
                    // "This feature is not yet implemented" at every call.
                    var call_args: std.meta.ArgsTuple(@TypeOf(method_fn)) = undefined;
                    call_args[0] = instance;
                    // How many of `call_args[1..]` hold a value, so a
                    // conversion that fails part-way frees only those - the
                    // branches above get that from one `defer` per argument.
                    var assigned: usize = 0;
                    defer {
                        inline for (params[1..], 1..) |param, i| {
                            if (i <= assigned) freeArgument(param.type.?, allocator, call_args[i]);
                        }
                    }
                    inline for (params[1..], 1..) |param, i| {
                        const ParamType = param.type.?;
                        call_args[i] = if (js_arg_count >= i) arg_blk: {
                            const v8_arg = info.get(@intCast(i - 1));
                            break :arg_blk try convertArg(ParamType, comptime argMode(modes, i - 1), allocator, isolate, v8_context, v8_arg);
                        } else arg_blk: {
                            if (comptime getDefaultArgValue(ParamType)) |default_val| {
                                break :arg_blk default_val;
                            } else if (comptime canUseUndefined(ParamType)) {
                                break :arg_blk undefined;
                            } else {
                                return error.NotEnoughArguments;
                            }
                        };
                        assigned = i;
                    }
                    break :blk try @call(.auto, method_fn, call_args);
                }
            };

            // Determine the payload type (unwrap error union if needed) for cleanup
            // Determine the payload type (unwrap error union and optional if needed) for cleanup
            const PayloadType = comptime blk: {
                var T = ReturnType;
                const type_info = @typeInfo(T);
                if (type_info == .error_union) {
                    T = type_info.error_union.payload;
                }
                break :blk T;
            };

            // Get the innermost type for cleanup (unwrap optional)
            const InnerType = comptime blk: {
                const type_info = @typeInfo(PayloadType);
                if (type_info == .optional) {
                    break :blk type_info.optional.child;
                } else {
                    break :blk PayloadType;
                }
            };

            // Check if InnerType is an array/slice type (for sequence cleanup)
            const is_sequence = comptime blk: {
                const type_info = @typeInfo(InnerType);
                break :blk type_info == .pointer and type_info.pointer.size == .slice;
            };

            // Get the element type if it's a sequence
            const ElementType = comptime blk: {
                if (is_sequence) {
                    const ptr_info = @typeInfo(InnerType).pointer;
                    break :blk ptr_info.child;
                } else {
                    break :blk void;
                }
            };

            // For string types that allocate memory, free after V8 conversion.
            // IMPORTANT: Impls MUST use instance.ctx.allocator for returned strings,
            // not internal.allocator, so this cleanup uses the correct allocator.
            // Static strings (empty string "") have len=0 and won't be freed.
            // Handles both optional and non-optional string types.
            // Also handles sequences (arrays) of strings.
            // Also handles JSValue with owned strings.
            const needs_string_cleanup = comptime (InnerType == runtime.USVString or
                InnerType == []const u8 or
                InnerType == runtime.DOMString or
                InnerType == runtime.JSValue);
            const needs_sequence_cleanup = comptime (is_sequence and
                (ElementType == []const u8 or ElementType == runtime.USVString));
            const is_optional = comptime (@typeInfo(PayloadType) == .optional);

            defer if (needs_string_cleanup) {
                if (InnerType == runtime.DOMString) {
                    if (is_optional) {
                        if (zig_result) |value| {
                            var mutable = value;
                            mutable.deinit(instance.ctx.allocator);
                        }
                    } else {
                        var mutable = zig_result;
                        mutable.deinit(instance.ctx.allocator);
                    }
                } else if (InnerType == runtime.USVString or InnerType == []const u8) {
                    if (is_optional) {
                        if (zig_result) |value| {
                            if (value.len > 0) {
                                instance.ctx.allocator.free(value);
                            }
                        }
                    } else {
                        if (zig_result.len > 0) {
                            instance.ctx.allocator.free(zig_result);
                        }
                    }
                } else if (InnerType == runtime.JSValue) {
                    // Free owned string data in JSValue after V8 conversion
                    if (is_optional) {
                        if (zig_result) |value| {
                            switch (value) {
                                .string => |s| {
                                    if (s.owned and s.data.len > 0) {
                                        instance.ctx.allocator.free(s.data);
                                    }
                                },
                                else => {},
                            }
                        }
                    } else {
                        switch (zig_result) {
                            .string => |s| {
                                if (s.owned and s.data.len > 0) {
                                    instance.ctx.allocator.free(s.data);
                                }
                            },
                            else => {},
                        }
                    }
                }
            };

            // Cleanup for sequences (arrays) - free the array itself
            // Note: Individual strings in the array are NOT freed here because
            // they should reference internal data, not be separately allocated
            defer if (needs_sequence_cleanup) {
                if (zig_result.len > 0) {
                    instance.ctx.allocator.free(zig_result);
                }
            };

            // Convert return value to V8
            // CROSS-REALM SUPPORT: Use return_context (method's realm) for object creation
            return try convertReturnValue(ReturnType, comptime returnsByteString(Interface, modes.fn_name), zig_result, allocator, isolate, return_context, result_owned);
        }

        /// Convert Zig return value to V8 Value
        fn convertReturnValue(
            comptime ReturnType: type,
            comptime byte_string: bool,
            result: anytype,
            allocator: std.mem.Allocator,
            isolate: *v8.Isolate,
            v8_context: *v8.Context,
            owned: *bool,
        ) !?*v8.Value {
            // Suppress unused parameter warning - allocator used only in recursive calls
            _ = allocator;

            // `owned` answers whether the handle returned is the binding's to
            // release once the caller has set it as the call's result
            // (setReturnValue copies). True where this conversion made the
            // handle, and for every handle a JSValue result carries - what an
            // impl returns is the binding's. A wrapper is the cache's, and a
            // union's or dictionary's parts are not told apart here, so they
            // stay false - a leak at worst, never a handle freed under its
            // holder.
            owned.* = false;

            const type_info = @typeInfo(ReturnType);

            // Handle error union - unwrap it
            if (type_info == .error_union) {
                const PayloadType = type_info.error_union.payload;
                return convertReturnValue(PayloadType, byte_string, result, std.heap.page_allocator, isolate, v8_context, owned);
            }

            // Handle void return
            if (ReturnType == void) {
                return null;
            }

            if (comptime byte_string) {
                owned.* = true;
                return try conv.byteStringToV8(ReturnType, isolate, result);
            }

            // Handle optional types
            if (type_info == .optional) {
                if (result) |value| {
                    const ChildType = type_info.optional.child;
                    return convertReturnValue(ChildType, false, value, std.heap.page_allocator, isolate, v8_context, owned);
                } else {
                    owned.* = true;
                    return @ptrCast(v8.v8_Null(isolate));
                }
            }

            // A platform object is its wrapper in its relevant realm
            // (`conv.instanceToV8`), whichever realm the operation's function
            // belongs to: wrapped in `v8_context` - the CALLEE's realm - an
            // object a method borrowed from another realm returned got a
            // second wrapper there, with that realm's prototype
            // (tests/v8/cross_realm_wrapper_test.zig). The wrapper is the
            // wrapper cache's; only the undefined of an object that cannot be
            // wrapped is this call's.
            if (ReturnType == *runtime.Instance) {
                const wrapper = conv.instanceToV8(isolate, result);
                owned.* = v8.v8_Value_IsUndefined(wrapper);
                return wrapper;
            }

            // Handle primitive types
            if (ReturnType == bool) {
                owned.* = true;
                return @ptrCast(v8.v8_Boolean_New(isolate, result));
            }

            if (ReturnType == i16 or ReturnType == i32 or ReturnType == i64 or ReturnType == u16 or ReturnType == u32 or ReturnType == u64) {
                owned.* = true;
                return @ptrCast(v8.v8_Number_New(isolate, @floatFromInt(result)));
            }

            if (ReturnType == f64 or ReturnType == f32) {
                owned.* = true;
                return @ptrCast(v8.v8_Number_New(isolate, result));
            }

            // Handle DOMString
            if (ReturnType == runtime.DOMString) {
                const slice = result.asSlice();
                // WTF-8: its lone surrogates kept (conv.newStringFromWtf8).
                const v8_str = conv.newStringFromWtf8(isolate, slice) orelse {
                    return v8.v8_Undefined(isolate);
                };
                owned.* = true;
                return @ptrCast(v8_str);
            }

            // Handle []const u8 (string slices)
            if (ReturnType == []const u8) {
                const v8_str = conv.newStringFromWtf8(isolate, result) orelse {
                    return v8.v8_Undefined(isolate);
                };
                owned.* = true;
                return @ptrCast(v8_str);
            }

            // Handle runtime.JSValue - engine-agnostic value wrapper
            if (ReturnType == runtime.JSValue) {
                // What an impl returns is the binding's (engine.Owned.take): a
                // handle - the impl's to hand over, a value it keeps going back
                // as a hold of its own (retainValue) - and every value made
                // here are released once set. Only an instance's wrapper is
                // not: it is the wrapper cache's.
                owned.* = result != .instance;
                return switch (result) {
                    .undefined => v8.v8_Undefined(isolate),
                    .null => @ptrCast(v8.v8_Null(isolate)),
                    .boolean => |b| @ptrCast(v8.v8_Boolean_New(isolate, b)),
                    .number => |n| @ptrCast(v8.v8_Number_New(isolate, n)),
                    .string => |s| blk: {
                        if (s.data.len == 0) {
                            break :blk @ptrCast(v8.v8_String_Empty(isolate) orelse return v8.v8_Undefined(isolate));
                        }
                        break :blk @ptrCast(conv.newStringFromWtf8(isolate, s.data) orelse return v8.v8_Undefined(isolate));
                    },
                    // A Global<Value>*, set as the result as it is.
                    .handle => |h| @ptrCast(h.ptr),
                    // Its wrapper in its relevant realm, as above.
                    .instance => |i| blk: {
                        const wrapper = conv.instanceToV8(isolate, @ptrCast(@alignCast(i)));
                        owned.* = v8.v8_Value_IsUndefined(wrapper);
                        break :blk wrapper;
                    },
                };
            }

            // An ArrayBufferView result is the binding's, as a JSValue
            // result's handle is (ArrayBufferView.jsHandle): an impl that
            // returns a view it was given or keeps returns it over a hold of
            // its own (`withJsHandle`), since the arguments are released
            // before this runs. Released once set.
            if (ReturnType == webidl.ArrayBufferView) {
                owned.* = true;
                const js = result.jsHandle() orelse return v8.v8_Undefined(isolate);
                return @ptrCast(@alignCast(js));
            }

            // A WebIDL enumeration value is the String of its value (WebIDL
            // 3.2.24) - "" included: canPlayType's "" answer. The conversion
            // and ownership the attribute getter path uses (enumToV8String
            // makes the string; released once set). Without this case an
            // enum fell to the fallback below and reached script as undefined.
            if (type_info == .@"enum") {
                owned.* = true;
                return conv.enumToV8String(ReturnType, isolate, result);
            }

            // A union (FormData.get's (File or USVString), getReader's
            // reader): its active member's conversion, and so that member's
            // ownership (`conv.unionValueIsOwned`) - a String made for a
            // string member is released once set, a wrapper is the cache's.
            // `owned` was left false for every union, so FormData.get kept
            // the String of every string entry it returned.
            if (type_info == .@"union") {
                const converted = conv.toV8Value(ReturnType, isolate, v8_context, result) catch {
                    owned.* = true;
                    return v8.v8_Undefined(isolate);
                };
                owned.* = conv.unionValueIsOwned(ReturnType, result);
                return converted;
            }

            // Handle Promise(T) types - extract the handle and return the V8 Promise
            if (@typeInfo(ReturnType) == .@"struct") {
                if (@hasDecl(ReturnType, "ResultType") and @hasField(ReturnType, "handle")) {
                    // This is a Promise(T) type - extract the V8 Promise handle
                    return @ptrCast(result.handle);
                }
                // A dictionary (URLPatternResult, NavigationResult): its object
                // is made for this call (WebIDL 3.2.18), and released once
                // set - kept, it leaked a Global per call. A JavaScript value
                // the impl handed over in it is the binding's too, as a
                // JSValue result is: released once the object holds it
                // (conv.releaseReturnedDictionaryHandles).
                owned.* = comptime conv.dictionaryValueIsOwned(ReturnType);
                defer conv.releaseReturnedDictionaryHandles(ReturnType, result);
                return conv.toV8Value(ReturnType, isolate, v8_context, result) catch {
                    owned.* = true;
                    return v8.v8_Undefined(isolate);
                };
            }

            // Handle *const anyopaque - SAFETY: Cannot blindly cast to V8 Value
            // These are often Zig-side objects (like *runtime.Instance for
            // Promise returns) that need proper wrapping, not raw casting.
            if (ReturnType == *const anyopaque) {
                // Return undefined to prevent crashes from misaligned pointers
                // TODO: Implement proper Promise creation for [NewObject] methods
                return v8.v8_Undefined(isolate);
            }

            // For other types, return undefined as fallback
            // TODO: Expand type conversion coverage
            return v8.v8_Undefined(isolate);
        }

        /// Register a method on the prototype template using generated callback
        ///
        /// CROSS-REALM SUPPORT: Does NOT use V8 Signature for receiver type checking.
        /// V8's signature checking is too strict for WebIDL cross-realm semantics.
        /// Our MethodCallback validates `this` via internal field inspection instead.
        fn registerMethod(
            comptime zig_name: []const u8,
            comptime method_name: []const u8,
            isolate: *v8.Isolate,
            receiver_template: *v8.FunctionTemplate,
            proto_tmpl: *v8.ObjectTemplate,
            arity: c_int,
            attributes: c_int,
        ) void {
            _ = receiver_template; // Unused - cross-realm support requires no V8 signature

            // Generate the method callback at comptime
            const Callback = MethodCallback(zig_name);

            // CROSS-REALM SUPPORT: Create function template WITHOUT V8 signature.
            //
            // V8's signature checking is too strict for WebIDL cross-realm semantics.
            // When obj is created via `new child.DOMParser()` (child realm's FunctionTemplate)
            // and we call `DOMParser.prototype.method.call(obj, ...)` (parent realm's method),
            // V8's signature check rejects it because obj's FunctionTemplate differs from
            // the parent realm's receiver_template.
            //
            // Per WebIDL spec, cross-realm `this` values SHOULD work - if an object was
            // created as a DOMParser in ANY realm, it should be usable with DOMParser
            // methods from ANY realm (within the same agent/isolate).
            //
            // Our MethodCallback already validates `this` by checking internal fields
            // (via getInstance/getInstanceTypeSafe), which correctly handles cross-realm
            // objects since they share the same Zig instance storage mechanism.
            const method_tmpl = v8.v8_FunctionTemplate_New(
                isolate,
                Callback.callback,
                null,
            ) orelse {
                std.debug.panic("Failed to create function template for method", .{});
            };
            // ObjectTemplate::Set below keeps the method template itself.
            defer v8.v8_FunctionTemplate_Dispose(method_tmpl);

            // Set method length (arity) - number of required parameters
            v8.v8_FunctionTemplate_SetLength(method_tmpl, arity);

            // Remove prototype property from method functions.
            // Per WebIDL spec, methods are not constructible and should not have
            // the legacy "arguments"/"caller" properties.
            // This ensures Reflect.ownKeys(method) returns ["length", "name"].
            v8.v8_FunctionTemplate_RemovePrototype(method_tmpl);

            // WebIDL's security check for a cross-origin `this`, unless HTML
            // lists the operation (cross_origin.zig).
            if (comptime engineChecksReceiver(method_name, zig_name)) v8.v8_FunctionTemplate_SetAcceptAnyReceiver(method_tmpl, false);

            // Add FunctionTemplate to prototype (not the function itself)
            // ObjectTemplate::Set accepts Templates or primitives
            // Set with DontEnum attribute to make methods non-enumerable (spec-compliant)
            const name_str = v8.v8_String_NewFromUtf8(
                isolate,
                method_name.ptr,
                @intCast(method_name.len),
            ) orelse {
                std.debug.panic("Failed to create string for method name", .{});
            };
            defer v8.v8_String_Dispose(name_str);
            // Per WebIDL spec §3.7.6, method properties should be:
            // { writable: true, enumerable: true, configurable: true } -
            // an unforgeable one's neither writable nor configurable.
            v8.v8_ObjectTemplate_SetWithAttributes(
                proto_tmpl,
                name_str,
                @ptrCast(method_tmpl),
                attributes,
            );
        }

        /// Constructor callback for V8
        ///
        /// Called when JavaScript does: new InterfaceName()
        ///
        /// Uses comptime reflection to parse constructor arguments and call
        /// the appropriate Interface.call_constructor() with converted arguments.
        fn constructorCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            debug.print("[V8_CONSTRUCTOR] constructorCallback called for: {s}\n", .{interface_name});

            // Always-on stderr debug for Worker and MutationObserver constructor to trace issues
            if (comptime std.mem.eql(u8, interface_name, "Worker") or std.mem.eql(u8, interface_name, "MutationObserver")) {
                log.debug("[CTOR_CALLBACK] {s} constructorCallback ENTRY\n", .{interface_name});
            }

            const isolate = info.getIsolate();

            // CRITICAL: Check if this is a constructor call (called with 'new')
            // If called as a function (without 'new'), 'this' may be the global object
            // which has 0 internal fields, causing "Internal field out of bounds" crash.
            if (!info.isConstructCall()) {
                // Owned handle; the null branch has none to release.
                const function_ctx = info.getFunctionCreationContext() orelse {
                    conv.throwTypeError(isolate, interface_name ++ " constructor: 'new' is required");
                    return;
                };
                defer v8.v8_Context_Dispose(function_ctx);
                conv.throwTypeErrorFromContext(isolate, function_ctx, interface_name ++ " constructor: 'new' is required");
                return;
            }

            // Get V8 contexts:
            // - current_context: The caller's context (for argument parsing)
            // - constructor_context: The constructor's creation context (for object realm)
            //
            // Per WebIDL §3.7.2 [[Construct]]: "Let realm be F's relevant realm"
            // Objects created by constructors belong to the constructor's realm, not the caller's realm.
            const current_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse {
                conv.throwError(isolate, "No current V8 context");
                return;
            };
            // Released unless converting a constructor argument makes the engine
            // keep the context (`new MutationObserver(callback)`) - the same
            // allowlist gate as MethodCallback's. The first parameter is the
            // runtime context, not an argument.
            const ctor_params_retain = comptime blk: {
                const fi = @typeInfo(@TypeOf(Interface.call_constructor)).@"fn";
                for (fi.params[1..]) |prm| {
                    const P = prm.type orelse break :blk true;
                    if (typeRetainsContext(P)) break :blk true;
                }
                break :blk false;
            };
            defer if (comptime !ctor_params_retain) v8.v8_Context_Dispose(current_context);

            // Implementation of GetFunctionRealm algorithm for constructor realm
            // This ensures we correctly handle cross-realm construction, bound functions, and proxies.
            // Using the constructor function's realm (F.[[Realm]]) per WebIDL spec.
            const constructor_v8_fn = info.getFunction();
            defer if (constructor_v8_fn) |f| v8.v8_Value_Dispose(@ptrCast(f));
            // Owned in both branches, and released: `ctx_mgr.getOrCreateWithIsolate`
            // keeps its own copy of the handle when it creates an entry, so the
            // caller's is always the caller's. (Before it did, this leaked one
            // Global<Context> per constructor call - each one keeping its page's
            // whole native context alive.)
            const constructor_v8_context = if (constructor_v8_fn) |f| getFunctionRealm(@ptrCast(f), isolate) else info.getFunctionCreationContext();
            defer if (constructor_v8_context) |c| v8.v8_Context_Dispose(c);
            const constructor_context = constructor_v8_context orelse current_context;

            // Get or create isolate allocator (uses page_allocator as fallback)
            const isolate_alloc = @import("isolate_allocator.zig");
            const allocator = isolate_alloc.getOrInitAllocator(isolate, std.heap.c_allocator) catch {
                conv.throwError(isolate, "Failed to get isolate allocator");
                return;
            };

            // Get or create runtime context from the CONSTRUCTOR'S context (not caller's)
            // This ensures the realm in ctx matches the constructor's realm
            const ctx_mgr = @import("context_manager.zig");
            const ctx = ctx_mgr.getOrCreateWithIsolate(constructor_context, isolate, allocator) catch {
                conv.throwError(isolate, "Failed to get runtime context");
                return;
            };

            // Get 'this' object (the newly created instance). Owned, like
            // every getThis(), until the wrapper cache takes it: `cache.set`
            // below stores this exact pointer as `entry.wrapper` and arms
            // `v8_Global_SetWeak` on it, so from a successful set the cache
            // owns it and frees it via `disposeEntryWrapper` - disposing it
            // then is a double free plus a weak callback pointing at freed
            // memory. Every other exit releases it here: a conversion that
            // threw, an impl that failed, an instance that already had a
            // wrapper, no cache, a failed set. Those exits used to keep it,
            // one Global<Object> per failed `new X()` of any interface (Codex
            // row 14 Q16; tests/v8/constructor_error_receiver_test.zig).
            const this_obj = info.getThis();
            var receiver_taken = false;
            defer if (!receiver_taken) v8.v8_Object_Dispose(this_obj);

            // HTML 3.2.3 "HTML element constructors" [html_constructor]: with
            // the agent's host hook, the construction is HTML's - the element
            // a custom element class's super() gets, new or upgrading.
            if (comptime is_html_constructor) {
                if (@import("protocol_agents.zig").htmlConstructorHookOf(isolate)) |hook| {
                    // It binds or releases the receiver itself.
                    receiver_taken = true;
                    constructHTMLElement(info, hook, this_obj, isolate, current_context, constructor_context, ctx, constructor_v8_fn);
                    return;
                }
            }

            // ========================================
            // CROSS-REALM CONSTRUCTOR SUPPORT (WebIDL §3.7.2)
            // ========================================
            // When NewTarget.prototype is not an object (e.g., primitive like 7),
            // we must fall back to the interface prototype object from the
            // appropriate realm (GetFunctionRealm(NewTarget)).
            //
            // V8 already creates 'this' with the correct prototype when NewTarget.prototype
            // is valid, but falls back to Object.prototype when it's invalid.
            // We need to detect this and fix it.
            // Note: Use current_context here since NewTarget comes from the caller's realm
            handleNewTargetPrototypeFallback(info, this_obj, isolate, current_context, interface_name);

            // Call the interface's constructor with arguments parsed at comptime
            // Note: Arguments are parsed from current_context (caller's values), but
            // the runtime ctx uses constructor_context (constructor's realm)
            if (comptime std.mem.eql(u8, interface_name, "Worker") or std.mem.eql(u8, interface_name, "MutationObserver")) {
                log.debug("[CTOR_CALLBACK] {s} calling callConstructorWithArgs\n", .{interface_name});
            }
            const instance = callConstructorWithArgs(info, allocator, ctx, current_context, isolate) catch |err| {
                // ExceptionPending means an exception was already rethrown during conversion
                // (e.g., from toString() throwing) - don't throw a second error
                if (comptime std.mem.eql(u8, interface_name, "Worker") or std.mem.eql(u8, interface_name, "MutationObserver")) {
                    log.debug("[CTOR_CALLBACK] {s} callConstructorWithArgs FAILED: {s}\n", .{ interface_name, @errorName(err) });
                }
                if (err == conv.ConversionError.ExceptionPending) {
                    return;
                }
                // Throw appropriate error type based on error name
                // Use throwWebIDLError which properly creates DOMException for WebIDL errors
                // Owned: this returns a fresh Global<Context> per call, which nothing was
                // disposing - 2 leaked handles per DOM object created. Dispose the OWNED
                // one only; the `orelse` fallback is borrowed and freeing it would be a
                // double free.
                const function_ctx_owned = info.getFunctionCreationContext();
                defer if (function_ctx_owned) |c| v8.v8_Context_Dispose(c);
                const function_ctx = function_ctx_owned orelse current_context;
                conv.throwWebIDLErrorFromContext(isolate, function_ctx, @errorName(err));
                return;
            };

            // An instance its own construction already wrapped (a traced edge
            // made its wrapper): that wrapper, given NewTarget's prototype, is
            // the result - binding `this_obj` instead would replace it, and
            // every edge drawn on it with it (WrapperCache.set refuses). The
            // receiver is then bound to nothing, and released.
            if (adoptExistingWrapper(info, this_obj, instance, constructor_context)) return;

            // Store the Zig instance in the V8 object's internal field (slot 0)
            // Also store WrapperTypeInfo in slot 1 for type-safe unwrapping
            const wrapper_type_info_registry_ctor = @import("wrapper_type_info_registry.zig");
            if (wrapper_type_info_registry_ctor.getWrapperTypeInfoByName(interface_name)) |type_info| {
                setInstanceWithTypeInfo(runtime.Instance, this_obj, instance, type_info);
            } else {
                // Fall back to legacy setInstance if type info not found via comptime lookup
                setInstance(runtime.Instance, this_obj, instance);
            }

            // ========================================
            // CACHE THE WRAPPER: Store constructor-created wrapper for identity
            // ========================================
            if (comptime hasConditionalUnforgeables(Interface)) installConditionalUnforgeables(isolate, constructor_context, this_obj);
            if (ctx.getV8WrapperCacheStorage()) |cache_storage| {
                const WrapperCache = @import("wrapper_cache.zig").WrapperCache;
                const cache: *WrapperCache = @ptrCast(@alignCast(cache_storage));

                // The cache owns the instance through `this` from here. When
                // it cannot take it (OutOfMemory), the construction fails:
                // returning `this` anyway left an instance nothing owned
                // (Codex row 15 Q22). The receiver is unbound - nothing reaches
                // the instance through it - and released by the deferred
                // dispose above (a set that fails stored nothing); the
                // instance, which nothing else ever wrapped, is freed, and the
                // error is thrown.
                cache.set(instance, this_obj, isolate) catch |err| {
                    unbindReceiver(this_obj);
                    instance.releaseIfUnwrapped(runtime.SlabAllocator.generationOf(instance));
                    const function_ctx_owned = info.getFunctionCreationContext();
                    defer if (function_ctx_owned) |c| v8.v8_Context_Dispose(c);
                    conv.throwWebIDLErrorFromContext(isolate, function_ctx_owned orelse current_context, @errorName(err));
                    return;
                };
                receiver_taken = true;
            }

            // ========================================
            // POST-CONSTRUCTOR HOOKS: Interface-specific initialization
            // ========================================
            // For DOMException: add stack property per WebIDL spec
            // If the implementation has a stack property on normal errors, DOMException must too
            if (comptime std.mem.eql(u8, interface_name, "DOMException")) {
                captureDOMExceptionStack(this_obj, isolate, constructor_context);
            }

            // Return 'this' (V8 does this automatically for constructors)
        }

        /// HTML 3.2.3 "HTML element constructors", the overridden constructor
        /// steps of an [HTMLConstructor] interface, across the seam
        /// (engine.HostHooks.htmlConstructor): step 1 here, then steps 10-11
        /// (the receiver's prototype), the host's 2-9, 12, 13 and 15, and 14
        /// and 16 here. Takes `this_obj`, V8's receiver for NewTarget: it is
        /// bound to the element, or released - never left registered for an
        /// element whose existing wrapper is the result.
        ///
        /// Order: V8 performed Get(NewTarget, "prototype") when it made the
        /// receiver, before step 1, so a throwing or side-effecting getter is
        /// seen before the TypeErrors of steps 1-9, 12 and 13 (the spec has it
        /// after them). Blink's V8HTMLConstructor::HtmlConstructor
        /// (third_party/blink/renderer/bindings/core/v8/v8_html_constructor.cc)
        /// runs under the same V8 construct path and has the same order.
        fn constructHTMLElement(
            info: *const v8.FunctionCallbackInfo,
            hook: @import("protocol_agents.zig").HTMLConstructorHook,
            this_obj: *v8.Object,
            isolate: *v8.Isolate,
            current_context: *v8.Context,
            function_context: *v8.Context,
            realm: runtime.Context,
            active_function: ?*v8.Function,
        ) void {
            var receiver_taken = false;
            defer if (!receiver_taken) v8.v8_Object_Dispose(this_obj);

            // The active function object: this interface's interface object.
            // A construct call's FunctionCallbackInfo names its target as the
            // FunctionTemplateInfo rather than the function (V8's
            // GetTargetFunctionTemplateInfo reads either), so info.getFunction()
            // is null there; the interface object is then the template's
            // instantiation in the current context - the callee's, which V8
            // entered for the call.
            const own_active: ?*v8.Function = if (active_function == null) activeInterfaceObject(current_context) else null;
            defer if (own_active) |f| v8.v8_Function_Dispose(f);
            const active = active_function orelse own_active;

            // A construct call always has NewTarget.
            const new_target = info.getNewTarget() orelse {
                conv.throwTypeErrorFromContext(isolate, function_context, "Illegal constructor");
                return;
            };
            defer v8.v8_Value_Dispose(new_target);

            // 1. If NewTarget is equal to the active function object, then
            //    throw a TypeError.
            if (active) |function| {
                if (v8.v8_Value_StrictEquals(new_target, @ptrCast(function))) {
                    conv.throwTypeErrorFromContext(isolate, function_context, "Illegal constructor");
                    return;
                }
            }

            // 10-11. Let prototype be ? Get(NewTarget, "prototype"); if it is
            //        not an Object, the interface prototype object of
            //        GetFunctionRealm(NewTarget) whose interface is the active
            //        function's. V8 made the receiver with NewTarget's
            //        prototype, or - for a non-object - the active function's
            //        own realm's. Only then can the realm be wrong, so only then
            //        is NewTarget read again (its getter runs twice there, as on
            //        every constructor's path); a prototype of NewTarget's own
            //        is never re-read, so its getter's script ran once, before
            //        the host's steps (the hook's single-call contract).
            //    V8's fallback for a non-object is %Object.prototype% of
            //    GetFunctionRealm(NewTarget) for an API constructor
            //    (JSFunction::GetDerivedMap: OBJECT_FUNCTION_INDEX when the
            //    constructor names no intrinsic), never an interface
            //    prototype - so a receiver given that object needs the
            //    fallback too (CE-S1: newtarget.html, newtarget-customized-
            //    builtins.html). The fallback re-reads NewTarget.prototype
            //    and changes nothing for a real object, so a NewTarget whose
            //    prototype IS that %Object.prototype% stays as it is.
            if (receiverHasActivePrototype(this_obj, active, current_context) or
                receiverHasRealmObjectPrototype(this_obj, new_target, isolate))
            {
                handleNewTargetPrototypeFallback(info, this_obj, isolate, current_context, interface_name);
            }

            // 2-9, 12, 13 and 15: the host's. NewTarget BORROWED for the call.
            const constructed = hook.call(hook.host, realm, .{ .handle = .{ .ptr = @ptrCast(new_target) } }, interface_name) catch |err| {
                if (err == error.ExceptionPending) return;
                // TypeError (steps 5, 7.1, 8.2 and 13): of the active
                // function's realm.
                conv.throwWebIDLErrorFromContext(isolate, function_context, @errorName(err));
                return;
            };
            switch (constructed) {
                // 9. A new element: wrapped in the receiver, whose prototype is
                //    NewTarget's (9.1). The construction's result is the
                //    receiver, as for any constructor - unless the element's
                //    creation already wrapped it (an edge traced to it made
                //    its wrapper): that wrapper is then the element's, and
                //    takes the receiver's prototype as an upgrade's does
                //    (steps 14 and 16 below). Binding the receiver would
                //    replace it, and every edge drawn on it with it (a
                //    template's content, PR-M1); WrapperCache.set refuses.
                .created => |element| {
                    if (adoptExistingWrapper(info, this_obj, element, function_context)) return;
                    receiver_taken = bindConstructedElement(this_obj, element, isolate) catch |err| {
                        // Not cached: the new element is this construction's
                        // to free (nothing else ever wrapped it), and the
                        // construction throws (Codex row 15 Q22).
                        element.releaseIfUnwrapped(runtime.SlabAllocator.generationOf(element));
                        conv.throwWebIDLErrorFromContext(isolate, function_context, @errorName(err));
                        return;
                    };
                },
                .upgrading => |element| {
                    // 14. Perform ? element.[[SetPrototypeOf]](prototype). An
                    //     ordinary object's answers false rather than throwing
                    //     (non-extensible): a normal completion, so nothing is
                    //     thrown.
                    // 16. Return element: its wrapper is the construction's
                    //     result (V8 takes an API constructor's object return
                    //     value). The receiver is discarded, bound to nothing.
                    if (adoptExistingWrapper(info, this_obj, element, function_context)) return;
                    // Never wrapped: the receiver becomes its wrapper, with
                    // the prototype already set (step 14) - and is the result
                    // (step 16).
                    receiver_taken = bindConstructedElement(this_obj, element, isolate) catch |err| {
                        // Not cached: the upgrading element stays the
                        // construction stack's; the construction throws.
                        conv.throwWebIDLErrorFromContext(isolate, function_context, @errorName(err));
                        return;
                    };
                },
            }
        }

        /// This interface's interface object in `context`: its FunctionTemplate's
        /// instantiation there (one per context, so identity holds). OWNED.
        fn activeInterfaceObject(context: *v8.Context) ?*v8.Function {
            const template = template_registry.getTemplate(interface_name) orelse return null;
            return v8.v8_FunctionTemplate_GetFunction(template, context);
        }

        /// Whether V8 gave `receiver` the active function's own `prototype` -
        /// what it does when NewTarget's is not an object (and when it is that
        /// very object). The active function is an interface object, whose
        /// `prototype` is a non-writable, non-configurable data property: the
        /// read runs no script.
        fn receiverHasActivePrototype(receiver: *v8.Object, active_function: ?*v8.Function, context: *v8.Context) bool {
            const function = active_function orelse return true;
            const isolate = v8.v8_Isolate_GetCurrent() orelse return true;
            const key = v8.v8_String_NewFromUtf8(isolate, "prototype", 9) orelse return true;
            defer v8.v8_String_Dispose(key);
            const active_prototype = v8.v8_Object_Get(@ptrCast(function), context, @ptrCast(key)) orelse return true;
            defer v8.v8_Value_Dispose(active_prototype);
            const prototype = v8.v8_Object_GetPrototypeV2(receiver) orelse return true;
            defer v8.v8_Value_Dispose(prototype);
            return v8.v8_Value_StrictEquals(prototype, active_prototype);
        }

        /// Whether V8 gave `receiver` %Object.prototype% of
        /// GetFunctionRealm(`new_target`) - what it does for an API
        /// constructor when NewTarget's `prototype` is not an object. A
        /// prototype whose own [[Prototype]] is not null cannot be it, and is
        /// answered without finding the realm.
        fn receiverHasRealmObjectPrototype(receiver: *v8.Object, new_target: *v8.Value, isolate: *v8.Isolate) bool {
            const prototype = v8.v8_Object_GetPrototypeV2(receiver) orelse return false;
            defer v8.v8_Value_Dispose(prototype);
            if (!v8.v8_Value_IsObject(prototype)) return false;
            const above = v8.v8_Object_GetPrototypeV2(@ptrCast(prototype)) orelse return false;
            defer v8.v8_Value_Dispose(above);
            if (!v8.v8_Value_IsNull(above)) return false;
            const realm = getFunctionRealm(new_target, isolate) orelse return false;
            defer v8.v8_Context_Dispose(realm);
            // An ordinary object made in that realm has its %Object.prototype%.
            const probe = v8.v8_Object_NewInContext(realm) orelse return false;
            defer v8.v8_Object_Dispose(probe);
            const object_prototype = v8.v8_Object_GetPrototypeV2(probe) orelse return false;
            defer v8.v8_Value_Dispose(object_prototype);
            return v8.v8_Value_StrictEquals(prototype, object_prototype);
        }

        /// The wrapper cache of `element`'s relevant realm.
        fn elementWrapperCache(element: *runtime.Instance) ?*@import("wrapper_cache.zig").WrapperCache {
            const storage = element.ctx.getV8WrapperCacheStorage() orelse return null;
            return @ptrCast(@alignCast(storage));
        }

        /// Bind `element` to `receiver` - the object V8 made for NewTarget - as
        /// the constructor path binds its instance: its Instance in the
        /// internal fields, and the wrapper cache's entry. Whether the cache
        /// took the receiver's handle.
        fn bindConstructedElement(receiver: *v8.Object, element: *runtime.Instance, isolate: *v8.Isolate) anyerror!bool {
            const wrapper_type_info_registry_ctor = @import("wrapper_type_info_registry.zig");
            if (wrapper_type_info_registry_ctor.getWrapperTypeInfoByName(interface_name)) |type_info| {
                setInstanceWithTypeInfo(runtime.Instance, receiver, element, type_info);
            } else {
                setInstance(runtime.Instance, receiver, element);
            }
            if (comptime hasConditionalUnforgeables(Interface)) {
                const context: *v8.Context = @ptrCast(@alignCast(element.ctx.engine_ctx orelse return false));
                installConditionalUnforgeables(isolate, context, receiver);
            }
            const cache = elementWrapperCache(element) orelse return false;
            cache.set(element, receiver, isolate) catch |err| {
                // Not cached (OutOfMemory): the receiver must not reach the
                // element, which nothing owns through it (Codex row 15 Q22).
                log.warn("a constructed {s}'s wrapper was not cached: {s}", .{ interface_name, @errorName(err) });
                unbindReceiver(receiver);
                return err;
            };
            return true;
        }

        /// Clear the internal fields `setInstance` wrote on `receiver`, so a
        /// receiver the wrapper cache did not take reaches no instance.
        fn unbindReceiver(receiver: *v8.Object) void {
            const count = v8.v8_Object_InternalFieldCount(receiver);
            if (count >= 1) v8.v8_Object_SetAlignedPointerInInternalField(receiver, 0, null);
            if (count >= 2) v8.v8_Object_SetAlignedPointerInInternalField(receiver, 1, null);
        }

        /// Call constructor with arguments parsed using comptime reflection
        ///
        /// This function uses @typeInfo to inspect the Interface.call_constructor signature
        /// and automatically parse and convert the required arguments from V8.
        fn callConstructorWithArgs(
            info: *const v8.FunctionCallbackInfo,
            allocator: std.mem.Allocator,
            ctx: runtime.Context,
            v8_context: *v8.Context,
            isolate: *v8.Isolate,
        ) !*runtime.Instance {
            // Get constructor function type info at comptime
            const constructor_fn = Interface.call_constructor;
            const fn_info = @typeInfo(@TypeOf(constructor_fn)).@"fn";
            const params = fn_info.params;

            // Verify first two parameters are allocator and context (our convention)
            if (params.len < 1) {
                @compileError("Constructor must have at least context parameter");
            }

            // Calculate number of WebIDL parameters (excluding allocator and context)
            const webidl_param_count = params.len - 1;

            // Check argument count from JavaScript
            const js_arg_count = info.length();

            // WebIDL 3.7.1 steps 1.6–1.7 / 3.6 step 5: an empty effective
            // overload set throws before converting ANY argument. Blink's
            // bind_gen/interface.py make_check_argument_length does the same.
            if (comptime @hasDecl(Interface, "constructor_required_arguments")) {
                if (js_arg_count < Interface.constructor_required_arguments) return error.NotEnoughArguments;
            }

            // Build arguments tuple at comptime based on constructor signature
            // Note: Constructors use ctx.allocator internally for consistency with deinit
            if (webidl_param_count == 0) {
                // No arguments constructor
                return try Interface.call_constructor(ctx);
            } else if (webidl_param_count == 1) {
                // Single argument constructor
                const Param1Type = params[1].type.?;

                // Debug for MutationObserver
                if (comptime std.mem.eql(u8, interface_name, "MutationObserver")) {
                    log.debug("[CTOR_ARGS] MutationObserver single-param path, Param1Type={s}, js_arg_count={d}\n", .{ @typeName(Param1Type), js_arg_count });
                }

                // An overloaded constructor takes its interface's generated
                // ConstructorArgs. Any other union parameter - a DOMString
                // (a union(enum) of its storage), CSSNumberish - is one
                // argument, converted and freed like every other: taken for a
                // ConstructorArgs, `new BroadcastChannel(name)` built its name
                // as an "interned" arm the cleanup never frees, and leaked the
                // argument's handle with it.
                if (comptime @hasDecl(Interface, "ConstructorArgs") and Param1Type == Interface.ConstructorArgs) {
                    // Overloaded: the overload resolution algorithm picks
                    // the variant over codegen's `constructor_overloads`.
                    const args = try overload_resolver.resolveConstructorOverloadWith(
                        Param1Type,
                        Interface.constructor_overloads,
                        if (@hasDecl(Interface, "constructor_interface_arguments")) Interface.constructor_interface_arguments else .{},
                        if (@hasDecl(Interface, "constructor_restricted_floats")) Interface.constructor_restricted_floats else .{},
                        info,
                        allocator,
                        isolate,
                        v8_context,
                    );
                    defer overload_resolver.freeConstructorOverload(Param1Type, Interface.constructor_overloads, allocator, args);
                    return try Interface.call_constructor(ctx, args);
                }

                // A sole variadic `T... args` (CSSMathSum's) collects every
                // argument, as an operation's does.
                if (comptime isVariadicParam(Param1Type)) {
                    const ElemType = @typeInfo(Param1Type).pointer.child;
                    const rest = try collectVariadicArgs(ElemType, comptime constructorArgMode(Interface, 0), allocator, isolate, v8_context, info, 0);
                    defer {
                        for (rest) |elem| freeArgument(ElemType, allocator, elem);
                        if (rest.len > 0) allocator.free(rest);
                    }
                    return try Interface.call_constructor(ctx, rest);
                }

                // Normal single-parameter constructor
                // Parameter may be optional - check type and provide default if needed
                const arg1 = if (js_arg_count >= 1) blk: {
                    if (comptime std.mem.eql(u8, interface_name, "MutationObserver")) {
                        log.debug("[CTOR_ARGS] MutationObserver converting arg from V8...\n", .{});
                    }
                    const v8_arg1 = info.get(0);
                    const converted = try convertArg(Param1Type, comptime constructorArgMode(Interface, 0), allocator, isolate, v8_context, v8_arg1);
                    if (comptime std.mem.eql(u8, interface_name, "MutationObserver")) {
                        log.debug("[CTOR_ARGS] MutationObserver arg converted OK\n", .{});
                    }
                    break :blk converted;
                } else blk: {
                    // No argument provided - use getDefaultArgValue for consistent handling
                    if (comptime getDefaultArgValue(Param1Type)) |default_val| {
                        break :blk default_val;
                    } else if (comptime canUseUndefined(Param1Type)) {
                        break :blk undefined;
                    } else {
                        return error.NotEnoughArguments;
                    }
                };
                defer freeArgument(Param1Type, allocator, arg1);

                if (comptime std.mem.eql(u8, interface_name, "MutationObserver")) {
                    log.debug("[CTOR_ARGS] MutationObserver calling Interface.call_constructor...\n", .{});
                }
                const result = try Interface.call_constructor(ctx, arg1);
                if (comptime std.mem.eql(u8, interface_name, "MutationObserver")) {
                    log.debug("[CTOR_ARGS] MutationObserver call_constructor returned OK\n", .{});
                }
                return result;
            } else if (webidl_param_count == 2) {
                // Two arguments constructor (second may be optional dictionary)
                const Param1Type = params[1].type.?;
                const Param2Type = params[2].type.?;

                // Check if first param has a default (e.g., webidl.Opt or optional)
                const arg1 = if (js_arg_count >= 1) blk: {
                    const v8_arg1 = info.get(0);
                    break :blk try convertArg(Param1Type, comptime constructorArgMode(Interface, 0), allocator, isolate, v8_context, v8_arg1);
                } else blk: {
                    // Try default for first param
                    if (comptime getDefaultArgValue(Param1Type)) |default_val| {
                        break :blk default_val;
                    } else if (comptime canUseUndefined(Param1Type)) {
                        break :blk undefined;
                    } else {
                        return error.NotEnoughArguments;
                    }
                };
                defer freeArgument(Param1Type, allocator, arg1);

                // A trailing variadic collects every argument from its index.
                if (comptime isVariadicParam(Param2Type)) {
                    const ElemType = @typeInfo(Param2Type).pointer.child;
                    const rest = try collectVariadicArgs(ElemType, comptime constructorArgMode(Interface, 1), allocator, isolate, v8_context, info, 1);
                    defer {
                        for (rest) |elem| freeArgument(ElemType, allocator, elem);
                        if (rest.len > 0) allocator.free(rest);
                    }
                    return try Interface.call_constructor(ctx, arg1, rest);
                }

                // Second param may be optional (use default if not provided)
                const arg2 = if (js_arg_count >= 2) blk: {
                    const v8_arg2 = info.get(1);
                    break :blk try convertArg(Param2Type, comptime constructorArgMode(Interface, 1), allocator, isolate, v8_context, v8_arg2);
                } else blk: {
                    // Use getDefaultArgValue for consistent handling
                    if (comptime getDefaultArgValue(Param2Type)) |default_val| {
                        break :blk default_val;
                    } else if (comptime canUseUndefined(Param2Type)) {
                        break :blk undefined;
                    } else {
                        return error.NotEnoughArguments;
                    }
                };
                defer freeArgument(Param2Type, allocator, arg2);

                return try Interface.call_constructor(ctx, arg1, arg2);
            } else if (webidl_param_count == 3) {
                // Three arguments constructor (all may be optional)
                const Param1Type = params[1].type.?;
                const Param2Type = params[2].type.?;
                const Param3Type = params[3].type.?;

                // Handle first parameter - may be optional
                const arg1 = if (js_arg_count >= 1) blk: {
                    const v8_arg1 = info.get(0);
                    break :blk try convertArg(Param1Type, comptime constructorArgMode(Interface, 0), allocator, isolate, v8_context, v8_arg1);
                } else blk: {
                    if (comptime getDefaultArgValue(Param1Type)) |default_val| {
                        break :blk default_val;
                    } else if (comptime canUseUndefined(Param1Type)) {
                        break :blk undefined;
                    } else {
                        return error.NotEnoughArguments;
                    }
                };
                defer freeArgument(Param1Type, allocator, arg1);

                // Handle second parameter - may be optional
                const arg2 = if (js_arg_count >= 2) blk: {
                    const v8_arg2 = info.get(1);
                    break :blk try convertArg(Param2Type, comptime constructorArgMode(Interface, 1), allocator, isolate, v8_context, v8_arg2);
                } else blk: {
                    if (comptime getDefaultArgValue(Param2Type)) |default_val| {
                        break :blk default_val;
                    } else if (comptime canUseUndefined(Param2Type)) {
                        break :blk undefined;
                    } else {
                        return error.NotEnoughArguments;
                    }
                };
                defer freeArgument(Param2Type, allocator, arg2);

                // Handle third parameter - may be optional
                const arg3 = if (js_arg_count >= 3) blk: {
                    const v8_arg3 = info.get(2);
                    break :blk try convertArg(Param3Type, comptime constructorArgMode(Interface, 2), allocator, isolate, v8_context, v8_arg3);
                } else blk: {
                    if (comptime getDefaultArgValue(Param3Type)) |default_val| {
                        break :blk default_val;
                    } else if (comptime canUseUndefined(Param3Type)) {
                        break :blk undefined;
                    } else {
                        return error.NotEnoughArguments;
                    }
                };
                defer freeArgument(Param3Type, allocator, arg3);

                return try Interface.call_constructor(ctx, arg1, arg2, arg3);
            } else if (webidl_param_count == 4) {
                // Four arguments constructor (all may be optional)
                const Param1Type = params[1].type.?;
                const Param2Type = params[2].type.?;
                const Param3Type = params[3].type.?;
                const Param4Type = params[4].type.?;

                // Handle first parameter - may be optional
                const arg1 = if (js_arg_count >= 1) blk: {
                    const v8_arg1 = info.get(0);
                    break :blk try convertArg(Param1Type, comptime constructorArgMode(Interface, 0), allocator, isolate, v8_context, v8_arg1);
                } else blk: {
                    if (comptime getDefaultArgValue(Param1Type)) |default_val| {
                        break :blk default_val;
                    } else if (comptime canUseUndefined(Param1Type)) {
                        break :blk undefined;
                    } else {
                        return error.NotEnoughArguments;
                    }
                };
                defer freeArgument(Param1Type, allocator, arg1);

                // Handle second parameter - may be optional
                const arg2 = if (js_arg_count >= 2) blk: {
                    const v8_arg2 = info.get(1);
                    break :blk try convertArg(Param2Type, comptime constructorArgMode(Interface, 1), allocator, isolate, v8_context, v8_arg2);
                } else blk: {
                    if (comptime getDefaultArgValue(Param2Type)) |default_val| {
                        break :blk default_val;
                    } else if (comptime canUseUndefined(Param2Type)) {
                        break :blk undefined;
                    } else {
                        return error.NotEnoughArguments;
                    }
                };
                defer freeArgument(Param2Type, allocator, arg2);

                // Handle third parameter - may be optional
                const arg3 = if (js_arg_count >= 3) blk: {
                    const v8_arg3 = info.get(2);
                    break :blk try convertArg(Param3Type, comptime constructorArgMode(Interface, 2), allocator, isolate, v8_context, v8_arg3);
                } else blk: {
                    if (comptime getDefaultArgValue(Param3Type)) |default_val| {
                        break :blk default_val;
                    } else if (comptime canUseUndefined(Param3Type)) {
                        break :blk undefined;
                    } else {
                        return error.NotEnoughArguments;
                    }
                };
                defer freeArgument(Param3Type, allocator, arg3);

                // Handle fourth parameter - may be optional
                const arg4 = if (js_arg_count >= 4) blk: {
                    const v8_arg4 = info.get(3);
                    break :blk try convertArg(Param4Type, comptime constructorArgMode(Interface, 3), allocator, isolate, v8_context, v8_arg4);
                } else blk: {
                    if (comptime getDefaultArgValue(Param4Type)) |default_val| {
                        break :blk default_val;
                    } else if (comptime canUseUndefined(Param4Type)) {
                        break :blk undefined;
                    } else {
                        return error.NotEnoughArguments;
                    }
                };
                defer freeArgument(Param4Type, allocator, arg4);

                return try Interface.call_constructor(ctx, arg1, arg2, arg3, arg4);
            } else {
                // TODO: Support more than 4 parameters if needed
                @compileError("Constructors with more than 4 parameters not yet supported");
            }
        }

        /// Callback for non-constructible interfaces
        /// Callback for non-constructible interfaces (has_constructor = false)
        ///
        /// Throws TypeError when JavaScript tries: new NonConstructibleInterface()
        /// or NonConstructibleInterface() (called as function)
        ///
        /// Per WebIDL spec §3.12 (Legacy callback interface objects):
        /// - Must throw TypeError, NOT a generic Error
        fn nonConstructorCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            // Owned handle; the null branch has none to release.
            const function_ctx = info.getFunctionCreationContext() orelse {
                conv.throwTypeError(isolate, "Illegal constructor: " ++ name ++ " is not constructible");
                return;
            };
            defer v8.v8_Context_Dispose(function_ctx);
            conv.throwTypeErrorFromContext(isolate, function_ctx, "Illegal constructor: " ++ name ++ " is not constructible");
        }

        /// HTMLAllCollection's legacy caller: `document.all(nameOrIndex)`.
        ///
        /// HTML declares `legacycaller (HTMLCollection or Element)? item(optional
        /// DOMString nameOrIndex)`, and WebIDL makes calling the object call that
        /// operation: its argument converted as item()'s (undefined is "not
        /// provided"; null is the string "null"), its result returned, its errors
        /// thrown. HTML item() step 1: "If nameOrIndex was not provided, return
        /// null" - the impl's, as every other step is.
        ///
        /// `info.getThis()` is the collection: V8 calls a non-function callable
        /// with its receiver overwritten by the called object
        /// (builtins-arm64.cc Generate_Call "Overwrite the original receiver with
        /// the (original) target", then HandleApiCallAsFunctionDelegate), so
        /// `document.all(x)` and `const a = document.all; a(x)` both arrive here
        /// with document.all as `this`.
        ///
        /// Everything the handler makes is released: the current context, the
        /// argument's handle, the converted string and the result. Kept, each
        /// call left a Context Global, the argument and an Undefined behind.
        ///
        /// This is ONLY used for HTMLAllCollection (comptime check ensures interface_name matches)
        fn htmlAllCollectionCallHandler(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            // Only compile this code for HTMLAllCollection
            if (comptime !std.mem.eql(u8, interface_name, "HTMLAllCollection")) {
                // Should never be called for other interfaces, but safety check
                return;
            }
            if (comptime !@hasDecl(Interface, "call_item")) return;

            const isolate = info.getIsolate();

            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            const instance = getInstance(runtime.Instance, this_obj) orelse {
                conv.throwTypeError(isolate, "Illegal invocation");
                return;
            };

            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return;
            // Owned: v8_Isolate_GetCurrentContext allocates a Global per call,
            // and nothing converted below keeps it.
            defer v8.v8_Context_Dispose(v8_context);
            const isolate_alloc = @import("isolate_allocator.zig");
            const allocator = isolate_alloc.getOrInitAllocator(isolate, std.heap.c_allocator) catch {
                conv.throwError(isolate, "Out of memory");
                return;
            };

            // item()'s one argument, as an operation's: missing (no argument,
            // or undefined) is "not provided".
            const NameOrIndex = @typeInfo(@TypeOf(Interface.call_item)).@"fn".params[1].type.?;
            const name_or_index: NameOrIndex = if (info.length() == 0)
                NameOrIndex.notPassed()
            else
                convertArgReleasing(NameOrIndex, allocator, isolate, v8_context, info.get(0)) catch |err| {
                    if (err != conv.ConversionError.ExceptionPending) conv.throwTypeError(isolate, @errorName(err));
                    return;
                };
            defer freeArgument(NameOrIndex, allocator, name_or_index);

            const result_allocator = instance.ctx.allocator;
            const result = Interface.call_item(instance, name_or_index) catch |err| {
                if (err == conv.ConversionError.ExceptionPending) return;
                conv.throwWebIDLErrorFromContext(isolate, v8_context, @errorName(err));
                return;
            };
            defer freeOwnedResult(@TypeOf(result), result_allocator, result);

            // (HTMLCollection or Element)?: null, or the impl's value. A
            // wrapper is the wrapper cache's; anything else is made here.
            const value = result orelse {
                const null_value = v8.v8_Null(isolate) orelse return;
                info.setReturnValue(@ptrCast(null_value));
                v8.v8_Global_Dispose(null_value);
                return;
            };
            const v8_value = conv.toV8Value(runtime.JSValue, isolate, v8_context, value) catch {
                conv.throwError(isolate, "Failed to convert result");
                return;
            };
            info.setReturnValue(@ptrCast(v8_value));
            if (value != .instance) v8.v8_Global_Dispose(@ptrCast(v8_value));
        }

        /// Placeholder method callback
        ///
        /// Used for methods until we implement full method callback generation
        fn placeholderMethodCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            conv.throwError(isolate, "Method not yet implemented");
        }

        /// Placeholder getter callback
        fn placeholderGetterCallback(
            property: *v8.Name,
            info: *const v8.PropertyCallbackInfo,
        ) callconv(.c) v8.Intercepted {
            _ = property;
            const isolate = info.getIsolate();
            conv.throwError(isolate, "Getter not yet implemented");
            return .kYes;
        }

        /// Indexed property getter for array-like access (obj[0], obj[1], etc.)
        /// Called when JavaScript accesses an indexed property on objects with WebIDL "getter" operations.
        /// For example, NodeList has "getter Node? item(unsigned long index)" which enables list[0] syntax.
        fn indexedPropertyGetter(
            index: u32,
            info: *const v8.PropertyCallbackInfo,
        ) callconv(.c) v8.Intercepted {
            // Only compile this function body if Interface has an indexed getter
            if (comptime !has_indexed_getter) {
                // No indexed getter - just return to let V8 handle lookup
                return .kNo;
            }
            const indexed_getter = @field(Interface, indexed_getter_name.?);

            const isolate = info.getIsolate();
            // The current context, taken where a path uses it - wrapping or
            // converting an item, or the realm of an error - and not for an
            // index past the end, which answers kNo. Owned:
            // v8_Isolate_GetCurrentContext allocates a Global per call.
            const CurrentContext = struct {
                isolate: *v8.Isolate,
                owned: ?*v8.Context = null,

                fn get(self: *@This()) ?*v8.Context {
                    if (self.owned == null) self.owned = v8.v8_Isolate_GetCurrentContext(self.isolate);
                    return self.owned;
                }

                fn release(self: *@This()) void {
                    if (self.owned) |c| v8.v8_Context_Dispose(c);
                    self.owned = null;
                }
            };
            var current_context: CurrentContext = .{ .isolate = isolate };
            defer current_context.release();

            // The instance: WebIDL's O, the object that has the interceptor
            // (the list, for `list[i]` and for `heir[i]` whose prototype is
            // the list), read from its internal field without a handle - a
            // Global for `this`, made and disposed per read, was a third of
            // `list[i]` (gc_bench profile, 2026-10-11).
            const instance_ptr = info.holderAlignedPointer(0);
            if (instance_ptr == null) {
                // Called on prototype, not an instance - let V8 continue normal lookup
                return .kNo;
            }

            // Safety check: detect use-after-free by checking for poison patterns
            const ptr_as_int = @intFromPtr(instance_ptr);
            const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
            const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
            if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
                (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
            {
                return .kNo;
            }

            const instance: *runtime.Instance = @ptrCast(@alignCast(instance_ptr));

            // An anonymous getter: only a supported property index reaches it.
            if (comptime indexed_getter_checks_length) {
                const length = Interface.get_length(instance) catch return .kNo;
                if (index >= length) return .kNo;
            }

            // Call the indexed getter
            std.log.debug("[indexedPropertyGetter] Calling {s}.{s}(instance={*}, index={})", .{ interface_name, indexed_getter_name.?, instance, index });
            const result_allocator = instance.ctx.allocator;
            const result = indexed_getter(instance, index) catch |err| {
                if (err == conv.ConversionError.ExceptionPending) {
                    return .kNo;
                }
                // The receiver's realm, the error's: `this` is taken here,
                // on the throwing path only.
                const this_obj = info.getThis();
                defer v8.v8_Object_Dispose(this_obj);
                // Owned when V8 answers it - a fresh Global<Context>.
                const creation_ctx = v8.v8_Object_GetCreationContext(this_obj);
                defer if (creation_ctx) |made| v8.v8_Context_Dispose(made);
                if (creation_ctx orelse current_context.get()) |realm| {
                    conv.throwWebIDLErrorFromContext(isolate, realm, @errorName(err));
                } else {
                    conv.throwError(isolate, @errorName(err));
                }
                return .kNo;
            };
            // A string item() made for the result is the binding's.
            defer freeOwnedResult(@TypeOf(result), result_allocator, result);

            // Convert result to V8 value based on return type
            const ReturnType = @typeInfo(@TypeOf(indexed_getter)).@"fn".return_type.?;
            const ActualReturnType = @typeInfo(ReturnType).error_union.payload;

            // Handle different return types
            const type_info = @typeInfo(ActualReturnType);
            if (type_info == .optional) {
                // Optional type - check for null
                if (result) |unwrapped_result| {
                    const ChildType = type_info.optional.child;
                    // Check if it's an Instance pointer
                    if (ChildType == *runtime.Instance) {
                        // Its wrapper in its relevant realm (`conv.instanceToV8`),
                        // the wrapper cache's - or, when it could not be
                        // wrapped, a fresh undefined that is ours to release.
                        // No current context: wrapping uses the item's own
                        // realm, and taking it here (a Global made and
                        // disposed) was a fifth of `list[i]`.
                        const wrapped = conv.instanceToV8(isolate, unwrapped_result);
                        info.setReturnValue(wrapped);
                        // An empty handle (a wrapper the collector took)
                        // answers undefined too, and is still the cache's.
                        if (!v8.v8_Global_IsEmpty(@ptrCast(wrapped)) and info.returnValueIsUndefined()) v8.v8_Value_Dispose(wrapped);
                    } else {
                        const v8_context = current_context.get() orelse {
                            conv.throwError(isolate, "No V8 context");
                            return .kNo;
                        };
                        // Other type (like DOMString, CSSOMString) - convert to V8 string
                        const v8_value = convertSpecialResult(ChildType, special.indexed_getter.?, isolate, v8_context, unwrapped_result) catch {
                            conv.throwError(isolate, "Failed to convert result to V8");
                            return .kNo;
                        };
                        info.setReturnValue(@ptrCast(v8_value));
                        // setReturnValue reads the handle into a Local; one the
                        // conversion made is the binding's to release.
                        if (comptime getterValueIsOwned(ChildType)) v8.v8_Global_Dispose(@ptrCast(v8_value));
                    }
                    return .kYes;
                } else {
                    // null - return kNo to let V8 continue property lookup
                    return .kNo;
                }
            } else {
                // Non-optional type (like CSSOMString)
                const v8_context = current_context.get() orelse {
                    conv.throwError(isolate, "No V8 context");
                    return .kNo;
                };
                const v8_value = convertSpecialResult(ActualReturnType, special.indexed_getter.?, isolate, v8_context, result) catch {
                    conv.throwError(isolate, "Failed to convert result to V8");
                    return .kNo;
                };
                info.setReturnValue(@ptrCast(v8_value));
                if (comptime getterValueIsOwned(ActualReturnType)) v8.v8_Global_Dispose(@ptrCast(v8_value));
                return .kYes;
            }
        }

        /// Indexed property enumerator for Reflect.ownKeys and Object.keys support
        /// Returns an array of indices as integers for enumeration
        /// Called when JavaScript needs to enumerate indexed properties
        fn indexedPropertyEnumerator(
            info: *const v8.PropertyCallbackInfo,
        ) callconv(.c) void {
            // Only compile this function body if Interface has get_length
            if (comptime !@hasDecl(Interface, "get_length")) {
                // No length property - can't enumerate
                return;
            }

            // Every handle made here is this callback's: SetReturnValue and
            // Array::Set copy what they are given. Kept, an enumeration of a
            // collection's keys cost its context, its array and one Integer
            // per index.
            const isolate = info.getIsolate();
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse {
                return;
            };
            defer v8.v8_Context_Dispose(v8_context);

            // Get the 'this' object (the interface instance)
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);

            // Extract instance pointer from internal field
            const instance_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(this_obj, 0);
            if (instance_ptr == null) {
                // Called on prototype, not an instance - return empty array
                const empty_arr = v8.v8_Array_New(isolate, 0);
                defer v8.v8_Array_Dispose(empty_arr);
                info.setReturnValue(@ptrCast(empty_arr));
                return;
            }

            // Safety check: detect use-after-free by checking for poison patterns
            const ptr_as_int = @intFromPtr(instance_ptr);
            const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
            const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
            if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
                (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
            {
                return;
            }

            const instance: *runtime.Instance = @ptrCast(@alignCast(instance_ptr));

            // Get the length of the collection
            const length = Interface.get_length(instance) catch {
                return;
            };

            // Create an array of indices as integers
            // V8's indexed property interceptor expects integer indices here.
            // V8 internally converts these to strings when needed for ownKeys.
            const indices_arr = v8.v8_Array_New(isolate, @intCast(length));
            defer v8.v8_Array_Dispose(indices_arr);
            var i: u32 = 0;
            while (i < length) : (i += 1) {
                const v8_idx = v8.v8_Integer_New(isolate, @intCast(i));
                defer v8.v8_Value_Dispose(@ptrCast(v8_idx));
                _ = v8.v8_Array_Set(indices_arr, v8_context, i, @ptrCast(v8_idx));
            }
            info.setReturnValue(@ptrCast(indices_arr));
        }

        /// Indexed property query callback for Object.getOwnPropertyDescriptor attribute queries
        /// Returns property attributes: None=0, ReadOnly=1, DontEnum=2, DontDelete=4
        /// Returns Intercepted::kYes if property exists, Intercepted::kNo otherwise
        fn indexedPropertyQuery(
            index: u32,
            info: *const v8.PropertyCallbackInfo,
        ) callconv(.c) v8.Intercepted {
            // Only compile if Interface has an indexed getter and get_length
            if (comptime !has_indexed_getter or !@hasDecl(Interface, "get_length")) {
                return .kNo;
            }

            // The instance: the object that has the interceptor (`i in list`,
            // and `i in heir` for an object whose prototype is the list),
            // read without a handle, as the getter reads it.
            const instance_ptr = info.holderAlignedPointer(0);
            if (instance_ptr == null) {
                return .kNo;
            }

            // Safety check
            const ptr_as_int = @intFromPtr(instance_ptr);
            const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
            const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
            if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
                (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
            {
                return .kNo;
            }

            const instance: *runtime.Instance = @ptrCast(@alignCast(instance_ptr));

            // Check if index is in range
            const length = Interface.get_length(instance) catch return .kNo;
            if (index >= length) {
                // Property doesn't exist
                return .kNo;
            }

            // Property exists - return attributes
            // Indexed properties are: enumerable, configurable, NOT writable (read-only) for most collections
            // 3.9.1 step 1.2.7: writable when there is an indexed setter.
            const attributes: i32 = if (has_indexed_setter) 0 else 1; // 1 = ReadOnly
            // A Smi in the return slot: no handle to make or release. Every
            // `i in list` and every element Array.prototype.indexOf visits
            // (HasProperty, then Get) asks this.
            info.setReturnValueInt32(attributes);
            return .kYes;
        }

        /// Indexed property descriptor callback for Object.getOwnPropertyDescriptor
        /// Returns a property descriptor object: { value, writable, enumerable, configurable }
        /// Returns Intercepted::kYes if property exists and descriptor was set, Intercepted::kNo otherwise
        fn indexedPropertyDescriptor(
            index: u32,
            info: *const v8.PropertyCallbackInfo,
        ) callconv(.c) v8.Intercepted {
            // Only compile if Interface has an indexed getter and get_length
            if (comptime !has_indexed_getter or !@hasDecl(Interface, "get_length")) {
                return .kNo;
            }
            const indexed_getter = @field(Interface, indexed_getter_name.?);

            const isolate = info.getIsolate();

            // The instance: the object whose own property this is - for
            // [[GetOwnProperty]] the holder is the receiver - read without a
            // handle, as the getter and the query read it. A proxy's
            // [[HasProperty]] that answers false asks this too (its
            // invariant check, ES 10.5.7 step 9), for every index past the
            // end of an HTMLCollection.
            const instance_ptr = info.holderAlignedPointer(0);
            if (instance_ptr == null) {
                return .kNo;
            }

            // Safety check
            const ptr_as_int = @intFromPtr(instance_ptr);
            const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
            const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
            if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
                (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
            {
                return .kNo;
            }

            const instance: *runtime.Instance = @ptrCast(@alignCast(instance_ptr));

            // Check if index is in range
            const length = Interface.get_length(instance) catch return .kNo;
            if (index >= length) {

                // Property doesn't exist
                return .kNo;
            }

            // The current context, for the descriptor and a converted value:
            // taken past the early returns. Owned: v8_Isolate_GetCurrentContext
            // allocates a Global per call.
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return .kNo;
            defer v8.v8_Context_Dispose(v8_context);

            // Get the value at this index
            const result_allocator = instance.ctx.allocator;
            const result = indexed_getter(instance, index) catch return .kNo;
            // A string item() made for the result is the binding's.
            defer freeOwnedResult(@TypeOf(result), result_allocator, result);

            // Convert result to V8 value
            const ReturnType = @typeInfo(@TypeOf(indexed_getter)).@"fn".return_type.?;
            const ActualReturnType = @typeInfo(ReturnType).error_union.payload;
            const type_info = @typeInfo(ActualReturnType);

            // The descriptor and the value - unless it is a wrapper, the
            // wrapper cache's - are made here and released once setReturnValue
            // has read the descriptor into a Local. Built key by key and kept,
            // the descriptor, its keys and its booleans were eight Globals per
            // Object.getOwnPropertyDescriptor(collection, i) - and per
            // Object.defineProperty on an indexed collection, which V8 asks
            // for the current descriptor first.
            var v8_value: ?*v8.Value = null;
            var value_owned = true;
            if (type_info == .optional) {
                if (result) |unwrapped_result| {
                    const ChildType = type_info.optional.child;
                    if (ChildType == *runtime.Instance) {
                        // Its wrapper in its relevant realm, the wrapper cache's.
                        v8_value = conv.instanceToV8(isolate, unwrapped_result);
                        value_owned = v8.v8_Value_IsUndefined(v8_value.?);
                    } else {
                        v8_value = convertSpecialResult(ChildType, special.indexed_getter.?, isolate, v8_context, unwrapped_result) catch return .kNo;
                        value_owned = comptime getterValueIsOwned(ChildType);
                    }
                } else {
                    // null value - use undefined
                    v8_value = v8.v8_Undefined(isolate);
                }
            } else {
                v8_value = convertSpecialResult(ActualReturnType, special.indexed_getter.?, isolate, v8_context, result) catch return .kNo;
                value_owned = comptime getterValueIsOwned(ActualReturnType);
            }

            if (v8_value == null) return .kNo;
            defer if (value_owned) v8.v8_Global_Dispose(v8_value.?);

            // 3.9.1 step 1.2.7: writable when there is an indexed setter.
            const writable = has_indexed_setter;

            // { value: v8_value, writable, enumerable: true, configurable: true },
            // made in one call (as the named descriptor's is).
            const desc = v8.v8_CreateDataPropertyDescriptor(
                v8_context,
                v8_value.?,
                writable,
                true, // enumerable: always, for indexed properties
                true, // configurable: always, for WebIDL properties
            ) orelse return .kNo;

            info.setReturnValue(@ptrCast(desc));
            // The descriptor is made for this call, and setReturnValue reads
            // it into a Local.
            v8.v8_Global_Dispose(@ptrCast(desc));
            return .kYes;
        }

        /// [[Delete]] (WebIDL 3.9.4) step 1, for an array index P of an
        /// object with indexed properties: "If index is not a supported
        /// property index, then return true. Return false." - a TypeError in
        /// strict code, which the interceptor throws (V8 throws nothing for a
        /// deleter's false). `delete list[0]` answered true.
        fn indexedPropertyDeleter(
            index: u32,
            info: *const v8.PropertyCallbackInfo,
        ) callconv(.c) v8.Intercepted {
            if (comptime !has_indexed_getter or !@hasDecl(Interface, "get_length")) return .kNo;
            const instance = instanceOf(info.holderAlignedPointer(0)) orelse return .kNo;
            const length = Interface.get_length(instance) catch return .kNo;
            if (index >= length) {
                info.setReturnValueBool(true);
                return .kYes;
            }
            info.setReturnValueBool(false);
            if (info.shouldThrowOnError()) conv.throwTypeError(info.getIsolate(), "Cannot delete an indexed property");
            return .kYes;
        }

        /// Indexed property setter for read-only collections
        /// Per WebIDL spec, [[Set]] on legacy platform objects without indexed setter:
        /// - In strict mode: throw TypeError
        /// - In sloppy mode: silently fail (return without error)
        ///
        /// Uses V8's ShouldThrowOnError() to check strict mode and throw TypeError accordingly.
        fn indexedPropertySetterReadOnly(
            index: u32,
            value: *v8.Value,
            info: *const v8.PropertyCallbackInfo,
        ) callconv(.c) v8.Intercepted {
            _ = value;

            // Only compile if Interface has an indexed getter
            if (comptime !has_indexed_getter or !@hasDecl(Interface, "get_length")) {
                return .kNo;
            }

            const isolate = info.getIsolate();

            // Get the 'this' object
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);

            // Extract instance pointer from internal field
            const instance_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(this_obj, 0);
            if (instance_ptr == null) {
                return .kNo;
            }

            // Safety check
            const ptr_as_int = @intFromPtr(instance_ptr);
            const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
            const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
            if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
                (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
            {
                return .kNo;
            }

            _ = @as(*runtime.Instance, @ptrCast(@alignCast(instance_ptr)));

            // Per WebIDL §3.9.3 [[DefineOwnProperty]] step 1.2:
            // "If O supports indexed properties and P is an array index, then:
            //   If O does not implement an interface with an indexed property setter,
            //   then return false."
            //
            // This applies to ALL array indices, not just in-range ones.
            // A read-only indexed collection rejects ALL indexed property assignments.
            // Returning false causes TypeError in strict mode.
            if (info.shouldThrowOnError()) {
                // Strict mode - throw TypeError from creation context for cross-realm correctness
                const creation_ctx = v8.v8_Object_GetCreationContext(this_obj) orelse {
                    // Fallback to error in current context if creation context unavailable
                    var buf: [64]u8 = undefined;
                    const msg = std.fmt.bufPrint(&buf, "Cannot set property \"{d}\" on read-only indexed collection", .{index}) catch "Cannot set property on read-only indexed collection";
                    conv.throwTypeError(isolate, msg);
                    return .kYes;
                };

                var buf: [64]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "Cannot set property \"{d}\" on read-only indexed collection", .{index}) catch "Cannot set property on read-only indexed collection";
                conv.throwTypeErrorFromContext(isolate, creation_ctx, msg);
            }
            // In sloppy mode or after throwing, indicate we handled the request
            return .kYes;
        }

        /// Indexed property setter for a collection with an indexed setter
        /// Actually sets the value at the given index
        fn indexedPropertySetter(
            index: u32,
            value: *v8.Value,
            info: *const v8.PropertyCallbackInfo,
        ) callconv(.c) v8.Intercepted {
            // Only compile if Interface has indexed setter
            if (comptime !has_indexed_setter) {
                return .kNo;
            }

            const isolate = info.getIsolate();

            // Get the 'this' object
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);

            // Extract instance pointer from internal field
            const instance_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(this_obj, 0);
            if (instance_ptr == null) {
                return .kNo;
            }

            // Safety check
            const ptr_as_int = @intFromPtr(instance_ptr);
            const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
            const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
            if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
                (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
            {
                return .kNo;
            }

            const instance: *runtime.Instance = @ptrCast(@alignCast(instance_ptr));

            // The indexed setter Meta.special_operations names.
            const setter_name = comptime special.indexed_setter.?;
            const setter_fn = @field(Interface, setter_name);

            // Get the value type from the setter function signature
            const SetterFnType = @TypeOf(setter_fn);
            const fn_info = @typeInfo(SetterFnType).@"fn";
            const params = fn_info.params;

            // Expected signature: fn(instance: *runtime.Instance, index: u32, value: ValueType) !void
            if (params.len < 3) {
                return .kNo;
            }

            const ValueType = params[2].type orelse return .kNo;

            // V8 hands an interceptor the value as a LOCAL - a pointer to a
            // handle slot - and fromV8Value reads a Global<Value>*, one level of
            // indirection further out. Read directly, the slot's contents were
            // taken for a slot, and `select[0] = option` (DefineOwnProperty.html)
            // dereferenced an object's first word. Persist it first, as the named
            // setter always has.
            const value_global = v8.v8_Value_Persist(isolate, @ptrCast(value)) orelse return .kNo;
            defer v8.v8_Value_Dispose(value_global);

            // The current context, for the conversion: acquired here, past the
            // early returns, and released unless converting a `ValueType` can
            // keep it (typeRetainsContext, the rule every binding path uses).
            // It is a fresh Global of the callee's realm per call; acquired at
            // entry and never released, each `select[0] = option` pinned the
            // realm.
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return .kNo;
            defer if (comptime !typeRetainsContext(ValueType)) v8.v8_Context_Dispose(v8_context);

            // Convert V8 value to the expected Zig type
            // An interface type converts to the interface codegen names for
            // the setter's value (its second argument).
            //
            // WebIDL 3.9.7 "invoke an indexed property setter", step 5:
            // "Let value be the result of converting V to an IDL value of
            // type T" - what that throws is the assignment's exception
            // (`select[0] = new Blob()` is a TypeError in every browser; a
            // value of the wrong interface was handed to the setter as an
            // option). It returned kNo, and V8 then defined an own property.
            const zig_value = conv.fromV8ValueAs(ValueType, comptime argumentInterface(Interface, setter_name, 1), instance.ctx.allocator, isolate, v8_context, value_global) catch |err| {
                if (err != conv.ConversionError.ExceptionPending) conv.throwTypeError(isolate, @errorName(err));
                return .kYes;
            };

            // Call the setter (in a binding catch scope when it is [CEReactions])
            callInCatchScopeIfListed(Interface, setter_name, isolate, setter_fn, .{ instance, index, zig_value }) catch {
                return .kNo;
            };

            return .kYes;
        }

        /// Indexed property definer callback for Object.defineProperty()
        /// Implements WebIDL §3.9.3 [[DefineOwnProperty]] for indexed properties.
        ///
        /// Per WebIDL spec:
        /// - If interface supports indexed properties but NO setter: reject all defines
        /// - If interface HAS indexed property setter: validate descriptor, then invoke setter
        fn indexedPropertyDefiner(
            index: u32,
            desc: *const v8.PropertyDescriptor,
            info: *const v8.PropertyCallbackInfoVoid,
        ) callconv(.c) v8.Intercepted {
            const isolate = info.getIsolate();
            // The current context is acquired below, only where a value is
            // converted: it is a fresh Global of the callee's realm per call,
            // and taken here at entry it was never released - every
            // Object.defineProperty on an indexed collection pinned the realm.

            // WebIDL §3.9.3 step 1: Interface supports indexed properties
            // This callback is only registered for interfaces with indexed property support,
            // so we know we're handling an indexed property access.

            // WebIDL 3.9.3 [[DefineOwnProperty]] step 1, P an array index:
            // 1.1. "If the result of calling IsDataDescriptor(Desc) is
            //      false, then return false."
            // 1.2. "If O does not implement an interface with an indexed
            //      property setter, then return false."
            // Both are refuseDefine's false - a TypeError for
            // Object.defineProperty and strict code, Reflect.defineProperty's
            // and the legacy platform object proxy's false otherwise. Thrown
            // unconditionally, a sloppy-mode `collection[0] = x` through the
            // proxy threw too.
            if (!has_indexed_setter) return refuseDefine(info, isolate);
            if (!v8.v8_PropertyDescriptor_IsDataDescriptor(desc)) return refuseDefine(info, isolate);

            // Step 1.4-1.6: Ignore writable, enumerable, configurable flags for indexed setters per WebIDL §3.9.3

            // Step 1.7: Invoke indexed property setter with value
            // Extract instance pointer from internal field of the actual instance (This)
            // Note: getThis() returns the actual object, getHolder() returns the prototype
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            const instance_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(this_obj, 0);
            if (instance_ptr) |ptr| {
                const instance: *runtime.Instance = @ptrCast(@alignCast(ptr));
                if (v8.v8_PropertyDescriptor_GetValue(desc)) |value| {
                    // A fresh Global the wrapper made for the descriptor's
                    // value: ours. The setter's conversion reads it; nothing
                    // keeps this handle (a value it keeps, it keeps through
                    // its own).
                    defer v8.v8_Global_Dispose(value);
                    // Step 1.3: invoke the indexed setter with P and
                    // Desc.[[Value]] (the setter Meta.special_operations
                    // names; this definer is installed only with one).
                    if (comptime has_indexed_setter) {
                        const setter_name = comptime special.indexed_setter.?;
                        const setter_fn = @field(Interface, setter_name);
                        const value_type = comptime @typeInfo(@TypeOf(setter_fn)).@"fn".params[2].type.?;
                        // Released unless converting the value can keep it
                        // (typeRetainsContext).
                        const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return .kYes;
                        defer if (comptime !typeRetainsContext(value_type)) v8.v8_Context_Dispose(v8_context);
                        const zig_value = conv.fromV8ValueAs(value_type, comptime argumentInterface(Interface, setter_name, 1), instance.ctx.allocator, isolate, v8_context, value) catch |err| {
                            conv.throwTypeError(isolate, @errorName(err));
                            return .kYes;
                        };
                        callInCatchScopeIfListed(Interface, setter_name, isolate, setter_fn, .{ instance, index, zig_value }) catch |err| {
                            conv.throwTypeError(isolate, @errorName(err));
                        };
                    }
                }
            }

            return .kYes;
        }

        // =====================================================================
        // Named properties of a legacy platform object (WebIDL 3.9)
        //
        // The named getter, setter and deleter are the functions
        // Meta.special_operations names (specialBinding). Each V8 named
        // interceptor reads its key's text (PropertyName) and runs one of the
        // `named*` steps below, which take the name as text: the indexed
        // interceptors of an interface with named properties and no indexed
        // ones run the same steps with an index's decimal text (WebIDL 3.9
        // knows only String property names; V8 routes an array index to the
        // indexed interceptors - Blink forwards them the same way,
        // bind_gen/interface.py make_indexed_property_*_callback).
        //
        // O, the legacy platform object, is the interceptor's holder for a
        // read ([[Get]] on an heir reaches its prototype's interceptor) and
        // the receiver for a write (V8 calls a setter or definer interceptor
        // only when they are the same object).
        // =====================================================================

        /// CSSStyleDeclaration's named properties are Crane's camel-cased CSS
        /// attributes (crane_css_properties): every CSS property name, not
        /// only the set ones, and the interceptor masks the prototype.
        const is_css_style_declaration = std.mem.endsWith(u8, interface_name, "CSSStyleDeclaration") or std.mem.endsWith(u8, interface_name, "CSSStyleProperties");

        /// Whether named properties shadow the prototype chain: WebIDL 3.4.7
        /// [LegacyOverrideBuiltIns] (the named property visibility
        /// algorithm's step 3, and a masking interceptor), or CSS's.
        const named_properties_mask = special.legacy_override_built_ins or is_css_style_declaration;

        /// A property key's text as a DOMString holds it: WTF-8 (WriteUtf8
        /// without REPLACE_INVALID_UTF8 keeps a lone surrogate as its three
        /// bytes), of any length, the empty string included - a key past the
        /// stack buffer is copied to the heap, where a 256-byte buffer used
        /// to refuse it. Not copied once read: the text may be its buffer.
        const PropertyName = struct {
            stack: [256]u8 = undefined,
            heap: ?[]u8 = null,

            /// `property`'s text, or null for a Symbol (or no memory).
            fn read(self: *PropertyName, property: *v8.Name) ?[]const u8 {
                if (!v8.v8_Name_IsString(property)) return null;
                const str: *v8.String = @ptrCast(property);
                const length: usize = @intCast(@max(v8.v8_String_Utf8Length_Raw(str), 0));
                // Room for WriteUtf8's terminating NUL.
                const buffer: []u8 = if (length < self.stack.len) self.stack[0 .. length + 1] else blk: {
                    const bytes = std.heap.c_allocator.alloc(u8, length + 1) catch return null;
                    self.heap = bytes;
                    break :blk bytes;
                };
                const written = v8.v8_String_WriteUtf8_Raw(str, buffer.ptr, @intCast(buffer.len));
                if (written < 0) return null;
                return buffer[0..@min(@as(usize, @intCast(written)), length)];
            }

            fn deinit(self: *PropertyName) void {
                if (self.heap) |bytes| std.heap.c_allocator.free(bytes);
                self.heap = null;
            }
        };

        /// An array index's text: the property name WebIDL sees.
        const IndexName = struct {
            buffer: [10]u8 = undefined,

            fn of(self: *IndexName, index: u32) []const u8 {
                return std.fmt.bufPrint(&self.buffer, "{d}", .{index}) catch unreachable;
            }
        };

        /// The instance behind `object` - O - or null for a prototype or a
        /// wrapper whose instance has gone.
        fn instanceOf(instance_ptr: ?*anyopaque) ?*runtime.Instance {
            const ptr = instance_ptr orelse return null;
            const as_int = @intFromPtr(ptr);
            const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
            const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
            if (as_int == poison_pattern_aa or as_int == poison_pattern_dead or
                (as_int & 0xFFFF000000000000) == 0xaaaa000000000000) return null;
            return @ptrCast(@alignCast(ptr));
        }

        /// O for a read: the interceptor's holder, without a handle.
        fn holderInstance(info: *const v8.PropertyCallbackInfo) ?*runtime.Instance {
            return instanceOf(info.holderAlignedPointer(0));
        }

        /// O for a write: the receiver (V8 runs a setter or definer
        /// interceptor only on the holder itself).
        fn receiverInstance(info: anytype) ?*runtime.Instance {
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            return instanceOf(v8.v8_Object_GetAlignedPointerFromInternalField(this_obj, 0));
        }

        /// The named property visibility algorithm's step 1 (WebIDL 3.9.7):
        /// whether `name` is one of `instance`'s supported property names
        /// (2.5.6.2). Asked of the impl for this one name when it answers
        /// that (special.supported_property_name; WebKit's
        /// isSupportedPropertyName, Blink's NamedPropertyQuery): a masking
        /// interceptor asks on EVERY property read, and a form's list is a
        /// walk of its tree (codex-lpo review M1). Otherwise the generated
        /// getSupportedPropertyNames' list, made in an arena over a stack
        /// buffer that spills to the heap: a fixed 8 KB buffer said "not
        /// supported" for every name of a long list (a Storage of many keys).
        /// A failure answers "not supported", as an unbuildable list does.
        fn isSupportedPropertyName(instance: *runtime.Instance, key: []const u8) bool {
            if (comptime special.supported_property_name) |query| {
                return @field(Interface, query)(instance, runtime.DOMString.initInterned(key)) catch false;
            }
            var fallback = std.heap.stackFallback(8192, std.heap.c_allocator);
            var arena = std.heap.ArenaAllocator.init(fallback.get());
            defer arena.deinit();
            const names = Interface.getSupportedPropertyNames(instance, arena.allocator()) catch return false;
            for (names) |supported| {
                if (std.mem.eql(u8, supported.asSlice(), key)) return true;
            }
            // CSS: script names a property camel-cased (backgroundColor), the
            // declaration lists it dashed (background-color).
            if (comptime special.crane_css_properties) {
                var kebab_buf: [256]u8 = undefined;
                if (camelToKebab(key, &kebab_buf)) |kebab_name| {
                    for (names) |supported| {
                        if (std.mem.eql(u8, supported.asSlice(), kebab_name)) return true;
                    }
                }
            }
            return false;
        }

        /// Convert camelCase to kebab-case for CSS property name matching
        /// e.g., "backgroundColor" -> "background-color"
        fn camelToKebab(input: []const u8, buf: *[256]u8) ?[]const u8 {
            if (input.len == 0) return null;
            var out_idx: usize = 0;

            for (input) |c| {
                if (out_idx >= buf.len - 2) return null; // Need room for potential '-' + char

                if (c >= 'A' and c <= 'Z') {
                    // Uppercase letter - insert hyphen and lowercase
                    if (out_idx > 0) {
                        buf[out_idx] = '-';
                        out_idx += 1;
                    }
                    buf[out_idx] = c + 32; // Convert to lowercase
                    out_idx += 1;
                } else {
                    buf[out_idx] = c;
                    out_idx += 1;
                }
            }

            return buf[0..out_idx];
        }

        /// Whether O - the holder of `info` - has a real own property named
        /// `name`, and whether its prototype chain does: interceptors'
        /// properties are neither (v8_LegacyPlatformObject_NamedPropertyState).
        const NameState = struct {
            own: bool,
            in_prototype_chain: bool,

            fn of(info: *const anyopaque, key: []const u8) NameState {
                // The name's code units: a lone surrogate stays itself.
                var fallback = std.heap.stackFallback(1024, std.heap.c_allocator);
                const allocator = fallback.get();
                const units = allocator.alloc(u16, key.len) catch return .{ .own = false, .in_prototype_chain = false };
                defer allocator.free(units);
                const count = value_operations.wtf8ToUtf16(key, units);
                const bits = v8.v8_LegacyPlatformObject_NamedPropertyState(info, units.ptr, @intCast(count));
                return .{ .own = bits & 1 != 0, .in_prototype_chain = bits & 2 != 0 };
            }
        };

        /// WebIDL 3.9.7 "named property visibility algorithm" for `name` on
        /// O: 1. a supported property name; 2. not an own property of O;
        /// 3. with [LegacyOverrideBuiltIns], visible; 4-6. otherwise visible
        /// unless a prototype has it (no named properties object: never for
        /// a [Global]'s, which have none of these handlers).
        fn isVisible(instance: *runtime.Instance, info: *const anyopaque, key: []const u8) bool {
            if (!isSupportedPropertyName(instance, key)) return false;
            const state = NameState.of(info, key);
            if (state.own) return false;
            if (named_properties_mask) return true;
            return !state.in_prototype_chain;
        }

        /// The named property's value - the named getter's result for
        /// `name` (3.9.1 step 2.1.3-4) - as a V8 value, or null when the
        /// getter answers null (or fails). `owned`: a handle the caller
        /// releases once read; a wrapper is the wrapper cache's.
        const NamedValue = struct { value: *v8.Value, owned: bool };

        fn convertSpecialResult(comptime T: type, comptime delegate: []const u8, isolate: *v8.Isolate, context: *v8.Context, value: T) !*v8.Value {
            if (comptime returnsByteString(Interface, delegate)) return conv.byteStringToV8(T, isolate, value);
            return conv.toV8Value(T, isolate, context, value);
        }

        fn namedPropertyValue(instance: *runtime.Instance, isolate: *v8.Isolate, v8_context: *v8.Context, key: []const u8) ?NamedValue {
            const getter_fn = @field(Interface, special.named_getter.?);
            const result_allocator = instance.ctx.allocator;
            const result = getter_fn(instance, runtime.DOMString.initInterned(key)) catch return null;
            // A string the named getter made for the result is the binding's.
            defer freeOwnedResult(@TypeOf(result), result_allocator, result);

            const ReturnType = @typeInfo(@TypeOf(getter_fn)).@"fn".return_type.?;
            const ActualReturnType = @typeInfo(ReturnType).error_union.payload;
            const type_info = @typeInfo(ActualReturnType);
            if (type_info == .optional) {
                const unwrapped = result orelse return null;
                const ChildType = type_info.optional.child;
                if (ChildType == *runtime.Instance) {
                    // Its wrapper in its relevant realm, the wrapper cache's -
                    // or, when it could not be wrapped, a fresh undefined.
                    const wrapped = conv.instanceToV8(isolate, unwrapped);
                    return .{ .value = wrapped, .owned = v8.v8_Value_IsUndefined(wrapped) };
                }
                if (ChildType == runtime.DOMString) {
                    // WTF-8: its lone surrogates kept.
                    const string = conv.newStringFromWtf8(isolate, unwrapped.asSlice()) orelse return null;
                    return .{ .value = string, .owned = true };
                }
                const v8_value = convertSpecialResult(ChildType, special.named_getter.?, isolate, v8_context, unwrapped) catch return null;
                return .{ .value = @ptrCast(v8_value), .owned = comptime getterValueIsOwned(ChildType) };
            }
            // DOMStringMap's anonymous getter comes here: one string per
            // `el.dataset.x` read - 60,000 a page on the legacy multi-byte
            // decode tests - each kept for the life of the process until the
            // conversion's handle was released.
            const v8_value = convertSpecialResult(ActualReturnType, special.named_getter.?, isolate, v8_context, result) catch return null;
            return .{ .value = @ptrCast(v8_value), .owned = comptime getterValueIsOwned(ActualReturnType) };
        }

        /// LegacyPlatformObjectGetOwnProperty step 2, for [[Get]]: the value
        /// of a named property the visibility algorithm (3.9.7) finds visible.
        /// What V8 has already answered decides which steps are asked here:
        ///   - a non-masking interceptor (no [LegacyOverrideBuiltIns]) is
        ///     consulted only once O's own properties and its prototype chain
        ///     have no P - steps 2 and 4-6 - so it asks step 1;
        ///   - a masking one is consulted BEFORE O's own properties
        ///     (LookupIterator visits a holder's interceptor first), so it asks
        ///     steps 1-3: step 2, an own property hides the named property, holds
        ///     under [LegacyOverrideBuiltIns], which skips only the prototype
        ///     chain (form-nameditem.html: `form.x = 5` before a control named
        ///     x is added keeps reading 5);
        ///   - an indexed one always masks, so a forwarded array index asks
        ///     the whole algorithm (`Storage.prototype[9] = p` hides
        ///     storage's key "9") - `whole_visibility`.
        /// Crane's CSS attributes are no WebIDL named properties: as before.
        fn namedGet(info: *const v8.PropertyCallbackInfo, key: []const u8, comptime whole_visibility: bool) v8.Intercepted {
            if (comptime !has_named_getter) return .kNo;
            const instance = holderInstance(info) orelse return .kNo;
            if (whole_visibility or (comptime special.legacy_override_built_ins and !is_css_style_declaration)) {
                // isVisible stops at step 1 for an unsupported name: the
                // own-property question is asked only of a supported one.
                if (!isVisible(instance, info, key)) return .kNo;
            } else if (!is_css_style_declaration and !isSupportedPropertyName(instance, key)) {
                // CSSStyleDeclaration answers every CSS property name -
                // computed style's are all set - not only the declared ones.
                return .kNo;
            }
            const isolate = info.getIsolate();
            // Taken past the early returns: this runs for every property miss
            // on a named-property interface. Owned: a Global per call.
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return .kNo;
            defer v8.v8_Context_Dispose(v8_context);
            const named = namedPropertyValue(instance, isolate, v8_context, key) orelse return .kNo;
            info.setReturnValue(named.value);
            // setReturnValue reads the handle into the return slot.
            if (named.owned) v8.v8_Value_Dispose(named.value);
            return .kYes;
        }

        /// [[GetOwnProperty]] (3.9.1, LegacyPlatformObjectGetOwnProperty step
        /// 2) as attributes: a visible named property is configurable,
        /// writable only with a named setter (step 2.1.7), and enumerable
        /// unless [LegacyUnenumerableNamedProperties] (step 2.1.8).
        fn namedQuery(info: *const v8.PropertyCallbackInfo, key: []const u8) v8.Intercepted {
            if (comptime !has_named_getter) return .kNo;
            const instance = holderInstance(info) orelse return .kNo;
            if (!isVisible(instance, info, key)) return .kNo;
            var attributes: i32 = 0;
            if (special.legacy_unenumerable_named_properties) attributes |= v8.PropertyAttribute.DontEnum;
            if (!has_named_setter) attributes |= v8.PropertyAttribute.ReadOnly;
            info.setReturnValueInt32(attributes);
            return .kYes;
        }

        /// [[GetOwnProperty]] (3.9.1, LegacyPlatformObjectGetOwnProperty step
        /// 2): a visible named property's descriptor - {[[Value]]: the named
        /// getter's result, [[Writable]]: a named setter exists,
        /// [[Enumerable]]: no [LegacyUnenumerableNamedProperties],
        /// [[Configurable]]: true}.
        fn namedDescriptor(info: *const v8.PropertyCallbackInfo, key: []const u8) v8.Intercepted {
            if (comptime !has_named_getter) return .kNo;
            const instance = holderInstance(info) orelse return .kNo;
            if (!isVisible(instance, info, key)) return .kNo;
            const isolate = info.getIsolate();
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return .kNo;
            // Owned: v8_Isolate_GetCurrentContext allocates a Global per call.
            defer v8.v8_Context_Dispose(v8_context);
            const named = namedPropertyValue(instance, isolate, v8_context, key) orelse return .kNo;
            defer if (named.owned) v8.v8_Value_Dispose(named.value);
            const desc = v8.v8_CreateDataPropertyDescriptor(
                v8_context,
                named.value,
                has_named_setter,
                !special.legacy_unenumerable_named_properties,
                true,
            ) orelse return .kNo;
            info.setReturnValue(@ptrCast(desc));
            // Made for this call; setReturnValue reads it into a Local.
            v8.v8_Global_Dispose(@ptrCast(desc));
            return .kYes;
        }

        /// "Invoke a named property setter" (WebIDL 3.9.7) on `instance` with
        /// P = `name` and V = `value` (a Global, the caller's): convert V to
        /// the setter's second argument type, then run it. False when it
        /// threw - the exception is pending (an exception the setter raises
        /// propagates, in sloppy code too: `dataset['-x'] = v` is a
        /// SyntaxError).
        fn invokeNamedSetter(isolate: *v8.Isolate, instance: *runtime.Instance, key: []const u8, value: *v8.Value, rethrow: bool) bool {
            const setter_name = comptime special.named_setter.?;
            const setter_fn = @field(Interface, setter_name);
            const ValueType = comptime @typeInfo(@TypeOf(setter_fn)).@"fn".params[2].type.?;
            // Released unless converting a `ValueType` can keep it
            // (typeRetainsContext). A fresh Global of the callee's realm per
            // call; acquired at entry and never released, every
            // `el.dataset.x = v` pinned the realm.
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return false;
            defer if (comptime !typeRetainsContext(ValueType)) v8.v8_Context_Dispose(v8_context);
            // Step 4: convert V to an IDL value of type T.
            const zig_value = conv.fromV8ValueAs(ValueType, comptime argumentInterface(Interface, setter_name, 1), instance.ctx.allocator, isolate, v8_context, value) catch |err| {
                // ExceptionPending: the conversion rethrew script's exception.
                if (err != conv.ConversionError.ExceptionPending and rethrow) conv.throwWebIDLError(isolate, @errorName(err));
                return false;
            };
            defer freeConvertedValue(ValueType, instance.ctx.allocator, zig_value);
            // Step 6: the operation's method steps with « P, value » (in a
            // binding catch scope when it is [CEReactions]).
            callInCatchScopeIfListed(Interface, setter_name, isolate, setter_fn, .{ instance, runtime.DOMString.initInterned(key), zig_value }) catch |err| {
                if (rethrow) conv.throwWebIDLError(isolate, @errorName(err));
                return false;
            };
            return true;
        }

        /// [[Set]] (3.9.2) step 1.2: O is the receiver (V8 calls a setter
        /// interceptor only then) and has a named setter, and P is a String -
        /// invoke the named setter with P and V, and return true. Every
        /// String: one not yet supported creates the property.
        fn namedSet(info: *const v8.PropertyCallbackInfo, key: []const u8, value: *v8.Value) v8.Intercepted {
            if (comptime !has_named_setter) return .kNo;
            const instance = receiverInstance(info) orelse return .kNo;
            // Crane's CSS attributes: CSSStyleDeclaration takes every CSS
            // property name, the other declaration interfaces their set ones.
            if (comptime special.crane_css_properties) {
                // A name that is no CSS property - cssText, length, an
                // expando - is the ordinary [[Set]]'s, so the masking
                // interceptor does not swallow it (lane style1). Stated: the
                // CSS names are then own keys of the object, where browsers
                // have prototype accessors (Object.keys lists them).
                if (!isSupportedPropertyName(instance, key)) return .kNo;
            }
            const isolate = info.getIsolate();
            // V8 hands an interceptor the value as a LOCAL; fromV8Value reads
            // a Global<Value>*.
            const value_global = v8.v8_Value_Persist(isolate, @ptrCast(value)) orelse return .kNo;
            defer v8.v8_Value_Dispose(value_global);
            // A CSS property's setter fails quietly in sloppy code, as an
            // attribute's would not: kept as it was.
            const rethrow = comptime !special.crane_css_properties;
            _ = invokeNamedSetter(isolate, instance, key, value_global, rethrow or info.shouldThrowOnError());
            return .kYes;
        }

        /// [[Set]] (3.9.2) with no named setter, where V8 consults the
        /// interceptor (a masking one consults it first): [[Set]] ignores
        /// named properties (step 2's ignoreNamedProps), so the assignment
        /// is ordinary unless it would create an own property for a
        /// supported name - [[DefineOwnProperty]] step 2.2.1 refuses that:
        /// false, a TypeError in strict code. With [LegacyOverrideBuiltIns]
        /// a property of the prototype chain is the ordinary one's (Blink:
        /// GetRealNamedPropertyAttributesInPrototypeChain), so an accessor
        /// such as Document's `title` still runs.
        fn namedSetReadOnly(info: *const v8.PropertyCallbackInfo, key: []const u8) v8.Intercepted {
            if (comptime !has_named_getter) return .kNo;
            const instance = receiverInstance(info) orelse return .kNo;
            if (!isSupportedPropertyName(instance, key)) return .kNo;
            const state = NameState.of(info, key);
            if (state.own) return .kNo;
            if (named_properties_mask and state.in_prototype_chain) return .kNo;
            if (info.shouldThrowOnError()) conv.throwTypeError(info.getIsolate(), "Cannot set a named property that has no setter");
            return .kYes;
        }

        /// [[DefineOwnProperty]] (3.9.3) step 2, for a String P:
        ///   1. creating: P is not a supported property name.
        ///   2. With [LegacyOverrideBuiltIns], or when O has no own property P:
        ///      1. Not creating and no named setter: return false.
        ///      2. A named setter: not a data descriptor - return false;
        ///         otherwise invoke it with P and Desc.[[Value]], return true.
        ///   3. Otherwise OrdinaryDefineOwnProperty.
        /// "Return false" is refuseDefine's.
        fn namedDefine(info: *const v8.PropertyCallbackInfoVoid, key: []const u8, desc: *const v8.PropertyDescriptor) v8.Intercepted {
            if (comptime !has_named_getter) return .kNo;
            const isolate = info.getIsolate();
            if (comptime special.crane_css_properties) {
                // Crane's CSS attributes, as they were: an accessor is a
                // TypeError, a value goes to the setter interceptor.
                if (v8.v8_PropertyDescriptor_IsAccessorDescriptor(desc)) {
                    conv.throwTypeError(isolate, "Cannot define accessor property on named property collection");
                    return .kYes;
                }
                return .kNo;
            }
            const instance = receiverInstance(info) orelse return .kNo;
            // Step 2.1.
            const creating = !isSupportedPropertyName(instance, key);
            // Step 2.2.
            if (!named_properties_mask and NameState.of(info, key).own) return .kNo;
            if (comptime !has_named_setter) {
                // Step 2.2.1; a new name is ordinary (step 3).
                if (creating) return .kNo;
                return refuseDefine(info, isolate);
            }
            // Step 2.2.2.1.
            if (!v8.v8_PropertyDescriptor_IsDataDescriptor(desc)) return refuseDefine(info, isolate);
            // Step 2.2.2.2: Desc.[[Value]] (undefined when the descriptor has
            // only [[Writable]]). A fresh Global the wrapper made: ours.
            const value = v8.v8_PropertyDescriptor_GetValue(desc) orelse (v8.v8_Undefined(isolate) orelse return .kYes);
            defer v8.v8_Value_Dispose(value);
            _ = invokeNamedSetter(isolate, instance, key, value, true);
            return .kYes;
        }

        /// [[DefineOwnProperty]]'s "return false" (3.9.3, indexed and
        /// named): the return slot's false
        /// (Reflect.defineProperty answers it) and, where the caller throws
        /// on failure (Object.defineProperty, a strict-mode definition), the
        /// TypeError, thrown here. Left to V8, a definer's false reached
        /// Object.defineProperty as a Just(false) with nothing thrown, and V8
        /// aborted on its CHECK (JSReceiver::DefineProperty, "Check failed:
        /// success.FromJust()", 2026-10-11: `Object.defineProperty(dataset,
        /// 'x', {get() {}})`). With the exception pending, V8 propagates it
        /// (GetBooleanReturnValue answers Nothing). The indexed definer
        /// throws its own the same way.
        fn refuseDefine(info: *const v8.PropertyCallbackInfoVoid, isolate: *v8.Isolate) v8.Intercepted {
            info.setFalse();
            if (info.shouldThrowOnError()) conv.throwTypeError(isolate, "Cannot define this property of a legacy platform object");
            return .kYes;
        }

        /// [[Delete]] (3.9.4) step 2: a visible named property of O -
        /// deleted by the named deleter, or, with none, not deletable
        /// (false: a TypeError in strict code, which the interceptor throws,
        /// v8-template.h NamedPropertyDeleterCallback). Anything else is
        /// step 3, ordinary.
        fn namedDelete(info: *const v8.PropertyCallbackInfo, key: []const u8) v8.Intercepted {
            if (comptime !has_named_getter) return .kNo;
            const instance = holderInstance(info) orelse return .kNo;
            if (!isVisible(instance, info, key)) return .kNo;
            const isolate = info.getIsolate();
            if (comptime has_named_deleter) {
                const deleter_name = comptime special.named_deleter.?;
                const deleter_fn = @field(Interface, deleter_name);
                // Step 2.4.1: the operation's method steps with « P ».
                const result = callInCatchScopeIfListed(Interface, deleter_name, isolate, deleter_fn, .{ instance, runtime.DOMString.initInterned(key) }) catch |err| {
                    conv.throwWebIDLError(isolate, @errorName(err));
                    return .kYes;
                };
                // Step 2.4.2: a deleter declared to return boolean that
                // answered false did not delete.
                const deleted = if (comptime @TypeOf(result) == bool) result else true;
                if (!deleted) return refuseDelete(info, isolate);
                info.setReturnValueBool(true);
                return .kYes;
            }
            // Step 2.1.
            return refuseDelete(info, isolate);
        }

        /// [[Delete]]'s "return false": `delete` evaluates to false, and is
        /// a TypeError in strict code.
        fn refuseDelete(info: *const v8.PropertyCallbackInfo, isolate: *v8.Isolate) v8.Intercepted {
            info.setReturnValueBool(false);
            if (info.shouldThrowOnError()) conv.throwTypeError(isolate, "Cannot delete a named property");
            return .kYes;
        }

        // The V8 named interceptors: each reads its key's text and runs the
        // step above.

        fn namedPropertyGetter(property: *v8.Name, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: PropertyName = .{};
            defer key.deinit();
            return namedGet(info, key.read(property) orelse return .kNo, false);
        }

        fn namedPropertyQuery(property: *v8.Name, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: PropertyName = .{};
            defer key.deinit();
            return namedQuery(info, key.read(property) orelse return .kNo);
        }

        fn namedPropertyDescriptor(property: *v8.Name, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: PropertyName = .{};
            defer key.deinit();
            return namedDescriptor(info, key.read(property) orelse return .kNo);
        }

        fn namedPropertySetter(property: ?*v8.Name, value: ?*v8.Value, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: PropertyName = .{};
            defer key.deinit();
            return namedSet(info, key.read(property orelse return .kNo) orelse return .kNo, value orelse return .kNo);
        }

        fn namedPropertySetterReadOnly(property: *v8.Name, _: *v8.Value, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: PropertyName = .{};
            defer key.deinit();
            return namedSetReadOnly(info, key.read(property) orelse return .kNo);
        }

        fn namedPropertyDefiner(property: *v8.Name, desc: *const v8.PropertyDescriptor, info: *const v8.PropertyCallbackInfoVoid) callconv(.c) v8.Intercepted {
            var key: PropertyName = .{};
            defer key.deinit();
            return namedDefine(info, key.read(property) orelse return .kNo, desc);
        }

        fn namedPropertyDeleter(property: *v8.Name, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: PropertyName = .{};
            defer key.deinit();
            return namedDelete(info, key.read(property) orelse return .kNo);
        }

        // An interface with named properties and no indexed ones: an array
        // index is a String P like any other (WebIDL 3.9), which V8 hands to
        // the indexed interceptors - these run the named steps with its text.

        fn forwardedIndexGetter(index: u32, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: IndexName = .{};
            return namedGet(info, key.of(index), true);
        }

        fn forwardedIndexQuery(index: u32, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: IndexName = .{};
            return namedQuery(info, key.of(index));
        }

        fn forwardedIndexDescriptor(index: u32, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: IndexName = .{};
            return namedDescriptor(info, key.of(index));
        }

        fn forwardedIndexSetter(index: u32, value: *v8.Value, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: IndexName = .{};
            if (comptime has_named_setter) return namedSet(info, key.of(index), value);
            return namedSetReadOnly(info, key.of(index));
        }

        fn forwardedIndexDefiner(index: u32, desc: *const v8.PropertyDescriptor, info: *const v8.PropertyCallbackInfoVoid) callconv(.c) v8.Intercepted {
            var key: IndexName = .{};
            return namedDefine(info, key.of(index), desc);
        }

        fn forwardedIndexDeleter(index: u32, info: *const v8.PropertyCallbackInfo) callconv(.c) v8.Intercepted {
            var key: IndexName = .{};
            return namedDelete(info, key.of(index));
        }

        /// [[OwnPropertyKeys]] (3.9.6) step 3 for the named interceptor: the
        /// supported property names that are visible, in their order - and
        /// only names. Step 2's indices are the indexed interceptor's
        /// enumerator's, which V8 lists first (KeyAccumulator::CollectOwnKeys
        /// collects element indices, the indexed interceptor's included,
        /// before property names; the legacy platform object proxy sorts them
        /// first too). A number from a NAMED enumerator stops V8 at
        /// FilterForEnumerableProperties' CHECK(IsName(*element)) whenever
        /// Object.keys, for-in or JSON.stringify filters for enumerable keys
        /// on an unproxied object (2026-10-12: a form, once Codex row 23
        /// bound both of its getters); the proxy's ownKeys, which never
        /// filters, had hidden it. Own properties (steps 4-5) are V8's.
        /// Not installed where every browser leaves the names out
        /// (special.named_properties_in_own_keys false: HTMLFormElement).
        fn namedPropertyEnumerator(info: *const v8.PropertyCallbackInfo) callconv(.c) void {
            if (comptime !has_named_getter) return;

            // Every handle made here is this callback's: SetReturnValue and
            // Array::Set copy what they are given.
            const isolate = info.getIsolate();
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(v8_context);

            const instance = holderInstance(info) orelse {
                const empty_arr = v8.v8_Array_New(isolate, 0);
                defer v8.v8_Array_Dispose(empty_arr);
                info.setReturnValue(@ptrCast(empty_arr));
                return;
            };

            const names = Interface.getSupportedPropertyNames(instance, std.heap.c_allocator) catch {
                const empty_arr = v8.v8_Array_New(isolate, 0);
                defer v8.v8_Array_Dispose(empty_arr);
                info.setReturnValue(@ptrCast(empty_arr));
                return;
            };
            defer {
                for (names) |*prop_name| prop_name.deinit(std.heap.c_allocator);
                if (names.len > 0) std.heap.c_allocator.free(names);
            }

            var keys: std.ArrayListUnmanaged(*v8.Value) = .empty;
            defer {
                for (keys.items) |key| v8.v8_Value_Dispose(key);
                keys.deinit(std.heap.c_allocator);
            }

            // The visible supported property names, in order.
            for (names) |prop_name| {
                const text = prop_name.asSlice();
                const state = NameState.of(info, text);
                if (state.own) continue;
                if (!named_properties_mask and state.in_prototype_chain) continue;
                const v8_str = conv.newStringFromWtf8(isolate, text) orelse continue;
                keys.append(std.heap.c_allocator, v8_str) catch v8.v8_Value_Dispose(v8_str);
            }

            const result_arr = v8.v8_Array_New(isolate, @intCast(keys.items.len));
            defer v8.v8_Array_Dispose(result_arr);
            for (keys.items, 0..) |v8_val, idx| {
                _ = v8.v8_Array_Set(result_arr, v8_context, @intCast(idx), v8_val);
            }
            info.setReturnValue(@ptrCast(result_arr));
        }

        /// entries() callback - returns iterator yielding [index, value] pairs
        fn entriesCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            returnNewIterator(info, .entries);
        }

        /// keys() callback - returns iterator yielding indices
        fn keysCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            returnNewIterator(info, .keys);
        }

        /// values() callback - returns iterator yielding values
        fn valuesCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            returnNewIterator(info, .values);
        }

        /// The body of @@iterator, entries(), keys() and values(): a new default
        /// iterator object for `this`, returned to script.
        ///
        /// Every handle taken here is released here. Inside an API callback the
        /// current context is the callee's realm, so a Global<Context> left
        /// behind pinned that realm for the life of the isolate:
        /// html5lib_write.html iterates its frames' childNodes from the parent
        /// page, and kept every frame of all 56 variants - 898 realms, 1.17 GB -
        /// alive to its end, and V8 aborted out of memory whenever a sweep ran
        /// anything before it.
        fn returnNewIterator(info: *const v8.FunctionCallbackInfo, kind: IteratorKind) void {
            const isolate = info.getIsolate();
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse {
                conv.throwError(isolate, "No V8 context");
                return;
            };
            // Owned: v8_Isolate_GetCurrentContext allocates a Global per call.
            defer v8.v8_Context_Dispose(v8_context);

            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            // Step 2.1.1.3 (and 2.2, 2.3): "If jsValue does not implement
            // definition, then throw a TypeError."
            if (pairIterationTarget(this_obj) == null) {
                conv.throwTypeErrorFromContext(isolate, v8_context, "Illegal invocation");
                return;
            }

            const iterator_obj = createValueIterator(isolate, v8_context, this_obj, kind) orelse {
                conv.throwError(isolate, "Failed to create iterator");
                return;
            };
            // Copied into the return value (SetReturnValueGlobal); ours goes.
            defer v8.v8_Object_Dispose(iterator_obj);
            info.setReturnValue(@ptrCast(iterator_obj));
        }

        /// The platform object a pair iterator's method was called on, when
        /// it implements this interface (WebIDL 3.7.9 step 2's "If jsValue
        /// does not implement definition, then throw a TypeError"); null
        /// otherwise. Instance.getState reads another interface's object as
        /// this one's state without asking, so nothing below may run first.
        fn pairIterationTarget(this_obj: *v8.Object) ?*runtime.Instance {
            if (!v8.v8_Value_IsObject(@ptrCast(this_obj))) return null;
            const instance = getInstance(runtime.Instance, this_obj) orelse return null;
            if (!conv.implements(instance, Interface)) return null;
            return instance;
        }

        /// forEach() callback for pair iterables - WebIDL 3.7.9 step 2.4:
        /// invokes callback(value, key, object) with thisArg for each value
        /// pair, re-reading the pairs after each call; what the callback
        /// throws propagates.
        fn forEachCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse {
                conv.throwError(isolate, "No V8 context");
                return;
            };
            // Owned: v8_Isolate_GetCurrentContext allocates a Global per call
            // (and pins its realm until released - see returnNewIterator).
            defer v8.v8_Context_Dispose(v8_context);

            // Get 'this' object (the Headers/URLSearchParams/etc instance)
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            // Step 2.4.1.3: a receiver that does not implement this
            // interface is a TypeError.
            const target = pairIterationTarget(this_obj) orelse {
                conv.throwTypeErrorFromContext(isolate, v8_context, "Illegal invocation");
                return;
            };

            // Get callback argument (required)
            if (info.length() < 1) {
                conv.throwTypeError(isolate, "forEach requires a callback argument");
                return;
            }

            // Owned: each argument is a Global the wrapper made for this call.
            const callback_arg = info.get(0);
            defer v8.v8_Value_Dispose(callback_arg);
            if (!v8.v8_Value_IsFunction(callback_arg)) {
                conv.throwTypeError(isolate, "forEach callback must be a function");
                return;
            }
            const callback_fn: *v8.Function = @ptrCast(callback_arg);

            // Get optional thisArg (second argument)
            const this_arg: *v8.Value = if (info.length() >= 2)
                info.get(1)
            else
                v8.v8_Undefined(isolate) orelse return;
            defer v8.v8_Value_Dispose(this_arg);

            // Get entries using getEntriesForIterable with live iteration
            // Per WebIDL spec, forEach must iterate live - modifications during iteration
            // should be visible (deletions skip items, additions are visited)
            if (comptime @hasDecl(Interface, "getEntriesForIterable")) {
                // Steps 6-8: for each value pair, re-reading the list after
                // each call ("It might have changed").
                var index: usize = 0;
                while (true) : (index += 1) {
                    const entries = Interface.getEntriesForIterable(target) orelse break;
                    if (index >= entries.len) break;
                    const entry = entries[index];

                    // Released at the end of each round: the call copies them
                    // into its arguments.
                    const key_str = pairStringToV8(true, isolate, entry.name) orelse continue;
                    defer v8.v8_Value_Dispose(key_str);
                    const val_v8 = entryValue(isolate, entry) orelse continue;
                    defer v8.v8_Value_Dispose(val_v8);

                    // Step 8.2: invoke idlCallback with « value, key,
                    // idlObject » and thisArg. "Invoke a callback function"
                    // rethrows what the callback throws, which ends forEach.
                    const args = [_]*v8.Value{ val_v8, @ptrCast(key_str), @ptrCast(this_obj) };
                    var threw = false;
                    const result = v8.v8_Function_CallCatching(v8_context, @ptrCast(callback_fn), this_arg, args.len, &args, &threw);
                    if (threw) {
                        if (result) |exception| {
                            // ThrowException takes the value, not our handle.
                            defer v8.v8_Value_Dispose(exception);
                            v8.v8_Isolate_ThrowException(isolate, exception);
                        }
                        return;
                    }
                    if (result) |r| v8.v8_Value_Dispose(r);
                }
            }
        }

        /// A pair iterable entry's value converted to an ECMAScript value
        /// (WebIDL 3.7.10.2 "get the next iteration result"), OWNED, or null
        /// when it cannot be. FormDataEntryValue's File arm is the File the
        /// entry keeps - the object get() and getAll() return - as its
        /// wrapper: a Global of our own (`v8_Global_Clone`), since the wrapper
        /// cache keeps the wrapper's. It was null, so a File entry iterated
        /// as `undefined` and forEach skipped it
        /// (xhr/formdata/set-blob.any.js, foreach.any.js; Codex row 44 D7).
        fn entryValue(isolate: *v8.Isolate, entry: anytype) ?*v8.Value {
            const ValueType = @TypeOf(entry.value);
            if (@typeInfo(ValueType) == .@"union") {
                return switch (entry.value) {
                    .usvstring => |s| conv.newStringFromWtf8(isolate, s) orelse return null,
                    inline else => |payload| if (comptime @TypeOf(payload) == *runtime.Instance)
                        v8.v8_Global_Clone(conv.instanceToV8(isolate, payload))
                    else
                        null,
                };
            }
            return pairStringToV8(false, isolate, entry.value);
        }

        fn pairStringToV8(comptime key: bool, isolate: *v8.Isolate, bytes: []const u8) ?*v8.Value {
            if (comptime @hasDecl(Meta, "iterable")) {
                const type_name = if (key) Meta.iterable.key_type else Meta.iterable.value_type;
                if (comptime @TypeOf(type_name) != @TypeOf(null) and std.mem.eql(u8, type_name, "runtime.ByteString")) {
                    return conv.byteStringToV8([]const u8, isolate, bytes) catch null;
                }
            }
            return conv.newStringFromWtf8(isolate, bytes);
        }

        const IteratorKind = enum { entries, keys, values };

        /// Get %IteratorPrototype% from the JavaScript realm. OWNED.
        /// Per WebIDL §3.7.7, iterator prototypes must have %IteratorPrototype% in their chain.
        /// We obtain %IteratorPrototype% via: Object.getPrototypeOf(Object.getPrototypeOf([].values()))
        fn getIteratorPrototype(isolate: *v8.Isolate, context: *v8.Context) ?*v8.Value {
            // Create an empty array
            const arr = v8.v8_Array_New(isolate, 0);
            defer v8.v8_Array_Dispose(arr);

            // Get the values() iterator from the array
            const values_key = v8.v8_String_NewFromUtf8(isolate, "values", 6) orelse return null;
            defer v8.v8_String_Dispose(values_key);
            const values_fn_val = v8.v8_Object_Get(@ptrCast(arr), context, @ptrCast(values_key)) orelse return null;
            defer v8.v8_Value_Dispose(values_fn_val);
            if (!v8.v8_Value_IsFunction(values_fn_val)) return null;

            // Call values() to get an array iterator
            const values_fn: *v8.Function = @ptrCast(@alignCast(values_fn_val));
            // For zero-argument calls, we still need a valid pointer (even though argc=0)
            var dummy_args: [1]*v8.Value = undefined;
            const array_iterator_val = v8.v8_Function_Call(values_fn, context, @ptrCast(arr), 0, &dummy_args) orelse return null;
            defer v8.v8_Value_Dispose(array_iterator_val);

            // Get Array Iterator's prototype (this is the Array Iterator prototype object)
            const array_iterator_obj: *v8.Object = @ptrCast(@alignCast(array_iterator_val));
            const array_iterator_proto = v8.v8_Object_GetPrototype(array_iterator_obj) orelse return null;
            defer v8.v8_Value_Dispose(array_iterator_proto);

            // Get %IteratorPrototype% (the prototype of Array Iterator prototype)
            const array_iterator_proto_obj: *v8.Object = @ptrCast(@alignCast(array_iterator_proto));
            return v8.v8_Object_GetPrototype(array_iterator_proto_obj);
        }

        /// The isolate's template for this interface's iterator prototype
        /// (borrowed), kept in the isolate's template storage beside the
        /// interface templates - made for an isolate that has none yet, as the
        /// template registry's is - for the isolate's life. A template holds
        /// no context. It was kept in a per-interface static for an isolate
        /// without storage, and the storage itself was thrown away whenever
        /// ANY agent ended (template_registry's process-wide generation): the
        /// realm's next iterator then had a new prototype.
        fn iteratorPrototypeTemplate(isolate: *v8.Isolate) ?*v8.FunctionTemplate {
            const isolate_templates = @import("isolate_templates.zig");
            // Not an interface name (it has a space), so it cannot collide with one.
            const key = interface_name ++ " Iterator";
            const storage = isolate_templates.storageFor(isolate) orelse return null;
            if (storage.get(key)) |template| return template;
            const template = v8.v8_FunctionTemplate_New(isolate, null, null) orelse return null;
            storage.put(key, template) catch {
                v8.v8_FunctionTemplate_Dispose(template);
                return null;
            };
            return template;
        }

        /// This realm's iterator prototype object for this interface - WebIDL
        /// §3.7.10 "%<Interface> Iterator Prototype%" (§3.7.8 for the iterator
        /// objects): one object per interface per realm, whose [[Prototype]] is
        /// the realm's %IteratorPrototype%, with next(), @@iterator and
        /// @@toStringTag. OWNED by the caller.
        ///
        /// Made from `iteratorPrototypeTemplate`: V8 caches a template's
        /// instantiation per native context, so GetFunction(context).prototype
        /// is the same object for every iterator of the realm and lives exactly
        /// as long as the realm - nothing of ours holds it. Blink makes its
        /// iterator prototypes from per-isolate templates the same way. The
        /// cache this replaces was one static per interface, compared by the
        /// address of a Global<Context> made fresh on every call: it never hit,
        /// so every iteration built a new prototype and overwrote the last one
        /// without releasing it - each a Global that pinned its realm.
        fn getOrCreateIteratorPrototype(isolate: *v8.Isolate, context: *v8.Context) ?*v8.Object {
            const template = iteratorPrototypeTemplate(isolate) orelse return null;
            const func = v8.v8_FunctionTemplate_GetFunction(template, context) orelse return null;
            defer v8.v8_Function_Dispose(func);

            const prototype_key = v8.v8_String_NewFromUtf8(isolate, "prototype", 9) orelse return null;
            defer v8.v8_String_Dispose(prototype_key);
            const prototype_val = v8.v8_Object_Get(@ptrCast(func), context, @ptrCast(prototype_key)) orelse return null;
            if (!v8.v8_Value_IsObject(prototype_val)) {
                v8.v8_Value_Dispose(prototype_val);
                return null;
            }
            const prototype: *v8.Object = @ptrCast(prototype_val);

            // First use in this realm: the object still has the "constructor"
            // V8 gives every template's prototype, which an iterator prototype
            // does not have. Set it up once, and drop that marker.
            const constructor_key = v8.v8_String_NewFromUtf8(isolate, "constructor", 11) orelse {
                v8.v8_Object_Dispose(prototype);
                return null;
            };
            defer v8.v8_String_Dispose(constructor_key);
            if (v8.v8_Object_HasOwnProperty(prototype, context, @ptrCast(constructor_key))) {
                _ = v8.v8_Object_Delete(prototype, context, @ptrCast(constructor_key));
                setUpIteratorPrototype(isolate, context, prototype);
            }
            return prototype;
        }

        /// Give this realm's iterator prototype its [[Prototype]] and members.
        fn setUpIteratorPrototype(isolate: *v8.Isolate, context: *v8.Context, prototype: *v8.Object) void {
            // Set [[Prototype]] to %IteratorPrototype%
            if (getIteratorPrototype(isolate, context)) |builtin_iter_proto| {
                defer v8.v8_Value_Dispose(builtin_iter_proto);
                _ = v8.v8_Object_SetPrototype(prototype, context, builtin_iter_proto);
            }

            // Set Symbol.toStringTag to "<Interface> Iterator" per WebIDL spec §3.7.7
            // The descriptor should be { writable: false, enumerable: false, configurable: true }
            if (v8.v8_Symbol_GetToStringTag(isolate)) |symbol| {
                defer v8.v8_Symbol_Dispose(symbol);
                const iterator_tag = interface_name ++ " Iterator";
                if (v8.v8_String_NewFromUtf8(isolate, iterator_tag.ptr, @intCast(iterator_tag.len))) |tag| {
                    defer v8.v8_String_Dispose(tag);
                    _ = v8.v8_Object_DefineProperty(
                        prototype,
                        context,
                        @ptrCast(symbol),
                        @ptrCast(tag),
                        false, // writable
                        false, // enumerable
                        true, // configurable
                    );
                }
            }

            // Create unified next() method on the prototype
            // The callback will check _entries vs _target to determine behavior
            // (a setlike interface's iterators are its set iterators).
            if (v8.v8_FunctionTemplate_New(isolate, if (has_setlike) setlikeIteratorNextCallback else unifiedIteratorNextCallback, null)) |next_tmpl| {
                defer v8.v8_FunctionTemplate_Dispose(next_tmpl);
                if (v8.v8_FunctionTemplate_GetFunction(next_tmpl, context)) |next_func| {
                    defer v8.v8_Function_Dispose(next_func);
                    if (v8.v8_String_NewFromUtf8(isolate, "next", 4)) |next_key| {
                        defer v8.v8_String_Dispose(next_key);
                        _ = v8.v8_Object_Set(prototype, context, @ptrCast(next_key), @ptrCast(next_func));
                    }
                }
            }

            // Set Symbol.iterator on the prototype (returns this)
            // This makes iterators iterable (required for for...of and spread)
            if (v8.v8_Symbol_GetIterator(isolate)) |symbol| {
                defer v8.v8_Symbol_Dispose(symbol);
                if (v8.v8_FunctionTemplate_New(isolate, iteratorSelfCallback, null)) |self_iterator_tmpl| {
                    defer v8.v8_FunctionTemplate_Dispose(self_iterator_tmpl);
                    if (v8.v8_FunctionTemplate_GetFunction(self_iterator_tmpl, context)) |func| {
                        defer v8.v8_Function_Dispose(func);
                        _ = v8.v8_Object_Set(prototype, context, @ptrCast(symbol), @ptrCast(func));
                    }
                }
            }
        }

        /// Unified next() callback that handles both pair and indexed iterators
        /// Checks for _entries (pair) vs _target (indexed) to determine behavior
        fn unifiedIteratorNextCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const context = v8.v8_Isolate_GetCurrentContext(isolate) orelse return;
            // Owned: v8_Isolate_GetCurrentContext allocates a Global per call.
            defer v8.v8_Context_Dispose(context);
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);

            // Check if this is null/undefined (happens with .call(null) or .call(undefined))
            // Per WebIDL, calling iterator.next() with invalid this throws TypeError
            if (v8.v8_Value_IsNullOrUndefined(@ptrCast(this_obj))) {
                conv.throwTypeErrorFromContext(isolate, context, "Illegal invocation");
                return;
            }

            // Check if this is a pair iterator (has _isPairIterator flag) or indexed iterator
            if (iteratorSlot(isolate, context, this_obj, "_isPairIterator")) |flag| {
                defer v8.v8_Value_Dispose(flag);
                if (v8.v8_Value_IsBoolean(@ptrCast(flag)) and v8.v8_Value_BooleanValue(@ptrCast(flag), isolate)) {
                    // This is a pair iterator - use live iteration
                    pairIteratorNextCallback(info);
                    return;
                }
            }

            // This is an indexed iterator
            iteratorNextCallback(info);
        }

        /// A new default iterator object for `target` (WebIDL §3.7.8), OWNED
        /// by the caller. Its slots (_index, _kind, _iterType, _target and, for
        /// a pair iterator, _isPairIterator) are copied in; every handle made
        /// for them is released here.
        fn createValueIterator(
            isolate: *v8.Isolate,
            context: *v8.Context,
            target: *v8.Object,
            kind: IteratorKind,
        ) ?*v8.Object {
            // Determine if this is a pair iterable (has forEach but no length)
            const has_length = if (iteratorSlot(isolate, context, target, "length")) |length_val| blk: {
                defer v8.v8_Value_Dispose(length_val);
                break :blk !v8.v8_Value_IsUndefined(@ptrCast(length_val));
            } else false;
            const is_pair_iterator = !has_length;

            // This realm's shared iterator prototype for this interface
            const iter_proto = getOrCreateIteratorPrototype(isolate, context) orelse return null;
            defer v8.v8_Object_Dispose(iter_proto);

            // Create iterator instance object
            const iterator_obj = v8.v8_Object_New(isolate) orelse return null;

            // Set the iterator's prototype to our interface-specific iterator prototype
            _ = v8.v8_Object_SetPrototype(iterator_obj, context, @ptrCast(iter_proto));

            // Store current index
            const zero = v8.v8_Number_New(isolate, 0);
            defer v8.v8_Value_Dispose(@ptrCast(zero));
            setIteratorSlot(isolate, context, iterator_obj, "_index", @ptrCast(zero));

            // Store iterator kind
            const kind_val = v8.v8_Number_New(isolate, @floatFromInt(@intFromEnum(kind)));
            defer v8.v8_Value_Dispose(@ptrCast(kind_val));
            setIteratorSlot(isolate, context, iterator_obj, "_kind", @ptrCast(kind_val));

            // Store interface type marker for brand checking in next()
            // This ensures next() can only be called with iterators of the same interface type
            if (v8.v8_String_NewFromUtf8(isolate, interface_name.ptr, @intCast(interface_name.len))) |type_val| {
                defer v8.v8_String_Dispose(type_val);
                setIteratorSlot(isolate, context, iterator_obj, "_iterType", @ptrCast(type_val));
            }

            // Store reference to target for LIVE iteration (not snapshot): per
            // WebIDL, iteration reflects concurrent modifications. A pair
            // iterable (Headers, URLSearchParams, FormData) is marked as such.
            setIteratorSlot(isolate, context, iterator_obj, "_target", @ptrCast(target));
            if (is_pair_iterator) {
                if (v8.v8_Boolean_New(isolate, true)) |flag| {
                    defer v8.v8_Value_Dispose(flag);
                    setIteratorSlot(isolate, context, iterator_obj, "_isPairIterator", flag);
                }
            }

            return iterator_obj;
        }

        /// `iterator[slot_name]`, OWNED, or null.
        fn iteratorSlot(isolate: *v8.Isolate, context: *v8.Context, iterator: *v8.Object, comptime slot_name: []const u8) ?*v8.Value {
            const key = v8.v8_String_NewFromUtf8(isolate, slot_name.ptr, @intCast(slot_name.len)) orelse return null;
            defer v8.v8_String_Dispose(key);
            return v8.v8_Object_Get(iterator, context, @ptrCast(key));
        }

        /// `iterator[slot_name] = value`; `value` is borrowed (Set copies it).
        fn setIteratorSlot(isolate: *v8.Isolate, context: *v8.Context, iterator: *v8.Object, comptime slot_name: []const u8, value: *v8.Value) void {
            const key = v8.v8_String_NewFromUtf8(isolate, slot_name.ptr, @intCast(slot_name.len)) orelse return;
            defer v8.v8_String_Dispose(key);
            _ = v8.v8_Object_Set(iterator, context, @ptrCast(key), value);
        }

        /// Callback for [Symbol.iterator] on iterator objects - returns this
        fn iteratorSelfCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            info.setReturnValue(@ptrCast(this_obj));
        }

        /// Collect entries from a pair iterable
        /// Tries to use getEntriesForIterable if available on the Interface,
        /// otherwise falls back to forEach-based collection (which may not work for all impls)
        fn collectPairIterableEntries(
            isolate: *v8.Isolate,
            context: *v8.Context,
            target: *v8.Object,
        ) ?*v8.Array {
            // Create an array to store entries
            const entries_array = v8.v8_Array_New(isolate, 0);

            // Try to get entries directly from the Interface if it has getEntriesForIterable
            if (comptime @hasDecl(Interface, "getEntriesForIterable")) {
                // Get the instance from the V8 object's internal field
                const instance_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(target, 0);
                if (instance_ptr) |ptr| {
                    // Safety check: detect use-after-free by checking for poison patterns
                    const ptr_as_int = @intFromPtr(ptr);
                    const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
                    const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
                    if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
                        (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
                    {
                        return entries_array;
                    }
                    const instance: *runtime.Instance = @ptrCast(@alignCast(ptr));

                    // Call getEntriesForIterable to get the Zig entries
                    if (Interface.getEntriesForIterable(instance)) |entries| {
                        // Convert entries to V8 array
                        var idx: u32 = 0;
                        for (entries) |entry| {
                            // Create [key, value] pair as V8 array
                            const pair = v8.v8_Array_New(isolate, 2);

                            // entry.name is the key
                            const key_str = pairStringToV8(true, isolate, entry.name);

                            // Handle the value - check if it's a union type or simple string
                            const ValueType = @TypeOf(entry.value);
                            const val_v8: ?*v8.Value = val_blk: {
                                if (@typeInfo(ValueType) == .@"union") {
                                    // It's a union - try to get the usvstring variant
                                    switch (entry.value) {
                                        .usvstring => |s| {
                                            break :val_blk @ptrCast(v8.v8_String_NewFromUtf8(isolate, s.ptr, @intCast(s.len)));
                                        },
                                        else => break :val_blk null, // Skip non-string variants for now
                                    }
                                } else {
                                    // Simple string type - use directly
                                    break :val_blk pairStringToV8(false, isolate, entry.value);
                                }
                            };

                            if (key_str) |k| {
                                _ = v8.v8_Array_Set(pair, context, 0, @ptrCast(k));
                            }
                            if (val_v8) |val| {
                                _ = v8.v8_Array_Set(pair, context, 1, val);
                            }

                            // Add pair to entries array
                            _ = v8.v8_Array_Set(entries_array, context, idx, @ptrCast(pair));
                            idx += 1;
                        }
                        return entries_array;
                    }
                }
            }

            // Fallback: try forEach-based collection (may not work if forEach impl is incomplete)
            const forEach_key = v8.v8_String_NewFromUtf8(isolate, "forEach", 7) orelse return entries_array;
            const forEach_val = v8.v8_Object_Get(target, context, @ptrCast(forEach_key)) orelse return entries_array;

            if (!v8.v8_Value_IsFunction(forEach_val)) {
                return entries_array;
            }

            // Create a callback function that collects entries via JavaScript
            const script_str =
                \\(function(target, entries) {
                \\  target.forEach(function(value, key) {
                \\    entries.push([key, value]);
                \\  });
                \\  return entries;
                \\})
            ;
            const script_v8_str = v8.v8_String_NewFromUtf8(isolate, script_str.ptr, @intCast(script_str.len)) orelse return entries_array;
            const script = v8.v8_Script_Compile(context, script_v8_str) orelse return entries_array;
            const func_val = v8.v8_Script_Run(context, script) orelse return entries_array;

            if (!v8.v8_Value_IsFunction(func_val)) {
                return entries_array;
            }

            // Call the function with target and entries array
            var args = [_]*v8.Value{ @ptrCast(target), @ptrCast(entries_array) };
            const global = v8.v8_Context_Global(context) orelse return entries_array;
            _ = v8.v8_Function_Call(@ptrCast(func_val), context, @ptrCast(global), 2, @ptrCast(&args));

            return entries_array;
        }

        /// next() callback for pair iterator objects (uses LIVE entries from target)
        /// Per WebIDL spec, iteration should reflect concurrent modifications
        fn pairIteratorNextCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse {
                conv.throwError(isolate, "No V8 context");
                return;
            };
            // Owned: v8_Isolate_GetCurrentContext allocates a Global per call.
            defer v8.v8_Context_Dispose(v8_context);

            // Get the iterator object (this)
            const iterator_obj = info.getThis();
            defer v8.v8_Object_Dispose(iterator_obj);

            // Check if this is null/undefined (happens with .call(null) or .call(undefined))
            // Per WebIDL, calling iterator.next() with invalid this throws TypeError
            if (v8.v8_Value_IsNullOrUndefined(@ptrCast(iterator_obj))) {
                conv.throwTypeErrorFromContext(isolate, v8_context, "Illegal invocation");
                return;
            }

            // Check that the iterator's type matches this interface (brand check)
            // This prevents calling URLSearchParams iterator's next() with a Headers iterator
            if (!hasIteratorBrand(isolate, v8_context, iterator_obj)) {
                throwIllegalIteratorInvocation(isolate, iterator_obj);
                return;
            }

            // Get stored state (index, kind, and target)
            const index_val = iteratorSlot(isolate, v8_context, iterator_obj, "_index") orelse return;
            defer v8.v8_Value_Dispose(index_val);
            const kind_val = iteratorSlot(isolate, v8_context, iterator_obj, "_kind") orelse return;
            defer v8.v8_Value_Dispose(kind_val);
            const target_val = iteratorSlot(isolate, v8_context, iterator_obj, "_target") orelse return;
            defer v8.v8_Value_Dispose(target_val);

            const index: u32 = @intFromFloat(v8.v8_Value_NumberValue(@ptrCast(index_val), v8_context));
            const kind: IteratorKind = @enumFromInt(@as(u2, @intFromFloat(v8.v8_Value_NumberValue(@ptrCast(kind_val), v8_context))));

            // Get live entries from the target object
            // This ensures concurrent modifications (like delete during iteration) are reflected
            const target_obj: *v8.Object = @ptrCast(target_val);

            // Get live entries from the Zig instance. The entry type is what
            // getEntriesForIterable returns: the generated interfaces declare
            // no IterableEntry of their own (it is their impl's), and requiring
            // one made every pair iterator report done at once - `for (const
            // [k, v] of new URLSearchParams("a=1"))` ran zero times.
            if (comptime @hasDecl(Interface, "getEntriesForIterable")) {
                const Entries = @typeInfo(@typeInfo(@TypeOf(Interface.getEntriesForIterable)).@"fn".return_type.?).optional.child;
                const entries: ?Entries = entry_blk: {
                    const instance_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(target_obj, 0);
                    if (instance_ptr) |ptr| {
                        // Safety check: detect use-after-free
                        const ptr_as_int = @intFromPtr(ptr);
                        const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
                        const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
                        if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
                            (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
                        {
                            break :entry_blk null;
                        }
                        const instance: *runtime.Instance = @ptrCast(@alignCast(ptr));
                        break :entry_blk Interface.getEntriesForIterable(instance);
                    }
                    break :entry_blk null;
                };

                const live = entries orelse {
                    // No entries available - done
                    returnIterDone(info, isolate, v8_context);
                    return;
                };
                if (index >= live.len) {
                    // Iterator exhausted
                    returnIterDone(info, isolate, v8_context);
                    return;
                }

                // Get entry at current index from live entries
                const entry = live[index];

                // Convert Zig strings to V8 strings
                const undef = v8.v8_Undefined(isolate) orelse return;
                defer v8.v8_Value_Dispose(undef);
                const key_v8 = pairStringToV8(true, isolate, entry.name);
                defer if (key_v8) |k| v8.v8_Value_Dispose(k);
                const val_v8 = entryValue(isolate, entry);
                defer if (val_v8) |v| v8.v8_Value_Dispose(v);

                // Return value based on kind
                switch (kind) {
                    .keys => returnIterResult(info, isolate, v8_context, key_v8 orelse undef, false),
                    .values => returnIterResult(info, isolate, v8_context, val_v8 orelse undef, false),
                    .entries => {
                        // Create [key, value] pair array
                        const pair = v8.v8_Array_New(isolate, 2);
                        defer v8.v8_Array_Dispose(pair);
                        _ = v8.v8_Array_Set(pair, v8_context, 0, key_v8 orelse undef);
                        _ = v8.v8_Array_Set(pair, v8_context, 1, val_v8 orelse undef);
                        returnIterResult(info, isolate, v8_context, @ptrCast(pair), false);
                    },
                }

                // Increment index
                const new_index = v8.v8_Number_New(isolate, @floatFromInt(index + 1));
                defer v8.v8_Value_Dispose(@ptrCast(new_index));
                setIteratorSlot(isolate, v8_context, iterator_obj, "_index", @ptrCast(new_index));
                return;
            }

            // Fallback: interface doesn't have getEntriesForIterable - return done immediately
            // This shouldn't happen for properly implemented pair iterables
            returnIterDone(info, isolate, v8_context);
        }

        /// next() callback for iterator objects
        fn iteratorNextCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse {
                conv.throwError(isolate, "No V8 context");
                return;
            };
            // Owned: v8_Isolate_GetCurrentContext allocates a Global per call.
            defer v8.v8_Context_Dispose(v8_context);

            // Get the iterator object (this)
            const iterator_obj = info.getThis();
            defer v8.v8_Object_Dispose(iterator_obj);

            // Validate that this is an actual iterator object, not the prototype
            // Per WebIDL spec: next() must throw TypeError when called on ineligible receiver
            const target = iteratorSlot(isolate, v8_context, iterator_obj, "_target");
            defer if (target) |t| v8.v8_Value_Dispose(t);
            const index_val = iteratorSlot(isolate, v8_context, iterator_obj, "_index");
            defer if (index_val) |i| v8.v8_Value_Dispose(i);
            const kind_val = iteratorSlot(isolate, v8_context, iterator_obj, "_kind");
            defer if (kind_val) |k| v8.v8_Value_Dispose(k);

            // Check if any of the iterator state properties are missing or undefined
            // This indicates the receiver is not a valid iterator (e.g., it's the prototype)
            const has_valid_target = if (target) |t| !v8.v8_Value_IsUndefined(@ptrCast(t)) else false;
            const has_valid_index = if (index_val) |i| !v8.v8_Value_IsUndefined(@ptrCast(i)) else false;
            const has_valid_kind = if (kind_val) |k| !v8.v8_Value_IsUndefined(@ptrCast(k)) else false;

            if (!has_valid_target or !has_valid_index or !has_valid_kind) {
                // Throw TypeError: next() called on ineligible receiver
                throwIllegalIteratorInvocation(isolate, iterator_obj);
                return;
            }

            // Check that the iterator's type matches this interface (brand check)
            // This prevents calling URLSearchParams iterator's next() with a Headers iterator
            if (!hasIteratorBrand(isolate, v8_context, iterator_obj)) {
                throwIllegalIteratorInvocation(isolate, iterator_obj);
                return;
            }

            const target_obj: *v8.Object = @ptrCast(target.?);
            const index: u32 = @intFromFloat(v8.v8_Value_NumberValue(@ptrCast(index_val.?), v8_context));
            const kind: IteratorKind = @enumFromInt(@as(u2, @intFromFloat(v8.v8_Value_NumberValue(@ptrCast(kind_val.?), v8_context))));

            // Get length from target
            const length: u32 = if (iteratorSlot(isolate, v8_context, target_obj, "length")) |length_val| blk: {
                defer v8.v8_Value_Dispose(length_val);
                break :blk @intFromFloat(v8.v8_Value_NumberValue(@ptrCast(length_val), v8_context));
            } else 0;

            if (index >= length) {
                // Iterator exhausted
                returnIterDone(info, isolate, v8_context);
                return;
            }

            const undef = v8.v8_Undefined(isolate) orelse return;
            defer v8.v8_Value_Dispose(undef);

            // Get value at index using indexed access
            const index_num = v8.v8_Number_New(isolate, @floatFromInt(index));
            defer v8.v8_Value_Dispose(@ptrCast(index_num));
            const item_val = v8.v8_Object_Get(target_obj, v8_context, @ptrCast(index_num));
            defer if (item_val) |item| v8.v8_Value_Dispose(item);

            switch (kind) {
                .keys => returnIterResult(info, isolate, v8_context, @ptrCast(index_num), false),
                .values => returnIterResult(info, isolate, v8_context, item_val orelse undef, false),
                .entries => {
                    // Create [index, value] array
                    const arr = v8.v8_Array_New(isolate, 2);
                    defer v8.v8_Array_Dispose(arr);
                    _ = v8.v8_Array_Set(arr, v8_context, 0, @ptrCast(index_num));
                    _ = v8.v8_Array_Set(arr, v8_context, 1, item_val orelse undef);
                    returnIterResult(info, isolate, v8_context, @ptrCast(arr), false);
                },
            }

            // Increment index
            const new_index = v8.v8_Number_New(isolate, @floatFromInt(index + 1));
            defer v8.v8_Value_Dispose(@ptrCast(new_index));
            setIteratorSlot(isolate, v8_context, iterator_obj, "_index", @ptrCast(new_index));
        }

        /// Whether `iterator` is one of this interface's iterators: its
        /// `_iterType` slot names this interface.
        fn hasIteratorBrand(isolate: *v8.Isolate, context: *v8.Context, iterator: *v8.Object) bool {
            const type_val = iteratorSlot(isolate, context, iterator, "_iterType") orelse return false;
            defer v8.v8_Value_Dispose(type_val);
            if (v8.v8_Value_IsUndefined(@ptrCast(type_val))) return false;
            // Get the stored type string and compare with interface_name
            const type_str = v8.v8_Value_ToString(@ptrCast(type_val), context) orelse return false;
            defer v8.v8_String_Dispose(type_str);
            var buf: [256]u8 = undefined;
            const len = v8.v8_String_WriteUtf8(type_str, &buf, @intCast(buf.len));
            if (len <= 1) return false; // len includes null terminator
            // Subtract 1 to exclude the null terminator from the slice
            const stored_type = buf[0..@intCast(len - 1)];
            return std.mem.eql(u8, stored_type, interface_name);
        }

        /// TypeError "Illegal invocation" for a next() on something that is not
        /// one of this interface's iterators - in the realm of the receiver's
        /// prototype when it has one (a cross-realm call).
        fn throwIllegalIteratorInvocation(isolate: *v8.Isolate, receiver: *v8.Object) void {
            if (v8.v8_Object_GetPrototypeCreationContext(receiver)) |creation_ctx| {
                defer v8.v8_Context_Dispose(creation_ctx);
                conv.throwTypeErrorFromContext(isolate, creation_ctx, "Illegal invocation");
            } else {
                conv.throwTypeError(isolate, "Illegal invocation");
            }
        }

        /// Return `{ value, done }` (ECMA-262 CreateIterResultObject) to
        /// script. `value` is borrowed; every handle made here is released.
        fn returnIterResult(info: *const v8.FunctionCallbackInfo, isolate: *v8.Isolate, context: *v8.Context, value: *v8.Value, done: bool) void {
            const result = v8.v8_Object_New(isolate) orelse return;
            defer v8.v8_Object_Dispose(result);
            const done_val = v8.v8_Boolean_New(isolate, done) orelse return;
            defer v8.v8_Value_Dispose(done_val);
            setIteratorSlot(isolate, context, result, "value", value);
            setIteratorSlot(isolate, context, result, "done", done_val);
            // Copied into the return value (SetReturnValueGlobal); ours goes.
            info.setReturnValue(@ptrCast(result));
        }

        /// Return `{ value: undefined, done: true }`.
        fn returnIterDone(info: *const v8.FunctionCallbackInfo, isolate: *v8.Isolate, context: *v8.Context) void {
            const undef = v8.v8_Undefined(isolate) orelse return;
            defer v8.v8_Value_Dispose(undef);
            returnIterResult(info, isolate, context, undef, true);
        }

        // ====================================================================
        // WebIDL 3.7.12 setlike declarations
        // ====================================================================
        //
        // The interface prototype object of a setlike interface has size,
        // has, forEach, entries, keys, values and %Symbol.iterator% - and,
        // read-write and not declared by the interface, add, delete and clear
        // - each a built-in function over the object's set entries, which the
        // impl keeps in a webidl.setlike.SetEntries (the generated
        // `setlikeEntries` hands them over). None is an operation an impl
        // implements (codegen's setlike.zig). An iterator is an object of
        // this realm's "<Interface> Iterator" prototype holding, in private
        // properties, the set's wrapper, its kind and the sequence of the
        // entry it yielded last (SetEntries.after): live, as a JavaScript
        // Set iterator is, with nothing in the set pointing back at it.
        // WebIDL makes it with CreateIteratorFromClosure and
        // %SetIteratorPrototype%, whose next() V8 runs only for its own Set
        // iterators; Blink's iterator objects have an interface iterator
        // prototype of their own, as these do.

        const SetlikeEntries = if (has_setlike)
            @typeInfo(@typeInfo(@typeInfo(@TypeOf(Interface.setlikeEntries)).@"fn".return_type.?).optional.child).pointer.child
        else
            void;

        const setlike_key_prefix = "crane:setlike:" ++ interface_name ++ ":";
        const setlike_target_key = setlike_key_prefix ++ "target";
        const setlike_kind_key = setlike_key_prefix ++ "kind";
        const setlike_cursor_key = setlike_key_prefix ++ "cursor";

        const SetIteratorKind = enum(u8) { value = 0, key_value = 1 };

        /// Whether the interface declares member `name` itself (an add,
        /// delete or clear operation overriding the binding's, 3.7.12.8-10).
        fn declaresOperation(comptime member_name: []const u8) bool {
            inline for (methods) |method| {
                if (comptime std.mem.eql(u8, method[0], member_name)) return true;
            }
            return false;
        }

        /// "Let O be the this value, implementation-checked against A", and
        /// O's set entries; null with a TypeError thrown for any other `this`.
        fn setlikeEntriesOf(isolate: *v8.Isolate, context: *v8.Context, this_obj: *v8.Object) ?*SetlikeEntries {
            if (v8.v8_Value_IsObject(@ptrCast(this_obj))) {
                if (getInstance(runtime.Instance, this_obj)) |instance| {
                    if (conv.implements(instance, Interface)) {
                        if (Interface.setlikeEntries(instance)) |entries| return entries;
                    }
                }
            }
            conv.throwTypeErrorFromContext(isolate, context, "Illegal invocation");
            return null;
        }

        /// The allocator of `this_obj`'s instance (it passed setlikeEntriesOf).
        fn setlikeAllocator(this_obj: *v8.Object) std.mem.Allocator {
            return getInstance(runtime.Instance, this_obj).?.ctx.allocator;
        }

        /// `valueArg` converted to an IDL value of the declaration's value
        /// type (3.7.12.7-9 step 4), OWNED by `allocator`; null with the
        /// exception thrown (or pending) when the conversion threw. A missing
        /// argument is undefined: these are built-in functions taking one
        /// argument, not operations with a required one.
        fn setlikeValueArgument(isolate: *v8.Isolate, context: *v8.Context, info: *const v8.FunctionCallbackInfo, allocator: std.mem.Allocator) ?[]const u8 {
            // Owned: info.get makes a Global for the call, v8_Undefined one too.
            const arg = (if (info.length() >= 1) info.get(0) else v8.v8_Undefined(isolate)) orelse return null;
            defer v8.v8_Value_Dispose(arg);
            if (comptime std.mem.eql(u8, Meta.setlike.value_type, "USVString")) {
                return conv.fromV8Value(runtime.USVString, allocator, isolate, context, arg) catch |err| {
                    throwMemberError(isolate, context, err);
                    return null;
                };
            } else if (comptime std.mem.eql(u8, Meta.setlike.value_type, "DOMString") or std.mem.eql(u8, Meta.setlike.value_type, "CSSOMString")) {
                var string = conv.fromV8Value(runtime.DOMString, allocator, isolate, context, arg) catch |err| {
                    throwMemberError(isolate, context, err);
                    return null;
                };
                defer string.deinit(allocator);
                return allocator.dupe(u8, string.asSlice()) catch {
                    throwMemberError(isolate, context, error.OutOfMemory);
                    return null;
                };
            } else {
                @compileError(interface_name ++ ": setlike<" ++ Meta.setlike.value_type ++ "> values are not converted yet");
            }
        }

        /// A set entry's value converted to an ECMAScript value, OWNED.
        fn setlikeValueToV8(isolate: *v8.Isolate, value: []const u8) ?*v8.Value {
            return conv.newStringFromWtf8(isolate, value);
        }

        /// The current context, OWNED, or null with nothing to release.
        fn setlikeContext(isolate: *v8.Isolate) ?*v8.Context {
            return v8.v8_Isolate_GetCurrentContext(isolate);
        }

        /// 3.7.12.1 size: the set's size.
        fn setlikeSizeCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const context = setlikeContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(context);
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            const entries = setlikeEntriesOf(isolate, context, this_obj) orelse return;
            const size = v8.v8_Number_New(isolate, @floatFromInt(entries.size()));
            defer v8.v8_Value_Dispose(@ptrCast(size));
            info.setReturnValue(@ptrCast(size));
        }

        /// 3.7.12.7 has: whether the set contains the converted value.
        fn setlikeHasCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const context = setlikeContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(context);
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            const entries = setlikeEntriesOf(isolate, context, this_obj) orelse return;
            const allocator = setlikeAllocator(this_obj);
            const value = setlikeValueArgument(isolate, context, info, allocator) orelse return;
            defer allocator.free(value);
            setlikeReturnBoolean(info, isolate, entries.contains(value));
        }

        /// 3.7.12.8 add: append the converted value, then return O.
        fn setlikeAddCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const context = setlikeContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(context);
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            const entries = setlikeEntriesOf(isolate, context, this_obj) orelse return;
            const allocator = setlikeAllocator(this_obj);
            const value = setlikeValueArgument(isolate, context, info, allocator) orelse return;
            defer allocator.free(value);
            entries.append(value) catch |err| {
                throwMemberError(isolate, context, err);
                return;
            };
            // Copied into the return slot; ours is released above.
            info.setReturnValue(@ptrCast(this_obj));
        }

        /// 3.7.12.9 delete: whether the set contained the converted value,
        /// which it no longer does.
        fn setlikeDeleteCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const context = setlikeContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(context);
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            const entries = setlikeEntriesOf(isolate, context, this_obj) orelse return;
            const allocator = setlikeAllocator(this_obj);
            const value = setlikeValueArgument(isolate, context, info, allocator) orelse return;
            defer allocator.free(value);
            setlikeReturnBoolean(info, isolate, entries.remove(value));
        }

        /// 3.7.12.10 clear: empty the set - the same set, so a suspended
        /// iterator yields what is added afterwards.
        fn setlikeClearCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const context = setlikeContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(context);
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            const entries = setlikeEntriesOf(isolate, context, this_obj) orelse return;
            entries.empty();
            conv.setReturnUndefined(info);
        }

        fn setlikeReturnBoolean(info: *const v8.FunctionCallbackInfo, isolate: *v8.Isolate, value: bool) void {
            const result = v8.v8_Boolean_New(isolate, value) orelse return;
            defer v8.v8_Value_Dispose(result);
            info.setReturnValue(result);
        }

        /// 3.7.12.6 forEach: "If IsCallable(callbackFn) is false, throw a
        /// TypeError"; for each value of the set - live, as its iterators
        /// are - Call(callbackFn, thisArg, « value, value, O »); what the
        /// callback throws propagates.
        fn setlikeForEachCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const context = setlikeContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(context);
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            if (setlikeEntriesOf(isolate, context, this_obj) == null) return;
            // Owned: each argument is a Global made for this call.
            const callback = (if (info.length() >= 1) info.get(0) else v8.v8_Undefined(isolate)) orelse return;
            defer v8.v8_Value_Dispose(callback);
            if (!v8.v8_Value_IsFunction(callback)) {
                conv.throwTypeErrorFromContext(isolate, context, "forEach: the callback is not callable");
                return;
            }
            const this_arg = (if (info.length() >= 2) info.get(1) else v8.v8_Undefined(isolate)) orelse return;
            defer v8.v8_Value_Dispose(this_arg);
            var cursor: u64 = 0;
            while (true) {
                // Re-read after every call: the callback can change the set,
                // or end the object's state.
                const entries = setlikeEntriesOf(isolate, context, this_obj) orelse return;
                const entry = entries.after(cursor) orelse break;
                cursor = entry.sequence;
                const value = setlikeValueToV8(isolate, entry.value) orelse return;
                defer v8.v8_Value_Dispose(value);
                const args = [_]*v8.Value{ value, value, @ptrCast(this_obj) };
                var threw = false;
                const result = v8.v8_Function_CallCatching(context, @ptrCast(callback), this_arg, args.len, &args, &threw);
                if (threw) {
                    if (result) |exception| {
                        // ThrowException takes the value, not our handle.
                        defer v8.v8_Value_Dispose(exception);
                        v8.v8_Isolate_ThrowException(isolate, exception);
                    }
                    return;
                }
                if (result) |r| v8.v8_Value_Dispose(r);
            }
            conv.setReturnUndefined(info);
        }

        /// 3.7.12.5 values (also keys and %Symbol.iterator%): a set iterator
        /// of kind "value".
        fn setlikeValuesCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            setlikeNewIterator(info, .value);
        }

        /// 3.7.12.3 entries: a set iterator of kind "key+value".
        fn setlikeEntriesCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            setlikeNewIterator(info, .key_value);
        }

        /// "Create a set iterator" from O's set entries and `kind`.
        fn setlikeNewIterator(info: *const v8.FunctionCallbackInfo, kind: SetIteratorKind) void {
            const isolate = info.getIsolate();
            const context = setlikeContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(context);
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            if (setlikeEntriesOf(isolate, context, this_obj) == null) return;
            const prototype = getOrCreateIteratorPrototype(isolate, context) orelse return;
            defer v8.v8_Object_Dispose(prototype);
            const iterator = v8.v8_Object_New(isolate) orelse return;
            defer v8.v8_Object_Dispose(iterator);
            _ = v8.v8_Object_SetPrototype(iterator, context, @ptrCast(prototype));
            // The edges: the iterator keeps the set's wrapper alive (and so
            // its instance) until it is done.
            v8.v8_Object_SetPrivateRef(iterator, setlike_target_key.ptr, setlike_target_key.len, @ptrCast(this_obj));
            const kind_v8 = v8.v8_Number_New(isolate, @floatFromInt(@intFromEnum(kind)));
            defer v8.v8_Value_Dispose(@ptrCast(kind_v8));
            v8.v8_Object_SetPrivateRef(iterator, setlike_kind_key.ptr, setlike_kind_key.len, @ptrCast(kind_v8));
            setlikeSetCursor(isolate, iterator, 0);
            info.setReturnValue(@ptrCast(iterator));
        }

        fn setlikeSetCursor(isolate: *v8.Isolate, iterator: *v8.Object, sequence: u64) void {
            const cursor = v8.v8_Number_New(isolate, @floatFromInt(sequence));
            defer v8.v8_Value_Dispose(@ptrCast(cursor));
            v8.v8_Object_SetPrivateRef(iterator, setlike_cursor_key.ptr, setlike_cursor_key.len, @ptrCast(cursor));
        }

        /// The number in private property `key` of `iterator`, or null when
        /// it has none (not one of this interface's set iterators).
        fn setlikeNumberSlot(context: *v8.Context, iterator: *v8.Object, comptime key: []const u8) ?f64 {
            const value = v8.v8_Object_GetPrivateRef(iterator, key.ptr, key.len) orelse return null;
            defer v8.v8_Value_Dispose(value);
            if (!v8.v8_Value_IsNumber(value)) return null;
            return v8.v8_Value_NumberValue(value, context);
        }

        /// A set iterator's next(): the entry after the one it yielded last,
        /// as « value » or « value, value » (CreateArrayFromList), or done -
        /// for good: a finished iterator lets the set go.
        fn setlikeIteratorNextCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();
            const context = setlikeContext(isolate) orelse return;
            defer v8.v8_Context_Dispose(context);
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);
            const kind_number = if (v8.v8_Value_IsObject(@ptrCast(this_obj))) setlikeNumberSlot(context, this_obj, setlike_kind_key) else null;
            const kind: SetIteratorKind = if (kind_number) |n| @enumFromInt(@as(u8, @intFromFloat(n))) else {
                conv.throwTypeErrorFromContext(isolate, context, "Illegal invocation");
                return;
            };
            const target = v8.v8_Object_GetPrivateRef(this_obj, setlike_target_key.ptr, setlike_target_key.len) orelse
                return setlikeReturnIterResult(info, isolate, context, null, true);
            defer v8.v8_Value_Dispose(target);
            const target_obj: *v8.Object = @ptrCast(target);
            const entries = setlikeEntriesOf(isolate, context, target_obj) orelse return;
            const cursor: u64 = @intFromFloat(setlikeNumberSlot(context, this_obj, setlike_cursor_key) orelse 0);
            const entry = entries.after(cursor) orelse {
                v8.v8_Object_DeletePrivateRef(this_obj, setlike_target_key.ptr, setlike_target_key.len);
                return setlikeReturnIterResult(info, isolate, context, null, true);
            };
            setlikeSetCursor(isolate, this_obj, entry.sequence);
            const value = setlikeValueToV8(isolate, entry.value) orelse return;
            defer v8.v8_Value_Dispose(value);
            switch (kind) {
                .value => setlikeReturnIterResult(info, isolate, context, value, false),
                .key_value => {
                    const pair = v8.v8_Array_NewInContext(context, 2) orelse return;
                    defer v8.v8_Array_Dispose(pair);
                    // v8_Array_Set defines (CreateDataProperty).
                    _ = v8.v8_Array_Set(pair, context, 0, value);
                    _ = v8.v8_Array_Set(pair, context, 1, value);
                    setlikeReturnIterResult(info, isolate, context, @ptrCast(pair), false);
                },
            }
        }

        /// CreateIteratorResultObject(value, done) - its properties defined,
        /// never assigned - as the return value; `value` borrowed (undefined
        /// when null); every handle made here is released.
        fn setlikeReturnIterResult(info: *const v8.FunctionCallbackInfo, isolate: *v8.Isolate, context: *v8.Context, value: ?*v8.Value, done: bool) void {
            const result = v8.v8_Object_NewInContext(context) orelse return;
            defer v8.v8_Object_Dispose(result);
            const undefined_v8 = v8.v8_Undefined(isolate) orelse return;
            defer v8.v8_Value_Dispose(undefined_v8);
            const done_v8 = v8.v8_Boolean_New(isolate, done) orelse return;
            defer v8.v8_Value_Dispose(done_v8);
            inline for (.{ .{ "value", value orelse undefined_v8 }, .{ "done", done_v8 } }) |property| {
                const key = v8.v8_String_NewFromUtf8(isolate, property[0].ptr, property[0].len) orelse return;
                defer v8.v8_String_Dispose(key);
                _ = v8.v8_Object_CreateDataProperty(result, context, key, property[1]);
            }
            info.setReturnValue(@ptrCast(result));
        }

        /// 3.7.12: the members on this realm's interface prototype object.
        /// values is also %Symbol.iterator% - one function object (3.7.12.2).
        /// keys runs values' steps as a function of its own, named "keys":
        /// WebIDL 3.7.12.4 makes it values' function object (as
        /// Set.prototype.keys is), but WPT's idlharness requires keys.name
        /// to be "keys" (idlharness.js test_member_setlike, which every
        /// setlike interface's idlharness file runs against the browsers).
        fn defineSetlikeMembers(isolate: *v8.Isolate, context: *v8.Context, proto: *v8.Object) void {
            // 3.7.12.1: { [[Get]]: "get size", enumerable, configurable }.
            if (v8.v8_String_NewFromUtf8(isolate, "size", 4)) |size_key| {
                defer v8.v8_String_Dispose(size_key);
                _ = v8.v8_Object_SetAccessorProperty(proto, context, size_key, setlikeSizeCallback, null);
            }
            if (pairIterationMethod(isolate, context, "values", setlikeValuesCallback, 0)) |values| {
                defer v8.v8_Function_Dispose(values);
                definePairIterationMethod(isolate, context, proto, "values", values);
                if (v8.v8_Symbol_GetIterator(isolate)) |symbol| {
                    defer v8.v8_Symbol_Dispose(symbol);
                    _ = v8.v8_Object_DefineProperty(proto, context, @ptrCast(symbol), @ptrCast(values), true, false, true);
                }
            }
            const members = [_]struct { name: []const u8, cb: v8.FunctionCallback, length: c_int, mutation: bool }{
                .{ .name = "keys", .cb = setlikeValuesCallback, .length = 0, .mutation = false },
                .{ .name = "entries", .cb = setlikeEntriesCallback, .length = 0, .mutation = false },
                .{ .name = "forEach", .cb = setlikeForEachCallback, .length = 1, .mutation = false },
                .{ .name = "has", .cb = setlikeHasCallback, .length = 1, .mutation = false },
                .{ .name = "add", .cb = setlikeAddCallback, .length = 1, .mutation = true },
                .{ .name = "delete", .cb = setlikeDeleteCallback, .length = 1, .mutation = true },
                .{ .name = "clear", .cb = setlikeClearCallback, .length = 0, .mutation = true },
            };
            inline for (members) |member| {
                // A readonly setlike has no mutation members, and a member
                // the interface declares is its own operation.
                const skip = comptime member.mutation and (Meta.setlike.readonly or declaresOperation(member.name));
                if (!skip) {
                    if (pairIterationMethod(isolate, context, member.name, member.cb, member.length)) |function| {
                        defer v8.v8_Function_Dispose(function);
                        definePairIterationMethod(isolate, context, proto, member.name, function);
                    }
                }
            }
        }

        fn registerSetlikeExternalReferences() void {
            const ext_refs = @import("external_references.zig");
            inline for (.{
                setlikeSizeCallback,   setlikeHasCallback,     setlikeAddCallback,
                setlikeDeleteCallback, setlikeClearCallback,   setlikeForEachCallback,
                setlikeValuesCallback, setlikeEntriesCallback, setlikeIteratorNextCallback,
                iteratorSelfCallback,
            }) |callback| ext_refs.registerCallbackRuntime(callback);
        }

        /// Async iterator callback for Symbol.asyncIterator
        ///
        /// This is called when JavaScript code calls stream[Symbol.asyncIterator]()
        /// or for-await-of loops. It creates a Zig async iterator and wraps it
        /// in a V8 object with next() and return() methods.
        fn asyncIteratorCallback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
            const isolate = info.getIsolate();

            // Get 'this' object (the instance)
            const this_obj = info.getThis();
            defer v8.v8_Object_Dispose(this_obj);

            // Try type-safe unwrapping first
            const wrapper_type_info_registry_iter = @import("wrapper_type_info_registry.zig");
            const instance = blk: {
                if (wrapper_type_info_registry_iter.getWrapperTypeInfoByName(interface_name)) |expected_type| {
                    break :blk getInstanceTypeSafe(runtime.Instance, this_obj, expected_type) orelse {
                        conv.throwError(isolate, "Invalid instance for async iterator - type mismatch");
                        return;
                    };
                } else {
                    break :blk getInstance(runtime.Instance, this_obj) orelse {
                        conv.throwError(isolate, "Invalid instance for async iterator");
                        return;
                    };
                }
            };

            // Call interface's call_values() method to get the Zig iterator
            // The return type is runtime.JSValue which wraps the iterator pointer
            if (@hasDecl(Interface, "call_values")) {
                // Determine signature of call_values at comptime
                const call_values_fn = @TypeOf(Interface.call_values);
                const fn_info = @typeInfo(call_values_fn).@"fn";
                const return_type_info = @typeInfo(fn_info.return_type.?);
                const ReturnPayload = return_type_info.error_union.payload;

                // Call call_values() based on argument count and handle return type appropriately
                if (fn_info.params.len == 1) {
                    // call_values(instance) - no options
                    const result = Interface.call_values(instance) catch |err| {
                        // Throw appropriate error type based on Zig error
                        switch (err) {
                            error.TypeError => conv.throwTypeError(isolate, "Cannot get async iterator on locked stream"),
                            else => {
                                const err_name = @errorName(err);
                                conv.throwError(isolate, err_name);
                            },
                        }
                        return;
                    };

                    // Handle both JSValue and *const anyopaque return types
                    const raw_ptr: *const anyopaque = if (ReturnPayload == runtime.JSValue)
                        result.toAnyopaque() orelse {
                            conv.throwError(isolate, "Failed to get async iterator");
                            return;
                        }
                    else
                        result;

                    const v8_object: *v8.Object = @ptrCast(@alignCast(@constCast(raw_ptr)));
                    info.setReturnValue(@ptrCast(v8_object));
                    // setReturnValue reads the handle into a Local; the
                    // impl handed the iterator over (an owned Global, as
                    // every value an impl returns is the binding's). Kept,
                    // it was a strong root: the iterator, its reader and
                    // its stream lived to the agent's end - one per
                    // `for await` (instances B2's measurement).
                    if (ReturnPayload == runtime.JSValue) {
                        if (result == .handle) v8.v8_Global_Dispose(@ptrCast(v8_object));
                    }
                } else if (fn_info.params.len == 2) {
                    // call_values(instance, options) - has options
                    // Parse options from JavaScript argument
                    const OptionsType = @import("dictionaries").ReadableStreamIteratorOptions;
                    var options: OptionsType = .{};

                    // Check if options argument was passed (arg 0)
                    const argc = info.length();
                    if (argc > 0) {
                        const options_v8 = info.get(0);
                        // Owned (info.get allocates a Global), and read only
                        // in this block: options_obj below is this same handle,
                        // cast, and only Get reads through it.
                        defer v8.v8_Value_Dispose(options_v8);
                        // Only parse if it's an object (not undefined/null)
                        if (!v8.v8_Value_IsNullOrUndefined(options_v8) and v8.v8_Value_IsObject(options_v8)) {
                            const options_obj: *v8.Object = @ptrCast(options_v8);
                            // Each owned, and used only to read one boolean
                            // member: the context (a fresh Global of the
                            // stream's realm per call), the key and the value
                            // Get returns. Kept, they were three Globals per
                            // `stream.values({...})` call, the first pinning
                            // the realm.
                            const ctx = v8.v8_Isolate_GetCurrentContext(isolate) orelse {
                                conv.throwError(isolate, "No context available");
                                return;
                            };
                            defer v8.v8_Context_Dispose(ctx);

                            // Get preventCancel property
                            const key = v8.v8_String_NewFromUtf8(isolate, "preventCancel", 13) orelse {
                                conv.throwError(isolate, "Failed to create property key");
                                return;
                            };
                            defer v8.v8_String_Dispose(key);

                            if (v8.v8_Object_Get(options_obj, ctx, @ptrCast(key))) |prevent_cancel_val| {
                                defer v8.v8_Value_Dispose(prevent_cancel_val);
                                if (!v8.v8_Value_IsNullOrUndefined(prevent_cancel_val)) {
                                    options.preventCancel = v8.v8_Value_BooleanValue(prevent_cancel_val, isolate);
                                }
                            }
                        }
                    }

                    const opt_options = webidl.Opt(OptionsType).passed(options);
                    const result = Interface.call_values(instance, opt_options) catch |err| {
                        // Throw appropriate error type based on Zig error
                        switch (err) {
                            error.TypeError => conv.throwTypeError(isolate, "Cannot get async iterator on locked stream"),
                            else => {
                                const err_name = @errorName(err);
                                conv.throwError(isolate, err_name);
                            },
                        }
                        return;
                    };

                    // Handle both JSValue and *const anyopaque return types
                    const raw_ptr: *const anyopaque = if (ReturnPayload == runtime.JSValue)
                        result.toAnyopaque() orelse {
                            conv.throwError(isolate, "Failed to get async iterator");
                            return;
                        }
                    else
                        result;

                    const v8_object: *v8.Object = @ptrCast(@alignCast(@constCast(raw_ptr)));
                    info.setReturnValue(@ptrCast(v8_object));
                    // setReturnValue reads the handle into a Local; the
                    // impl handed the iterator over (an owned Global, as
                    // every value an impl returns is the binding's). Kept,
                    // it was a strong root: the iterator, its reader and
                    // its stream lived to the agent's end - one per
                    // `for await` (instances B2's measurement).
                    if (ReturnPayload == runtime.JSValue) {
                        if (result == .handle) v8.v8_Global_Dispose(@ptrCast(v8_object));
                    }
                } else {
                    @compileError("Unexpected call_values signature");
                }
            } else {
                conv.throwError(isolate, "Interface does not support async iteration");
            }
        }

        /// Real setter callback generator (uses FunctionCallback signature)
        /// Setter receives the new value as info.get(0)
        /// Generate a property setter callback for a specific property at comptime.
        /// The iface_name parameter ensures uniqueness of the function object per interface.
        fn makeSetterCallback(comptime iface_name: []const u8, comptime setter_name_param: []const u8) v8.FunctionCallback {
            _ = iface_name; // Used only for uniqueness of instantiation
            return struct {
                /// A [CEReactions] attribute's setter is dispatched in a
                /// binding catch scope (engine.withPendingExceptionSetAside).
                fn callback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
                    if (comptime runsCEReactions(Interface, setter_name_param)) return inBindingCatchScope(info, body);
                    body(info);
                }

                fn body(info: *const v8.FunctionCallbackInfo) void {
                    const zig_setter = @field(Interface, setter_name_param);
                    const isolate_inner = info.getIsolate();
                    const context = v8.v8_Isolate_GetCurrentContext(isolate_inner) orelse {
                        conv.throwError(isolate_inner, "No context available");
                        return;
                    };
                    // Released unless converting the value may keep it - the
                    // allowlist every other binding path consults. Before, a
                    // setter never released it, so each `el.onclick = f` pinned
                    // its page.
                    const value_retains = comptime blk: {
                        const fi = @typeInfo(@TypeOf(zig_setter)).@"fn";
                        if (fi.params.len < 2) break :blk false;
                        break :blk typeRetainsContext(fi.params[1].type orelse break :blk true);
                    };
                    defer if (comptime !value_retains) v8.v8_Context_Dispose(context);

                    // Get function's creation context for cross-realm error throwing
                    // Per WebIDL spec: "Throw a TypeError using the function's realm."
                    // Owned: this returns a fresh Global<Context> per call, which nothing was
                    // disposing - 2 leaked handles per DOM object created. Dispose the OWNED
                    // one only; the `orelse` fallback is borrowed and freeing it would be a
                    // double free.
                    const setter_context_owned = info.getFunctionCreationContext();
                    defer if (setter_context_owned) |c| v8.v8_Context_Dispose(c);
                    const setter_context = setter_context_owned orelse context;

                    // WebIDL attribute setter 4.5.2 precedes conversion.
                    // CrossOriginProperties exempts href's setter.
                    if (comptime std.mem.eql(u8, interface_name, "Location") and
                        !acceptsAnyReceiver(setter_name_param["set_".len..], .setter))
                    {
                        if (!cross_origin.receiverIsAccessible(info)) {
                            conv.throwWebIDLErrorFromContext(isolate_inner, setter_context, "SecurityError");
                            return;
                        }
                    }

                    // Get the new value from info[0] - handle missing arguments as undefined
                    // Per WebIDL spec, missing arguments should be treated as undefined
                    const raw_value_v8 = if (info.length() > 0) info.get(0) else v8.v8_Undefined(isolate_inner) orelse unreachable;
                    const new_value_v8 = if (comptime legacyNullToEmptyMask(Interface, setter_name_param) != 0)
                        nullToEmptyString(isolate_inner, raw_value_v8)
                    else
                        raw_value_v8;
                    // The value's handle is owned (`info.get` allocates a Global,
                    // as does `v8_Undefined`), and released here unless it was
                    // handed to a conversion that may keep it - the rule
                    // `convertArgReleasing` applies to an operation's arguments,
                    // `argHandleIsCopied`. A setter released nothing, so every
                    // assignment leaked one handle, and one that held an object
                    // of another realm kept that realm alive.
                    const value_is_copied = comptime blk: {
                        const fi = @typeInfo(@TypeOf(zig_setter)).@"fn";
                        if (fi.params.len < 2) break :blk true;
                        break :blk argHandleIsCopied(fi.params[1].type orelse break :blk false);
                    };
                    // An `any` value is BORROWED by the setter
                    // (`setterValueIsBorrowed`): never handed over, so the defer
                    // releases it once the setter has returned or failed - and
                    // when its conversion fails, which made nothing that refers
                    // to it. Every other kept type is handed over to its
                    // conversion below.
                    const value_is_borrowed = comptime blk: {
                        const fi = @typeInfo(@TypeOf(zig_setter)).@"fn";
                        if (fi.params.len < 2) break :blk false;
                        break :blk setterValueIsBorrowed(fi.params[1].type orelse break :blk false);
                    };
                    // A callback value's Global is the value itself, borrowed
                    // for the setter: a take moved its function out, and the
                    // emptied box goes without the general dispose's lookups
                    // (v8_Global_DisposeCallbackValue), as an argument's does.
                    const value_is_callback = comptime blk: {
                        const fi = @typeInfo(@TypeOf(zig_setter)).@"fn";
                        if (fi.params.len < 2) break :blk false;
                        break :blk isCallbackFunctionShape(fi.params[1].type orelse break :blk false);
                    };
                    var value_handed_over = false;
                    defer if (value_is_copied or !value_handed_over) {
                        if (comptime value_is_callback) v8.v8_Global_DisposeCallbackValue(new_value_v8) else v8.v8_Value_Dispose(new_value_v8);
                    };

                    // Extract instance from 'this'
                    const this_obj = info.getThis();
                    defer v8.v8_Object_Dispose(this_obj);

                    // Derive property name from setter_name_param (strip "set_" prefix)
                    const prop_name = comptime blk: {
                        if (setter_name_param.len > 4 and std.mem.eql(u8, setter_name_param[0..4], "set_")) {
                            break :blk setter_name_param[4..];
                        }
                        break :blk setter_name_param;
                    };

                    // Check if this is a [LegacyLenientThis] attribute
                    const is_lenient_this = comptime isLenientThisProperty(prop_name);

                    // For [Global] interfaces (like Window), we need special handling:
                    // Per WebIDL §3.8, if this is null/undefined, use the method's global object.
                    // See PropertyGetterCallback for detailed explanation.
                    const resolved_instance: ?*anyopaque = blk: {
                        if (is_global_interface) {
                            if (v8.v8_Isolate_GetCurrentContext(isolate_inner)) |method_ctx| {
                                // Owned, as in the getter: one Global<Context> per [Global] setter
                                // call leaked, pinning the page.
                                defer v8.v8_Context_Dispose(method_ctx);
                                if (v8.v8_Context_Global(method_ctx)) |method_global| {
                                    // Owned: v8_Context_Global allocates where V8's Context::Global()
                                    // returns a borrowed Local. Everything below only compares it or
                                    // reads an internal field, so releasing at block exit is correct.
                                    defer v8.v8_Object_Dispose(method_global);
                                    // Check if this IS the method's global object
                                    if (v8.v8_Value_StrictEquals(@ptrCast(this_obj), @ptrCast(method_global))) {
                                        const global_ptr = realmWindow(method_ctx, method_global);
                                        if (global_ptr != null) {
                                            break :blk global_ptr;
                                        }
                                    }

                                    // this is NOT the method's global - check if it's caller's global
                                    const this_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(this_obj, 0);

                                    if (this_ptr == null) {
                                        // No internal field -> this is NOT a valid global object
                                        // (globals always have internal fields pointing to Window instance)
                                        //
                                        // This happens for Object.create(Window.prototype) or other
                                        // incompatible objects. Per WebIDL §3.8, we must throw TypeError.
                                        //
                                        // Note: if method.call(null, ...) is used, V8 coerces null to
                                        // the caller's global in sloppy mode, which DOES have internal
                                        // fields. So this_ptr == null means it's definitely NOT
                                        // a coerced null - it's an incompatible object.
                                        //
                                        // Fall through to throw TypeError
                                    } else {
                                        // Another realm's WindowProxy: the setter acts on
                                        // that window (see PropertyGetterCallback).
                                        if (globalReceiverWindow(this_obj)) |this_window| break :blk this_window;
                                    }
                                }
                            }
                        } else {
                            // Non-[Global] interface: use normal this handling
                            //
                            // We MUST verify that `this` is actually an instance of this interface
                            // BEFORE using the internal field pointer. This is critical because in
                            // sloppy mode, `setter.call(null)` coerces null to the global object (Window),
                            // which HAS internal fields but is NOT an instance of this interface.
                            // Without this check, we'd pass the Window's internal pointer to the setter,
                            // causing InvalidStateError instead of the correct TypeError.
                            //
                            // Per WebIDL spec:
                            // - For regular attributes: throw TypeError if `this` is not a valid instance
                            // - For [LegacyLenientThis]: silently return if `this` is not a valid instance

                            // CROSS-REALM SUPPORT: Use internal slot checking instead of HasInstance.
                            // HasInstance uses prototype chain which fails across realms because
                            // different realms have different prototype objects even for same interface.
                            // Internal slot (WrapperTypeInfo in slot 1) works across realms because
                            // it's tied to the Zig type system, not the JavaScript prototype chain.
                            //
                            // Per WebIDL spec, type checking should be done via internal slots:
                            // "If the this value is null or undefined, or is not a platform object
                            // that implements the interface, then throw a TypeError"
                            const wrapper_type_info_registry_setter = @import("wrapper_type_info_registry.zig");
                            if (wrapper_type_info_registry_setter.getWrapperTypeInfoByName(interface_name)) |expected_type| {
                                if (getInstanceTypeSafe(runtime.Instance, this_obj, expected_type)) |inst| {
                                    break :blk @ptrCast(inst);
                                }
                                // Type check failed - not an instance of this interface
                                if (is_lenient_this) {
                                    // [LegacyLenientThis] - silently return per WebIDL §4.3.10
                                    conv.setReturnUndefined(info);
                                    return;
                                }
                                // Regular attribute - fall through to throw TypeError
                            } else {
                                // Type info not found via comptime lookup - check WrapperTypeInfo in slot 1
                                if (getWrapperTypeInfo(this_obj)) |stored_type_info| {
                                    // WrapperTypeInfo is present - use it for type checking
                                    // Per WebIDL spec: "If the this value is null or undefined, or is not a
                                    // platform object that implements the interface, then throw a TypeError"
                                    //
                                    // IMPORTANT: Check inheritance chain, not just exact match!
                                    // E.g., if setter is on Node.prototype and this is HTMLDivElement,
                                    // we need to check if HTMLDivElement inherits from Node.
                                    var current_type: ?*const WrapperTypeInfo = stored_type_info;
                                    const type_matches = while (current_type) |type_info| {
                                        if (std.mem.eql(u8, type_info.getName(), interface_name)) {
                                            break true;
                                        }
                                        current_type = type_info.parent;
                                    } else false;

                                    if (type_matches) {
                                        // Type matches (including inheritance) - get instance pointer from slot 0
                                        const instance_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(this_obj, 0);
                                        if (instance_ptr != null) {
                                            break :blk instance_ptr;
                                        }
                                    }
                                    // Type mismatch - fall through to throw TypeError
                                } else {
                                    // No WrapperTypeInfo in slot 1 - fall back to legacy getInstance check
                                    const instance_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(this_obj, 0);
                                    if (instance_ptr != null) {
                                        break :blk instance_ptr;
                                    }
                                }
                                // [LegacyLenientThis] - silently return instead of throwing
                                if (is_lenient_this) {
                                    conv.setReturnUndefined(info);
                                    return;
                                }
                            }
                        }

                        // [LegacyLenientThis] on a [Global] interface: `this` is
                        // no Window - return (WebIDL 3.7.6 setter step 1.3.1).
                        if (is_lenient_this) {
                            conv.setReturnUndefined(info);
                            return;
                        }

                        // Throw TypeError from setter's realm (function's creation context)
                        // Per WebIDL spec: "Throw a TypeError using the function's realm."
                        conv.throwTypeErrorFromContext(isolate_inner, setter_context, "Illegal invocation");
                        return;
                    };

                    if (resolved_instance == null) {
                        conv.throwTypeErrorFromContext(isolate_inner, setter_context, "Illegal invocation");
                        return;
                    }

                    // Safety check: detect use-after-free by checking for poison patterns
                    const ptr_as_int = @intFromPtr(resolved_instance.?);
                    const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
                    const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
                    if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
                        (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
                    {
                        conv.throwError(isolate_inner, "Cannot set property on freed object");
                        return;
                    }

                    const instance: *runtime.Instance = @ptrCast(@alignCast(resolved_instance.?));

                    if (!implementsInterface(instance)) {
                        if (!is_lenient_this) {
                            conv.throwTypeErrorFromContext(isolate_inner, setter_context, "Illegal invocation");
                        }
                        return;
                    }

                    // Analyze setter signature
                    const fn_info = @typeInfo(@TypeOf(zig_setter)).@"fn";
                    const params = fn_info.params;

                    // Setter signature: fn(instance: *Instance, value: T) !void
                    if (params.len != 2) {
                        conv.throwError(isolate_inner, "Invalid setter signature");
                        return;
                    }

                    // Get the value parameter type (second parameter after instance)
                    const ValueType = params[1].type.?;

                    // Get allocator from instance context
                    const allocator = instance.ctx.allocator;

                    // Convert V8 value to Zig type
                    // Per WebIDL spec, for enumeration types, if the value is not a valid
                    // enum value, the setter should be a no-op (silently return without error).
                    // https://webidl.spec.whatwg.org/#idl-enums
                    value_handed_over = comptime !value_is_borrowed;
                    // An [EnforceRange] or [Clamp] attribute (`enforce_range` /
                    // `clamp`, bit 0): its branch of ConvertToInt, on the number.
                    const setter_integer: conv.IntegerConversion = comptime if (integerConversionMask(Interface, setter_name_param, .enforce_range) & 1 != 0)
                        .enforce_range
                    else if (integerConversionMask(Interface, setter_name_param, .clamp) & 1 != 0)
                        .clamp
                    else
                        .modulo;
                    const legacy_callback = comptime blk: {
                        if (!@hasDecl(Interface, "legacy_treat_non_object_as_null")) break :blk false;
                        for (Interface.legacy_treat_non_object_as_null) |member| {
                            if (std.mem.eql(u8, member, setter_name_param)) break :blk true;
                        }
                        break :blk false;
                    };
                    const converted_value = if (comptime legacy_callback)
                        conv.fromV8LegacyCallbackAttribute(ValueType, new_value_v8)
                    else if (comptime setter_integer != .modulo)
                        conv.fromV8ValueInteger(ValueType, setter_integer, allocator, isolate_inner, context, new_value_v8)
                    else
                        convertV8ToZig(ValueType, comptime argumentInterface(Interface, setter_name_param, 0), allocator, isolate_inner, context, new_value_v8);
                    var zig_value = converted_value catch |err| {
                        // A strict callback rejects before taking its Global.
                        // The setter's defer still owns that failed argument.
                        if (comptime isCallbackFunctionType(ValueType) or isOptionalCallbackType(ValueType)) value_handed_over = false;
                        // ExceptionPending means an exception was already rethrown
                        if (err == conv.ConversionError.ExceptionPending) {
                            return;
                        }
                        // For enum types, silently ignore invalid values (no-op)
                        if (@typeInfo(ValueType) == .@"enum" and err == error.TypeError) {
                            // Return undefined without calling setter - this is spec-compliant behavior
                            conv.setReturnUndefined(info);
                            return;
                        }
                        conv.throwWebIDLErrorFromContext(isolate_inner, setter_context, @errorName(err));
                        return;
                    };
                    defer freeConvertedValue(ValueType, allocator, zig_value);
                    // A value that does not refer to the handle it was
                    // converted from - a null, a primitive `any` - leaves it
                    // to no one: release it here. Kept, `el.onclick = null`
                    // and `el.hidden = false` were a Global per assignment.
                    if (comptime !value_is_copied) {
                        if (setterValueLeavesHandle(ValueType, zig_value)) value_handed_over = false;
                    }

                    // A restricted `double` or `float` (`restricted_floats`):
                    // NaN and the infinities are a TypeError, before the
                    // setter steps run.
                    if (comptime restrictedFloatMask(Interface, setter_name_param) & 1 != 0) {
                        conv.requireFinite(ValueType, zig_value) catch |err| {
                            conv.throwWebIDLErrorFromContext(isolate_inner, setter_context, @errorName(err));
                            return;
                        };
                    }
                    // A ByteString (`byte_string_arguments`): a code unit
                    // above 0xFF is a TypeError, before the setter steps run.
                    if (comptime byteStringMask(Interface, setter_name_param) & 1 != 0) {
                        conv.encodeByteStringOwned(ValueType, allocator, &zig_value) catch |err| {
                            conv.throwWebIDLErrorFromContext(isolate_inner, setter_context, @errorName(err));
                            return;
                        };
                    }

                    // Call the setter (handle error union return)
                    const ReturnType = fn_info.return_type.?;
                    const return_type_info = @typeInfo(ReturnType);

                    if (return_type_info == .error_union) {
                        // ExceptionPending - script's own exception, which
                        // the impl's conversion left pending (an iterator, a
                        // toString) - is rethrown as it is: throwMemberError
                        // throws nothing over it.
                        zig_setter(instance, zig_value) catch |err| {
                            throwMemberError(isolate_inner, setter_context, err);
                            return;
                        };
                    } else {
                        zig_setter(instance, zig_value);
                    }

                    // Setter succeeded - return undefined
                    conv.setReturnUndefined(info);
                }
            }.callback;
        }

        /// [PutForwards] setter callback generator
        ///
        /// Per WebIDL spec §4.3.10: When a [PutForwards=X] attribute is set,
        /// the assignment is performed by:
        /// 1. Invoking [[Get]] on the object to get the attribute's value
        /// 2. Invoking [[Set]] on that value with property name X and the assigned value
        ///
        /// This ensures JavaScript getter/setter overrides are respected.
        fn PutForwardsSetterCallback(comptime attr_name: []const u8, comptime forward_prop: []const u8) type {
            return struct {
                /// Helper to get a property value, respecting own property getters.
                /// When a user defines an own accessor property using Object.defineProperty,
                /// we must explicitly call their getter function.
                fn getPropertyWithOwnGetterSupport(
                    isolate: *v8.Isolate,
                    context: *v8.Context,
                    obj: *v8.Object,
                    key: *v8.Value,
                ) ?*v8.Value {
                    // Object::Get is a full [[Get]]: it runs an own accessor's getter
                    // with `obj` as the receiver already. The descriptor walk this
                    // did first leaked its descriptor, key and getter every call.
                    _ = isolate;
                    // No own property getter - use standard property access
                    return v8.v8_Object_Get(obj, context, key);
                }

                pub fn callback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
                    const isolate_inner = info.getIsolate();
                    const context = v8.v8_Isolate_GetCurrentContext(isolate_inner) orelse {
                        conv.throwError(isolate_inner, "No context available");
                        return;
                    };

                    // Get the new value from info[0] - handle missing arguments as undefined
                    // Per WebIDL spec, missing arguments should be treated as undefined
                    // Every handle below is owned and released here: this path had
                    // released only `this`, so each `location = url` or
                    // `el.relList = x` leaked the context, the value, both keys
                    // and the forwarded object - and a context handle pins a page.
                    defer v8.v8_Context_Dispose(context);
                    const new_value_v8 = if (info.length() > 0) info.get(0) else v8.v8_Undefined(isolate_inner) orelse unreachable;
                    defer v8.v8_Value_Dispose(new_value_v8);
                    // Get 'this' object
                    const this_obj = info.getThis();
                    defer v8.v8_Object_Dispose(this_obj);

                    // Step 1: Use JavaScript [[Get]] to get the attribute's value
                    // This MUST respect user-defined getters on the object
                    // Per WebIDL spec §3.7.6, we use JavaScript [[Get]] semantics
                    const attr_name_v8 = v8.v8_String_NewFromUtf8(
                        isolate_inner,
                        attr_name.ptr,
                        @intCast(attr_name.len),
                    ) orelse {
                        conv.throwError(isolate_inner, "Failed to create property name");
                        return;
                    };
                    defer v8.v8_String_Dispose(attr_name_v8);

                    // Use our helper that properly invokes own property getters
                    const target_value = getPropertyWithOwnGetterSupport(
                        isolate_inner,
                        context,
                        this_obj,
                        @ptrCast(attr_name_v8),
                    ) orelse {
                        // [[Get]] returned empty/exception
                        // The exception is already set on the context, just return
                        return;
                    };
                    defer v8.v8_Value_Dispose(target_value);

                    // Step 2: Check if the target is an object (not null/undefined)
                    // Per WebIDL spec: "if the result is not an object, throw a TypeError"
                    if (v8.v8_Value_IsNull(target_value) or v8.v8_Value_IsUndefined(target_value)) {
                        // Owned: this returns a fresh Global<Context> per call, which nothing was
                        // disposing - 2 leaked handles per DOM object created. Dispose the OWNED
                        // one only; the `orelse` fallback is borrowed and freeing it would be a
                        // double free.
                        const function_ctx_owned = info.getFunctionCreationContext();
                        defer if (function_ctx_owned) |c| v8.v8_Context_Dispose(c);
                        const function_ctx = function_ctx_owned orelse context;
                        conv.throwTypeErrorFromContext(isolate_inner, function_ctx, "Cannot set property on null or undefined");
                        return;
                    }

                    if (!v8.v8_Value_IsObject(target_value)) {
                        // Owned: this returns a fresh Global<Context> per call, which nothing was
                        // disposing - 2 leaked handles per DOM object created. Dispose the OWNED
                        // one only; the `orelse` fallback is borrowed and freeing it would be a
                        // double free.
                        const function_ctx_owned = info.getFunctionCreationContext();
                        defer if (function_ctx_owned) |c| v8.v8_Context_Dispose(c);
                        const function_ctx = function_ctx_owned orelse context;
                        conv.throwTypeErrorFromContext(isolate_inner, function_ctx, "Cannot set property on non-object");
                        return;
                    }

                    // Step 3: Use JavaScript [[Set]] to set the forwarded property
                    // This respects any user-defined setters on the target object
                    const forward_prop_v8 = v8.v8_String_NewFromUtf8(
                        isolate_inner,
                        forward_prop.ptr,
                        @intCast(forward_prop.len),
                    ) orelse {
                        conv.throwError(isolate_inner, "Failed to create forward property name");
                        return;
                    };
                    defer v8.v8_String_Dispose(forward_prop_v8);

                    const target_obj: *v8.Object = @ptrCast(target_value);
                    _ = v8.v8_Object_Set(target_obj, context, @ptrCast(forward_prop_v8), new_value_v8);

                    // Per WebIDL spec: "if [[Set]] returns false, this is NOT an error"
                    // The setter should NOT throw even if [[Set]] returns false

                    // Return undefined
                    conv.setReturnUndefined(info);
                }
            };
        }

        /// Convert V8 value to Zig type based on comptime type information
        ///
        /// `value_interface`: the interface an interface-typed attribute's
        /// value converts to (`argumentInterface`, argument 0) - a TypeError
        /// before the setter steps unless the value implements it.
        fn convertV8ToZig(comptime T: type, comptime value_interface: ?type, allocator: std.mem.Allocator, isolate: *v8.Isolate, context: *v8.Context, v8_value: *v8.Value) !T {
            // Handle primitive types
            if (T == runtime.DOMString) {
                // WebIDL 3.2.10: "Let x be ? ToString(V)" - what a toString
                // throws propagates as it is (ExceptionPending, rethrown),
                // and a Symbol is a TypeError: conv.fromV8Value's DOMString
                // conversion, as an operation argument's. A ToString done
                // here turned every throw into a TypeError of its own.
                return try conv.fromV8Value(runtime.DOMString, allocator, isolate, context, v8_value);
            } else if (T == runtime.USVString or T == []const u8) {
                // DOMString conversion, then every lone surrogate becomes
                // U+FFFD (WebIDL 3.2.11); the bytes are the fresh copy
                // fromV8String allocated, so they are rewritten in place.
                const dom_str = try conv.fromV8Value(runtime.DOMString, allocator, isolate, context, v8_value);
                const bytes = dom_str.asSlice();
                if (bytes.len > 0) conv.replaceLoneSurrogates(@constCast(bytes));
                return bytes;
            } else if (T == bool or T == runtime.Boolean) {
                return conv.fromV8Boolean(isolate, v8_value);
            } else if (@typeInfo(T) == .int or @typeInfo(T) == .float) {
                // Every integer and floating-point type converts as an
                // operation argument does: ToNumber, then ConvertToInt for an
                // integer - `short`'s wrap included, where an @intCast from
                // `long` would have panicked on 70000.
                return try conv.fromV8Value(T, allocator, isolate, context, v8_value);
            } else {
                // For complex types (callbacks, optionals, interfaces, etc.),
                // use the generic converter - an interface type to the
                // interface codegen names for this attribute.
                return try conv.fromV8ValueAs(T, value_interface, allocator, isolate, context, v8_value);
            }
        }

        /// Free converted value if it needs cleanup (e.g., DOMString, USVString, []const u8, JSValue)
        fn freeConvertedValue(comptime T: type, allocator: std.mem.Allocator, value: T) void {
            const type_info = @typeInfo(T);

            // Handle optional types - unwrap and recurse if non-null
            if (type_info == .optional) {
                if (value) |inner_value| {
                    freeConvertedValue(type_info.optional.child, allocator, inner_value);
                }
                return;
            }

            if (T == runtime.DOMString) {
                // DOMString owns its buffer - deinit it
                var mutable_value = value;
                mutable_value.deinit(allocator);
            } else if (T == runtime.USVString or T == []const u8) {
                // USVString and []const u8 are slices from a DOMString allocation
                // The slice points to memory that was allocated by fromV8String
                // We need to free the underlying buffer
                if (value.len > 0) {
                    // The slice was created by DOMString.asSlice() which returns data[0..len]
                    // We need to free the original allocation
                    allocator.free(value);
                }
            } else if (T == runtime.JSValue) {
                // JSValue may contain an owned string that needs cleanup
                // This is used by [Replaceable] setters and other 'any' type parameters
                switch (value) {
                    .string => |str| {
                        if (str.owned and str.data.len > 0) {
                            allocator.free(str.data);
                        }
                    },
                    .handle => |h| {
                        // The argument's own handle, not this value's: its
                        // owner releases it - an attribute setter's binding
                        // once the setter has returned (`setterValueIsBorrowed`).
                        // Releasing it here too would free it twice. Nothing
                        // else cleans it up - not the context's end: a Global
                        // outlives its context.
                        _ = h;
                    },
                    else => {}, // Other variants don't need cleanup
                }
            } else if (type_info == .@"union" and type_info.@"union".tag_type != null) {
                // A union-typed attribute ((TrustedHTML or DOMString)
                // innerHTML, the Trusted Types setters): free the arm the
                // conversion took, as freeConvertedArg does for an
                // operation's union argument. An interface arm is a borrowed
                // *Instance - nothing to free.
                switch (value) {
                    inline else => |payload| freeConvertedValue(@TypeOf(payload), allocator, payload),
                }
            }
            // Other types (primitives, etc.) don't need cleanup
        }

        /// Generate a static method callback for a specific method at comptime
        ///
        /// Static methods don't operate on an existing instance - they create new
        /// instances (factory methods) or perform class-level operations.
        ///
        /// This creates a callback that:
        /// 1. Gets the runtime context from V8 context manager
        /// 2. Creates a "template" instance to pass context to the method
        /// 3. Parses arguments from V8
        /// 4. Calls the Interface static method
        /// 5. Converts and returns the result to V8
        fn StaticMethodCallback(comptime zig_name: []const u8) type {
            return struct {
                fn callback(info: *const v8.FunctionCallbackInfo) callconv(.c) void {
                    if (comptime returnsPromise(Interface, zig_name)) return rejectOnThrow(info, scoped);
                    scoped(info);
                }

                /// A [CEReactions] operation is dispatched in a binding catch
                /// scope (engine.withPendingExceptionSetAside).
                fn scoped(info: *const v8.FunctionCallbackInfo) void {
                    if (comptime runsCEReactions(Interface, zig_name)) return inBindingCatchScope(info, body);
                    body(info);
                }

                fn body(info: *const v8.FunctionCallbackInfo) void {
                    const isolate = info.getIsolate();

                    // Get V8 context
                    const v8_context = v8.v8_Isolate_GetCurrentContext(isolate) orelse {
                        conv.throwError(isolate, "No current V8 context");
                        return;
                    };
                    // Ours to release (v8_Isolate_GetCurrentContext allocates a
                    // Global per call), unless converting an argument makes the
                    // engine keep it - the rule MethodCallback applies, by the
                    // same allowlist (typeRetainsContext answers "retains" for
                    // any type it does not know). getOrCreateWithIsolate below
                    // keeps its own copy. Nothing released it: one Global
                    // Context - a pin on the whole page - per `URL.canParse()`,
                    // `AbortSignal.timeout()`, `Response.json()`.
                    const params_retain = comptime blk: {
                        const fi = @typeInfo(@TypeOf(@field(Interface, zig_name))).@"fn";
                        for (fi.params) |prm| {
                            const P = prm.type orelse break :blk true;
                            if (P == *runtime.Instance) continue; // the call vehicle
                            if (typeRetainsContext(P)) break :blk true;
                        }
                        break :blk false;
                    };
                    defer if (comptime !params_retain) v8.v8_Context_Dispose(v8_context);

                    // WebIDL "create an operation function" step 3 (no `this`
                    // to check for a static operation): too few arguments is
                    // a TypeError before any is converted.
                    if (throwIfTooFewArguments(zig_name, info, isolate, v8_context)) return;

                    // Get allocator
                    const isolate_alloc = @import("isolate_allocator.zig");
                    const allocator = isolate_alloc.getOrInitAllocator(isolate, std.heap.c_allocator) catch {
                        conv.throwError(isolate, "Failed to get isolate allocator");
                        return;
                    };

                    // Get runtime context from context manager
                    const context_manager = @import("context_manager.zig");
                    const runtime_ctx = context_manager.getOrCreateWithIsolate(v8_context, isolate, allocator) catch {
                        conv.throwError(isolate, "Failed to get runtime context");
                        return;
                    };

                    // Create a template instance to carry context to the static method
                    // This instance is just a vehicle for passing allocator/context
                    const template_instance = runtime.Instance.init(allocator, struct {}, &runtime.VTable{
                        // Not a real interface - a vehicle for handing the static
                        // method an allocator and context. Named so that if it ever
                        // does reach getInstanceInterfaceName the answer is honest
                        // rather than a plausible-looking lie.
                        .name = "<static-call-vehicle>",
                        .deinit = null,
                        .methods_ptr = &.{},
                    }, runtime_ctx) catch {
                        conv.throwError(isolate, "Failed to create template instance");
                        return;
                    };
                    defer runtime.Instance.deinit(template_instance);

                    // Get the static method function at comptime
                    const method_fn = @field(Interface, zig_name);
                    const fn_info = @typeInfo(@TypeOf(method_fn)).@"fn";
                    const params = fn_info.params;
                    const ReturnType = fn_info.return_type.?;

                    // First parameter should be *runtime.Instance (template for context)
                    if (params.len < 1) {
                        @compileError("Static method must have at least instance parameter");
                    }

                    // Calculate number of WebIDL parameters (excluding instance)
                    const webidl_param_count = params.len - 1;

                    // Call the static method with appropriate arguments
                    // For indexed callbacks, return_context is same as v8_context (no cross-realm)
                    var result_owned = false;
                    const result = callMethodWithArgs(
                        method_fn,
                        params,
                        webidl_param_count,
                        ReturnType,
                        comptime legacyNullToEmptyMask(Interface, zig_name),
                        comptime argModesOf(Interface, zig_name),
                        template_instance,
                        info,
                        allocator,
                        isolate,
                        v8_context,
                        v8_context, // return_context: same as caller context for indexed callbacks
                        &result_owned,
                    ) catch |err| {
                        if (err == conv.ConversionError.ExceptionPending) {
                            return;
                        }
                        conv.throwWebIDLErrorFromContext(isolate, v8_context, @errorName(err));
                        return;
                    };

                    // Convert and set return value. setReturnValue copies, so a
                    // handle the conversion made or the impl handed over is
                    // released here - kept, a promise or an object pinned its
                    // whole page.
                    if (result) |v8_result| {
                        info.setReturnValue(v8_result);
                        if (result_owned) v8.v8_Global_Dispose(v8_result);
                    }
                    // If result is null, V8 will return undefined (correct for void methods)
                }
            };
        }
    };
}

// ============================================================================
// Helper Functions
// ============================================================================
//
// POINTER TAGGING AUDIT NOTES
// ===========================
//
// ## Summary
//
// The getInstance/setInstance family of functions are SAFE from pointer tagging
// issues because they operate directly on V8 internal fields, NOT on values
// returned from conv.fromV8Value().
//
// ## Pointer Flow Analysis
//
// ### SAFE Paths (no tagging involved):
//
// 1. getInstance(object) -> v8_Object_GetAlignedPointerFromInternalField
//    - Extracts raw Zig pointer from V8 internal storage
//    - This pointer was stored by setInstance, never passed through fromV8Value
//    - NO TAGGING: Direct V8 API call returns raw pointer
//
// 2. setInstance(object, instance) -> v8_Object_SetAlignedPointerInInternalField
//    - Stores raw Zig pointer into V8 internal storage
//    - NO TAGGING: Direct storage, pointer identity preserved
//
// 3. constructorCallback -> info.getThis() -> getInstance()
//    - `this` object comes from V8 callback, not fromV8Value
//    - Internal field extraction is untagged
//
// ### POTENTIALLY TAGGED Paths (require attention):
//
// 1. callConstructorWithArgs -> conv.fromV8Value(Param1Type, ...)
//    - Returns tagged pointers when Param1Type is *const anyopaque
//    - These go to Zig impl constructors, which must handle tagged pointers
//    - IMPL CODE RESPONSIBILITY: Untag before V8 FFI calls
//
// 2. callMethodWithArgs -> conv.fromV8Value(ParamType, ...)
//    - Same as above: tagged pointers for *const anyopaque params
//    - IMPL CODE RESPONSIBILITY: Untag before V8 FFI calls
//
// ## Conclusion
//
// interface.zig itself is SAFE - it never passes tagged pointers to V8 FFI.
// Tagged pointers only flow to impl code via constructor/method parameters.
// Impl code must follow the tagging contract documented in pointer_tag.zig.
//
// ============================================================================

/// Extract Zig instance from V8 object internal field (legacy - no type checking)
/// Prefer getInstanceTypeSafe for production code.
///
/// ## Pointer Tagging Note
///
/// This function returns an UNTAGGED pointer. The pointer is extracted directly
/// from V8's internal field storage, not from conv.fromV8Value(). No untagging
/// is required by callers.
/// The overload resolution algorithm's view of one call's arguments
/// (webidl.overload_resolution.select calls `at` for the distinguishing index).
///
/// `FunctionCallbackInfo.get` allocates a Global per call, and the caller owns
/// it: `at` keeps the one argument it fetched until `release`.
pub const OverloadArgs = struct {
    info: *const v8.FunctionCallbackInfo,
    isolate: *v8.Isolate,
    held: ?*v8.Value = null,

    pub fn at(self: *OverloadArgs, i: usize) OverloadArg {
        self.release();
        if (i >= @as(usize, @intCast(self.info.length()))) return .{ .value = null, .isolate = self.isolate };
        const value = self.info.get(@intCast(i));
        self.held = value;
        return .{ .value = value, .isolate = self.isolate };
    }

    pub fn release(self: *OverloadArgs) void {
        if (self.held) |value| v8.v8_Value_Dispose(value);
        self.held = null;
    }
};

/// One JavaScript argument, answering the questions of the overload
/// resolution algorithm's step 12. `value` is null for an argument that was
/// not passed, which reads as undefined.
pub const OverloadArg = struct {
    value: ?*v8.Value,
    isolate: *v8.Isolate,

    const Error = error{ TypeError, JavaScriptException };

    pub fn isUndefined(self: OverloadArg) bool {
        const v = self.value orelse return true;
        return v8.v8_Value_IsUndefined(v);
    }
    pub fn isNull(self: OverloadArg) bool {
        const v = self.value orelse return false;
        return v8.v8_Value_IsNull(v);
    }
    pub fn isObject(self: OverloadArg) bool {
        const v = self.value orelse return false;
        return v8.v8_Value_IsObject(v);
    }
    pub fn isCallable(self: OverloadArg) bool {
        const v = self.value orelse return false;
        return v8.v8_Value_IsFunction(v);
    }
    fn instance(self: OverloadArg) ?*runtime.Instance {
        const v = self.value orelse return null;
        if (!v8.v8_Value_IsObject(v)) return null;
        return getInstance(runtime.Instance, @ptrCast(v));
    }
    pub fn isPlatformObject(self: OverloadArg) bool {
        return self.instance() != null;
    }
    /// Does the platform object implement the interface `id` names - is that
    /// interface's State in its state ancestry? The same brand check the
    /// receiver gets.
    pub fn implements(self: OverloadArg, id: webidl.overload_resolution.Id) bool {
        const inst = self.instance() orelse return false;
        for (inst.vtable.ancestors) |ancestor| {
            if (ancestor.id == id) return true;
        }
        return false;
    }
    pub fn hasArrayBufferData(self: OverloadArg) bool {
        const v = self.value orelse return false;
        return v8.v8_Value_IsArrayBuffer(v);
    }
    pub fn isDataView(self: OverloadArg) bool {
        const v = self.value orelse return false;
        return v8.v8_Value_IsDataView(v);
    }
    pub fn typedArrayName(self: OverloadArg) ?[]const u8 {
        const v = self.value orelse return null;
        return conv.typedArrayNameOf(v);
    }
    /// A String object ([[StringData]]). Only step 12.9 (async sequences
    /// against a string type) asks; no FFI predicate exists, and no overload
    /// set in the IDL corpus reaches that case.
    pub fn hasStringData(self: OverloadArg) bool {
        _ = self;
        return false;
    }
    pub fn hasIteratorMethod(self: OverloadArg) Error!bool {
        return self.hasMethod(v8.v8_Symbol_GetIterator);
    }
    pub fn hasAsyncIteratorMethod(self: OverloadArg) Error!bool {
        if (try self.hasMethod(v8.v8_Symbol_GetAsyncIterator)) return true;
        return self.hasMethod(v8.v8_Symbol_GetIterator);
    }
    pub fn isBoolean(self: OverloadArg) bool {
        const v = self.value orelse return false;
        return v8.v8_Value_IsBoolean(v);
    }
    pub fn isNumber(self: OverloadArg) bool {
        const v = self.value orelse return false;
        return v8.v8_Value_IsNumber(v);
    }
    pub fn isBigInt(self: OverloadArg) bool {
        const v = self.value orelse return false;
        return v8.v8_Value_IsBigInt(v);
    }

    /// ECMAScript GetMethod(V, symbol) is not undefined. GetMethod runs the
    /// property's getter, which can throw; a present but non-callable value is
    /// a TypeError (GetMethod step 3).
    fn hasMethod(self: OverloadArg, getSymbol: *const fn (*v8.Isolate) callconv(.c) ?*v8.Symbol) Error!bool {
        const v = self.value orelse return false;
        if (!v8.v8_Value_IsObject(v)) return false;
        const context = v8.v8_Isolate_GetCurrentContext(self.isolate) orelse return error.JavaScriptException;
        defer v8.v8_Context_Dispose(context);
        const symbol = getSymbol(self.isolate) orelse return false;
        defer v8.v8_Symbol_Dispose(symbol);
        const method = v8.v8_Object_Get(@ptrCast(v), context, @ptrCast(symbol)) orelse return error.JavaScriptException;
        defer v8.v8_Value_Dispose(method);
        if (v8.v8_Value_IsNullOrUndefined(method)) return false;
        if (!v8.v8_Value_IsFunction(method)) return error.TypeError;
        return true;
    }
};

pub fn getInstance(comptime T: type, object: *v8.Object) ?*T {
    const ptr = v8.v8_Object_GetAlignedPointerFromInternalField(object, 0);
    if (ptr == null) return null;

    // Safety check: detect use-after-free by checking for poison patterns
    const ptr_as_int = @intFromPtr(ptr);
    const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
    const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
    if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
        (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
    {
        return null;
    }

    return @ptrCast(@alignCast(ptr));
}

/// Extract Zig instance from V8 object with type-safe unwrapping
///
/// Validates that the stored type tag matches the expected type before returning.
/// Returns null if:
/// - The object has no internal fields set
/// - The stored type is not compatible with the expected type
/// - The instance pointer appears to be freed (poison pattern detected)
pub fn getInstanceTypeSafe(
    comptime T: type,
    object: *v8.Object,
    expected_type: *const WrapperTypeInfo,
) ?*T {
    // Get stored type info from slot 1
    const type_info_ptr = v8.v8_Object_GetAlignedPointerFromInternalField(object, 1);
    if (type_info_ptr == null) {
        // No type info stored - fall back to legacy behavior for compatibility
        return getInstance(T, object);
    }

    // Safety check: detect use-after-free on type info pointer
    const type_ptr_as_int = @intFromPtr(type_info_ptr);
    const poison_pattern_aa: usize = 0xaaaaaaaaaaaaaaaa;
    const poison_pattern_dead: usize = 0xdeaddeaddeaddead;
    if (type_ptr_as_int == poison_pattern_aa or type_ptr_as_int == poison_pattern_dead or
        (type_ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
    {
        return null;
    }

    const stored_type_info: *const WrapperTypeInfo = @ptrCast(@alignCast(type_info_ptr));

    // Validate that stored type is compatible with expected type
    // Use registry.isSubclassOf for authoritative check (walks parent chain using registry indices)
    // The tag check is just a fast path/preliminary check, and WrapperTypeInfo.parent pointers
    // are null in the registry, so we must use the registry helper.
    const wrapper_type_info_registry = @import("wrapper_type_info_registry.zig");
    if (!wrapper_type_info_registry.isSubclassOf(stored_type_info, expected_type)) {
        return null;
    }

    // Type check passed, get the instance pointer from slot 0
    const ptr = v8.v8_Object_GetAlignedPointerFromInternalField(object, 0);
    if (ptr == null) return null;

    // Safety check: detect use-after-free on instance pointer
    const ptr_as_int = @intFromPtr(ptr);
    if (ptr_as_int == poison_pattern_aa or ptr_as_int == poison_pattern_dead or
        (ptr_as_int & 0xFFFF000000000000) == 0xaaaa000000000000)
    {
        return null;
    }

    return @ptrCast(@alignCast(ptr));
}

/// Get the WrapperTypeInfo from a V8 object (if set)
pub fn getWrapperTypeInfo(object: *v8.Object) ?*const WrapperTypeInfo {
    const ptr = v8.v8_Object_GetAlignedPointerFromInternalField(object, 1);
    if (ptr == null) return null;
    return @ptrCast(@alignCast(ptr));
}

/// Store Zig instance in V8 object internal field (legacy - no type info)
/// Prefer setInstanceWithTypeInfo for new code.
///
/// ## Pointer Tagging Note
///
/// This function stores an UNTAGGED pointer directly into V8's internal field.
/// The pointer can later be retrieved via getInstance(), which also returns
/// it untagged. This bypasses the pointer tagging system entirely.
pub fn setInstance(comptime T: type, object: *v8.Object, instance: *T) void {
    v8.v8_Object_SetAlignedPointerInInternalField(
        object,
        0,
        @ptrCast(instance),
    );
    // [wrap_tracking]: the object reaches the instance from here.
    if (T == runtime.Instance) runtime.instance_lifecycle.markWrapped(instance);
}

/// Store Zig instance in V8 object with type info for safe unwrapping
///
/// Stores:
/// - Slot 0: Zig instance pointer
/// - Slot 1: WrapperTypeInfo pointer (for type checking during unwrap)
pub fn setInstanceWithTypeInfo(
    comptime T: type,
    object: *v8.Object,
    instance: *T,
    type_info: *const WrapperTypeInfo,
) void {
    // Store instance pointer in slot 0
    v8.v8_Object_SetAlignedPointerInInternalField(
        object,
        0,
        @ptrCast(instance),
    );
    // [wrap_tracking]: the object reaches the instance from here - a
    // constructor's `this`, a custom element's at construction or upgrade.
    if (T == runtime.Instance) runtime.instance_lifecycle.markWrapped(instance);
    // Store type info pointer in slot 1
    v8.v8_Object_SetAlignedPointerInInternalField(
        object,
        1,
        @ptrCast(@constCast(type_info)),
    );
}

// ============================================================================
// Cross-Realm Constructor Support
// ============================================================================

/// Handle NewTarget.prototype fallback per WebIDL §3.7.2
///
/// When NewTarget.prototype is not an object (e.g., a primitive like 7),
/// V8 falls back to Object.prototype. We must detect this and fix it
/// by setting the prototype to the interface's prototype object from
/// GetFunctionRealm(NewTarget).
///
/// Per WebIDL spec:
/// "The prototype of the newly created object will be the value of the
/// 'prototype' property of NewTarget. If the prototype is not an object,
/// the prototype will be the interface prototype object of the associated
/// global object's relevant Realm."
/// A constructor's instance that already has a wrapper - its construction
/// wrapped it: an edge traced to it, a host step that handed it to script -
/// keeps that wrapper. It is given `receiver`'s prototype (NewTarget's, or
/// the fallback's), and is the construction's result: V8 takes an API
/// constructor's object return value over its receiver
/// (Builtins::HandleApiConstruct), as for an upgrade's element (HTML 3.2.3
/// steps 14 and 16). Binding the receiver instead would replace the wrapper
/// and drop every edge drawn on it - the template whose content was freed
/// under it (PR-M1, tests/v8/constructed_wrapper_test.zig). Whether it did;
/// `receiver` is the caller's to release either way, bound to nothing when
/// this answers true.
fn adoptExistingWrapper(info: *const v8.FunctionCallbackInfo, receiver: *v8.Object, instance: *runtime.Instance, function_context: *v8.Context) bool {
    const storage = instance.ctx.getV8WrapperCacheStorage() orelse return false;
    const cache: *@import("wrapper_cache.zig").WrapperCache = @ptrCast(@alignCast(storage));
    if (cache.is_tearing_down) return false;
    const borrowed = cache.existingWrapper(instance) orelse return false;
    // Held at once: the cache holds it weakly, and the prototype calls
    // below allocate.
    const wrapper = v8.v8_Global_Clone(@ptrCast(borrowed)) orelse return false;
    defer v8.v8_Global_Dispose(wrapper);
    if (v8.v8_Value_IsUndefined(wrapper) or !v8.v8_Value_IsObject(wrapper)) return false;
    if (v8.v8_Object_GetPrototypeV2(receiver)) |prototype| {
        defer v8.v8_Value_Dispose(prototype);
        _ = v8.v8_Object_SetPrototypeV2(@ptrCast(wrapper), function_context, prototype);
    }
    info.setReturnValue(wrapper);
    return true;
}

fn handleNewTargetPrototypeFallback(
    info: *const v8.FunctionCallbackInfo,
    this_obj: *v8.Object,
    isolate: *v8.Isolate,
    v8_context: *v8.Context,
    comptime interface_name: []const u8,
) void {
    // Get NewTarget - returns null for non-construct calls (already checked)
    // Every handle below is owned. NewTarget is usually the constructor
    // itself, so leaking it kept one handle per `new X()` on the page's
    // interface object - and with it the page.
    const new_target_val = info.getNewTarget() orelse return;
    defer v8.v8_Value_Dispose(new_target_val);

    // Get the "prototype" property of NewTarget
    const prototype_key = v8.v8_String_NewFromUtf8(
        isolate,
        "prototype",
        9,
    ) orelse return;
    defer v8.v8_String_Dispose(prototype_key);

    const new_target_obj: *v8.Object = @ptrCast(new_target_val);
    const proto_val = v8.v8_Object_Get(new_target_obj, v8_context, @ptrCast(prototype_key));
    defer if (proto_val) |pv| v8.v8_Value_Dispose(pv);

    // Check if prototype is a valid object
    // If it IS an object, V8 already set the prototype correctly - nothing to do
    if (proto_val) |pv| {
        if (v8.v8_Value_IsObject(pv)) {
            // NewTarget.prototype is a valid object - V8 handled it correctly
            return;
        }
    }

    // NewTarget.prototype is NOT an object (e.g., primitive like 7)
    // We need to fall back to the interface prototype from GetFunctionRealm(NewTarget)

    // Get the realm of NewTarget using GetFunctionRealm algorithm
    // For bound functions: recurse to [[BoundTargetFunction]]
    // For proxies: recurse to [[ProxyTarget]]
    // Otherwise: function's creation context
    const target_realm_owned = getFunctionRealm(new_target_val, isolate);
    defer if (target_realm_owned) |r| v8.v8_Context_Dispose(r);
    const target_realm = target_realm_owned orelse v8_context;

    // Get the interface constructor from the target realm
    // The constructor is available as a property on the global object
    const global = v8.v8_Context_Global(target_realm) orelse return;
    defer v8.v8_Object_Dispose(global);

    const ctor_name = v8.v8_String_NewFromUtf8(
        isolate,
        interface_name.ptr,
        @intCast(interface_name.len),
    ) orelse return;
    defer v8.v8_String_Dispose(ctor_name);

    const ctor_val = v8.v8_Object_Get(global, target_realm, @ptrCast(ctor_name)) orelse return;
    defer v8.v8_Value_Dispose(ctor_val);

    if (!v8.v8_Value_IsFunction(ctor_val)) return;

    // Get the constructor's prototype property
    const ctor_obj: *v8.Object = @ptrCast(ctor_val);
    const interface_proto = v8.v8_Object_Get(ctor_obj, target_realm, @ptrCast(prototype_key)) orelse return;
    defer v8.v8_Value_Dispose(interface_proto);

    if (!v8.v8_Value_IsObject(interface_proto)) return;

    // Set the prototype on 'this' to the interface prototype
    _ = v8.v8_Object_SetPrototype(this_obj, v8_context, interface_proto);
}

/// Implement GetFunctionRealm algorithm per ECMA-262 §7.3.22
///
/// 1. If func is a bound function, return GetFunctionRealm(func.[[BoundTargetFunction]])
/// 2. If func is a Proxy, return GetFunctionRealm(func.[[ProxyTarget]])
/// 3. Return func.[[Realm]]
fn getFunctionRealm(func: *v8.Value, isolate: *v8.Isolate) ?*v8.Context {
    return getFunctionRealmWithDepth(func, isolate, 0);
}

fn getFunctionRealmWithDepth(func: *v8.Value, isolate: *v8.Isolate, depth: u32) ?*v8.Context {
    // Limit recursion depth to prevent infinite loops
    // (in case proxy target returns something unexpected)
    if (depth > 10) {
        // Fall back to creation context
        if (v8.v8_Value_IsFunction(func)) {
            const fn_obj: *v8.Function = @ptrCast(func);
            return v8.v8_Function_GetCreationContext(fn_obj);
        }
        return null;
    }

    // Step 2: If func is a Proxy, recurse on [[ProxyTarget]]
    if (v8.v8_Value_IsProxy(func)) {
        const proxy_obj: *v8.Object = @ptrCast(func);
        if (v8.v8_Proxy_GetTarget(proxy_obj)) |target| {
            // OWNED (a Global per call): released once the recursion has
            // its answer, a Context of its own. Kept, it was one leaked
            // handle per proxy NewTarget whose prototype fell back
            // (`leaks --atExit`: ROOT LEAK <malloc in v8_Proxy_GetTarget>).
            defer v8.v8_Value_Dispose(target);
            return getFunctionRealmWithDepth(target, isolate, depth + 1);
        }
        // Revoked proxy or error - fall through to function check
    }

    // Step 1: If func is a bound function, recurse on [[BoundTargetFunction]]
    // NOTE: V8's public API doesn't fully expose [[BoundTargetFunction]].
    // Our v8_BoundFunction_GetBoundTargetFunction can't reliably get the
    // original function, so we just use the bound function's creation context.
    // This works because the bound function was created in the target's realm.

    // Step 3: Return func.[[Realm]] (creation context)
    if (v8.v8_Value_IsFunction(func)) {
        const fn_obj: *v8.Function = @ptrCast(func);
        return v8.v8_Function_GetCreationContext(fn_obj);
    }

    return null;
}

// ============================================================================
// Post-Constructor Hooks
// ============================================================================

/// Capture stack trace for DOMException instances
///
/// Per WebIDL spec and WPT tests (DOMException-custom-bindings.any.js):
/// "If the implementation has a stack property on normal errors, it also does on DOMExceptions"
///
/// This function compiles and runs a small JS snippet that uses Error.captureStackTrace
/// (V8-specific) to capture the current stack trace and assign it to the DOMException.
fn captureDOMExceptionStack(
    this_obj: *v8.Object,
    isolate: *v8.Isolate,
    v8_context: *v8.Context,
) void {
    // Use Error.captureStackTrace if available (V8/Node.js specific)
    // This creates a proper stack trace on the target object
    //
    // We pass 'this_obj' as a temporary global variable for the script to use
    // Every handle below is an owned Global, and each is released here: the
    // global object, the script and its completion value. v8_Object_Set and
    // v8_Script_Run read them as Locals and keep nothing. Kept, they were three
    // Globals per DOMException - the global object is the whole page, and
    // the script is bound to the realm - so every page that made or threw
    // one stayed alive for the life of the process.
    const global = v8.v8_Context_Global(v8_context) orelse return;
    defer v8.v8_Object_Dispose(global);

    // Store the DOMException object as a temporary global for the script to access
    const temp_key = v8.v8_String_NewFromUtf8(isolate, "__domex_stack_target__", 22) orelse return;
    defer v8.v8_String_Dispose(temp_key);
    _ = v8.v8_Object_Set(global, v8_context, @ptrCast(temp_key), @ptrCast(this_obj));

    // Compile and run a script that captures the stack trace
    // This handles the case where Error.captureStackTrace may not exist
    const script_src =
        \\(function() {
        \\  if (typeof Error.captureStackTrace === 'function') {
        \\    Error.captureStackTrace(__domex_stack_target__, DOMException);
        \\  } else {
        \\    // Fallback: create an Error and copy its stack
        \\    var e = new Error();
        \\    if (e.stack !== undefined) {
        \\      __domex_stack_target__.stack = e.stack;
        \\    }
        \\  }
        \\  // Clean up temporary global
        \\  delete __domex_stack_target__;
        \\})();
    ;
    const source = v8.v8_String_NewFromUtf8(isolate, script_src.ptr, @intCast(script_src.len)) orelse return;
    defer v8.v8_String_Dispose(source);
    const script = v8.v8_Script_Compile(v8_context, source) orelse return;
    defer v8.v8_Script_Dispose(script);
    if (v8.v8_Script_Run(v8_context, script)) |result| v8.v8_Value_Dispose(result);
}

