test "V8Interface compiles" {
    const testing = std.testing;
    testing.refAllDecls(@This());
}

test "V8Interface uses Meta hints" {
    // Create a mock interface with Meta hints (as generated by codegen)
    const MockInterface = struct {
        pub const Meta = struct {
            pub const name = "MockInterface";
            pub const BaseType = void;
            pub const MixinTypes = .{};
            // Pre-computed hints (as generated by codegen)
            pub const properties = .{
                .{ "value", "get_value", "set_value" },
                .{ "readonly", "get_readonly", null },
            };
            pub const methods = .{
                .{ "doSomething", "call_doSomething" },
                .{ "doAnother", "call_doAnother" },
            };
            pub const has_constructor = false;
        };

        pub const State = struct {
            value: u32 = 0,
        };

        pub fn get_value() u32 {
            return 0;
        }
        pub fn set_value(_: u32) void {}
        pub fn get_readonly() u32 {
            return 0;
        }
        pub fn call_doSomething() void {}
        pub fn call_doAnother() void {}
    };

    const Binding = V8Interface(MockInterface);

    // Verify interface name
    const testing = std.testing;
    try testing.expectEqualStrings("MockInterface", Binding.name);

    // Verify methods from hints
    try testing.expectEqual(@as(usize, 2), Binding.all_methods.len);
}
